INSERT INTO public.t_memo_archive (user_id,category,title,memo,link_url,currency_unit,detail_count,closed_flg,del_flg,create_tim,update_tim) VALUES
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'道東ドライブ','大自然と絶品海の幸を巡る道東ドライブ旅','釧路から知床、網走にかけての道東エリアを、男2人で巡る2泊3日のドライブ旅行です。
INSERT INTO public.t_memo_archive (user_id,category,title,memo,link_url,currency_unit,detail_count,closed_flg,del_flg,create_tim,update_tim) VALUES
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'秋田満喫旅','竿燈の街と秘湯を巡る！秋田満喫ドライブ旅','大自然と伝統文化を求めて、秋田県を巡る1泊2日のドライブ旅行に行ってきました。
INSERT INTO public.t_memo_archive (user_id,category,title,memo,link_url,currency_unit,detail_count,closed_flg,del_flg,create_tim,update_tim) VALUES
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'大阪グルメ','大阪満喫！新世界から新大阪への旅','新幹線で大阪に到着後、新世界の通天閣や日本橋、道頓堀のグルメを満喫。
INSERT INTO public.t_memo_archive (user_id,category,title,memo,link_url,currency_unit,detail_count,closed_flg,del_flg,create_tim,update_tim) VALUES
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'名古屋グルメ','名古屋名物を食べ尽くす極上グルメ旅','喫茶店の小倉トーストから始まり、名古屋コーチン、味噌カツ、ひつまぶし、台湾ラーメンまで、名古屋が誇る魅惑の名物グルメを一日で贅沢に食べ歩く旅。歴史ある名古屋城や栄の街並みも巡り、心もお腹も満たされる充実のルート。','','JPY',16,false,false,'2026-08-01 21:59:51.737518+09','2026-08-01 22:00:24.13769+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'日光神社仏閣','世界遺産・日光東照宮と大自然を巡る旅','世界遺産に登録される日光東照宮や輪王寺、二荒山神社の荘厳な社寺建築を巡り、華厳の滝や中禅寺湖の美しい大自然に癒やされる旅。
INSERT INTO public.t_memo_archive (user_id,category,title,memo,link_url,currency_unit,detail_count,closed_flg,del_flg,create_tim,update_tim) VALUES
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'香川うどん男旅','男二人で挑む香川のうどん食べつくし旅','本場の讃岐うどんをハシゴして食べまくる男二人旅！行列のセルフ店から製麺所直営の隠れ家まで完全制覇し、夜はスパイシーな名物「骨付鳥」とビールで熱く語り合う、胃袋も心も限界まで満たされる最高に最高な男のグルメドライブ旅。','','JPY',16,false,false,'2026-08-02 01:35:25.086879+09','2026-08-02 01:35:55.895579+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'米子山陰リゾート','米子城跡と皆生温泉を満喫する山陰の旅','天空の城と称される「米子城跡」からの大パノラマや、日本海の波音が心地よい名湯「皆生温泉」、美しい弓ヶ浜の海岸線、霊峰大山の自然とご当地グルメを網羅した、山陰・米子の魅力を満喫する笑顔いっぱいの観光プラン。','','JPY',16,false,false,'2026-08-02 01:27:16.327071+09','2026-08-02 01:27:37.314591+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'四国お遍路夫婦旅','50代夫婦で巡る四国お遍路の旅','発心・修行の道中を50代の夫婦二人で支え合い、全30スポットの厳かな霊場や絶景を丁寧に巡るお遍路旅！お互いの健康を祈り、歴史ある寺院で心穏やかな時間を過ごしながら、絆がさらに深まる最高に温かい夫婦のグルメ＆巡礼ドライブ旅。','','JPY',30,false,false,'2026-08-02 01:44:28.15501+09','2026-08-02 01:45:00.338541+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'岡山観光めぐり','晴れの国・岡山を巡る歴史とグルメ旅','漆黒の岡山城と日本三名園の後楽園、白壁が美しい倉敷美観地区の川舟流し、瀬戸大橋が望める鷲羽山の絶景を大満喫！さらにデミカツ丼や絶品フルーツパフェなど、岡山の魅力と美味しいグルメをぎっしり詰め込んだ充実の観光プラン。','','JPY',16,false,false,'2026-08-02 01:37:59.550303+09','2026-08-02 01:38:30.245869+09'),
	 ('f2dfd247-bd9c-4757-a366-7a93a30ae11a'::uuid,'【24時間マイクラ】','【24時間マイクラ】あの有吉弘行を感動させろ！井口の挑戦wi','旅の思い出についての情報を書き込みましょう。','','JPY',16,false,false,'2026-08-11 11:13:37.973345+09','2026-08-22 11:30:08.628047+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'高知かつお旅','太平洋と城下町を巡る高知の一日旅','高知駅から始まり、桂浜の雄大な太平洋、坂本龍馬像、ひろめ市場の賑わい、高知城の歴史を巡る明るい一日旅。海・街・食の魅力がぎゅっと詰まった高知らしい体験が続き、歩くたびに新しい発見がある充実した旅になった。','','JPY',15,false,false,'2026-08-02 01:58:27.047402+09','2026-08-02 01:59:34.331952+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'四国漫遊記','四国をぐるっと巡る3日間の記録','四国を回っていると、土地ごとに空気の色が少しずつ違っていて、移動するたびに「次はどんな景色かな」と胸がふわっと弾む旅になった。港の風、山の上の静けさ、太平洋の力強さ、温泉街のやわらかい灯り。
INSERT INTO public.t_memo_archive (user_id,category,title,memo,link_url,currency_unit,detail_count,closed_flg,del_flg,create_tim,update_tim) VALUES
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'湯布院女子旅','景色と温泉を楽しむ癒やしの女子旅','湯布院の街歩きやカフェ、金鱗湖の散策、宿の露天風呂など、女子旅らしい癒やしの時間が続く旅。由布岳の景色と温泉が心を落ち着かせ、写真映えするスポットも多く、自然と楽しい思い出が積み重なるルート。','','JPY',12,false,false,'2026-08-02 07:37:04.894384+09','2026-08-02 07:40:18.731648+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'下関フグ旅','下関で味わうフグ尽くしの一日','下関の海沿いを巡りながら、名物のフグを思う存分楽しむ一日旅。唐戸市場の活気ある食べ歩きから始まり、フグ寿司・唐揚げ・フグ汁など多彩な味を堪能。海峡ゆめタワーや火の山公園、長府城下町など景色の美しいスポットも巡り、食と風景の両方で下関の魅力を感じられる。大学生4人の旅らしく、にぎやかさと発見が詰まったプロモーション向けのフグ体験旅。','','JPY',15,false,false,'2026-08-02 02:35:22.146541+09','2026-08-02 02:37:11.534223+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'青海島サイクリング旅','海上アルプスを走る、長門の絶景サイクリング','長門市駅から仙崎の港町を抜け、青海島の海岸線を走るサイクリング旅。青海島は「海上アルプス」と呼ばれるほど地形が豊かで、断崖・洞門・岩壁・入り江が次々と現れる。仙崎の港町では地元の食堂や市場の雰囲気を味わい、島内では展望地や遊歩道を巡りながら自然の雄大さを体感できる。長門らしい素朴さと海の力強さが詰まった、プロモーション向けのサイクリング旅。','','JPY',15,false,false,'2026-08-02 02:57:17.775334+09','2026-08-02 03:03:07.129106+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'出雲縁結び旅','出雲大社でご縁を結ぶ静かな一日','出雲大社を中心に、神話と歴史が息づく出雲の街を歩く縁結びの旅。勢溜の大鳥居から続く松の参道は空気が澄んでいて、歩くだけで心が整う。荘厳な本殿や神楽殿、素鵞社などを巡りながら、ゆっくりと自分の気持ちと向き合える時間が流れる。稲佐の浜では神話の舞台を感じ、参道の甘味や出雲そばで体を癒し、旅の終わりには自然と気持ちがやわらかくなるような、出雲らしい穏やかな縁結びの一日。','','JPY',15,false,false,'2026-08-02 02:40:53.40301+09','2026-08-02 02:43:39.376134+09'),
	 ('940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'ゆったり田舎旅','庄原と三次で楽しむ、ゆっくり過ごすお年寄りの旅','三次駅から始まり、商店街や川沿いをゆっくり歩きながら庄原方面へ向かう穏やかな田舎旅。車で移動しつつ、平坦で歩きやすい場所だけを短く散策するため、お年寄りでも安心して楽しめる。
