	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'気まぐれ旅','兵庫温泉と城下町ラーメン巡り旅','北近畿の豊かな自然と歴史ある街並みを巡る、男子会1泊2日旅行。
INSERT INTO public.t_memo_archive_pub (archive_id,user_id,category,title,memo,link_url,currency_unit,detail_count,report_count,closed_flg,limited_open_flg,del_flg,create_tim,update_tim,click_stats) VALUES
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'気まぐれ旅','奥羽山脈を越えて！日本海から太平洋を巡る横断旅','東北を東西に横断する壮大なドライブ計画として、日本海側の庄内エリアから出発し、険しい山々を越えて太平洋側の宮城・松島へと抜ける1泊2日の男二人旅に行ってきました。
INSERT INTO public.t_memo_archive_pub (archive_id,user_id,category,title,memo,link_url,currency_unit,detail_count,report_count,closed_flg,limited_open_flg,del_flg,create_tim,update_tim,click_stats) VALUES
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'気まぐれ旅','岩手で満喫！女三人食いしん坊旅','仲良し女友達3人で、食いしん坊全開の岩手1泊2日旅行に行ってきました。
INSERT INTO public.t_memo_archive_pub (archive_id,user_id,category,title,memo,link_url,currency_unit,detail_count,report_count,closed_flg,limited_open_flg,del_flg,create_tim,update_tim,click_stats) VALUES
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'気まぐれ旅','大阪満喫！1泊2日ひとり旅の記','新世界の活気ある通天閣から始まり、日本橋や道頓堀の賑わい、アメリカ村の路地裏散策を経て、初日は難波で宿泊。
INSERT INTO public.t_memo_archive_pub (archive_id,user_id,category,title,memo,link_url,currency_unit,detail_count,report_count,closed_flg,limited_open_flg,del_flg,create_tim,update_tim,click_stats) VALUES
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,'気まぐれ旅','男4人！ノープランの北海道ドライブ旅','男友達4人で「とりあえず北海道に行こう」とだけ決めて飛び乗った、行き当たりばったりの1泊2日ドライブ旅行。
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.600833330,130.571111110,'城山展望台へ移動','城山展望台へ向かう道は緑が多くて気持ちが良い。展望台からは桜島が大きく見えて、鹿児島らしい景色に感動する。
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710000000,139.810700000,'押上駅で解散・それぞれの道へ','楽しかった卒業旅行もついに終わりの時間。最寄りの駅からそれぞれの家に帰る電車のホームで、「社会人になってもまた集まろうな」と約束して笑顔で手を振って別れた。','2026-03-15','21:30','🥺','0','',0,0,false,'2026-03-15 21:35:10.88+09','2026-08-02 22:21:10.868408+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.833656000,135.499700000,'今宮三丁目 (大阪府)','簡易メモ','2026-08-02','14:35','😀','0000','',0,0,true,'2026-08-02 14:35:36.905755+09','2026-08-02 22:23:22.372453+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.631200000,139.878200000,'アドベンチャーランドでジャングルクルーズ','最初の アトラクションはジャングルクルーズ！船長さんの楽しいトークに子どもたちが大爆笑。リアルな動物の動きにみんなで大興奮した。','2026-08-05','10:15','🥳','0','',0,1,true,'2026-08-05 10:20:10.5+09','2026-08-01 16:43:46.307334+09'),
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.667000000,135.504000000,'難波のホテルにチェックイン','夕方にホテルへ戻ってチェックイン。少し部屋のベッドで横になったら、そのままウトウトしてしまいそうになる。夜ご飯に向けて、少し体力回復を優先して部屋でゴロゴロ。','2026-08-01','20:00','😴','0','',0,0,false,'2026-08-01 20:03:12.3+09','2026-08-01 09:28:00.797366+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633500000,139.879000000,'ウエスタンランドのレストランでランチ','お昼ごはんはハンバーガーとチキンレッグにかぶりつく！ボリューム満点で美味しいけれど、お昼時ですごい混雑していて席を探すのに一苦労した。','2026-08-05','12:00','🍔','1','',-4500,0,true,'2026-08-05 12:05:40.1+09','2026-08-01 16:43:46.307334+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710000000,139.810700000,'とうきょうスカイツリー駅で合流','朝からテンション高めで全員集合。駅を降りた瞬間に目の前にそびえ立つ巨大なスカイツリーの迫力に思わず歓声が上がる。学生最後の思い出づくりがここからスタートする。','2026-03-15','10:00','🎓','0','',0,1,false,'2026-03-15 10:02:15.12+09','2026-08-02 22:21:10.868408+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710300000,139.811300000,'東京スカイツリー展望デッキ','高速エレベーターで一気に地上350mの展望デッキへ。窓の外に広がる東京の絶景にみんなで大興奮しながら記念撮影の嵐。遠くの方まで見渡せて本当に気持ちがいい。','2026-03-15','10:45','✨','0','',-2100,1,false,'2026-03-15 10:48:40.5+09','2026-08-02 22:21:10.868408+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.711874500,139.812934399,'ソラマチ商店街でお土産探し','キャラクターショップやおしゃれな雑貨店が並ぶエリアをみんなでブラブラ。お互いに「これ似合いそう」などと言い合いながら、記念にお揃いのキーホルダーを購入した。','2026-03-15','14:00','🛍️','0','',-1500,1,false,'2026-03-15 14:03:20.15+09','2026-08-02 22:21:10.868408+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.711708983,139.795757532,'浅草寺と雷門の定番スポット','言わずと知れた観光名所の雷門に到着。圧倒的な提灯の大きさに改めて感動しつつ、仲見世通りで人形焼きを買ってその場でパクつく。すごい人混みだけどそれもまた楽しい。','2026-03-15','16:10','🏮','0','',-500,1,false,'2026-03-15 16:15:12.3+09','2026-08-02 22:21:10.868408+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.713207335,139.793515205,'浅草のレトロな老舗喫茶店','歩き疲れて足がパンパンになったので、昔ながらの雰囲気漂う喫茶店で休憩。名物のクリームソーダを頼んで、学生時代のバカだったエピソードを振り返りながら大笑いする。','2026-03-15','17:20','☕','0','',-850,1,false,'2026-03-15 17:25:40.9+09','2026-08-02 22:21:10.868408+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.805000000,'駅ナカで夕食','駅ナカの食堂で軽い夕食。疲れた体に温かい料理が染みる。夕食1100円。','2026-08-02','18:40','🙂','0000','',-1100,1,false,'2026-08-02 18:42:00+09','2026-08-01 19:13:30.384146+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.709766310,139.801379442,'夕暮れの吾妻橋からスカイツリーを望む','すっかり日も傾いてきて、夕暮れに染まる空とライトアップが始まったスカイツリーを眺める。昼間とは違う幻想的な景色に、みんな少ししんみりしつつも写真を撮りまくる。','2026-03-15','18:30','🌇','0','',0,1,false,'2026-03-15 18:35:15.4+09','2026-08-02 22:21:10.868408+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710079929,139.809629917,'ソラマチに戻り最後の夜ご飯','再びスカイツリーの足元に戻り、夕飯はちょっとお高めの焼肉で打ち上げ。4年間一緒に頑張ってきた仲間と食べるお肉は格別に美味しくて、お酒も進んで最高に盛り上がる。','2026-03-15','19:30','🍻','0','',-4500,1,false,'2026-03-15 19:35:50.22+09','2026-08-02 22:21:10.868408+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.261836191,131.355843544,'湯布院駅に到着','朝の湯布院駅は霧が少し残っていて幻想的。女子旅の始まりにぴったりの雰囲気で、駅前の可愛い看板を見つけて友達と写真を撮りまくる。山並みが見えてテンションが上がる。','2026-09-10','10:05','📸','0000','',0,1,false,'2026-09-10 10:05:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.260939070,131.360864639,'由布見通りを散策','由布見通りは小さな雑貨屋やカフェが並んでいて歩くだけで楽しい。友達と「これ可愛い」と言いながら店を巡る時間が最高。湯布院らしい落ち着いた空気が心地よい。','2026-09-10','10:40','🛍️','0000','',0,1,false,'2026-09-10 10:40:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.256883969,131.356101036,'カフェでプリン休憩','湯布院の人気カフェでプリンを注文。濃厚でしっかりした味わいが美味しくて、友達と「これ当たり」と盛り上がる。店内の雰囲気も可愛くて女子旅感が増す。','2026-09-10','11:20','🍮','0000','',-900,1,false,'2026-09-10 11:20:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.259073029,131.343955994,'金鱗湖へ向かう道','金鱗湖へ向かう途中の道は木々が多くて、光が差し込む感じがとても綺麗。写真映えするスポットが多くて、歩くたびに立ち止まって撮影会になる。','2026-09-10','12:00','🌿','0000','',0,1,false,'2026-09-10 12:00:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.260651989,131.334300041,'金鱗湖を散策','湖面に映る景色が美しくて、友達と何枚も写真を撮る。静かな空気が心地よくて、都会では味わえないゆったりした時間が流れる。湖畔のベンチで少し休憩。','2026-09-10','12:35','🌅','0000','',0,1,false,'2026-09-10 12:35:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.265388699,131.326446533,'湖畔カフェで昼食','湖畔のカフェでパスタを注文。窓から見える景色が綺麗で、食事がより美味しく感じる。女子旅らしく写真を撮りながらゆっくりランチを楽しむ。','2026-09-10','13:10','🍝','0000','',-1500,1,false,'2026-09-10 13:10:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.270017507,131.323313713,'宿にチェックイン','少し高台にある宿に到着。ロビーから見える由布岳が美しくて、友達と「やばい景色」と感動。部屋も綺麗で女子旅にぴったりの雰囲気。','2026-09-10','14:00','🏨','0000','',0,1,false,'2026-09-10 14:00:00+09','2026-08-02 22:32:23.750814+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.270833330,131.318333330,'露天風呂でゆったり','宿の露天風呂は景色が最高で、由布岳を眺めながら入る温泉は格別。湯気と風が気持ちよくて、友達とゆっくり話す時間が幸せ。','2026-09-10','15:00','♨️','0000','',0,1,false,'2026-09-10 15:00:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.270914535,131.321167946,'ラウンジで休憩','温泉後にラウンジでアイスティーを飲みながら休憩。静かで落ち着いた空間が心地よくて、旅の疲れが少し取れた気がする。','2026-09-10','16:00','🫖','0000','',-600,1,false,'2026-09-10 16:00:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.268366952,131.322069168,'宿の夕食を楽しむ','地元食材を使った料理が並び、どれも美味しくて感動。女子旅らしく写真を撮りながら楽しい夕食時間。デザートまでしっかり堪能した。','2026-09-10','18:00','🍽️','0000','',0,1,false,'2026-09-10 18:00:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.269586931,131.320137978,'夜の湯布院を散歩','夜の湯布院は静かで幻想的。街灯に照らされた道を歩くと昼とは違う雰囲気で、友達と「夜の方が好きかも」と話しながら散歩を楽しむ。','2026-09-10','19:30','🌙','0000','',0,1,false,'2026-09-10 19:30:00+09','2026-08-02 22:32:23.750814+09'),
	 (66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.267577546,131.320695877,'朝の由布岳を眺める','翌朝、宿のテラスから見る由布岳は美しくて、女子旅の締めくくりにふさわしい景色だった。朝の空気が澄んでいて深呼吸したくなる。','2026-09-11','07:30','🌄','0000','',0,1,false,'2026-09-11 07:30:00+09','2026-08-02 22:32:23.750814+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.404722000,133.190556000,'向島へ渡るフェリー','短い船旅でも海の上を進む感覚が楽しくて、旅の気分が一気に高まる。','2026-08-04','09:00','🚢','0000','',-180,1,false,'2026-08-04 09:00:00+09','2026-08-02 22:41:01.052054+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.246000000,135.192000000,'ポルトヨーロッパ散策','ヨーロッパ風の街並みで写真が止まらない。家族ではしゃぎすぎて笑いが絶えない。','2026-08-15','10:20','🙂','0000','',0,1,true,'2026-08-15 10:22:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680000000,135.838000000,'老舗の茶屋で名物ランチ休憩','奈良公園近くの落ち着いた和風茶屋で、名物の柿の葉寿司とそうめんのセットを味わう。伝統の優しい味わいにホッとする。','2026-07-01','13:30','🍱','0','',-1500,4,true,'2026-07-01 13:35:00+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.683300000,135.847200000,'春日大社の神秘的な境内を散策','世界遺産・春日大社へ。約3000基の釣燈籠が並ぶ回廊や、深い緑に包まれた神聖な雰囲気に包まれながら参道を進む。','2026-07-01','15:00','🌲','0','',-500,5,true,'2026-07-01 15:05:12.3+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.678000000,135.830000000,'町家カフェで絶品かき氷を堪能','奈良の古い町並みが残るエリアでおしゃれな町家カフェを発見。火照った体を冷やすために、こだわりフルーツのかき氷を食べる。','2026-07-01','16:30','🍧','0','',-1100,6,true,'2026-07-01 16:35:40.1+09','2026-08-01 17:15:34.285211+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.675000000,135.820000000,'若草山の夕景を眺めるドライブ','夕暮れ時に若草山周辺の高台へ。奈良盆地に沈んでいく美しい夕日を眺めながら、穏やかな時間に浸る。','2026-07-01','17:40','🌅','0','',0,7,true,'2026-07-01 17:45:10+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680000000,135.825000000,'奈良市内の和風ホテルへチェックイン','古都の景観に溶け込む落ち着いた和風ホテルに到着。部屋で少し荷物を整理して、夜の街へ繰り出す準備をする。','2026-07-01','18:30','🏨','0','',-14000,8,true,'2026-07-01 18:35:20+09','2026-08-01 17:15:34.285211+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.545000000,139.899000000,'宇都宮城址公園でお腹を休める','食後の運動を兼ねて、綺麗に整備された城址公園を散歩。復元された美しいお城や広大な芝生を眺めながら、ベンチでまったり休憩。','2026-08-05','17:00','🌳','0','',0,1,false,'2026-08-05 17:05:15.3+09','2026-08-01 16:47:54.502649+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.003700000,135.760000000,'京都駅で待ち合わせ','朝、京都駅の烏丸口で無事に合流！今日のルートを確認しながら、テンション高めで地下鉄に乗り込む。天気も良くて最高の女子旅日和になりそう。','2026-08-03','10:00','👯‍♀️','0','',0,1,false,'2026-08-03 10:02:15.12+09','2026-08-01 09:37:37.584085+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.552000000,139.895000000,'隠れ家カフェでコーヒーブレイク','夕暮れ時の街を眺めながら、おしゃれな個人カフェへ。甘いチーズケーキとブラックコーヒーで、お口の中をさっぱりリセット。','2026-08-05','18:00','🍰','0','',-850,1,false,'2026-08-05 18:05:50.8+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.557000000,139.897500000,'餃子テーマパークで最後の食べ比べ','夜の部は複数の専門店が集まる人気スポットへ。揚げ餃子やシソ餃子など、バラエティ豊かな味を少しずつ欲張って食べ比べ！','2026-08-05','19:15','🥳','0','',-1600,1,false,'2026-08-05 19:20:10.2+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.555000000,139.895000000,'市内をのんびりお散歩しながら移動','次の目的地に向けて、宇都宮の街並みを眺めながらぶらぶら歩き。夏の暑さで少し汗ばんできたけれど、緑豊かな通りが気持ちいい。','2026-08-05','12:45','🚶‍♂️','1','',0,0,false,'2026-08-05 12:50:10.5+09','2026-08-01 16:47:54.502649+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686000000,135.830000000,'近鉄奈良駅ビルでお土産選び','駅に戻り、奈良のお土産売り場で柿の葉寿司や大仏プリン、鹿モチーフの可愛いお菓子などをたくさん買い込む。','2026-07-02','17:00','🛍️','0','',-3000,15,true,'2026-07-02 17:05:11.1+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.832900000,'近鉄奈良駅から帰路へ','たくさんの思い出とお土産をカバンに詰め込んで、特急列車に乗車。古都の余韻に浸りながら帰路につく。','2026-07-02','18:00','👋','0','',0,16,true,'2026-07-02 18:05:05.1+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.700000000,135.500000000,'新大阪駅で旅の締めくくりに一杯','新大阪駅に到着後、新幹線の出発まで少し時間があったので、駅構内の立ち飲み屋で奈良の旅を振り返りながらビールを一杯。','2026-07-02','19:30','🍻','0','',-800,17,true,'2026-07-02 19:35:00+09','2026-08-01 17:15:34.285211+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632500000,139.881000000,'シンデレラ城前でエレクトリカルパレード','夕暮れのシンデレラ城をバックに、大迫力のナイトパレードを鑑賞。光り輝くフロートとキャラクターの笑顔に、家族全員で感動の嵐。','2026-08-05','19:30','🎆','0','',0,1,false,'2026-08-05 19:35:22.4+09','2026-08-01 16:41:55.293734+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668700000,135.785000000,'奈良町にぎわいの家','古い町家の展示を見学。歴史を感じる空間で気持ちが落ち着く。入館料500円。','2026-08-02','16:20','🙂','0000','',-500,1,false,'2026-08-02 16:22:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.669500000,135.784000000,'甘味処で休憩','かき氷を食べて涼む。歩き疲れた体に甘さが染みる。かき氷850円。','2026-08-02','17:00','🤩','0000','',-850,1,false,'2026-08-02 17:02:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.805000000,'奈良駅へ戻る道','夕暮れの街を歩きながら駅へ。少し疲れが出てきたが満足感が大きい。','2026-08-02','18:00','🙂','0000','',0,1,false,'2026-08-02 18:02:00+09','2026-08-01 19:13:30.384146+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.245500000,135.191500000,'黒潮市場で朝ごはん','海鮮丼を家族みんなで堪能。新鮮すぎて思わず声が出る。1200円。','2026-08-15','09:40','🤩','0000','',-1200,1,true,'2026-08-15 09:42:00+09','2026-08-01 21:33:47.291888+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632300000,139.880400000,'東京ディズニーランド・エントランス','手荷物検査を抜けて、ついにワールドバザールへ！お馴染みの音楽とシンデレラ城が見えてきて大人も胸が熱くなる。まずはポップコーンバケットをゲット！','2026-08-05','09:00','✨','0','',-3400,1,false,'2026-08-05 09:05:20.2+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.631200000,139.878200000,'アドベンチャーランドでジャングルクルーズ','最初の アトラクションはジャングルクルーズ！船長さんの楽しいトークに子どもたちが大爆笑。リアルな動物の動きにみんなで大興奮した。','2026-08-05','09:45','🥳','0','',0,1,false,'2026-08-05 09:50:10.5+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.630500000,139.877000000,'カリブの海賊で涼みながら冒険','ひんやりした洞窟を進むカリブの海賊へ。迫力ある砲撃音にびっくりしつつも、スリリングなボートの雰囲気を家族みんなで満喫した。','2026-08-05','10:30','🏴‍☠️','0','',0,1,false,'2026-08-05 10:35:00+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.631800000,139.878500000,'ウエスタンランドでスナック休憩','ちょっと小腹が空いたので、スモークターキーレッグを買い食い。ジューシーでスパイシーな肉汁がたまらない！パパと半分こして食べた。','2026-08-05','11:15','🍖','1','',-900,1,false,'2026-08-05 11:20:12.3+09','2026-08-01 16:41:55.293734+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.690100000,135.352100000,'白浜温泉の宿でゆったり温泉と会席料理','温泉に浸かって一日の運転の疲れをしっかりリフレッシュ。海の幸がふんだんに使われた豪華な夕食を家族で囲み、楽しい夜を過ごした。','2026-09-12','20:00','♨️','0','',-32000,1,false,'2026-09-12 20:30:00+09','2026-08-01 21:08:04.82446+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725000000,135.385000000,'円月島（高月島）の景色をドライブ中に眺める','海にぽっかり浮かぶ円月島の丸い穴に沈む夕日は見られなかったが、青い海と美しいコントラストをなす昼間の姿を車窓から満喫。','2026-09-13','11:00','🚗','0','',0,1,false,'2026-09-13 11:20:00+09','2026-08-01 21:08:04.82446+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.800000000,135.420000000,'とれとれ市場でお土産の海産物を物色','新鮮な魚介類や紀州の特産品が並ぶ巨大な市場へ。家族それぞれが気になるお土産や乾物を楽しそうに選んで買い込んだ。','2026-09-13','12:00','🛍️','0','',-4200,1,false,'2026-09-13 12:30:00+09','2026-08-01 21:08:04.82446+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.733300000,135.466700000,'南部梅林の近くのドライブロードを爽快走行','心地よい海風と山あいの緑を感じながら、快適な海岸線沿いのドライブを楽しむ。車内での家族の会話も弾む。','2026-09-13','13:30','🎶','0','',0,1,false,'2026-09-13 13:50:00+09','2026-08-01 21:08:04.82446+09'),
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702400000,135.495900000,'梅田の地下街でランチ','大阪城から梅田へ移動。複雑怪奇な梅田の地下街（ウメダ地下迷宮）にやっぱり少し迷う。なんとかたどり着いたお店で、絶品のどて焼き定食をいただく。味が染み込んでいて最高。','2026-08-02','12:00','😋','0','',-1100,1,false,'2026-08-02 12:05:15.4+09','2026-08-01 09:28:00.797366+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.032100000,135.195000000,'紀州梅の里でたくさんの梅干しをお土産に購入','道の駅でバラエティ豊かな紀州南高梅の梅干しや梅ジュースを試食してお気に入りを発見。自宅用と親戚用にたくさん買い込んだ。','2026-09-13','14:45','🍊','0','',-5000,1,false,'2026-09-13 15:15:00+09','2026-08-01 21:08:04.82446+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.195000000,135.152500000,'海辺のカフェで昼食','海を眺めながらパスタを食べる。家族で「ここ最高！」と一致。1100円。','2026-08-15','13:00','🤩','0000','',-1100,1,true,'2026-08-15 13:02:00+09','2026-08-01 21:33:47.291888+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.408056000,133.204167000,'尾道駅から旅を始める','朝の尾道駅は静かで海風が心地よい。ここからしまなみ海道の旅が始まると思うと胸が高鳴る。','2026-08-04','08:30','🙂','0000','',0,1,false,'2026-08-04 08:30:00+09','2026-08-02 07:30:32.144728+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.407222000,133.168333000,'向島の海沿いを散歩','海沿いの道は静かで、波の音だけが聞こえる。ゆったりした時間が流れて心が落ち着く。','2026-08-04','09:40','🙂','0000','',0,1,false,'2026-08-04 09:40:00+09','2026-08-02 07:30:32.144728+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.427778000,133.156111000,'因島大橋を渡る瞬間','橋の上から見える海が美しくて、思わず速度を落として景色を眺めた。','2026-08-04','10:20','🙂','0000','',0,1,false,'2026-08-04 10:20:00+09','2026-08-02 07:30:32.144728+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.285556000,133.204444000,'因島でレモンソフトを食べる','名物のレモンソフトは爽やかで暑い日にぴったり。島の雰囲気と相まって気分が良くなる。','2026-08-04','11:00','🤩','0000','',-350,1,false,'2026-08-04 11:00:00+09','2026-08-02 07:30:32.144728+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.250833000,133.226944000,'生口橋を渡る','白い橋が美しくて、瀬戸内海の穏やかな景色が広がる。写真を撮りたくなる場所。','2026-08-04','11:40','🙂','0000','',0,1,false,'2026-08-04 11:40:00+09','2026-08-02 07:30:32.144728+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578000000,136.648000000,'金沢駅に到着！鼓門がお出迎え','北陸新幹線で金沢駅に到着。立派な「鼓門」の前で記念撮影をして、ゆったりとした温泉旅行のスタートに心が弾む。','2026-08-05','10:30','📸','0','',0,1,false,'2026-08-05 10:35:15.1+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.561000000,136.656500000,'近江町市場で新鮮な海の幸ランチ','お昼ごはんは活気あふれる近江町市場へ。ノドグロや甘エビがたっぷり乗った海鮮丼を味わう。新鮮でとろける美味しさに思わず笑みがこぼれる。','2026-08-05','12:00','丼','0','',-3800,1,false,'2026-08-05 12:05:20.2+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.562200000,136.662000000,'金沢城公園の広大な敷地をのんびり散策','白亜の美しい石川門や復元された長屋を見学。よく手入れされた広大な芝生と歴史ある建造物を、自分のペースでゆっくり歩いて見て回った。','2026-08-05','13:45','🏯','0','',0,1,false,'2026-08-05 13:50:10.5+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.561300000,136.663700000,'兼六園の日本庭園で緑に癒やされる','日本三名園の一つ、兼六園へ。樹齢数百年の松や美しい霞ヶ池を眺めながらそぞろ歩き。風情ある景色に心がすっきりと洗われるような心地よさ。','2026-08-05','15:00','🌲','0','',-650,1,false,'2026-08-05 15:05:00+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.560000000,136.660000000,'老舗茶屋で金箔入り抹茶休憩','歩き疲れたので、伝統的な日本家屋の茶屋でひと休み。きらびやかな金箔が乗った抹茶と和菓子をいただき、上品な甘さに旅の疲れが癒やされる。','2026-08-05','16:20','🍵','0','',-1200,1,false,'2026-08-05 16:25:12.3+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'山代温泉の老舗旅館に到着','夕方に金沢から特急と送迎バスを乗り継ぎ、加賀温泉郷の山代温泉へ。趣のある純和風の温泉宿にチェックインし、仲居さんの温かいお出迎えにホッとする。','2026-08-05','17:40','🏨','0','',-35000,1,false,'2026-08-05 17:45:40.1+09','2026-08-01 16:53:24.05998+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.832900000,'近鉄奈良駅から帰路へ','たくさんの思い出とお土産をカバンに詰め込んで、特急列車に乗車。古都の余韻に浸りながら帰路につく。','2026-07-02','18:00','👋','0','',0,16,true,'2026-07-02 18:05:05.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.700000000,135.500000000,'新大阪駅で旅の締めくくりに一杯','新大阪駅に到着後、新幹線の出発まで少し時間があったので、駅構内の立ち飲み屋で奈良の旅を振り返りながらビールを一杯。','2026-07-02','19:30','🍻','0','',-800,17,true,'2026-07-02 19:35:00+09','2026-08-01 19:03:48.822924+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.230100000,135.165000000,'公園でひと休み','木陰で休憩。風が気持ちよくて少し元気が戻る。','2026-08-10','11:20','🙂','0','',0,1,false,'2026-08-10 11:22:00+09','2026-08-01 19:28:00.274263+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.832900000,'近鉄奈良駅に到着！古都めぐりの幕開け','近鉄奈良駅に到着し、いざ歴史と文化の街・奈良へ。駅からすぐに広がる古都の雰囲気に気分が高まる。','2026-07-01','09:30','🚅','0','',0,1,true,'2026-07-01 09:35:15.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681100000,135.842700000,'奈良公園で鹿たちとふれあい','奈良公園の芝生エリアを散策。あちこちにいる鹿に鹿せんべいをあげたり、のんびりとした時間を楽しむ。','2026-07-01','10:15','🦌','0','',-200,2,true,'2026-07-01 10:20:10.5+09','2026-08-01 19:03:48.822924+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.321000000,136.351000000,'名湯・山代温泉の源泉かけ流しを満喫','夕食前に大浴場へ。歴史ある名湯にゆっくりと体を沈めると、一日の歩き疲れがじんわりとほぐれていく。肌触りの優しいお湯に大満足。','2026-08-05','18:30','♨️','0','',0,1,false,'2026-08-05 18:35:20+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'お部屋で加賀懐石の豪華な夕食','お部屋食で、北陸の旬の食材を使った懐石料理を堪能。カニや加賀野菜の煮物など、見た目も美しく上品な味付けに夫婦で感動しながら味わう。','2026-08-05','19:45','🦀','0','',0,1,false,'2026-08-05 19:50:15.3+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'心地よい布団で早めの就寝','美味しい食事と温泉ですっかりリラックス。夜は静かなお部屋で早めに床につき、ぐっすりと心地よい眠りにつく。','2026-08-05','21:30','🌙','0','',0,1,false,'2026-08-05 21:35:50.8+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.321000000,136.351000000,'朝風呂で清々しい一日の始まり','翌朝は早起きして再び温泉へ。朝日が差し込む大浴場で朝風呂を楽しみ、体の芯からすっきりと目覚める。','2026-08-06','07:00','☀️','0','',0,1,false,'2026-08-06 07:05:10.2+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'旅館の和朝食でしっかり栄養補給','焼き魚や温泉卵、手作りの豆腐など体に優しい和朝食をいただく。炊き立ての白ご飯が美味しくて、ついついおかわりしてしまう。','2026-08-06','08:15','🍚','0','',0,1,false,'2026-08-06 08:20:00+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320500000,136.352000000,'温泉街の総湯周辺を朝のお散歩','チェックアウト前に、山代温泉の総湯周辺をのんびりお散歩。昔ながらの共同浴場やレトロな街並みを眺めながら、のどかな雰囲気を満喫した。','2026-08-06','09:30','🚶‍♀️','0','',0,1,false,'2026-08-06 09:35:22.4+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578000000,136.648000000,'金沢駅に戻りお土産選び','送迎バスと特急を乗り継いで金沢駅へ戻ってきた。駅ナカの大きなお土産処で、加賀棒茶や金沢銘菓のきんつばを家族や自分用にじっくり選んで購入。','2026-08-06','11:30','🛍️','0','',-4500,1,false,'2026-08-06 11:35:11.1+09','2026-08-01 16:53:24.05998+09'),
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578000000,136.648000000,'駅構内のお店で名物のお寿司を軽く堪能','新幹線の発車時刻まで余裕があったので、駅ビル内で名物の回転寿司に立ち寄る。職人さんが握る北陸の白身魚が絶品で、旅の締めくくりにふさわしい味。','2026-08-06','13:00','🍣','0','',-2400,1,false,'2026-08-06 13:05:05.1+09','2026-08-01 16:53:24.05998+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.000000000,135.000000000,'最寄り駅に到着して無事に帰路へ','新幹線と在来線を乗り継いで、夕方に地元の最寄り駅へ到着。大きな怪我や体調不良もなく、温泉と美食に癒やされた大満足の1泊2日旅行となった。','2026-08-06','17:30','🚉','0','',0,1,false,'2026-08-06 17:35:00+09','2026-08-01 16:53:24.05998+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.276389000,133.142222000,'瀬戸田でレモンケーキを買う','瀬戸田の商店街は小さくて温かい雰囲気。名物のレモンケーキを買って小休憩。','2026-08-04','12:20','🙂','0000','',-600,1,false,'2026-08-04 12:20:00+09','2026-08-02 07:30:32.144728+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.245556000,133.132222000,'耕三寺を見学','赤い建物が印象的で、島にこんな場所があるのかと驚く。静かで落ち着いた時間を過ごせた。','2026-08-04','13:00','🙂','0000','',-1200,1,false,'2026-08-04 13:00:00+09','2026-08-02 07:30:32.144728+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.686940000,'姫路の活気あふれる商店街「おみやげ歩行者天国」で特産品探し','夕暮れ時の街に戻り、地元の人や観光客で賑わうアーケード商店街をぶらりとお散歩。姫路名物の穴子寿司や、地元で愛される播磨の銘菓、可愛らしい姫路城グッズなど、旅の思い出を彩る素敵なお土産をじっくりと吟味して買い揃える。','2026-10-11','16:00','🛍️','0','',-4500,1,false,'2026-10-11 16:45:00+09','2026-08-02 01:09:13.862814+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.544440000,134.223610000,'「鳥取砂丘リフト」に揺られて、空中散歩を楽しみながら砂丘を一望','砂丘の景色を違った角度から楽しむため、観光リフトに乗ってのんびり空中散歩。足元に広がる雄大な砂丘の風景と日本海の潮風を心地よく感じながら、ゆったりと揺られるリラックスした時間に家族みんなでほっこりとした笑顔になる。','2027-05-15','15:00','🚡','0','',-400,1,false,'2027-05-15 15:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.004000000,135.768100000,'烏丸御池のおしゃれ文房具店','最初の目的地は、洗練されたセレクト雑貨や文房具が集まるお店。お互いに可愛いマスキングテープやレターセットを見つけて、さっそくお揃いでお買い上げ。','2026-08-03','10:45','✨','0','',-1400,1,false,'2026-08-03 10:48:40.5+09','2026-08-01 09:37:37.584085+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720092033,135.383448601,'三段壁の洞窟探検でスリルを味わう','地下深くへエレベーターで降りて、波が打ち寄せる洞窟内部を見学。自然の迫力を間近で体感して子どもたちも大興奮。','2026-09-13','09:30','🌊','0','',-3000,1,true,'2026-09-13 10:00:00+09','2026-08-01 21:05:34.850528+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.032100000,135.195000000,'紀州梅の里でたくさんの梅干しをお土産に購入','ドライブの帰りがてら、道の駅でバラエティ豊かな紀州南高梅の梅干しや梅ジュースを試食してお気に入りを発見。たくさん買い込んだ。','2026-09-13','13:30','🛍️','0','',-5000,1,true,'2026-09-13 14:00:00+09','2026-08-01 21:05:34.850528+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226000000,135.167500000,'無事に自宅へ到着、思い出話に花が咲く','渋滞も大きなトラブルもなく無事に帰宅。車から荷物を下ろしながら、今回の楽しかった思い出を振り返る温かい締めくくりに。','2026-09-13','17:00','🏠','0','',0,1,true,'2026-09-13 17:30:00+09','2026-08-01 21:05:34.850528+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.180000000,135.230000000,'紀ノ川SAで旅の最後の夕日を眺める','高速道路に乗る前の最後のSA。夕暮れに染まる紀ノ川の景色を眺めながら、今回の楽しいドライブ旅行の思い出を家族で語り合った。','2026-09-13','17:30','🌆','0','',-1200,1,false,'2026-09-13 18:00:00+09','2026-08-01 21:08:04.82446+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.250000000,135.300000000,'阪和道の上りPAで最後のトイレ休憩','帰路の途中、夜の高速道路を安全運転しながら最後のパーキングエリアでリフレッシュ。','2026-09-13','19:00','🚗','0','',-500,1,false,'2026-09-13 19:20:00+09','2026-08-01 21:08:04.82446+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350000000,135.400000000,'大阪府境手前の最後のルート確認ポイント','和歌山エリアでの充実したドライブ旅を終え、いよいよ県境を越えて北上する最後のスポット。','2026-09-13','19:45','✨','0','',0,1,false,'2026-09-13 20:00:00+09','2026-08-01 21:08:04.82446+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226200000,135.167000000,'和歌山城へ移動','車で城へ。天守閣が見えてきて家族みんなテンションアップ。','2026-08-15','14:10','🙂','0000','',0,1,true,'2026-08-15 14:12:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226200000,135.167000000,'和歌山城天守閣','天守閣からの景色に家族全員感動。写真を撮りまくる。410円。','2026-08-15','14:40','🤩','0000','',-410,1,true,'2026-08-15 14:42:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.230100000,135.165000000,'公園でアイス休憩','暑さで少しバテたけどアイスで復活。家族で笑いながらひと休み。350円。','2026-08-15','15:20','🙂','0000','',-350,1,true,'2026-08-15 15:22:00+09','2026-08-01 21:33:47.291888+09'),
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705000000,135.498000000,'中崎町のレトロな雑貨屋巡り','梅田のすぐ近くとは思えない、落ち着いた古民家が並ぶ中崎町へ。おしゃれな雑貨屋さんやギャラリーをのんびり覗き歩く。時間に追われない、こういうマイペースな散策が一番落ち着く。','2026-08-02','14:00','✨','0','',-500,1,false,'2026-08-02 14:03:50.22+09','2026-08-01 09:28:00.797366+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702400000,135.495900000,'大阪駅に戻り、最高の仲間と解散','再び大阪駅に戻り、名残惜しさを抱えながらそれぞれの最寄りへ。「また絶対に集まろう！」と固い握手を交わし、最高の卒業旅行が幕を閉じた。','2026-03-02','17:00','👋','0','',0,1,false,'2026-03-02 17:05:00+09','2026-08-01 16:58:34.539546+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.684000000,135.834000000,'老舗和菓子店で甘味休憩','ならまちの散策途中に見つけた老舗の和菓子店へ。できたての和菓子とお抹茶をいただきながら、旅の思い出を振り返る。','2026-07-02','15:45','🍵','0','',-800,14,true,'2026-07-02 15:50:22.4+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686000000,135.830000000,'近鉄奈良駅ビルでお土産選び','駅に戻り、奈良のお土産売り場で柿の葉寿司や大仏プリン、鹿モチーフの可愛いお菓子などをたくさん買い込む。','2026-07-02','17:00','🛍️','0','',-3000,15,true,'2026-07-02 17:05:11.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681100000,135.842700000,'奈良公園で鹿たちとふれあい','奈良公園の芝生エリアを散策。あちこちにいる鹿に鹿せんべいをあげたり、のんびりとした時間を楽しむ。','2026-07-01','12:00','🦌','0','',-200,3,true,'2026-07-01 12:05:10.5+09','2026-08-01 19:03:48.822924+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680000000,135.838000000,'老舗の茶屋で名物ランチ休憩','奈良公園近くの落ち着いた和風茶屋で、名物の柿の葉寿司とそうめんのセットを味わう。伝統の優しい味わいにホッとする。','2026-07-01','13:30','🍱','0','',-1500,4,true,'2026-07-01 13:35:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.683300000,135.847200000,'春日大社の神秘的な境内を散策','世界遺産・春日大社へ。約3000基の釣燈籠が並ぶ回廊や、深い緑に包まれた神聖な雰囲気に包まれながら参道を進む。','2026-07-01','15:00','🌲','0','',-500,5,true,'2026-07-01 15:05:12.3+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.678000000,135.830000000,'町家カフェで絶品かき氷を堪能','奈良の古い町並みが残るエリアでおしゃれな町家カフェを発見。火照った体を冷やすために、こだわりフルーツのかき氷を食べる。','2026-07-01','16:30','🍧','0','',-1100,6,true,'2026-07-01 16:35:40.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.675000000,135.820000000,'若草山の夕景を眺めるドライブ','夕暮れ時に若草山周辺の高台へ。奈良盆地に沈んでいく美しい夕日を眺めながら、穏やかな時間に浸る。','2026-07-01','17:40','🌅','0','',0,7,true,'2026-07-01 17:45:10+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680000000,135.825000000,'奈良市内の和風ホテルへチェックイン','古都の景観に溶け込む落ち着いた和風ホテルに到着。部屋で少し荷物を整理して、夜の街へ繰り出す準備をする。','2026-07-01','18:30','🏨','0','',-14000,8,true,'2026-07-01 18:35:20+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.679000000,135.828000000,'奈良の郷土料理と地酒で夕食','夕食は地元の食材をふんだんに使った郷土料理と、奈良の地酒をゆっくり堪能。静かな夜の奈良をしみじみ味わう。','2026-07-01','19:30','🍶','0','',-4500,9,true,'2026-07-01 19:35:15.3+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680300000,135.788100000,'法隆寺で世界最古の木造建築群を見学','翌朝は少し足を延ばして斑鳩町の法隆寺へ。飛鳥時代の息吹を感じさせる五重塔や金堂の建築美をじっくり見学する。','2026-07-02','09:30','🏛️','0','',-1500,10,true,'2026-07-02 09:35:50.8+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.629500000,135.717500000,'日本最古の神社・大神神社を参拝','三輪山の麓にある日本最古の神社「大神神社」へ。厳かな空気が漂う境内で、神聖なパワーを感じる。','2026-07-02','11:15','⛩️','0','',0,11,true,'2026-07-02 11:20:10.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.630000000,135.718000000,'三輪そうめんの老舗で名物ランチ','大神神社の近くで、本場の「三輪そうめん」をいただく。冷たくてコシのある喉ごし抜群のそうめんに大満足。','2026-07-02','12:30','🍜','0','',-1100,12,true,'2026-07-02 12:35:00+09','2026-08-01 19:03:48.822924+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578100000,136.648000000,'金沢駅の鼓門前で卒業旅行スタート！','大学の仲良しグループ4人で金沢駅に集合！シンボルの「鼓門」を背景に、これから始まる北陸・金沢の卒業旅行へ出発の記念撮影。','2026-03-01','09:30','🎒','0','',0,1,false,'2026-03-01 09:35:15.1+09','2026-08-01 17:02:02.62512+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.562300000,136.662500000,'日本三名園・兼六園をゆったり散策','バスで移動して兼六園へ。雪吊りが残る美しい庭園の景色を眺めながら、池の周りをのんびりお散歩。歴史ある雰囲気に感動。','2026-03-01','10:30','🌳','0','',-320,1,false,'2026-03-01 10:35:20.2+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.564500000,136.661000000,'金沢城公園の広大な敷地を探検','兼六園から橋を渡ってすぐの金沢城公園へ。白亜の美しい石川門や復元された長屋を見上げながら、殿様気分で城内を歩き回る。','2026-03-01','12:00','🏯','0','',0,1,false,'2026-03-01 12:05:10.5+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.561500000,136.657500000,'近江町市場で海の幸ドカ盛り海鮮丼ランチ','金沢の台所「近江町市場」へ移動。新鮮な甘エビやカニ、ウニがこれでもかと乗った贅沢な海鮮丼をみんなで頬張る。美味しさに言葉を失う！','2026-03-01','13:30','丼','0','',-2800,1,false,'2026-03-01 13:50:00+09','2026-08-01 17:02:02.62512+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685000000,135.835000000,'奈良町（ならまち）のレトロな街並みを散策','再び市内へ戻り、江戸時代の町家が残る「ならまち」へ。おしゃれな雑貨店やギャラリーを覗きながらのんびり歩く。','2026-07-02','14:30','🏡','0','',0,13,true,'2026-07-02 14:35:00+09','2026-08-01 19:03:48.822924+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.770900000,'温泉街で昼食','鯛めしをいただく。ふわっとした食感がたまらなくて幸せな気分になる。','2026-08-12','12:00','🍚','0000','',-1400,1,false,'2026-08-12 12:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.841640000,132.765300000,'松山駅で休憩','駅ナカでアイスコーヒー。四国旅の写真を見返しながら余韻に浸る。','2026-08-12','13:00','☕','0000','',-520,1,false,'2026-08-12 13:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342566000,134.046549000,'高松駅で旅の締め','四国を巡った充実の旅。駅ナカでゆっくりしながら','','','','','',0,0,true,'2026-08-02 02:06:09.889713+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720400000,135.375000000,'市場でちょっと疲れた😵','人が多くて少しバテる。休憩スペースで座り込む家族。0円。','2026-08-20','15:30','😵','1','',0,-1,true,'2026-08-20 15:32:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957900000,130.941200000,'海沿いを散歩','市場を出て海沿いを歩くと、風が気持ちよくて「ちょっと落ち着くな」と全員が深呼吸。関門海峡を行き交う船を眺めながら、食べすぎたお腹を休める時間に。海の青さが広がっていて、旅の中のゆるい休憩タイムが心地よかった。','2026-11-03','12:20','🌊','0000','',0,1,true,'2026-11-03 12:20:00+09','2026-08-02 02:38:00.798541+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702400000,135.495900000,'大阪駅に集合！卒業旅行の幕開け','大学の仲良しグループ4人で大阪駅に集合！これから始まるワイワイ賑やかな卒業旅行に、朝からテンションが最高潮に盛り上がる。','2026-03-01','09:30','🎒','0','',0,1,false,'2026-03-01 09:35:15.1+09','2026-08-01 16:58:34.539546+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.693700000,135.502200000,'梅田のランドマークで空中散歩','梅田スカイビルへ移動し、空中庭園展望台から大阪の街並みを一望。ガラス張りのエスカレーターで「高い！」と大はしゃぎしながら記念撮影。','2026-03-01','10:30','🏙️','0','',-2000,1,false,'2026-03-01 10:35:20.2+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.693000000,135.500000000,'老舗の地下街で大阪名物ランチ','梅田の地下街にある有名店へ行き、熱々の「大阪名物ミックスお好み焼き」をシェアして食べる。ソースの香ばしい匂いに食欲が止まらない。','2026-03-01','12:00','😋','0','',-1500,1,false,'2026-03-01 12:05:10.5+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668700000,135.501300000,'難波・道頓堀のグリコサイン前へ','電車で一気にミナミへ移動。道頓堀のグリコサインの前でお決まりのポーズをして写真をパシャリ。観光客の多さと活気に圧倒される！','2026-03-01','13:45','📸','0','',0,1,false,'2026-03-01 13:50:00+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.665500000,135.502000000,'アメリカ村でおしゃれ古着めぐり','アメ村へ歩いて移動し、個性的な古着屋さんや雑貨屋さんをハシゴ。お互いに似合いそうな服を選びっこして、それぞれお気に入りのアイテムをゲット。','2026-03-01','15:00','🛍️','0','',-5800,1,false,'2026-03-01 15:05:12.3+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.652500000,135.506300000,'新世界・通天閣周辺で串カツ体験','さらに南へ下り、新世界エリアへ。レトロな街並みの中、ド派手な看板が並ぶお店で「二度づけ禁止」の絶品串カツをたらふく食べる！','2026-03-01','17:00','🍢','0','',-2800,1,false,'2026-03-01 17:05:40.1+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.650000000,135.505000000,'ハプニング！急な雨でダッシュ','新世界を出たところで急に雨がパラパラと降ってきて、近くのコンビニまでみんなで大笑いしながら走って避難。これもいい思い出。','2026-03-01','18:30','☔','0','',-300,-1,false,'2026-03-01 18:35:20+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668700000,135.501300000,'雨が上がり、なんばの夜景とカフェへ','雨が上がってネオンが反射する夜の道頓堀を眺めつつ、おしゃれなリバーサイドカフェに入ってまったり。大学生活の思い出話に花が咲く。','2026-03-01','19:30','☕','0','',-1100,1,false,'2026-03-01 19:35:15.3+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.698000000,135.500000000,'梅田のネオン街で二次会カラオケ','再び梅田に戻り、駅前のカラオケ店でオールナイトの二次会へ突入！懐かしい曲や定番の卒業ソングを大声で歌って盛り上がる。','2026-03-01','21:30','🎤','0','',-2500,1,false,'2026-03-01 21:35:50.8+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.816000000,135.470000000,'早朝の箕面大滝でマイナスイオンを浴びる','少し足を伸ばして北摂の箕面へ。早朝の箕面大滝までひんやりとした空気を吸いながらハイキング。夜通し遊んだ体に清々しい空気が染みる。','2026-03-02','07:30','🌲','0','',0,1,false,'2026-03-02 07:35:10.2+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.818000000,135.472000000,'名物の「もみじの天ぷら」を食べ歩き','滝道の名物である「もみじの天ぷら」を買い食い。カリッとした食感とほんのり甘い味わいに「意外と美味い！」とみんなで感動する。','2026-03-02','09:00','🍁','0','',-500,1,false,'2026-03-02 09:05:00+09','2026-08-01 16:58:34.539546+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.825000000,135.465000000,'箕面温泉スパーガーデンで朝風呂','そのまま近くの温泉施設へ直行し、絶景露天風呂で一晩の疲れを完全にリセット。大きなお風呂に浸かりながら、社会人への不安を語り合う。','2026-03-02','10:30','♨️','0','',-1800,1,false,'2026-03-02 10:35:22.4+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.785000000,135.438000000,'万博記念公園の太陽の塔を見上げる','モノレールを乗り継いで万博記念公園へ。ド迫力の「太陽の塔」を見上げて、その圧倒的な存在感にみんなで大興奮する。','2026-03-02','13:00','☀️','0','',-720,1,false,'2026-03-02 13:05:11.1+09','2026-08-01 16:58:34.539546+09'),
	 (20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.787000000,135.445000000,'大型ショッピングモールで遅めのランチ','公園に隣接する巨大なモールへ移動し、フードコートで各自好きなものをチョイスして遅めのお昼ご飯。旅の終わりの寂しさが少しずつ漂い始める。','2026-03-02','14:45','🍔','0','',-1200,1,false,'2026-03-02 14:50:05.1+09','2026-08-01 16:58:34.539546+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.560800000,136.655800000,'金沢21世紀美術館で現代アート体験','話題の「スイミング・プール」をはじめ、ユニークな現代アートの展示を体験。水面を下から覗き込んだり、不思議な空間で大はしゃぎ。','2026-03-01','15:00','🎨','0','',-1200,1,false,'2026-03-01 15:05:12.3+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.570000000,136.671500000,'ひがし茶屋街のレトロな町並みと金箔ソフト','伝統的な出格子が続く情緒あふれるひがし茶屋街へ。ピカピカの「金箔ソフトクリーム」をみんなで買って食べ歩き。写真映えもバッチリ！','2026-03-01','16:45','🍦','0','',-900,1,false,'2026-03-01 17:05:40.1+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.571000000,136.672000000,'急な日本海の雨に降られてカフェに駆け込む','夕暮れ時に雨がパラついてきて、町家を改装したおしゃれな隠れ家カフェへ避難。温かい加賀棒茶を飲みながら外の雨を眺めてまったり。','2026-03-01','18:15','☕','0','',-800,-1,false,'2026-03-01 18:35:20+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.579000000,136.650000000,'駅ナカで金沢おでんと地酒の夕食','金沢駅に戻り、地元で大人気の「金沢おでん」の店へ。車麩やカニ面といったご当地おでんに舌鼓を打ちつつ、北陸の地酒で乾杯！','2026-03-01','20:00','🍢','0','',-3500,1,false,'2026-03-01 19:35:15.3+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.581000000,136.652000000,'ホテルでの夜更かしトーク','駅前のホテルにチェックイン。ベッドに転がりながら、これまでの大学生活の思い出や将来の夢について夜遅くまで語り合う。','2026-03-01','22:00','🌙','0','',-7000,1,false,'2026-03-01 21:35:50.8+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559000000,136.649000000,'長町武家屋敷跡の土塀小路を朝散歩','朝食を済ませ、土塀と石畳が続く長町武家屋敷跡を散策。静寂に包まれた朝の落ち着いた街並みが、昨晩の賑やかさとは違った良さを醸し出す。','2026-03-02','08:30','📷','0','',0,1,false,'2026-03-02 07:35:10.2+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.557000000,136.648000000,'老舗工房で金沢箔貼り体験','伝統工芸の街ならではの体験として、小さなお皿への「金箔貼り」に挑戦。慎重に金箔をピンセットで扱いながら、世界に一つの記念品を手作り。','2026-03-02','10:00','✨','0','',-2200,1,false,'2026-03-02 09:05:00+09','2026-08-01 17:02:02.62512+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.545000000,136.658000000,'にし茶屋街でほっこり和スイーツ休憩','少し足を伸ばして「にし茶屋街」へ。趣のある通りにある人気甘味処で、もっちりした特製わらび餅を食べてひと息つく。','2026-03-02','11:45','🍡','0','',-950,1,false,'2026-03-02 10:35:22.4+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.563000000,136.650000000,'香林坊でお土産ショッピング','金沢の中心街・香林坊エリアの商業施設に戻り、加賀棒茶やきんつばなどの定番お土産をみんなで吟味して大量買い！','2026-03-02','13:30','🛍️','0','',-4000,1,false,'2026-03-02 13:05:11.1+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.580000000,136.651000000,'金沢駅の百番街で最後のシメランチ','金沢駅の商業施設「金沢百番街」に入り、ご当地の能登牛を使った贅沢なローストビーフ丼を旅の最後のランチとして味わう。','2026-03-02','15:00','🥩','0','',-2400,1,false,'2026-03-02 14:50:05.1+09','2026-08-01 17:02:02.62512+09'),
	 (21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578100000,136.648000000,'金沢駅に戻り、それぞれの道へ解散','再び金沢駅の鼓門前に戻り、「絶対にまた旅行しよう！」と固い握手を交わしてそれぞれの帰路へ。最高の北陸・金沢の思い出が完成。','2026-03-02','16:30','👋','0','',0,1,false,'2026-03-02 17:05:00+09','2026-08-01 17:02:02.62512+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720400000,135.375000000,'とれとれ市場で買い物🎁','お土産選びが楽しすぎて時間が溶ける。家族であれこれ悩む。1600円。','2026-08-20','15:00','🎁','1','',-1600,1,true,'2026-08-20 15:02:00+09','2026-08-01 20:07:48.570937+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838330000,134.693330000,'ホテルの最上階ラウンジで、旅を振り返る穏やかなナイトキャップ','一日の締めくくりに、ホテルの落ち着いたラウンジスペースへ。今日巡った世界遺産や古刹の風景、美味しい料理の思い出を静かに振り返りながら、温かいハーブティーを片手に、旅の余韻に浸る穏やかな夜の時間がゆっくりと流れていく。','2026-10-11','21:00','☕','0','',-1200,1,false,'2026-10-11 21:45:00+09','2026-08-02 01:09:13.862814+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.786940000,134.835830000,'翌日、少し足を延ばして訪れた瀬戸内海に面する美しい海岸線をドライブ','旅行2日目はレンタカーを借りて、穏やかな瀬戸内海の海岸線へとドライブに出かける。キラキラと太陽の光を反射して輝く青い海と、点在する島々の美しい景色を眺めながら、心地よい海風を感じる最高のドライブコースを満喫する。','2026-10-12','10:00','🚗','0','',-3000,1,false,'2026-10-12 11:30:00+09','2026-08-02 01:09:13.862814+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.693890000,'「JR姫路駅」に戻り、たくさんの思い出と感動を胸に帰路につく','すべての行程を大満足で終えて再びJR姫路駅へ戻る。駅ナカのショップで買い忘れたお土産を買い足し、新幹線のホームへと向かう。「歴史とグルメを満喫できた最高の旅だったね」と笑顔で語り合いながら、たくさんの思い出を胸に帰路の途につく。','2026-10-12','15:00','👋','0','',0,1,false,'2026-10-12 15:30:00+09','2026-08-02 01:09:13.862814+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.452780000,135.391670000,'歴史とロマンが息づく重厚な建物群「舞鶴赤れんがパーク」の散策','明治から大正期にかけて建設されたレンガ倉庫群がそのまま残る「舞鶴赤れんがパーク」へ。レトロで重厚な赤れんがの建物が織りなす独特の美しい景観の中をのんびりと歩き、当時の旧海軍の歴史やロマンあふれる雰囲気を肌でしみじみと感じ取る。','2027-04-10','10:30','🧱','0','',-300,1,false,'2027-04-10 11:15:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.453330000,135.392220000,'2軒目：赤れんが棟の中にあるおしゃれなカフェで、特製珈琲とスイーツのひととき','赤れんがパーク内にある風情あるカフェに立ち寄り、歩き疲れた体を少し休める。レトロな内装が落ち着く空間の中で、香ばしいこだわり珈琲と甘い特製チーズケーキをいただきながら、窓の外に広がる穏やかな港町の景色を眺めて優雅な休憩時間を過ごす。','2027-04-10','11:30','🤩','0','',-850,1,false,'2027-04-10 12:15:00+09','2026-08-02 01:20:50.513158+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.451390000,135.395560000,'「舞鶴港遊覧船」に乗り込み、間近で見る自衛隊の護衛艦とリアス式海岸の迫力','舞鶴港から出航する遊覧船の甲板に乗り込み、海からの観光クルーズへ出発。目の前に次々と現れる迫力満点の海上自衛隊の巨大な護衛艦の姿や、若狭湾特有の美しいリアス式海岸の景色を間近で眺め、大迫力の海の冒険に大興奮。','2027-04-10','13:00','🛥️','0','',-1800,1,false,'2027-04-10 13:45:00+09','2026-08-02 01:20:50.513158+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.652500000,135.506300000,'新世界・通天閣周辺','新幹線と電車を乗り継いで、ようやく大阪に到着！通天閣の下はすごい活気で、一気に大阪らしい雰囲気にテンションが上がる。まずは名物の串カツの匂いに誘われて、お腹の虫が鳴り始める。','2026-08-01','12:30','🤩','0','',-1200,1,true,'2026-08-01 12:32:15.12+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.654700000,135.505200000,'元祖串かつでソース二度漬け禁止を体験','サクサクの衣と特製ソースが絶品！二度漬け禁止のルールを守りつつ、ビールと串カツの最高の組み合わせを満喫した。','2026-08-01','13:15','🍻','0','',-2400,1,true,'2026-08-01 13:20:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.662000000,135.502000000,'日本橋の家電・カルチャー街を散策','オタロードや電子パーツ店が並ぶエリアをぶらり。夏の暑さで少しバテつつも、ディープな雰囲気を楽しむ。','2026-08-01','14:45','🥵','1','',-850,0,true,'2026-08-01 15:00:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668700000,135.501300000,'道頓堀・グリコサイン前で記念撮影','観光客の熱気がすごい！ネオンが光り始める前の夕暮れ時、道頓堀川沿いを歩きながら名物の看板を見て回る。','2026-08-01','17:30','📸','0','',0,1,true,'2026-08-01 17:45:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.669500000,135.502200000,'道頓堀の老舗でアツアツのたこ焼きを実食','外はカリッと、中はトロトロの絶品たこ焼き。一口食べた瞬間に熱すぎて口の中をやけどしたが、それでも美味い！','2026-08-01','18:15','🐙','0','',-700,1,true,'2026-08-01 18:30:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702500000,135.495900000,'梅田スカイビル・空中庭園展望台','大阪の夜景を一望するためにビルへ。しかし、エレベーターとエスカレーターの混雑が激しく、少し疲弊してしまった。','2026-08-01','20:00','🌀','0','',-2000,-1,true,'2026-08-01 20:30:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680300000,135.788100000,'法隆寺で世界最古の木造建築群を見学','西へ移動し斑鳩町の法隆寺へ。飛鳥時代の息吹を感じさせる五重塔や金堂の建築美をじっくり見学する。','2026-07-02','11:45','🏛️','0','',-1500,13,true,'2026-07-02 11:50:50.8+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.629500000,135.717500000,'日本最古の神社・大神神社を参拝','さらに南へ移動し、三輪山の麓にある日本最古の神社「大神神社」へ。厳かな空気が漂う境内で神聖なパワーを感じる。','2026-07-02','13:30','⛩️','0','',0,14,true,'2026-07-02 13:35:10.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.630000000,135.718000000,'三輪そうめんの老舗で名物ランチ','大神神社の近くで、本場の「三輪そうめん」をいただく。冷たくてコシのある喉ごし抜群のそうめんに大満足。','2026-07-02','14:45','🍜','0','',-1100,15,true,'2026-07-02 14:50:00+09','2026-08-01 19:03:48.822924+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.715000000,135.363000000,'千畳敷へ移動🪨','岩の広がりに家族全員びっくり。風が強くて帽子が飛びそう。','2026-08-20','13:30','🪨','1','',0,0,true,'2026-08-20 13:32:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.180000000,135.230000000,'紀ノ川SAで旅の最後の夕日を眺める','高速道路に乗る前の最後のSA。夕暮れに染まる紀ノ川の景色を眺めながら、今回の楽しいドライブ旅行の思い出を家族で語り合った。','2026-09-13','17:30','🌆','0','',-1200,1,true,'2026-09-13 18:00:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.250000000,135.300000000,'阪和道の上りPAで最後のトイレ休憩','帰路の途中、夜の高速道路を安全運転しながら最後のパーキングエリアでリフレッシュ。','2026-09-13','19:00','🚗','0','',-500,1,true,'2026-09-13 19:20:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350000000,135.400000000,'大阪府境手前の最後のルート確認ポイント','和歌山エリアでの充実したドライブ旅を終え、いよいよ県境を越えて北上する最後のスポット。','2026-09-13','19:45','✨','0','',0,1,true,'2026-09-13 20:00:00+09','2026-08-01 21:16:24.073386+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.693890000,'「JR姫路駅」に到着、目の前にそびえる白亜の姫路城に胸を高鳴らせる朝','歴史と現代が美しく調和するJR姫路駅に降り立ち、一直線に伸びる大手前通りの向こう側に堂々とそびえ立つ白亜の世界遺産・姫路城の姿を望む。青空の下で圧倒的な存在感を放つ「白鷺城」との出会いに、これからの歴史探訪の旅への期待感が一気に高まる。','2026-10-10','09:00','🚅','0','',0,1,false,'2026-10-10 09:30:00+09','2026-08-02 01:09:13.862814+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838890000,134.692500000,'1軒目：駅前のおしゃれなカフェで味わう、姫路モーニングと名物のアーモンドトースト','姫路ならではの食文化を楽しむため、駅前の老舗カフェへ朝のひとときに立ち寄る。香ばしいアーモンドの香りと濃厚なバターのコクが絶妙にマッチした名物の「アーモンドトースト」を一口頬張り、香り高いブレンドコーヒーとともに優雅で贅沢な朝の時間を過ごす。','2026-10-10','09:30','🍞','0','',-850,1,false,'2026-10-10 10:00:00+09','2026-08-02 01:09:13.862814+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.501390000,135.372500000,'「五老ヶ岳公園」の山頂へ、緑豊かなドライブウェイを抜けて爽快にアクセス','車窓から緑豊かな山の風景を楽しみながら、舞鶴湾を一望できる「五老ヶ岳公園」の山頂へと車を走らせる。心地よい山の空気を吸い込みながら、美しい自然に包まれたワインディングロードのドライブを爽やかに満喫する。','2027-04-10','14:30','🚗','0','',0,1,false,'2027-04-10 15:15:00+09','2026-08-02 01:20:50.513158+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.083300000,138.433300000,'両津港に到着！佐渡島観光の幕開け','ジェットフォイルで両津港に到着！潮風を感じながら、これから始まる佐渡島一周の大冒険にワクワクが止まらない。','2026-06-01','09:30','🚢','0','',0,1,false,'2026-06-01 09:35:15.1+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.026400000,138.254200000,'佐渡金山で歴史のロマンを体感','世界文化遺産に登録された「佐渡金山」へ移動。江戸時代の採掘跡（道遊の割戸など）を見学し、当時のスケールの大きさに圧倒される。','2026-06-01','11:00','⛏️','0','',-900,1,false,'2026-06-01 11:05:20.2+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.031000000,138.245000000,'相川の町並みで名物グルメランチ','相川エリアのレトロな街並みの中にある食堂で、佐渡の海の幸を使った「ブリカツ丼」をガッツリ食べる。サクサクで美味しい！','2026-06-01','12:30','🍽️','0','',-1400,1,false,'2026-06-01 12:35:10.5+09','2026-08-01 17:06:31.041046+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702500000,135.495000000,'大阪駅（帰路へ）','楽しかった1泊2日のひとり旅もあっという間に終わり。お土産の豚まんをしっかりリュックに詰め込んで、新大阪へ向かう電車のホームで少し寂しさを感じつつ帰路につく。','2026-08-02','17:00','🥺','0','',-1500,0,false,'2026-08-02 17:04:10.88+09','2026-08-01 09:28:00.797366+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.016700000,138.233300000,'北沢浮遊選鉱場で幻想的な近代遺跡を見学','まるで「ラピュタ」のようだと言われる北沢浮遊選鉱場跡へ。巨大なコンクリートの廃墟が緑に覆われた神秘的な光景にカメラが止まらない。','2026-06-01','14:00','📸','0','',0,1,false,'2026-06-01 14:05:00+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.216700000,138.450000000,'佐渡の最北端・大野亀の絶景へ','車で一気に北上し、ミシュラン・グリーンガイドで2つ星を獲得した「大野亀」へ。巨大な一枚岩と日本海のダイナミックな青さに息をのむ。','2026-06-01','16:00','🌊','0','',0,1,false,'2026-06-01 16:05:12.3+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.150000000,138.400000000,'突然のにわか雨！海岸沿いのカフェへ避難','北東部の海岸線をドライブ中に雨がパラついてきて、おしゃれな海沿いのカフェに駆け込む。雨の日本海を眺めながら温かいコーヒーでひと息。','2026-06-01','17:30','☕','0','',-600,-1,false,'2026-06-01 17:35:40.1+09','2026-08-01 17:06:31.041046+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685300000,135.843000000,'東大寺の大仏様に圧倒される','世界最大級の木造建築である大仏殿へ。堂内に鎮座する高さ約15メートルの奈良の大仏の圧倒的なスケールに息をのむ。','2026-07-01','11:30','⛩️','0','',-600,3,true,'2026-07-01 11:35:20.2+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680000000,135.838000000,'老舗の茶屋で名物ランチ休憩','奈良公園近くの落ち着いた和風茶屋で、名物の柿の葉寿司とそうめんのセットを味わう。伝統の優しい味わいにホッとする。','2026-07-01','13:00','🍱','0','',-1500,4,true,'2026-07-01 13:05:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.683300000,135.847200000,'春日大社の神秘的な境内を散策','世界遺産・春日大社へ。約3000基の釣燈籠が並ぶ回廊や、深い緑に包まれた神聖な雰囲気に包まれながら参道を進む。','2026-07-01','14:30','🌲','0','',-500,5,true,'2026-07-01 14:35:12.3+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685000000,135.835000000,'奈良町（ならまち）のレトロな街並みを散策','再び市内へ戻り、江戸時代の町家が残る「ならまち」へ。おしゃれな雑貨店やギャラリーを覗きながらのんびり歩く。','2026-07-01','16:00','🏡','0','',0,6,true,'2026-07-01 16:05:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.684000000,135.834000000,'老舗和菓子店で甘味休憩','ならまちの散策途中に見つけた老舗の和菓子店へ。できたての和菓子とお抹茶をいただきながら、旅の思い出を振り返る。','2026-07-01','17:00','🍵','0','',-800,7,true,'2026-07-01 17:05:22.4+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.678000000,135.830000000,'町家カフェで絶品かき氷を堪能','奈良の古い町並みが残るエリアでおしゃれな町家カフェを発見。火照った体を冷やすために、こだわりフルーツのかき氷を食べる。','2026-07-01','18:00','🍧','0','',-1100,8,true,'2026-07-01 18:05:40.1+09','2026-08-01 19:03:48.822924+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.677500000,135.356000000,'白良浜で砂遊び⛱','真っ白な砂に感動。靴が濡れてちょっと悲しいけど楽しい。','2026-08-20','10:20','⛱','1','',0,-1,true,'2026-08-20 10:22:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.677000000,135.356500000,'海辺カフェで休憩🍹','海を眺めながらジュース。家族で「ここ最高」と盛り上がる。450円。','2026-08-20','11:00','🍹','1','',-450,1,true,'2026-08-20 11:02:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.674000000,135.354000000,'円月島へドライブ📸','海沿いの道が気持ちよすぎて窓全開。写真スポットで撮影大会。','2026-08-20','11:40','📸','1','',0,1,true,'2026-08-20 11:42:00+09','2026-08-01 20:07:48.570937+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.070000000,138.360000000,'真野湾の夕日を眺めながら温泉宿へチェックイン','島の中央部へ戻り、真野湾に沈む美しい夕日を車窓から眺めながら温泉旅館に到着。旅の疲れを癒やす極上の温泉へ。','2026-06-01','19:00','🌅','0','',-12000,1,false,'2026-06-01 19:35:20+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.070000000,138.360000000,'新鮮な海の幸と佐渡の地酒で宴会','夕食は大皿に盛られた佐渡の旬の魚介と、キリッとした佐渡の地酒を堪能。楽しかった一日の思い出話で夜遅くまで盛り上がる。','2026-06-01','20:30','🍶','0','',0,1,false,'2026-06-01 20:35:15.3+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.950000000,138.350000000,'佐渡西三川ゴールドパークで砂金採り体験','今度は自分で金を見つけるため「西三川ゴールドパーク」へ。川の水の中で砂金をすくい、キラリと光る金が見つかると大歓声があがる。','2026-06-02','12:30','✨','0','',-900,1,false,'2026-06-02 12:05:00+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.010000000,138.420000000,'トキの森公園で本物のトキを見学','国の特別天然記念物「トキ」を保護・飼育しているトキの森公園へ。間近で観察できる朱鷺資料館で、優雅な姿のトキに魅了される。','2026-06-02','15:30','🐦','0','',-400,1,false,'2026-06-02 15:35:11.1+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.083300000,138.433300000,'両津港からフェリーに乗り、佐渡島をあとに','思い出いっぱいの荷物を抱えてフェリーに乗船。甲板から遠ざかる佐渡島を眺めながら、充実感に浸りつつ帰路につく。','2026-06-02','18:00','👋','0','',0,1,false,'2026-06-02 18:05:00+09','2026-08-01 17:06:31.041046+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.065358564,138.427133560,'両津港のお土産市場で特産品を爆買い','両津港に戻り、ターミナルのお土産売り場で佐渡のお米や「おけさ柿」のお菓子、日本酒などを大量に買い込む。','2026-06-02','17:00','🛍️','0','',-3500,1,false,'2026-06-02 17:05:05.1+09','2026-08-01 17:08:38.108506+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'駅ナカで最後の乾杯をして特急で帰路へ','電車の発車時刻までの間、駅ビルのお店に入って冷えたビールで「富士山登頂お疲れ様！」の乾杯をしました。全身の筋肉痛と心地よい疲労感に包まれながら、スマホの写真フォルダを見返して大興奮のまま特急列車に乗り込みました。','2026-08-06','19:45','🍻','0','',-1500,0,false,'2026-08-06 19:48:50.22+09','2026-08-01 11:10:50.466944+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.858591416,138.391513824,'小木港へ移動して名物のたらい舟体験','翌朝は南部の小木エリアへドライブ。矢島・経島（やじま・きょうじま）で、エメラルドグリーンの入江をゆく名物の「たらい舟」を体験！','2026-06-02','09:00','🛶','0','',-600,1,false,'2026-06-02 09:35:50.8+09','2026-08-01 17:09:09.086083+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.741200000,140.721200000,'鳴子温泉郷の歴史ある温泉宿にチェックイン','山越えのドライブで心地よい疲労感を覚えつつ、今日の宿泊先である鳴子温泉郷の老舗宿に到着しました。木造りの風情ある佇まいに迎えられ、さっそく硫黄の香りが漂う名湯の大浴場へ向かいます。横断を成し遂げた達成感を味わいながら、熱めのお湯にじっくりと体を浸して最高のリフレッシュタイムを過ごしました。','2026-10-05','18:15','♨️','0','',-17000,1,false,'2026-10-05 18:18:50.22+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.371200000,141.061200000,'日本三景・松島海岸の太平洋ビューを満喫','太平洋側のハイライトとして、日本三景・松島海岸のエリアへと到着しました。昨日眺めていた日本海の荒々しい海とは打って変わって、穏やかな内海にたくさんの小島が浮かぶ静かな太平洋の景色を眺めながら、海沿いの遊歩道をのんびりと歩いて横断の旅情をしみじみとかみしめました。','2026-10-06','10:30','⛩️','0','',0,1,false,'2026-10-06 10:34:40.5+09','2026-08-01 10:59:25.361797+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.874311385,138.412799835,'宿根木の風情ある船大工の町並みを散策','国の重要伝統的建造物群保存地区である「宿根木（しゅくねぎ）」の細い路地を散策。板壁の民家が密集する独特のノスタルジックな風景に感動。','2026-06-02','10:30','🏡','0','',-500,1,false,'2026-06-02 10:35:10.2+09','2026-08-01 17:09:18.265211+09'),
	 (22,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.960000000,138.360000000,'ご当地グルメのお蕎麦でランチ休憩','佐渡産のそば粉を使ったこだわりのお蕎麦屋さんで、コシの強い手打ちそばと山菜の天ぷらを味わう。素朴で味わい深い美味しさ。','2026-06-02','14:00','🍜','0','',-1100,1,false,'2026-06-02 14:05:22.4+09','2026-08-01 17:09:52.405942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.200000000,135.200000000,'阪和道 PAで最初の休憩とコーヒーブレイク','ドライブのスタート直後、サービスエリアに立ち寄ってリフレッシュ。これから始まる和歌山旅行への期待感が高まる。','2026-09-12','08:30','☕','0','',-600,1,true,'2026-09-12 08:35:12+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226000000,135.167500000,'和歌山城の天守閣と豊かな緑を散策','歴史ある和歌山城へ。天守閣からの眺めが素晴らしく、青空の下で城内の石垣や庭園を家族でのんびり歩いた。','2026-09-12','09:45','🏯','0','',-800,1,true,'2026-09-12 10:00:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.700500000,135.358200000,'黒潮市場で新鮮な海の幸ランチを満喫','紀州黒潮市場に到着。マグロの解体ショーを家族で間近で見学し、その場で買った海鮮丼やお寿司をみんなでシェアして食べた。','2026-09-12','12:00','🍣','0','',-4500,1,true,'2026-09-12 12:30:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.692200000,135.335100000,'アドベンチャーワールドでパンダに癒やされる','大人気のジャイアントパンダやたくさんの動物たちを見学。サファリワールドを車で回ったり、イルカショーを見て家族みんなが大はしゃぎ。','2026-09-12','14:00','🐼','0','',-12000,1,true,'2026-09-12 14:30:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.682300000,135.333100000,'千畳敷のダイナミックな景観に感動','波の浸食によってできた壮大な岩畳を見学。太平洋の水平線が広がり、夕暮れ時の景色が言葉を失うほど美しかった。','2026-09-12','17:30','🌅','0','',0,1,true,'2026-09-12 18:00:00+09','2026-08-01 21:16:24.073386+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.685000000,135.340000000,'白良浜の真っ白な砂浜を少しお散歩','日が暮れる前の白良浜へ。足裏に心地よい真っ白な砂浜と透明度の高い海を眺めながら波打ち際を歩く。','2026-09-12','18:15','🏖️','0','',0,1,true,'2026-09-12 18:30:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.675800000,135.496500000,'アメリカ村・三角公園周辺','若者カルチャーの発信地アメ村へ。古着屋巡りをするも、人の多さと独特の雰囲気に少し圧倒され足早に通り抜ける。','2026-08-02','13:30','👟','0','',-1500,0,true,'2026-08-02 14:00:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.670100000,135.499800000,'心斎橋筋商店街で最後のショッピング','家族へのお土産のお菓子や自分用のグッズを買い込む。両手が荷物でいっぱいに。','2026-08-02','15:30','🛍️','0','',-5400,1,true,'2026-08-02 16:00:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702400000,135.495200000,'新大阪駅ナカで最後の豚まん＆お土産チェック','新幹線の発車時刻まで時間調整。有名店の豚まんを買って、満足感に浸りながら帰りの新幹線に乗り込んだ。','2026-08-02','18:00','🚄','0','',-1950,1,true,'2026-08-02 18:30:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705500000,135.498300000,'大阪駅前ビル地下のディープな居酒屋で反省会','レトロで昭和感あふれるビル地下の居酒屋へ潜入。安くて美味いホルモン焼きとハイボールで今日の疲れを癒やす。','2026-08-01','21:30','🥳','0','',-3100,1,true,'2026-08-01 22:00:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.693700000,135.502200000,'北浜のカフェで川風を感じながらモーニング','2日目の朝。おしゃれな北浜のテラス席で、川を眺めながらゆったりとしたモーニングコーヒーを味わう。','2026-08-02','09:00','☕','0','',-1100,1,true,'2026-08-02 09:30:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.687300000,135.526200000,'大阪城公園・天守閣エリアへ移動','緑豊かな公園内を歩いて天守閣へ。歴史ある石垣の大きさに圧倒されるが、夏の暑さで汗が止まらない。','2026-08-02','11:00','🏯','1','',-600,0,true,'2026-08-02 11:30:00+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.715500000,135.363500000,'三段壁へドライブ🌊','断崖の迫力に家族で「すごっ！」と声が揃う。少し怖いけど楽しい。','2026-08-20','14:00','🌊','1','',0,1,true,'2026-08-20 14:02:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720400000,135.375000000,'海鮮丼で復活🍚','疲れた体に海鮮丼が染みる。家族全員「うまっ！」と声が揃う。1300円。','2026-08-20','16:00','🍚','1','',-1300,1,true,'2026-08-20 16:02:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.715000000,135.363000000,'夕景の千畳敷🌅','夕日が岩に反射して綺麗すぎる。家族でしばらく無言で眺める。','2026-08-20','17:10','🌅','0','',0,1,true,'2026-08-20 17:12:00+09','2026-08-01 20:07:48.570937+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720400000,135.375000000,'帰りの準備📱','撮った写真を見返して大笑い。今日のハイライトを家族で語り合う。','2026-08-20','18:00','📱','0','',0,1,true,'2026-08-20 18:02:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720400000,135.375000000,'白浜に到着🚗','高速を降りた瞬間に潮の香り。家族みんなテンション上がる。','2026-08-20','09:10','🚗','1','',0,1,true,'2026-08-20 09:12:00+09','2026-08-01 20:07:48.570937+09'),
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686300000,135.520000000,'大阪城公園の早朝散歩','2日目の朝。少し早起きして、ホテルから地下鉄で移動し大阪城公園へ。朝の澄んだ空気の中でお堀の周りを歩く地元の人たちとすれ違う。天守閣が朝日に照らされていてとても綺麗。','2026-08-02','08:30','🌿','0','',0,1,false,'2026-08-02 08:33:40.9+09','2026-08-01 09:28:00.797366+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.690100000,135.352100000,'白浜温泉の宿でゆったり温泉と会席料理','温泉に浸かって一日の運転の疲れをしっかりリフレッシュ。海の幸がふんだんに使われた豪華な夕食を家族で囲み、楽しい夜を過ごした。','2026-09-12','20:00','♨️','0','',-32000,1,true,'2026-09-12 20:30:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.716500000,135.378900000,'三段壁の洞窟探検でスリルを味わう','2日目の朝、地下深くへエレベーターで降りて波が打ち寄せる洞窟内部を見学。自然の迫力を間近で体感して子どもたちも大興奮。','2026-09-13','09:30','🌊','0','',-3000,1,true,'2026-09-13 10:00:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725000000,135.385000000,'円月島（高月島）の景色をドライブ中に眺める','海にぽっかり浮かぶ円月島の丸い穴に沈む夕日は見られなかったが、青い海と美しいコントラストをなす昼間の姿を車窓から満喫。','2026-09-13','11:00','🚗','0','',0,1,true,'2026-09-13 11:20:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.800000000,135.420000000,'とれとれ市場でお土産の海産物を物色','新鮮な魚介類や紀州の特産品が並ぶ巨大な市場へ。家族それぞれが気になるお土産や乾物を楽しそうに選んで買い込んだ。','2026-09-13','12:00','🛍️','0','',-4200,1,true,'2026-09-13 12:30:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.733300000,135.466700000,'南部梅林の近くのドライブロードを爽快走行','心地よい海風と山あいの緑を感じながら、快適な海岸線沿いのドライブを楽しむ。車内での家族の会話も弾む。','2026-09-13','13:30','🎶','0','',0,1,true,'2026-09-13 13:50:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.032100000,135.195000000,'紀州梅の里でたくさんの梅干しをお土産に購入','道の駅でバラエティ豊かな紀州南高梅の梅干しや梅ジュースを試食してお気に入りを発見。自宅用と親戚用にたくさん買い込んだ。','2026-09-13','14:45','🍊','0','',-5000,1,true,'2026-09-13 15:15:00+09','2026-08-01 21:16:24.073386+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.150000000,135.210000000,'道の駅紀の川万葉の里でちょっとひと息','ドライブの締めくくり前に、地元農産物やフルーツが並ぶ道の駅に立ち寄り。冷たいみかんソフトクリームを食べて一息つく。','2026-09-13','16:00','🍦','0','',-800,1,true,'2026-09-13 16:30:00+09','2026-08-01 21:16:24.073386+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728000000,135.985000000,'新宮駅に到着、レンタカーで男子会旅スタート','仲間たちとテンション高く新宮駅に集合。レンタカーに乗り込んで、男だらけの熱い1泊2日旅行がついに出発！','2026-10-10','10:00','🚗','0','',0,1,false,'2026-10-10 10:05:12+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.729000000,135.992000000,'熊野速玉大社で旅の安全と男の勝負祈願','世界遺産に登録されている熊野速玉大社を参拝。鮮やかな朱色の社殿を見学し、今後の健闘をみんなで祈る。','2026-10-10','10:45','⛩️','0','',0,1,false,'2026-10-10 11:00:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.723000000,135.989000000,'1軒目：新宮名物の濃厚豚骨ラーメンで腹ごしらえ','観光の前に腹ペコの胃袋を満たすべく、地元で評判の濃厚ラーメン店へ。ガツンとくるスープが男ウケ抜群の美味さ。','2026-10-10','12:00','🍜','0','',-950,1,false,'2026-10-10 12:30:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.721000000,135.991000000,'神倉神社の急な石段（538段）に男気チャレンジ','ゴツゴツした険しい538段の石段を全員で息を切らしながら登り切る。登頂した時の達成感と街並みの絶景が最高。','2026-10-10','13:30','🧗','0','',0,1,false,'2026-10-10 14:00:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725000000,135.987000000,'2軒目：あっさり系中華そばでラーメン食べ比べ','少し歩いたところで、先ほどとは対照的なあっさりスープの中華そばをみんなでシェア。味の違いを語り合う。','2026-10-10','16:30','🍜','0','',-850,1,false,'2026-10-10 17:00:00+09','2026-08-01 21:17:55.265904+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.344143000,134.050210000,'高松港で海風を感じる','港の海風が心地よくて、瀬戸内海の穏やかな景色に自然と笑顔になる。','2026-08-03','09:40','🌊','0000','',0,1,true,'2026-08-03 09:40:00+09','2026-08-02 02:10:39.052942+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.842220000,134.693890000,'「大手前公園」を抜け、美しい城の姿を間近に眺めながらのんびりお散歩','きれいに整備された大手前公園の開放的な歩道を、心地よい春風を感じながら北へと歩みを進める。木々の緑の向こう側に少しずつ大きく迫ってくる姫路城の美しく優美な大天守の姿に、思わず何度も足を止めてカメラのシャッターを切ってしまう。','2026-10-10','10:30','🌳','0','',0,1,false,'2026-10-10 11:00:00+09','2026-08-02 01:09:13.862814+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.005000000,135.771000000,'木屋町の路地裏を散策','高瀬川沿いの道をのんびりお散歩。柳並木とレトロな建物が並んでいて、どこを切り取っても写真映えする景色。歩きながら次に行くパフェのお店をスマホで再確認。','2026-08-03','13:30','🌿','0','',0,1,false,'2026-08-03 13:33:20.15+09','2026-08-01 09:37:37.584085+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.845560000,134.693890000,'世界遺産・国宝「姫路城」の美しい大天守と巧みな防御の工夫を見学','ついに世界文化遺産・国宝である姫路城の境内へ足を踏み入れる。幾重にも張り巡らされた複雑な門や狭間など、戦国時代の高度な建築美と巧妙な防御の仕組みに感嘆しながら、真っ白な漆喰壁が美しい大天守の内部へとじっくりと登っていく。','2026-10-10','11:00','🏯','0','',-1000,1,false,'2026-10-10 12:00:00+09','2026-08-02 01:09:13.862814+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.843060000,134.690830000,'日本庭園の傑作「好古園」で、四季折々の自然と静寂な日本庭園を散策','姫路城の西側に広がる、趣の異なる九つの庭園群からなる本格的な日本庭園「好古園」へ。手入れされた美しい池や滝、見事な松の緑が織りなす静寂で雅な空間をゆっくりと歩き、日本の伝統的な美意識に触れながら心穏やかなひとときを過ごす。','2026-10-10','13:30','🍁','0','',-310,1,false,'2026-10-10 14:15:00+09','2026-08-02 01:09:13.862814+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.843330000,134.690000000,'2軒目：好古園内の茶室「好古園 活水軒」で味わう、優美な抹茶と和菓子','庭園の緑を一望できる好古園内の風情ある茶室「活水軒」に立ち寄る。静かに流れる水の音に耳を傾けながら、職人が一つひとつ丁寧に作り上げた上品な上生菓子と、点てたての香り高いお抹茶をいただく。旅の疲れがすーっと癒やされる至福の休憩時間。','2026-10-10','14:30','🍵','0','',-700,1,false,'2026-10-10 15:00:00+09','2026-08-02 01:09:13.862814+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.840560000,134.691670000,'3軒目：城下町の隠れ家的名店でいただく、ご当地グルメ「姫路おでん」のランチ','お昼時は、生姜醤油で食べるのがご当地流である名物の「姫路おでん」を味わいに老舗の食事処へ。じっくりと出汁の染み込んだ大根や牛すじに、キリッとした生姜醤油の風味がアクセントとなり、他では味わえない奥深い美味しさに箸が止まらない。','2026-10-11','12:00','🍢','0','',-1400,1,false,'2026-10-11 12:45:00+09','2026-08-02 01:09:13.862814+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.240833000,133.097222000,'多々羅大橋を渡る','しまなみ海道でも特に美しい橋。海と島の重なりが絶景で、思わず声が出るほど。','2026-08-04','14:00','🤩','0000','',0,1,false,'2026-08-04 14:00:00+09','2026-08-02 07:30:32.144728+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'甲府駅でレンタカーを借りて富士山麓へ出発','登らない贅沢な富士山周辺の撮影・散策ドライブ旅をスタートさせるため、朝の甲府駅前でレンタカーを借り受けて出発しました。車窓から見える遠くの山並みと青空にワクワクしながら、ハンドルを握って富士五湖エリアを目指して高速道路を軽快に飛ばします。','2026-09-10','09:00','🚙','0','',0,1,false,'2026-09-10 09:32:15.12+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.512300000,138.761200000,'河口湖畔に到着し見事な富士山の姿に感動','車を走らせて最初の目的地である河口湖のほとりへと到着しました。雲ひとつない青空の下、湖の向こう側にドンとそびえ立つ美しい富士山の姿が目の前に飛び込んできて、男2人で「うわ、すげぇ綺麗だな…！」と思わず歓声を上げました。湖畔の風がとても心地よい最高のロケーションです。','2026-09-10','10:30','🗻','0','',0,1,false,'2026-09-10 10:34:40.5+09','2026-08-01 11:12:22.077634+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.652500000,135.506300000,'新世界・通天閣周辺','新幹線と電車を乗り継いで、ようやく大阪に到着！通天閣の下はすごい活気で、一気に大阪らしい雰囲気にテンションが上がる。まずは名物の串カツの匂いに誘われて、お腹の虫が鳴り始める。','2026-08-01','12:30','🤩','0','',-1200,1,false,'2026-08-01 12:32:15.12+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.656000000,135.504500000,'元祖串かつでソース二度漬け禁止を体験','サクサクの衣と特製ソースが絶品！二度漬け禁止のルールを守りつつ、ビールと串カツの最高の組み合わせを満喫した。','2026-08-01','13:15','🍻','0','',-2400,1,false,'2026-08-01 13:20:00+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.662000000,135.502000000,'日本橋の家電・カルチャー街を散策','オタロードや電子パーツ店が並ぶエリアをぶらり。夏の暑さで少しバテつつも、ディープな雰囲気を楽しむ。','2026-08-01','14:45','🥵','1','',-850,0,false,'2026-08-01 15:00:00+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668700000,135.501300000,'道頓堀・グリコサイン前で記念撮影','観光客の熱気がすごい！ネオンが光り始める前の夕暮れ時、道頓堀川沿いを歩きながら名物の看板を見て回る。','2026-08-01','17:30','📸','0','',0,1,false,'2026-08-01 17:45:00+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.675800000,135.496500000,'アメリカ村・三角公園周辺','若者カルチャーの発信地アメ村へ。古着屋巡りをするも、人の多さと独特の雰囲気に少し圧倒され足早に通り抜ける。','2026-08-01','18:30','👟','0','',-1500,0,false,'2026-08-01 19:00:00+09','2026-08-01 18:59:51.377147+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676500000,135.500200000,'心斎橋筋商店街で最後のショッピング','家族へのお土産のお菓子や自分用のグッズを買い込む。両手が荷物でいっぱいに。','2026-08-01','19:45','🛍️','0','',-5400,1,false,'2026-08-01 20:00:00+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.687300000,135.526200000,'大阪城公園・天守閣エリアへ移動','緑豊かな公園内を歩いて天守閣へ。歴史ある石垣の大きさに圧倒されるが、夏の暑さで汗が止まらない。','2026-08-02','10:00','🏯','1','',-600,0,false,'2026-08-02 10:30:00+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.693700000,135.502200000,'北浜のカフェで川風を感じながらモーニング','おしゃれな北浜のテラス席で、川を眺めながらゆったりとしたモーニングコーヒーを味わう。','2026-08-02','11:30','☕','0','',-1100,1,false,'2026-08-02 12:00:00+09','2026-08-01 18:59:51.377147+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.732000000,135.373500000,'とれとれ市場で朝ごはん🐟','海鮮の試食が楽しすぎて歩くたびに食べてしまう。海鮮丼1200円。','2026-08-20','09:40','🐟','1','',-1200,1,true,'2026-08-20 09:42:00+09','2026-08-01 20:07:48.570937+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702500000,135.495900000,'梅田スカイビル・空中庭園展望台','大阪の夜景を一望するためにビルへ。エレベーターから見る景色が最高で気分爽快！','2026-08-02','14:00','🏙️','0','',-2000,1,false,'2026-08-02 14:30:00+09','2026-08-01 18:59:51.377147+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.681470000,135.375160000,'とれとれ市場','白浜に到着してまず向かったのがとれとれ市場。海鮮の香りと観光客の熱気で一気に旅モードに入る。','2026-08-01','10:15','🤩','0000','',-2500,1,true,'2026-08-01 10:17:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.677940000,135.363520000,'白良浜','真っ白な砂浜と透明な海に感動。海風が心地よくてしばらく景色を眺めた。','2026-08-01','11:20','😊','0000','',0,1,true,'2026-08-01 11:22:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.646630000,135.368320000,'アドベンチャーワールド','パンダを見てテンション爆上がり。イルカショーの迫力も最高。','2026-08-01','13:40','🤩','0000','',-4500,1,true,'2026-08-01 13:42:00+09','2026-08-01 21:02:31.781628+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705500000,135.498300000,'大阪駅前ビル地下のディープな居酒屋で昼飲み','レトロで昭和感あふれるビル地下の居酒屋へ潜入。安くて美味いホルモン焼きとハイボールを満喫。','2026-08-02','16:00','🥳','0','',-3100,1,false,'2026-08-02 16:30:00+09','2026-08-01 18:59:51.377147+09'),
	 (27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.733600000,135.500100000,'新大阪駅ナカで最後の豚まん＆お土産チェック','新幹線の発車時刻まで時間調整。有名店の豚まんを買って、満足感に浸りながら帰りの新幹線に乗り込んだ。','2026-08-02','18:00','🚄','0','',-1950,1,false,'2026-08-02 18:30:00+09','2026-08-01 18:59:51.377147+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.882220000,134.646390000,'ロープウェイに揺られ、映画のロケ地としても名高い「書写山円教寺」へ','市街地を離れて北西へ向かい、豊かな自然に包まれた書写山へ。ロープウェイの窓から眼下に広がる雄大な山々と播磨平野の景色を眺めながら空中散歩を楽しみ、西の比叡山とも称される歴史ある天台宗の古刹・円教寺の境内へと足を踏み入れる。','2026-10-11','13:30','🚡','0','',-1000,1,false,'2026-10-11 14:15:00+09','2026-08-02 01:09:13.862814+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702400000,135.495200000,'新大阪駅ナカで最後の豚まん＆お土産チェック','新幹線の発車時刻まで時間調整。有名店の豚まんを買って、満足感に浸りながら帰りの新幹線に乗り込んだ。','2026-08-02','18:00','🚄','0','',-1950,1,true,'2026-08-02 18:30:00+09','2026-08-01 19:03:48.822924+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.883330000,134.639170000,'重厚な木造建築が立ち並ぶ円教寺の国重要文化財「大講堂・食堂・常行堂」を見学','深い森の静寂に包まれた円教寺の核心部に到着。ダイナミックで重厚な佇まいを見せる「大講堂」「食堂」「常行堂」の三つのお堂（三之堂）を目の当たりにし、室町時代から受け継がれてきた圧倒的な歴史の重みと、木造建築の美しさに深く感動する。','2026-10-11','14:30','寺','0','',-500,1,false,'2026-10-11 15:15:00+09','2026-08-02 01:09:13.862814+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728000000,135.985000000,'新宮駅前にてレンタカー返却前の最終ミーティング','楽しかった2日間の思い出を振り返りながら、駅前でレンタカーを返却する直前のひとコマ。','2026-10-11','17:45','🚗','0','',0,1,false,'2026-10-11 18:10:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728500000,135.985500000,'新宮駅ホームで特急電車の到着を待つ','たくさんの観光地とラーメンを制覇した満足感に浸りながら、帰りの特急電車のホームで旅の終わりを惜しむ。','2026-10-11','18:30','🚄','0','',0,1,false,'2026-10-11 19:00:00+09','2026-08-01 21:17:55.265904+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.503400000,138.755000000,'新倉山浅間公園で定番の五重塔と富士山を撮影','外国人観光客にも大人気の撮影スポットである新倉山浅間公園の階段を登り、展望デッキへとやってきました。朱色の五重塔と雄大な富士山が同じフレームに収まる日本らしい絶景をカメラでバッチリ撮影します。完璧な構図の写真が撮れて大満足の撮影タイムになりました。','2026-09-10','12:00','📷','0','',0,1,false,'2026-09-10 12:35:10.8+09','2026-08-01 11:12:22.077634+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838330000,134.693330000,'歴史ある佇まいとモダンが融合した、駅チカの上質なホテルにチェックイン','本日の宿泊先である、姫路の街並みに溶け込む洗練されたホテルにチェックイン。モダンで機能的ながらも落ち着きのある客室に通され、窓の外にライトアップが始まる直前の夕暮れの姫路城を遠くに眺めながら、旅の荷物を解いてほっと一息つく。','2026-10-11','17:00','宿','0','',-24000,1,false,'2026-10-11 17:30:00+09','2026-08-02 01:09:13.862814+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.694440000,'夜の闇に白く浮かび上がる幻想的な「ライトアップされた姫路城」を観賞','夕食の前に、夜の闇の中で美しくライトアップされた幻想的な「姫路城」を眺めに夜のお散歩へ。昼間の白さとは一変し、漆黒の夜空に浮かび上がる白鷺城の姿は息を呑むほどに妖艶で美しく、いつまでも眺めていたくなるような絶景が広がる。','2026-10-11','18:30','✨','0','',0,1,false,'2026-10-11 19:00:00+09','2026-08-02 01:09:13.862814+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.670550000,135.349410000,'円月島','夕日の穴抜けが幻想的でしばらく見入った。','2026-08-01','18:10','🥺','0000','',0,1,true,'2026-08-01 18:12:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.661390000,135.350320000,'千畳敷','岩盤の広がりが壮大で風の強さも迫力を増す。','2026-08-01','17:00','😮','0000','',0,1,true,'2026-08-01 17:02:00+09','2026-08-01 21:02:31.781628+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.719280000,135.355880000,'崎の湯','海を眺めながら入る温泉が最高。波音が心地よい。','2026-08-01','19:00','😌','0000','',-500,1,true,'2026-08-01 19:02:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.803110000,135.527020000,'熊野本宮大社','森に囲まれた神聖な空気に気持ちが整う。','2026-08-02','09:30','🙏','0000','',0,1,true,'2026-08-02 09:32:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.853250000,135.778610000,'熊野那智大社','朱色の社殿が緑に映えて美しい。','2026-08-02','11:10','😌','0000','',0,1,true,'2026-08-02 11:12:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.673320000,135.891660000,'那智の滝','落差133mの迫力に圧倒。水しぶきが届くほど。','2026-08-02','12:00','😮','0000','',0,1,true,'2026-08-02 12:02:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.490410000,135.792290000,'勝浦漁港','朝の漁港の活気がすごい。マグロ丼が絶品。','2026-08-02','08:10','🤤','0000','',-1800,1,true,'2026-08-02 08:12:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226110000,135.584690000,'高野山 奥之院','杉木立の参道が静寂で心が整う。','2026-08-03','10:00','😌','0000','',0,1,true,'2026-08-03 10:02:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.217520000,135.628410000,'金剛峯寺','広い敷地と静かな空気が印象的。','2026-08-03','11:30','😮','0000','',0,1,true,'2026-08-03 11:32:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226810000,135.613290000,'壇上伽藍','朱色の根本大塔が圧巻。曼荼羅も美しい。','2026-08-03','12:20','🙏','0000','',0,1,true,'2026-08-03 12:22:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.230320000,135.612920000,'大門','巨大な門をくぐると聖地に入った感覚になる。','2026-08-03','09:40','😮','0000','',0,1,true,'2026-08-03 09:42:00+09','2026-08-01 21:02:31.781628+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.652410000,135.506210000,'新世界・通天閣','大阪の締めにぴったりの賑やかさ。串カツが最高。','2026-08-03','18:00','🤩','0000','',-1200,1,true,'2026-08-03 18:02:00+09','2026-08-01 21:02:31.781628+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'和歌山駅周辺へドライブ戻り','夕方の街を車で走りながら「今日めっちゃ楽しかったね」と家族で振り返る。','2026-08-15','16:10','🙂','0000','',0,1,true,'2026-08-15 16:12:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.229000000,135.167000000,'駅ナカでお土産購入','梅干しや海産物を家族で選ぶ。誰がどれ買うかでちょっとした騒ぎに。1500円。','2026-08-15','16:40','🤩','0000','',-1500,1,true,'2026-08-15 16:42:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'帰路へ','車に乗り込み、今日の写真を見返しながら家族で大笑い。最高の一日だった。','2026-08-15','17:20','🙂','0000','',0,1,true,'2026-08-15 17:22:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'和歌山へ向けて出発','朝早く家族で車に乗り込み和歌山へ。お菓子をつまみながらワイワイ移動。','2026-08-15','08:10','🙂','0000','',0,1,true,'2026-08-15 08:12:00+09','2026-08-01 21:33:47.291888+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.008000000,135.765000000,'三条の隠れ家カフェで早めのランチ','町家をリノベーションした素敵なカフェでランチ。アボカドとサーモンのオープンサンドをシェアして食べた。店内の雰囲気が落ち着いていて、おしゃべりに花が咲く。','2026-08-03','12:00','🥑','0','',-1850,1,false,'2026-08-03 12:05:10.8+09','2026-08-01 09:37:37.584085+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560040000,133.531430000,'高知城天守に登る','天守からの眺めが最高。高知の街並みと青空が広がっていて気持ちが明るくなる。','2026-08-11','13:30','📸','0000','',0,1,false,'2026-08-11 13:30:00+09','2026-08-02 02:06:55.502943+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013500000,135.677500000,'夕暮れの嵐山駅で名残惜しいお別れ','楽しかったデートの時間もあっという間に過ぎて、夕暮れの駅ホームに到着した。<br>名残惜しい気持ちでいっぱいになりながらも、今日の楽しかった思い出を振り返る。<br>「また次も色んなところに出かけようね」と笑顔で手を振って帰路についた。','2026-09-12','18:15','🥺','0','',0,1,false,'2026-09-12 18:18:10.88+09','2026-08-01 09:43:49.952679+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.245000000,135.191000000,'和歌山マリーナシティ到着','海が見えてテンション上がる。家族で写真撮影大会が始まる。','2026-08-15','09:00','🤩','0000','',0,1,true,'2026-08-15 09:02:00+09','2026-08-01 21:33:47.291888+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.081200000,144.451200000,'釧路湿原展望台でスケールの大きさに圧倒される','車を走らせて日本最大の湿原へ。見渡す限り果てしなく広がる緑の大地に、男2人で「うわ、すげえ……」とただただ圧倒される。風が吹き抜けていく音が心地よい。','2026-08-10','13:00','🌿','0','',-500,1,false,'2026-08-10 13:05:10.8+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.151200000,144.512300000,'細岡展望台から蛇行する釧路川を望む','湿原の反対側にある細岡展望台へも移動。眼下に蛇行しながら流れる釧路川の景色がまるで絵画のようで、しばらく言葉を失ってカメラのシャッターを切りまくる。','2026-08-10','14:30','📷','0','',0,1,false,'2026-08-10 14:33:20.15+09','2026-08-01 10:19:22.49106+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.431200000,144.531200000,'阿寒のワインディングロードを駆け抜ける','北へ向けて車を走らせると、緑深い森の中を縫うようなワインディングロードに入る。エンジンの心地よい唸りを聞きながら、お気に入りの音楽をかけてドライブを全力で楽しむ。','2026-08-10','16:00','🎵','0','',0,1,false,'2026-08-10 16:04:00+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.441200000,144.431200000,'阿寒湖温泉の宿にチェックイン','夕方に阿寒湖のほとりにある温泉宿へ到着。広めの和室に荷物を放り込み、さっそく冷えた体を温めるために硫黄の香りが漂う大浴場へ向かう。','2026-08-10','18:00','♨️','0','',-12000,1,false,'2026-08-10 18:04:12.3+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.442000000,144.433000000,'湖畔の居酒屋でワカサギと地酒を堪能','夜ご飯は温泉街の居酒屋へ繰り出す。阿寒湖で採れたワカサギの天ぷらと地元の日本酒を合わせながら、明日のルートについて地図を広げて熱く語り合う。','2026-08-10','20:00','🍶','0','',-4500,1,false,'2026-08-10 20:03:40.9+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.581200000,144.551200000,'神秘の湖・摩周湖の第1展望台へ','2日目の朝。霧が多いことで有名な摩周湖だが、この日は奇跡的に雲ひとつない快晴。どこまでも深く濃い青色をした「摩周ブルー」の湖面に感動する。','2026-08-11','09:00','✨','0','',-500,1,false,'2026-08-11 09:03:15.12+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.631200000,144.612300000,'硫黄山で地球の息吹を間近で感じる','あたり一面に黄色い硫黄の結晶が広がり、あちこちからゴゴゴと音を立てて白煙が噴き出しているスポットへ。ダイナミックな大地のエネルギーを肌でひしひしと感じる。','2026-08-11','10:30','🌋','0','',-500,1,false,'2026-08-11 10:34:40.5+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.791200000,144.681200000,'屈斜路湖の砂湯で足湯体験','湖畔の砂を少し掘ると温かいお湯が湧き出てくる「砂湯」に立ち寄る。冷たい湖風を受けながら、足湯に浸かってのんびり小休憩。白鳥の親子も近くを泳いでいて和む。','2026-08-11','12:00','🦆','0','',0,1,false,'2026-08-11 12:03:10.8+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.841200000,144.821200000,'美幌峠の頂上から屈斜路湖を一望','峠道を一気に登りきった美幌峠の展望台へ。眼下に広がる日本最大のカルデラ湖・屈斜路湖のパノラマビューが文字通り「絶景」の一言で、缶コーヒー片手にしばらく見入ってしまう。','2026-08-11','13:30','⛰️','0','',-200,1,false,'2026-08-11 13:35:20.15+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.981200000,144.912300000,'オホーツク海に面した網走市街へ到着','山道を抜けてオホーツク海側へと一気に北上。海の匂いを感じながら網走の街に入り、遅めの昼食として地元で人気の海鮮食堂へ駆け込む。','2026-08-11','15:30','🌊','0','',-1800,1,false,'2026-08-11 15:34:00+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.021200000,145.012300000,'知床半島の入り口・ウトロへドライブ','さらに東へ、知床の入り口であるウトロ漁港の周辺まで車を走らせる。険しい断崖絶壁が海に落ち込むワイルドな景色に変わり、いよいよ秘境感が増してくる。','2026-08-11','17:15','🚗','0','',0,1,false,'2026-08-11 17:18:12.3+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.061200000,145.001200000,'知床の岬の見える温泉宿にチェックイン','3日目の拠点となる知床の宿に到着。夕暮れのオホーツク海を窓から眺めながら、旅の疲れをほぐすために再び温泉へと向かう。夕日が海に沈むグラデーションが最高。','2026-08-11','19:00','🌇','0','',-14000,1,false,'2026-08-11 19:04:50.22+09','2026-08-01 10:19:22.49106+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.101200000,145.112300000,'世界遺産・知床五郷の地上遊歩道へ','3日目の朝。ガイドの案内を聞きながら、原生林に囲まれた知床五湖の地上遊歩道を散策する。野生のシカに遭遇したり、手つかずの大自然の空気を胸いっぱいに吸い込む。','2026-08-12','09:30','🦌','0','',-2500,1,false,'2026-08-12 09:35:10.88+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.081200000,145.151200000,'知床の有名スポット・オシンココの滝','轟音を立てて豪快に流れ落ちる「オシンココの滝」に立ち寄る。マイナスイオンを全身に浴びて、近くの売店で売っていた名物の網走産ホタテ焼きをその場で頬張る。','2026-08-12','11:30','瀑','0','',-600,1,false,'2026-08-12 11:34:15.12+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.912300000,144.281200000,'北見市内で名物の焼肉ランチ','内陸へ戻りながら、焼肉の街として知られる北見市へ。地元で有名な肉屋に飛び込み、サガリやホルモンを香ばしく焼き上げてガッツリと昼食をとる。これが驚くほどの美味さ。','2026-08-12','13:30','🥩','0','',-2200,1,false,'2026-08-12 13:35:40.5+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.812300000,144.151200000,'女満別空港へ向けてラストスパート','旅の終盤、どこまでも続くまっすぐな道（メルヘンの丘付近）を車窓から眺めながら空港へと車を走らせる。「あっという間の3日間だったな」と、車内で思い出話に花が咲く。','2026-08-12','15:30','🌾','0','',0,1,false,'2026-08-12 15:34:10.8+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.881200000,144.161200000,'女満別空港でレンタカーを返却','無事にトラブルもなく女満別空港に到着し、レンタカーを返却する。大量に走り抜けたメーターの数値に驚きつつ、出発ロビーへと足を進めてお土産の買い出しへ。','2026-08-12','16:45','🤝','0','',-6500,1,false,'2026-08-12 16:48:20.15+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.883000000,144.163000000,'空港のラーメンで道東旅を締めくくる','保安検査場を通る直前、最後の締めくくりに空港内の食堂でコクのある味噌ラーメンを食べる。「また絶対に道東に来ようぜ」と誓い合い、帰りの飛行機へと乗り込む。','2026-08-12','17:30','🍜','0','',-1100,0,false,'2026-08-12 17:35:00+09','2026-08-01 10:19:22.49106+09'),
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.042547207,144.193153381,'釧路空港でレンタカーを借りて出発','朝の釧路空港に到着し、さっそくレンタカーの手続きを済ませる。窓の外のどこかひんやりとした空気に「いよいよ道東に来たぞ」と実感が湧き、テンションが上がってエンジンをかける。','2026-08-10','09:30','🚙','0','',0,1,false,'2026-08-10 09:32:15.12+09','2026-08-01 10:19:42.453173+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.341200000,142.381200000,'富良野の早朝コンビニで朝食調達','2日目の朝。寝ぼけ眼で宿をチェックアウトし、近くのセイコーマート（セコマ）に駆け込む。ホットシェフのおにぎりとザンギを買って、車のなかで頬張る。','2026-06-11','07:30','🍙','0','',-700,1,false,'2026-06-11 07:33:15.12+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.923400000,141.572100000,'道央道を北上しながら最初の休憩','走り出してすぐに北海道のスケールのデカさにテンションが上がる。運転を交代しながら、とりあえずサービスエリアで北海道限定のソフトクリームを食べて気合を入れる。','2026-06-10','10:45','🍦','0','',-450,1,false,'2026-06-10 10:48:40.5+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.342100000,141.782300000,'岩見沢の田園風景ロードで寄り道','高速を降りて一般道に入ると、どこまでも続く水平線のような田園風景が広がる。車を路肩に止めて、あまりの開放感に全員で大の字になって写真を撮りまくる。','2026-06-10','12:00','🌾','0','',0,1,false,'2026-06-10 12:05:10.8+09','2026-08-01 10:05:26.899298+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.541200000,142.213400000,'旭川ラーメンでガッツリ昼食','「昼はやっぱりラーメンだろ」と、看板を見つけて飛び込んだ地元のラーメン店。濃厚な味噌ラーメンとチャーハンを頼んで、空腹だった胃袋が一気に満たされる。','2026-06-10','13:30','🍜','0','',-1100,1,false,'2026-06-10 13:33:20.15+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.432100000,142.451200000,'美瑛のパッチワークの路をドライブ','なだらかな丘陵地帯が続く美瑛の景色の中を車で駆け抜ける。雑誌で見たような絶景が次々と現れて、助手席の奴が「うわ、すげえ！」と窓から身を乗り出す。','2026-06-10','15:00','📷','0','',0,1,false,'2026-06-10 15:04:00+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.411200000,142.632100000,'青い池で幻想的な景色に感動','観光客に混じって噂の青い池に立ち寄る。本当に絵の具を溶かしたような鮮やかな青色をしていて、男4人で「おぉ…」と妙に感心してしばらく眺めてしまった。','2026-06-10','16:15','✨','0','',0,1,false,'2026-06-10 16:18:12.3+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.441200000,142.651200000,'白ひげの滝でマイナスイオンを浴びる','青い池のすぐ近くにある滝にも足を延ばす。轟音とともに勢いよく水が流れ落ちていて、ドライブの疲れが一気に吹き飛ぶような爽快感を味わう。','2026-06-10','17:00','🌊','0','',0,1,false,'2026-06-10 17:03:40.9+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.342100000,142.751200000,'十勝岳望岳台で夕日を眺める','少し標高の高いところまで車を走らせたら、雲の上から夕日が沈む最高のロケーションに遭遇。寒風の中、男4人で並んで沈む夕日を眺めるシュールな絵面になる。','2026-06-10','18:10','🌇','0','',0,1,false,'2026-06-10 18:15:15.4+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.351200000,142.851200000,'富良野の温泉宿に駆け込みチェックイン','すっかり暗くなった山道を抜けて、今夜の宿である温泉街へ到着。予約なしだったが運よく空きがあり、冷えた体を温めるべく即座に大浴場へ直行する。','2026-06-10','20:00','♨️','0','',-8500,1,false,'2026-06-10 20:04:50.22+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.352000000,142.853000000,'宿の居酒屋で北海道の夜を満喫','温泉のあとは浴衣のまま食堂に集まり、ジンギスカンとビールで盛大な宴会がスタート。明日どこに行くかも決めずに、昔のバカ話で夜遅くまで盛り上がり続ける。','2026-06-10','21:30','🍺','0','',-4000,1,false,'2026-06-10 21:35:10.88+09','2026-08-01 10:05:26.899298+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.981200000,142.281200000,'山岳ワインディングロードを快走','南下しながら、車通りの少ない気持ちいいワインディングロードを進む。エンジンの唸りを聞きながら、音楽を大音量にかけてドライブの醍醐味を全力で満喫する。','2026-06-11','10:30','🎵','0','',0,1,false,'2026-06-11 10:35:10.8+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.812300000,142.151200000,'道の駅でご当地グルメを買い食い','ドライブの定番、道の駅を発見して迷わずピットイン。特大のメロンパンと、その場で焼いたホタテの串焼きをシェアして食べる。これが想像以上の美味さでテンションが上がる。','2026-06-11','12:00','🍈','0','',-900,1,false,'2026-06-11 12:03:20.15+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.612300000,141.951200000,'日勝峠の展望スペースで絶景堪能','険しい峠道を登りきったところにある展望スペース。眼下に広がる十勝平野の圧倒的なパノラマビューに、男4人揃って「すげぇ……」と言葉を失って見入ってしまう。','2026-06-11','13:30','⛰️','0','',0,1,false,'2026-06-11 13:35:00+09','2026-08-01 10:04:29.495627+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.512300000,141.751200000,'夕張のメロン城跡地付近を通過','かつての観光名所の前を車で通り過ぎる。「おお、ここがメロン城か！」と謎の感動を覚えつつ、車内で夕張メロンの歌を適当に大合唱しながら通り抜ける。','2026-06-11','14:45','🎶','0','',0,1,false,'2026-06-11 14:48:12.3+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.821200000,141.512300000,'千歳市内の大型ショッピングモール','そろそろ旅の終わりが近づき、お土産の買い出しのために大きめの施設へピットイン。家族や自分用に大量のバターサンドや海鮮スナックをカゴに放り込んでいく。','2026-06-11','16:15','🛍️','0','',-3500,1,false,'2026-06-11 16:18:40.9+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.801200000,141.651200000,'旅の最後のガソリンスタンド','レンタカーを返却する直前、満タン返しのためにスタンドへ滑り込む。大量に走り抜けたメーターの数値を見て、「めちゃくちゃ走ったな！」と謎の達成感を分かち合う。','2026-06-11','17:30','⛽','0','',-6500,1,false,'2026-06-11 17:35:15.4+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'新千歳空港でレンタカー返却','無事にトラブルもなくレンタカーを返却完了。車体にこびりついた虫の跡すらも勲章のように見えながら、空港のロビーへと足を進める。','2026-06-11','18:15','🤝','0','',0,1,false,'2026-06-11 18:18:50.22+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.821400000,141.671200000,'空港のスープカレーで締めくくり','保安検査場に入る前、最後の最後でどうしてもスープカレーが食べたくなり滑り込み。スパイスの効いた熱々のカレーを食べて、最高だった北海道ドライブ旅を締めくくる。','2026-06-11','19:00','🍛','0','',-1600,1,false,'2026-06-11 19:05:10.88+09','2026-08-01 10:04:29.495627+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'新千歳空港でレンタカーを借りる','飛行機を降りてすぐレンタカーの手続きを済ませ、ワゴン車に乗り込む。「どこ行く？」「とりあえず北へ向かおうぜ！」と、完全ノープランで男4人の珍道中がスタートする。','2026-06-10','09:30','🚗','0','',0,1,false,'2026-06-10 09:32:15.12+09','2026-08-01 10:05:26.899298+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'駅ビルで最後の締めくくりビールを飲んで帰路へ','新幹線の発車時刻の直前、駅ナカのお店で最後のお疲れ様ビールを軽く一杯引っ掛けました。「次はさらに南の福島あたりまで足を伸ばしてみるか」と次の計画に思いを馳せながら、心地よい疲労感に包まれて帰りの新幹線へと乗り込みました。','2026-09-02','18:00','🍻','0','',-1100,0,false,'2026-09-02 18:03:50.22+09','2026-08-01 10:54:11.026663+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.013000000,141.343000000,'宿のバイキングで北海道の味覚を満喫','夜ご飯はホテル内の豪華なバイキング。カニや新鮮なお寿司、目の前で焼いてくれるステーキなどをお腹いっぱい食べる。子どもたちもデザートのケーキに大満足の様子。','2026-07-20','19:30','🦀','0','',0,1,false,'2026-07-20 19:35:15.4+09','2026-08-01 10:12:13.671235+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.915000000,139.835000000,'日本海側の酒田港に到着して横断旅スタート','日本海と太平洋を横断する今回のドライブ旅の起点として、庄内・酒田エリアに男2人で降り立ちました。まずは地元のレンタカー営業所で手続きを済ませ、目の前に広がる日本海を眺めながらエンジンを始動させます。山脈を越えて太平洋側まで走り抜く壮大な計画に、朝から胸が高鳴ります。','2026-10-05','09:00','🚙','0','',0,1,false,'2026-10-05 09:32:15.12+09','2026-08-01 10:59:25.361797+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559500000,133.532200000,'城下で休憩','城下のカフェでアイスコーヒー。旅の充実感がじんわり広がる。','2026-08-11','14:00','☕','0000','',-580,1,false,'2026-08-11 14:00:00+09','2026-08-02 02:06:55.502943+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.922000000,139.841000000,'酒田の海鮮市場で朝獲れ日本海の魚介を堪能','旅の最初のイベントとして、酒田港のすぐ近くにある海鮮市場へと駆け込みました。日本海の荒波が育てた新鮮な甘エビや旬の白身魚がたっぷり乗った豪快な朝昼兼用の海鮮丼を注文します。一口食べた瞬間に広がる濃厚な甘みと弾力のある歯ごたえに、男2人で「やっぱり日本海の魚はレベルが違う…」と唸りました。','2026-10-05','10:30','🐟','0','',-2200,1,false,'2026-10-05 10:34:40.5+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.751200000,139.951200000,'庄内の平野部を抜けて内陸の山あいへ進む','日本海側の海岸線をあとにして、いよいよ本州の中央を縦断する奥羽山脈のふもとへと車を進めました。どこまでも広がる庄内平野の黄金色の田園風景を右手に眺めながら、徐々に勾配がきつくなる山道へとハンドルを切っていきます。ここから本格的な横断ドライブの幕開けです。','2026-10-05','12:00','🌾','0','',0,1,false,'2026-10-05 12:35:10.8+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.651200000,140.051200000,'新庄エリアの山あいでローカルコーヒー休憩','山越えの本格的なワインディングロードに突入する前に、山あいの静かなスポットで少し小休憩を取りました。途中で見つけた趣のある小さなカフェに立ち寄り、マスターこだわりのブレンドコーヒーをテイクアウトします。ひんやりとした山の空気を吸い込みながら、これからの険しい山越えに向けて気合を入れ直しました。','2026-10-05','13:30','☕','0','',-600,1,false,'2026-10-05 13:38:20.15+09','2026-08-01 10:59:25.361797+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'新千歳空港で家族みんなが合流','待ちに待った家族旅行のスタート。空港に到着してさっそくレンタカーを手配し、チャイルドシートを確認して車に乗り込む。子どもたちもワクワクした様子で後部座席ではしゃぎ出す。','2026-07-20','09:30','👨‍👩‍👧‍👦','0','',0,1,false,'2026-07-20 09:32:15.12+09','2026-08-01 10:12:13.671235+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅でレンタカーを借りて南下旅スタート','東北を南へ下るドライブ旅行の拠点として、朝の仙台駅に男2人で集合しました。手際よくレンタカーの手続きを済ませ、今日から始まる宮城のグルメと絶景巡りに向けてエンジンを始動させます。車内では「まずは何を食べるか」の話題で最初からテンションが最高潮です。','2026-09-01','09:00','🚙','0','',0,1,false,'2026-09-01 09:32:15.12+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.371200000,141.061200000,'日本三景・松島海岸で潮風を感じるお散歩','車を走らせて最初の目的地である日本三景・松島へと到着しました。無数の島々が浮かぶ穏やかな湾の景色を眺めながら、松の木が並ぶ海岸線をのんびりと歩きます。朝の爽やかな潮風を全身に浴びながら、これから始まる旅の無事を祈ってまずはしっかりと景色を目に焼き付けました。','2026-09-01','10:30','🌊','0','',0,1,false,'2026-09-01 10:34:40.5+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.373400000,141.065600000,'松島の名物グルメ・焼きカキをその場で堪能','松島に来たら外せない海の幸ということで、海岸沿いの炭火焼きのお店に立ち寄りました。目の前で豪快にジュージューと焼かれる大ぶりのカキを注文し、熱々を一口で頬張ります。口いっぱいに広がる濃厚な磯の旨みと香ばしさに、男2人で「これはたまらん…」と思わず顔を見合わせて感動しました。','2026-09-01','11:45','🦪','0','',-1500,1,false,'2026-09-01 11:48:20.15+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.151200000,140.751200000,'内陸へ向けて緑豊かなロードを快走ドライブ','松島をあとにして、今度は西側の内陸部である蔵王エリアへ向けて車を走らせました。徐々に街並みから豊かな緑の山あいへと景色が変わり、緩やかなカーブが続く走りやすい道路を心地よい音楽をかけながら駆け抜けます。ドライブ好きの血が騒ぐ最高の移動時間になりました。','2026-09-01','13:15','🚗','0','',0,1,false,'2026-09-01 13:18:00+09','2026-08-01 10:54:11.026663+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.323000000,141.123000000,'平泉・中尊寺の金色堂へ向けてドライブ','2日目の朝。ホテルをチェックアウトして車を南下させ、世界遺産の平泉へ。少しひんやりとした朝の空気の中、緑深い参道を3人でおしゃべりしながら歩く。','2026-09-06','09:30','🚗','0','',0,1,false,'2026-09-06 09:33:15.12+09','2026-08-01 10:27:00.927255+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.981200000,141.451200000,'北広島の大型アウトレットで寄り道','札幌へ向かう道中で、ちょっと寄り道してショッピングモールへ。家族それぞれにお揃いの帽子や夏服を選んだり、さっそく北海道のソフトクリームを食べて休憩する。','2026-07-20','11:00','🍦','0','',-2400,1,false,'2026-07-20 11:04:40.5+09','2026-08-01 10:12:13.671235+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.031200000,141.381200000,'札幌市内のスープカレーでランチ','お昼ごはんは、やっぱり本場のスープカレーを食べようと有名店へ。ゴロゴロ入った野菜と柔らかいチキンに家族みんな大満足。子ども用のマイルドな辛さもあって完食。','2026-07-20','12:30','🍛','0','',-4200,1,false,'2026-07-20 12:35:10.8+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.051200000,141.351200000,'大通公園の噴水広場でひと遊び','札幌中心部に戻り、大通公園の緑豊かな芝生や噴水の周りを家族でのんびりお散歩。子どもたちが水遊びをしたがるので、濡れないようにハラハラしつつ見守る。','2026-07-20','14:00','🌳','0','',0,1,false,'2026-07-20 14:03:20.15+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.055000000,141.348000000,'札幌市時計台の前で記念撮影','せっかくなので観光の定番である時計台へ立ち寄る。みんなで並んで「はい、チーズ！」と記念写真をパシャリ。レトロな建物の前で家族の素敵な思い出が形に残る。','2026-07-20','15:00','📷','0','',0,1,false,'2026-07-20 15:04:00+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.045000000,141.312000000,'円山動物園で動物たちを間近で見る','少し移動して、緑に囲まれた円山動物園へ。ホッキョクグマ館やゾウのエリアなどを見て回り、子どもたちが目を輝かせて大喜びしている姿を見て親としても嬉しくなる。','2026-07-20','16:00','🦁','0','',-2500,1,false,'2026-07-20 16:04:12.3+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.012000000,141.341200000,'定山渓温泉の温泉宿にチェックイン','夕方に車を走らせて、札幌の奥座敷である定山渓温泉へ到着。広々とした和室の部屋に荷物を置き、旅の疲れを癒やすためにさっそく家族みんなで温泉の大浴場へ向かう。','2026-07-20','18:00','♨️','0','',-28000,1,false,'2026-07-20 18:05:40.9+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.012000000,141.341200000,'温泉街の夜をのんびりお散歩','夕食のあとは、浴衣を着て家族一緒に温泉街の川沿いを少しお散歩。夜風がとても心地よく、ライトアップされた渓流の景色を眺めながらゆったりとした時間を過ごす。','2026-07-20','21:00','🌙','0','',0,1,false,'2026-07-20 21:04:50.22+09','2026-08-01 10:12:13.671235+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.841640000,132.765300000,'松山駅に移動','電車で松山へ。駅前の落ち着いた雰囲気が心地よい。','2026-08-12','09:00','🚉','0000','',0,1,false,'2026-08-12 09:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.021200000,141.321200000,'翌朝、定山渓の自然の中をドライブ出発','2日目の朝。朝風呂ですっきり目覚めたあと、宿をチェックアウトして再び車に乗り込む。窓から見える木々の緑と綺麗な川の景色に癒やされながら車を走らせる。','2026-07-21','09:00','🚗','0','',0,1,false,'2026-07-21 09:03:15.12+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.031200000,141.251200000,'白い恋人パークでお菓子作り見学','子どもたちのリクエストで「白い恋人パーク」に到着。お菓子の甘い香りに包まれながら、工場見学をしたり可愛い中庭の景色を見て回る。お土産のチョコレートもたくさん買う。','2026-07-21','10:30','🍫','0','',-1800,1,false,'2026-07-21 10:34:40.5+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.081200000,141.371200000,'サッポロビール園で名物ランチ','お昼はちょっと贅沢にサッポロビール園の大きなホールへ。ジューシーなジンギスカンをみんなでワイワイ焼きながら食べる。お肉が柔らかくて箸が止まらない。','2026-07-21','12:30','🍖','0','',-5500,1,false,'2026-07-21 12:35:10.8+09','2026-08-01 10:12:13.671235+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.061200000,141.411200000,'モエレ沼公園の広大なアートを満喫','イサム・ノグチがデザインした広大なモエレ沼公園へ。ガラスのピラミッドを見たり、大きな山の上から札幌の街並みを眺めたりして、子どもたちは芝生を思い切り駆け回る。','2026-07-21','14:15','⛰️','0','',0,1,false,'2026-07-21 14:18:20.15+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.812300000,141.651200000,'新千歳空港でお土産を大量買い出し','楽しかった旅行も終盤。早めに空港へ戻り、大きなお土産売り場で定番のバターサンドや海鮮弁当、チーズケーキなどを家族みんなで吟味してカゴいっぱいに買い込む。','2026-07-21','16:30','🛍️','0','',-6000,1,false,'2026-07-21 16:35:00+09','2026-08-01 10:12:13.671235+09'),
	 (6,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'家族みんなで笑顔で帰路へ','レンタカーを無事に返却し、出発ロビーへ。たくさん遊んで少し疲れた子どもたちがウトウトし始める中、「また来年も家族みんなで来ようね」と話し合って飛行機に乗り込む。','2026-07-21','18:30','✈️','0','',0,0,false,'2026-07-21 18:35:10.88+09','2026-08-01 10:12:13.671235+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅に到着して食いしん坊旅スタート','朝の新幹線で盛岡駅に無事に3人集合。改札を出た瞬間から「お昼は何食べる？」と食のことで頭がいっぱいの3人。テンション高めでレンタカーに乗り込む。','2026-09-05','09:30','🚅','0','',0,1,false,'2026-09-05 09:32:15.12+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.701000000,141.152000000,'盛岡城跡公園をのんびりお散歩','最初の目的地として、緑豊かな盛岡城跡公園の石垣を眺めながらお散歩。これからの食べ歩きに備えて、まずはしっかり歩いてお腹のスペースを空けておく。','2026-09-05','10:30','🌳','0','',0,1,false,'2026-09-05 10:34:40.5+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.703000000,141.141000000,'老舗の盛岡冷麺でランチ','お昼ごはんはやっぱり外せない盛岡冷麺の有名店へ。透き通るコシのある麺とコクのあるスープ、別盛りのキムチを少しずつ入れながら、その美味しさに3人とも無言で夢中になる。','2026-09-05','12:00','🍜','0','',-3300,1,false,'2026-09-05 12:35:10.8+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.704000000,141.143000000,'おしゃれなレトロカフェでデザート休憩','冷麺のあとはすぐ近くの古民家カフェへ移動。自家製の季節のフルーツタルトとカフェラテを頼み、甘いものは別腹と言いながらペロリと完食して女子トークに花を咲かせる。','2026-09-05','13:45','🍰','0','',-2100,1,false,'2026-09-05 13:48:20.15+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.706000000,141.161000000,'盛岡の名所・石割桜を見物','大きな岩の割れ目から力強く育っている天然記念物の石割桜を見学。自然の生命力に感動しつつ、記念にお互いの写真を撮り合ってワイワイ楽しむ。','2026-09-05','15:15','🌸','0','',0,1,false,'2026-09-05 15:18:00+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.701500000,141.138000000,'福わらしなどの可愛い雑貨屋さん巡り','中心街に戻り、可愛い民芸品や地元の作家さんの雑貨が並ぶお店を覗く。お揃いの南部鉄器の小さな小皿や、可愛いキーホルダーを見つけてみんなでお買い上げ。','2026-09-05','16:30','🛍️','0','',-2500,1,false,'2026-09-05 16:35:40.9+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702500000,141.137000000,'盛岡市内の温泉付きホテルにチェックイン','今日の宿泊先であるホテルに到着。すっきりと綺麗なお部屋に荷物を置いて、夜のメインイベントに向けて少し早めに温泉に入ってさっぱりリフレッシュする。','2026-09-05','18:00','♨️','0','',-18000,1,false,'2026-09-05 18:04:50.22+09','2026-08-01 10:27:00.927255+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.703500000,141.139000000,'牛タンと県産牛の炭火焼き専門店で夕食','待ちに待った夜ご飯！厚切りでジューシーな牛タンの炭火焼きと、とろけるような岩手県産牛のステーキを贅沢にオーダー。香ばしい匂いと抜群の美味しさに3人とも大興奮。','2026-09-05','19:30','🥩','0','',-7500,1,false,'2026-09-05 19:35:15.4+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702500000,141.137000000,'夜の繁華街で地酒を軽く一杯','夕食のあともおしゃべりが止まらず、隠れ家風のバーへ移動。岩手の地酒やおしゃれなカクテルを飲みながら、今日の楽しかった出来事を振り返って夜遅くまで笑い合う。','2026-09-05','21:30','🥂','0','',-3000,1,false,'2026-09-05 21:35:10.88+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.324000000,141.109000000,'中尊寺の金色堂を見学','荘厳な雰囲気に包まれた金色堂へ到着。金ピカに輝く堂内の美しさに圧倒されながら、「すごいね……」と思わず静かに見入ってしまう。歴史のロマンを肌で感じる。','2026-09-06','10:30','⛩️','0','',-800,1,false,'2026-09-06 10:34:40.5+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.321000000,141.115000000,'平泉レストハウスでご当地おやつ','たくさん歩いて小腹が空いたので、平泉のレストハウスへ立ち寄る。名物の「餅パフェ」や、香ばしい胡麻だれがかかったお餅を3人でシェアして食べる。これが想像以上の美味しさ。','2026-09-06','12:00','🍡','0','',-1200,1,false,'2026-09-06 12:03:20.15+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.482300000,141.123400000,'道の駅で岩手のお土産を大量買い出し','盛岡へ戻る道中、大きめの道の駅にピットイン。ずらりと並んだ新鮮な野菜や、ごまのクッキー、りんごを使ったお菓子などを「これ美味しそう！」とカゴにどんどん入れていく。','2026-09-06','14:00','🛍️','0','',-4000,1,false,'2026-09-06 14:04:00+09','2026-08-01 10:27:00.927255+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅ビルで最後の名物ランチ','旅の締めくくりとして盛岡駅ビルへ戻り、最後のランチは「じゃじゃ麺」に挑戦。最後に卵を割ってスープを入れる「チータンタン」までしっかり完食して大満足。','2026-09-06','16:00','🍳','0','',-1500,1,false,'2026-09-06 16:03:10.8+09','2026-08-01 10:27:00.927255+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559705000,133.531110000,'高知駅に到着','南国の空気がふわっと広がる高知駅。駅前のヤシの木が旅のテンションを一気に上げてくれる。','2026-08-04','09:20','🚉','0000','',0,1,false,'2026-08-04 09:20:00+09','2026-08-02 01:58:27.047402+09'),
	 (8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅から名残惜しく帰路へ','レンタカーを無事に返却し、お土産の詰まった大きな紙袋を抱えて新幹線のホームへ。あっという間の2日間を振り返り、「また次の食いしん坊旅も絶対計画しようね！」と笑顔で手を振って別れた。','2026-09-06','18:00','👋','0','',0,0,false,'2026-09-06 18:03:50.22+09','2026-08-01 10:27:00.927255+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.121200000,140.451200000,'蔵王エコーラインを登りダイナミックな景色へ','さらに標高をぐんぐん上げていき、宮城と山形を繋ぐ本格的な山岳道路「蔵王エコーライン」へと突入しました。幾重にも重なる山々の大パノラマや、急勾配を力強く登っていくエンジンの唸り音にワクワクが止まりません。標高が高くなるにつれて空気がひんやりとしてきて一気に涼しくなります。','2026-09-01','14:45','⛰️','0','',0,1,false,'2026-09-01 14:48:12.3+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.141200000,140.441200000,'蔵王のシンボル・神秘の「御釜」を見学','山頂近くの駐車場に車を停めて、エメラルドグリーンの美しい火口湖「御釜」を見に行きました。荒々しい岩肌の中にぽっかりと浮かぶ神秘的なエメラルドの湖面を目の当たりにして、大自然の生み出した芸術的な絶景にしばらくと言葉を失って見入ってしまいました。','2026-09-01','16:00','✨','0','',-500,1,false,'2026-09-01 16:04:10.8+09','2026-08-01 10:54:11.026663+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.131200000,140.481200000,'遠刈田温泉の風情ある温泉宿にチェックイン','山を下りて、今日の宿泊地である遠刈田温泉の温泉街へと到着しました。昔ながらの湯の街情緒が残る素敵な温泉宿にチェックインし、広めの和室に荷物を置いて一息つきます。さっそく名物の源泉掛け流しの大浴場へ向かい、ドライブの冷えと疲れをじっくりと芯から癒やしました。','2026-09-01','18:00','♨️','0','',-16000,1,false,'2026-09-01 18:04:50.22+09','2026-08-01 10:54:11.026663+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.585000000,140.455000000,'津軽藩ねぷた村で文化体験と大きなお土産選び','伝統的なねぷたの山車がずらりと展示されている津軽藩ねぷた村に立ち寄りました。迫力あるお祭りの雰囲気を間近で感じられたほか、子どもたちは可愛いリンゴの形をした民芸品や地元の特産品に夢中になっていました。お土産のコーナーでもたくさんのりんごお菓子をカゴに入れて大満足の様子でした。','2026-10-10','16:45','🏮','0','',-1800,1,false,'2026-10-10 16:48:12.3+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.630000000,140.300000000,'岩木山のふもとにある温泉宿にチェックイン','夕方に車を走らせて、雄大な岩木山のふもとにひっそりと佇む温泉宿に到着しました。広々とした和室の客室に荷物を置き、旅の疲れをしっかりと癒やすために家族みんなで大浴場へ直行しました。温かい温泉にゆっくり浸かると、日頃の忙しさがすーっと溶けていくような最高の心地よさを味わえました。','2026-10-10','18:30','♨️','0','',-32000,1,false,'2026-10-10 18:35:15.4+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.631000000,140.302000000,'宿の豪華な郷土料理とリンゴを使った夕食','夜ご飯はホテル内のレストランで、青森の美味しい食材をふんだんに使った豪華な夕食をいただきました。郷土料理の貝焼き味噌や新鮮なお刺身はもちろん、デザートや料理の隠し味に使われたリンゴの風味を存分に楽しみました。家族でお酒やジュッチを片手に、今日一日楽しかった思い出を語り合いながら最高な夜を過ごしました。','2026-10-10','20:00','🥂','0','',0,1,false,'2026-10-10 20:04:50.22+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.620000000,140.350000000,'2日目の朝、岩木山を眺める爽快ドライブ','2日目の朝は朝風呂ですっきりと目覚め、宿をチェックアウトして再び車に乗り込みました。目の前にそびえ立つ美しい岩木山の姿を眺めながら、整備された気持ちの良い農免道路をドライブします。澄んだ朝の空気がとても美味しくて、車内では子どもたちも元気いっぱいに歌を歌っていました。','2026-10-11','09:00','⛰️','0','',0,1,false,'2026-10-11 09:03:15.12+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.590000000,140.380000000,'観光農園で待ちに待ったりんご狩り体験','今回の旅行の最大メインイベントである観光農園でのリンゴ狩りにやってきました。農園のおじさんに美味しい品種の見分け方を教わりながら、木に実った真っ赤なリンゴを自分の手で丁寧に収穫します。太陽の光をたっぷり浴びた採れたてのリンゴをその場でかじると、シャキッとした食感と濃厚な果汁が口いっぱいに広がって感動しました。','2026-10-11','10:30','🍏','0','',-2500,1,false,'2026-10-11 10:34:40.5+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.610000000,140.450000000,'りんご公園で大きなすべり台とピクニック','収穫のあとは、たくさんのリンゴの木が植えられた広大な「弘前アップル公園」へ移動しました。広い芝生の上で子どもたちは思い切り走り回り、リンゴをモチーフにした遊具やすべり台で大はしゃぎです。青空の下で食べるおやつもいつもより格別に美味しく感じられ、家族みんなの笑顔がたくさんあふれる時間になりました。','2026-10-11','12:00','🏃‍♂️','0','',0,1,false,'2026-10-11 12:03:20.15+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.824300000,140.740000000,'青森空港に到着してレンタカーで出発','待ちに待った青森への家族旅行がいよいよスタートしました。飛行機を降りてすぐにレンタカーの手続きを済ませ、チャイルドシートに子どもたちを乗せて出発進行。車窓から見える景色がいつもと違う北国の雰囲気で、家族みんなのテンションが一気に上がっていきます。','2026-10-10','09:30','🍎','0','',0,1,false,'2026-10-10 09:32:15.12+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.832000000,140.735000000,'青森市内の市場で名物の海鮮丼朝食','朝早くから移動してお腹がペコペコだったので、地元の活気ある市場へ立ち寄りました。新鮮なホタテやマグロがこれでもかと乗った贅沢な海鮮丼を家族みんなで注文し、一口食べるごとに「美味しいね！」と笑顔がこぼれます。朝から大満足の最高の食べ始めになりました。','2026-10-10','11:00','🦀','0','',-4500,1,false,'2026-10-10 11:04:40.5+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.607000000,140.463000000,'弘前市へ向かうドライブとリンゴ並木','青森市内から車を走らせて、りんごの街として知られる弘前市周辺へと移動しました。道路の両側に広がる果樹園には、真っ赤に色づいたたくさんのりんごがたわわに実っており、窓を開けるとふんわりと甘い香りが漂ってきてドライブが一層楽しくなります。','2026-10-10','12:30','🚗','0','',0,1,false,'2026-10-10 12:35:10.8+09','2026-08-01 10:34:41.94158+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.598000000,140.472000000,'弘前観光の定番・弘前公園をのんびり散策','立派な石垣と豊かな緑に囲まれた弘前公園を家族みんなでのんびりとお散歩しました。お堀の水面に映る美しい景色を眺めながら歩いていると心地よい秋風が吹き抜けていき、歴史あるお城の雰囲気を肌で感じながらリフレッシュできる素晴らしい時間を過ごせました。','2026-10-10','14:00','🌳','0','',0,1,false,'2026-10-10 14:03:20.15+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.601000000,140.465000000,'おしゃれなカフェで弘前アップルパイを堪能','歩き疲れたので、街で見つけたレトロでおしゃれなカフェへと滑り込みました。青森といえばやっぱりアップルパイということで、サクサクのパイ生地と甘酸っぱいリンゴのコンポートが絶妙な一品を注文。温かい紅茶とともに味わい、家族みんなで「今まで食べた中で一番美味しいね」と大絶賛でした。','2026-10-10','15:30','🥧','0','',-2400,1,false,'2026-10-10 15:34:00+09','2026-08-01 10:34:41.94158+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅でレンタカーを借りて三陸へ出発','美味しい魚介を腹一杯食べるために、男2人で仙台駅に集合しました。さっそくレンタカーの手続きを済ませて、今日からの爆食ドライブ旅行に向けてエンジンを始動させます。車内では「まずは何の海鮮を食べるか」の話題で最初から大盛り上がりです。','2026-11-05','09:00','🚙','0','',0,1,false,'2026-11-05 09:32:15.12+09','2026-08-01 10:39:14.245601+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.605000000,140.468000000,'弘前市内の老舗洋食店でご当地ランチ','お昼ごはんは、地元で長く愛されているレトロな洋食屋さんに入って少し早めのランチにしました。デミグラスソースがたっぷりとかかったハンバーグや、青森の食材を使ったボリューム満点のメニューをお腹いっぱい堪能しました。お店の温かい雰囲気も含めて、とても居心地が良くて大満足のランチタイムでした。','2026-10-11','13:30','🍛','0','',-3800,1,false,'2026-10-11 13:35:00+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.750000000,140.580000000,'道の駅でさらなるお土産と限定ジュースを調達','青森空港へ戻る道すがら、大きな道の駅に立ち寄って最後のお土産の買い出しを行いました。ずらりと並んだ色々な種類の100%リンゴジュースの飲み比べパックや、家族や友人向けのお菓子をカゴいっぱいに詰め込みました。レジのおばちゃんとの方言まじりの温かいやり取りにも、旅の良さをしみじみと感じました。','2026-10-11','15:00','🛍️','0','',-5000,1,false,'2026-10-11 15:04:12.3+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.824000000,140.738000000,'青森空港へ戻りレンタカーを無事に返却','楽しかった1泊2日のドライブ旅行もいよいよ終盤となり、無事に青森空港のレンタカー営業所へと車を返却しました。車体にたくさん思い出を乗せて走ってくれた車にお礼を言いながら、お土産がぎっしり詰まった重たい荷物を持って出発ロビーへと向かいました。あっという間の時間で名残惜しさがこみ上げます。','2026-10-11','16:45','🤝','0','',-6500,1,false,'2026-10-11 16:48:50.22+09','2026-08-01 10:34:41.94158+09'),
	 (9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.824300000,140.740000000,'保安検査場を通り家族みんなで帰路へ','最後に空港の売店で名残惜しくソフトクリームを食べたあと、保安検査場を通って帰りの飛行機へと乗り込みました。たくさん遊んで少し疲れた子どもたちがすぐにウトウト眠り始める中、スマホの写真フォルダを見返しつつ「また来年も家族で青森のりんごを食べに来ようね」と優しく話しながら帰路につきました。','2026-10-11','17:30','✈️','0','',0,0,false,'2026-10-11 17:35:10.88+09','2026-08-01 10:34:41.94158+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.833129000,132.876512000,'庄原の田園を眺める','道の駅近くの田園は広く、風が通り抜ける音が心地よい。ゆっくり歩きながら景色を眺めると、庄原らしい穏やかな時間が流れる。旅の終盤にふさわしい静かな場所だった。','2026-10-22','15:30','🌾','0000','',0,1,false,'2026-10-22 15:30:00+09','2026-10-22 15:30:00+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.132500000,140.483000000,'温泉街の居酒屋で宮城の地酒と美食を堪能','夜ご飯は温泉街を少し歩いて、地元で人気の隠れ家風居酒屋へ繰り出しました。宮城の新鮮なお刺身や地元の食材を使ったおつまみを頼みつつ、辛口でキリッとした宮城の銘酒を次々と合わせます。仕事の話やこれからの人生計画について、男同士で夜遅くまでグラスを傾けながら熱く語り合いました。','2026-09-01','19:45','🍶','0','',-5500,1,false,'2026-09-01 19:48:15.4+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.051200000,140.691200000,'2日目の朝、豊かな田園風景を眺めながら南下','2日目の朝は朝風呂ですっきりと目覚め、宿をあとにしてさらに南の白石エリアへと車を走らせました。見渡す限りの黄金色の田園風景が広がる農免道路を、朝の澄んだ空気を感じながら気持ちよく走ります。車の流れもスムーズで、最高の朝のドライブタイムを満喫しました。','2026-09-02','09:15','🌾','0','',0,1,false,'2026-09-02 09:18:15.12+09','2026-08-01 10:54:11.026663+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.081200000,140.621200000,'歴史ある白石城の白亜の天守閣を見学','伊達政宗の重臣・片倉小十郎の居城として知られる白石城に立ち寄りました。綺麗に復元された美しい白亜の天守閣を見上げながら、歴史のロマンに思いを馳せます。最上階からの眺望も素晴らしく、周辺の城下町の様子を一望しながら静かな時間を過ごしました。','2026-09-02','10:45','🏯','0','',-600,1,false,'2026-09-02 10:48:40.5+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'再び仙台市内に戻りお昼は本場の牛タンランチ','再び車を北へ走らせて仙台市内の中心街へと戻り、旅のメインの一つである本場の牛タンを食べるために有名店へ飛び込みました。分厚くカットされながらも驚くほど柔らかくジューシーな炭火焼き牛タンと、麦飯、テールスープの王道セットを夢中で平らげます。「やっぱり仙台の牛タンは格別だな」と大満足でした。','2026-09-02','13:00','🥩','0','',-2800,1,false,'2026-09-02 13:04:10.8+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.251200000,140.861200000,'仙台のシンボル・青葉城址で伊達政宗公像と対面','ランチのあとは、仙台市街を一望できる青葉城址（仙台城跡）へと足を伸ばしました。馬に跨ったお馴染みの伊達政宗公の銅像の前に立ち、眼下に広がる広大な仙台の街並みを眺めます。かつての伊達60万石の威厳を肌で感じつつ、青空の下で記念写真を撮影して思い出をしっかりと残しました。','2026-09-02','14:30','⛩️','0','',0,1,false,'2026-09-02 14:35:20.15+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.261200000,140.871200000,'市内の老舗お土産店でずんだスイーツを堪能','帰りの新幹線の時間まで少し余裕があったので、仙台名物の「ずんだ」を味わうために甘味処へ立ち寄りました。つぶつぶとした枝豆の風味豊かな特製ずんだシェイクと、甘さ控えめのずんだ餅を注文して小休憩。最後まで宮城のローカルグルメを徹底的に満喫して、お腹もすっかり大満足です。','2026-09-02','15:45','🍵','0','',-900,1,false,'2026-09-02 15:48:00+09','2026-08-01 10:54:11.026663+09'),
	 (12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅に戻りレンタカーを無事に返却','2日間のドライブ旅行もいよいよフィナーレとなり、仙台駅近くの営業所へ戻ってレンタカーを無事に返却しました。大きなトラブルもなく快適に走り切ってくれた相棒に感謝しつつ、お土産の詰まった重たい荷物を持って駅のコンコースへと向かいます。あっという間の充実した時間でした。','2026-09-02','17:00','🤝','0','',-6500,1,false,'2026-09-02 17:04:12.3+09','2026-08-01 10:54:11.026663+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720000000,135.980000000,'新宮市内的ビジネスホテルにチェックイン','男旅らしくリーズナブルなホテルにチェックイン。荷物を置いて、夜の宴会とさらなるラーメンに向けて準備。','2026-10-10','18:00','🏨','0','',-8000,1,false,'2026-10-10 18:30:00+09','2026-08-01 21:17:55.265904+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.451200000,140.351200000,'奥羽山脈を横断する峠道をダイナミックに疾走','山形と宮城の県境を跨ぐダイナミックな山岳道路へと突入しました。幾重にも折り重なる急カーブを、マニュアル感覚のシフトチェンジで力強くクリアしながら標高を上げていきます。窓の外には見渡す限りの深い原生林が広がり、エンジンの心地よいエキゾーストノートが山々に響き渡る最高のドライビングロードです。','2026-10-05','15:00','⛰️','0','',0,1,false,'2026-10-05 15:04:00+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.351200000,140.651200000,'山を越えて太平洋側・鳴子峡の絶景に感動','険しい峠道を無事に抜け出し、ついに太平洋側の宮城サイドへと突入しました。東北屈指の紅葉名所としても知られる「鳴子峡」の巨大なV字谷の展望スポットに車を停め、目の前に広がる大迫力の断崖絶壁と深い谷底の景色に圧倒されます。日本海から太平洋へと本当にやってきたんだという実感が湧いてきました。','2026-10-05','16:30','✨','0','',0,1,false,'2026-10-05 16:34:12.3+09','2026-08-01 10:59:25.361797+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401200000,138.801200000,'富士スバルラインを登り五合目へ到着','日本最高峰の富士山登頂に挑むため、男2人でレンタカーを走らせて富士スバルラインを登り、登山の拠点となる富士山五合目へと到着しました。標高が一気に上がり、ひんやりとした澄んだ空気の中で登山靴の紐をしっかりと締め直します。これから始まる過酷で最高な挑戦に向けて、胸の高鳴りが最高潮に達しました。','2026-08-05','08:30','🚙','0','',-2100,1,false,'2026-08-05 08:34:15.12+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.361200000,138.731200000,'吉田口の登山道からいよいよアタック開始','準備を万全にして、いよいよ吉田口の登山口から本格的な登山道へと足を踏み入れました。最初はなだらかな樹林帯を進みつつ、徐々に傾斜がきつくなっていく道のりを一歩一歩確実に進んでいきます。すれ違う下山者と「こんにちは！」と声を掛け合いながら、男2人で気合を入れてペースを維持します。','2026-08-05','09:45','🥾','0','',0,1,false,'2026-08-05 09:48:40.5+09','2026-08-01 11:10:50.466944+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.365000000,138.735000000,'急な岩場を登り七合目の山小屋で小休憩','標高が上がり、周囲が火山性のゴツゴツとした岩場に変わってきたところで、七合目の山小屋に到着しました。少し冷えてきた体を休めるために小屋のベンチで温かいお湯を飲み、標高の高さによる息切れを整えつつ、目の前に広がり始めた見事な雲海の景色を眺めてエネルギーを補給しました。','2026-08-05','12:30','⛰️','0','',-800,1,false,'2026-08-05 12:35:10.8+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.363000000,138.729000000,'八合目の山小屋に到着して一時待機と夕食','夕方に八合目の山小屋へ無事に到着し、明日の早朝アタックに向けた体力温存と高所順応のための小休止を取りました。簡易的な夕食をかき込みながら、窓の外に沈む幻想的な夕日と、眼下に広がる街の明かりを眺めます。標高3000メートルを超える圧倒的なスケール感に、男2人で静かに感動しました。','2026-08-05','17:00','🌅','0','',-8500,1,false,'2026-08-05 17:04:20.15+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.360600000,138.727400000,'真夜中の山小屋を出発し山頂アタック開始','まだ辺りが真っ暗な夜中、ヘッドライトの灯りを頼りに八合目の山小屋を出発して最後の山頂アタックへ踏み出しました。一歩一歩足元を確認しながら急勾配の九十九折を進みます。満天の星空と眼下に広がる街の夜景の美しさが、過酷な登攀のつらさを忘れさせてくれる最高の励みになりました。','2026-08-06','02:00','✨','0','',0,1,false,'2026-08-06 02:04:00+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.360600000,138.727400000,'ついに富士山剣ヶ峰の山頂へ登頂成功','過酷な登りを耐え抜き、ついに日本最高峰である富士山頂（剣ヶ峰）へと足を踏み入れました。東の空からゆっくりと昇ってくる神々しい「ご来光」を目の当たりにし、言葉を失うほどの感動が全身を包み込みます。「やり遂げたな！」と男2人で固い握手を交わし、忘れられない最高の瞬間を噛み締めました。','2026-08-06','04:45','☀️','0','',0,1,false,'2026-08-06 04:48:12.3+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.361000000,138.730000000,'山頂の売店で温かいカップ麺をすする','登頂の達成感に浸りながら、山頂にある売店で販売されている名物の温かいカップ麺を注文しました。標高3776メートルの極寒の空気の中で食べるアツアツの汁物が、疲労した体に染み渡るように美味しくて感動します。こんな贅沢な食事はほかにありません。','2026-08-06','05:30','🍜','0','',-800,1,false,'2026-08-06 05:34:12.3+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.362000000,138.732000000,'火山灰の続く道を慎重に下山開始','山頂での感動的な時間を満喫したあとは、足元に気をつけながら長い下山道へと入りました。砂走りやザクザクとした火山灰の斜面をバランスを取りながら慎重に下っていきます。疲労がピークに達した足に鞭を打ちつつ、声を掛け合って一歩ずつ着実に下を目指しました。','2026-08-06','06:45','🥾','0','',0,1,false,'2026-08-06 06:48:50.22+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401200000,138.801200000,'無事に五合目へ下山しレンタカーに乗り込む','長い下山路をようやく歩ききり、出発地点である五合目の登山口へと無事に戻ってきました。無事に登頂を果たして戻ってきた愛車を見た瞬間、心地よい達成感と安堵感が一気にこみ上げてきます。重いザックをトランクに積み込み、麓の温泉街へと車を発進させました。','2026-08-06','11:30','🤝','0','',0,1,false,'2026-08-06 11:35:15.12+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.451200000,138.781200000,'麓の温泉施設で登山の手足を徹底的に癒やす','山を下りて河口湖周辺にある日帰り温泉施設へ直行しました。広々とした露天風呂から富士山の姿を眺めながら、登山でパンパンに張った筋肉と疲れた体をゆっくりとほぐしていきます。「本当によく頑張ったな」と湯船に浸かりながら男2人でしみじみと語り合う、至福の回復タイムになりました。','2026-08-06','13:00','♨️','0','',-1200,1,false,'2026-08-06 13:04:40.5+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.501200000,138.761200000,'富士吉田の老舗で名物の吉田うどんを食らう','お腹がペコペコになった状態で、コシが強くて有名な富士吉田のローカルうどん店に入りました。力強い手打ち麺とキャベツや馬肉が入った濃厚なスープの「吉田のうどん」を夢中ですすり上げます。登山で疲労した体に塩分と炭水化物がガツンとダイレクトに染み渡り、最高のエネルギーチャージになりました。','2026-08-06','14:45','🍲','0','',-900,1,false,'2026-08-06 14:48:20.15+09','2026-08-01 11:10:50.466944+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.724000000,135.988000000,'3軒目：夜の〆に食べる絶品こってり豚骨ラーメン','居酒屋で盛り上がった後の深夜、男子会の定番である「〆のラーメン」を求めて深夜営業の店へ。背脂たっぷりがたまらない。','2026-10-10','22:00','🍻','0','',-1000,1,false,'2026-10-10 22:30:00+09','2026-08-01 21:17:55.265904+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.503400000,138.755000000,'新倉山浅間公園で五重塔と富士山の絶景を撮影','登頂の記念と記録を兼ねて、世界的に有名な絶景スポットである新倉山浅間公園へと立ち寄りました。階段を少し登った先にある展望デッキから、朱色の五重塔と雄大な富士山が綺麗に重なる圧巻の景色をカメラに収めます。自分たちがさっきまであのてっぺんにいたんだという実感が再び湧いてきました。','2026-08-06','16:15','📷','0','',0,1,false,'2026-08-06 16:18:00+09','2026-08-01 11:10:50.466944+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.411200000,141.101200000,'日本三景・松島海岸で海風を浴びる','太平洋側のルートを進み、まずは日本三景の松島に立ち寄りました。美しい島々が浮かぶ湾の景色を眺めながら、海の香りが漂う海岸沿いを少しお散歩します。これからの食い倒れ旅に向けて、まずは景勝地でしっかりと気分を高めておきます。','2026-11-05','10:30','🌊','0','',0,1,false,'2026-11-05 10:34:40.5+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.512300000,141.312300000,'石巻の市場で豪快な海鮮丼の昼食','お昼どきに合わせて石巻の市場周辺に到着し、地元で人気の海鮮食堂へ飛び込みました。丼からはみ出るほど分厚いマグロや新鮮な旬の地魚が乗った特製海鮮丼を注文し、男2人で夢中になってかき込みます。一口食べるごとに感動の歓声が漏れるほどの絶品でした。','2026-11-05','12:15','🐟','0','',-2600,1,false,'2026-11-05 12:35:10.8+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.745600000,141.456700000,'南三陸の海沿いワインディングロードを疾走','さらに北へと車を走らせ、三陸のリアス式海岸が続くダイナミックな道路へと入っていきました。青い海をすぐ右手に見下ろしながら、心地よいエンジンの音を響かせてワインディングロードを駆け抜けます。ドライブ好きの血が騒ぐ最高のシチュエーションです。','2026-11-05','14:00','🚗','0','',0,1,false,'2026-11-05 14:03:20.15+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.901200000,141.678900000,'気仙沼の魚市場で活気ある雰囲気を満喫','水揚げ量で有名な気仙沼の魚市場周辺に立ち寄りました。港町ならではの活気に満ちた雰囲気を肌で感じつつ、水産加工品のお店を覗いてお土産の目星をつけます。海を知り尽くした街の力強さに男2人で圧倒されました。','2026-11-05','15:30','⚓','0','',0,1,false,'2026-11-05 15:34:00+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.278900000,141.912300000,'大船渡の海辺にある温泉宿にチェックイン','夕暮れ時に今日の宿泊先である大船渡の温泉ホテルに到着しました。お部屋に荷物を放り出し、冷えた体を温めるためにさっそくオーシャンビューの大浴場へ向かいます。窓の外に広がる夕暮れの海を眺めながら浸かる温泉は格別の心地よさでした。','2026-11-05','18:15','♨️','0','',-16000,1,false,'2026-11-05 18:35:15.4+09','2026-08-01 10:39:14.245601+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.823144000,132.873912000,'庄原市街へ戻る','市街へ戻る道は平坦で歩きやすく、ゆっくり進むと今日の出来事が自然と頭に浮かんだ。庄原の静けさと三次の町並みが心に残り、落ち着いた旅になったと感じた。','2026-10-22','16:00','🚶','0000','',0,1,false,'2026-10-22 16:00:00+09','2026-10-22 16:00:00+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.279500000,141.913500000,'三陸の海の幸を肴に地酒で熱い夜宴会','お待ちかねの夕食は、三陸で獲れたアワビやホタテ、カキなどの豪華な網焼きと刺身の舟盛りが登場しました。地元のキリッとした日本酒を片手に、海の男たちの豪快な料理を次々と平らげていきます。これまでの仕事のことやこれからの人生について、男同士で夜遅くまで語り合いました。','2026-11-05','20:00','🍶','0','',-7500,1,false,'2026-11-05 20:04:50.22+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.812300000,141.956700000,'宮古市内の老舗食堂で磯ラーメンをすする','お昼ごはんは地元で長年愛されているローカル食堂に入り、名物の「磯ラーメン」を注文しました。ウニやワカメ、フノリといった海の幸のダシがこれでもかと効いた黄金色の塩スープが体に染み渡ります。麺と一緒に海の風味を余すところなくすすり上げて大満足のランチでした。','2026-11-06','13:15','🍜','0','',-1200,1,false,'2026-11-06 13:35:00+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.123400000,141.812300000,'久慈の道の駅で海の特産品を爆買い','さらに北上して、あまちゃんの舞台としても知られる久慈市の道の駅へピットインしました。新鮮な海の珍味や、瓶詰めのウニ、地元の海苔などを「これは絶対うまいやつだ」とカゴにどんどん放り込んでいきます。旅の終わりに向けてお土産の荷物がすごいことになりました。','2026-11-06','15:00','🛍️','0','',-5500,1,false,'2026-11-06 15:04:12.3+09','2026-08-01 10:39:14.245601+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅へ戻りレンタカーを無事に返却','三陸海岸を大満喫したあとは内陸へ抜けて盛岡駅近くの営業所へ戻り、レンタカーを無事に返却しました。たくさんの思い出と大量の海鮮土産を積んで無事故で走り切ってくれた相棒に感謝しつつ、新幹線の改札へと向かいます。','2026-11-06','17:30','🤝','0','',-6500,1,false,'2026-11-06 17:48:50.22+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'駅ナカで最後の締めくくりに一杯やって帰路へ','新幹線の発車時刻まで少し時間があったので、駅ビルのお店で最後のお疲れ様ビールと地元の旬の刺身を少しだけつまむ。「やっぱり三陸の魚は最高だったな」と振り返りながら、心地よい疲労感に包まれて帰りの新幹線へと乗り込みました。','2026-11-06','18:30','🍻','0','',-2100,0,false,'2026-11-06 18:35:10.88+09','2026-08-01 10:39:14.245601+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.027185424,141.813840866,'三陸の海岸線を望む絶景スポットへ寄り道','ドライブの途中で見つけた見晴らしの良い展望台に車を停めました。切り立った崖とどこまでも広がる太平洋の水平線を眺め、大自然のスケールの大きさに思わず息を呑みます。男同士で並んで海風に吹かれながら、贅沢なコーヒーブレイクを楽しみました。','2026-11-05','16:45','☕','0','',-300,1,false,'2026-11-05 16:48:12.3+09','2026-08-01 10:39:49.866597+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.468203628,141.950397491,'2日目の朝、釜石の海沿いを快走ドライブ','2日目の朝もスッキリと目覚め、ホテルを後にしてさらに北上を続けます。朝の澄んだ空気の中、道路のすぐ脇に広がる穏やかな海の景色を相棒に車を走らせます。車の少ない早朝の海岸線ドライブは、開放感抜群で最高の気分転換になりました。','2026-11-06','09:00','🌊','0','',0,1,false,'2026-11-06 09:03:15.12+09','2026-08-01 10:40:08.087351+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.629490256,141.966705322,'道の駅で名物のホタテとウニをその場で実食','途中で立ち寄った海沿いの大きな道の駅で、朝ごはんに匹敵するサブランチを狙いました。店頭の網でジュージューと香ばしい音を立てて焼かれている巨大なホタテ焼きと、新鮮なウニの串焼きをその場でオーダー。一口食べた瞬間に広がる磯の香りと濃厚な旨みに、男2人で思わず唸ってしまいました。','2026-11-06','10:30','🐚','0','',-1800,1,false,'2026-11-06 10:34:40.5+09','2026-08-01 10:40:22.870241+09'),
	 (10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.646212929,141.977949142,'浄土ヶ浜の透き通る青さと白い岩肌に感動','宮古市にある名勝・浄土ヶ浜へと足を伸ばしました。鋭く白い流紋岩と、底まで透けて見えるほど透明度の高いエメラルドグリーンの海のコントラストが美しすぎます。言葉を失うほどの絶景を目の前にして、しばらく2人で波の音に耳を傾けていました。','2026-11-06','11:45','✨','0','',0,1,false,'2026-11-06 12:03:20.15+09','2026-08-01 10:40:30.947243+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.491200000,138.771200000,'道の駅で山梨の特産品とぶどうジュースを購入','帰路につく前に、地元の大きな道の駅に立ち寄って家族や自分向けのお土産を選びました。山梨ならではの新鮮な桃や、濃厚な果汁100%のぶどうジュースを「これは絶対うまいやつだ」とカゴに放り込みます。旅の終わりを感じながらも充実感に浸る楽しいショッピングタイムでした。','2026-08-06','17:30','🛍️','0','',-4500,1,false,'2026-08-06 17:34:12.3+09','2026-08-01 11:10:50.466944+09'),
	 (14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'甲府駅周辺へ戻りレンタカーを無事に返却','富士山登頂の過酷で素晴らしい挑戦をともに乗り越えた相棒のレンタカーを、甲府駅近くの営業所へ無事に返却しました。車体にたくさんの思い出と旅の埃を乗せて走り切ってくれた車に心から感謝しつつ、駅のコンコースへと向かいました。','2026-08-06','19:00','🤝','0','',-6500,1,false,'2026-08-06 19:04:10.8+09','2026-08-01 11:10:50.466944+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.742500000,140.723000000,'温泉街の居酒屋で日本海と太平洋の酒を飲み比べる','夜ご飯は温泉街の隠れ家的な居酒屋に繰り出しました。日本海側の山形の銘酒と、太平洋側の宮城の銘酒を両方揃えてもらい、それぞれの味わいの違いを男2人で熱く語り合いながら宮城の美味しい郷土料理を次々と平らげます。横断成功の乾杯のグラスが何度も鳴り響く、最高に熱い夜宴会になりました。','2026-10-05','20:00','🍶','0','',-6000,1,false,'2026-10-05 20:04:15.4+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.561200000,141.051200000,'2日目の朝、一気に太平洋側へ南下ドライブ','2日目の朝は朝風呂でシャキッと目覚め、宿をあとにして今度は宮城の太平洋側を目指して南東方向へ車を走らせました。なだらかな丘陵地帯を抜けて、徐々に海の気配が近づいてくる道をリズミカルに走ります。車窓を流れる景色が日本海側から太平洋側へと完全に切り替わっていくのが面白いです。','2026-10-06','09:00','🌊','0','',0,1,false,'2026-10-06 09:03:15.12+09','2026-08-01 10:59:25.361797+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.373400000,141.065600000,'松島の海鮮処で太平洋のカキ焼きを実食','日本海側の魚介と食べ比べるために、松島の海岸沿いにあるお店で名物のカキ焼きを再びオーダーしました。目の前で香ばしく焼かれた大ぶりのカキを口に含むと、太平洋ならではの濃厚でクリーミーな旨みが一気に広がります。「どちらの海もそれぞれの良さがあって最高だな」と男2人で深く納得しながら完食しました。','2026-10-06','12:00','🦪','0','',-1600,1,false,'2026-10-06 12:03:20.15+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台市内に戻り旅のフィナーレへ向かう','松島をあとにして車をさらに南西へ走らせ、今回の横断ドライブのゴール地点となる仙台市内の中心街へと戻ってきました。都会的なビル街の景色に変わり、無事にここまで走り抜けてくれた相棒の車にお疲れ様と言いながら大通りを進みます。旅の終わりが近づいて少し名残惜しい気持ちになります。','2026-10-06','13:30','🚙','0','',0,1,false,'2026-10-06 13:35:00+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.269200000,140.875000000,'仙台市内の名店で本場の厚切り牛タンランチ','横断旅の最後の晩餐（お昼ごはん）として、仙台市内の大人気牛タン専門店へ飛び込みました。分厚くカットされて炭火で香ばしく焼き上げられたジューシーな牛タンと、お代わり必須の麦飯を夢中になって平らげます。この旅ですっかり肥えたお腹と心に、最高の形でガツンとご馳走が染み渡りました。','2026-10-06','14:45','🥩','0','',-2900,1,false,'2026-10-06 14:48:12.3+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅でレンタカーを無事に返却','日本海側を出発し、奥羽山脈を越えて太平洋側まで見事に走り抜いた2日間の横断ドライブの全日程が終了し、仙台駅近くの営業所でレンタカーを無事に返却しました。大きなトラブルもなく、たくさんの絶景と美食を運んでくれた相棒の車に心から感謝しました。','2026-10-06','16:30','🤝','0','',-7000,1,false,'2026-10-06 16:34:50.22+09','2026-08-01 10:59:25.361797+09'),
	 (13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'駅ビルで最後の乾杯をして新幹線で帰路へ','新幹線の発車時刻まで少し時間があったので、駅構内のお店で最後のお疲れ様ビールを軽く一杯引っ掛けました。「日本海から太平洋への横断、本当に最高のルートだったな」と地図を広げながら振り返り、心地よい疲労感と大きな達成感に包まれながら帰りの新幹線へと乗り込みました。','2026-10-06','17:30','🍻','0','',-1200,0,false,'2026-10-06 17:35:10.88+09','2026-08-01 10:59:25.361797+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.718600000,140.102400000,'秋田空港に到着してレンタカーで出発','秋田でのドライブ旅行をスタートさせるため、飛行機を降りてすぐにレンタカーの手続きを済ませました。車に乗り込み、これから始まる東北の旅に胸を躍らせながらアクセルを踏み込みます。車窓から見える穏やかな田園風景が、旅情をグッと盛り上げてくれます。','2026-12-05','09:30','🚙','0','',0,1,false,'2026-12-05 09:32:15.12+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.716700000,140.116700000,'秋田市内で名物の比内地鶏ランチ','最初の目的地として秋田市内の老舗料理店に立ち寄り、日本三大地鶏のひとつである比内地鶏の親子丼を注文しました。香ばしく焼き上げられた鶏肉と、とろとろの濃厚な卵が絶妙に絡み合い、一口食べた瞬間に思わず笑顔がこぼれるほどの美味しさでした。','2026-12-05','11:30','🐔','0','',-1800,1,false,'2026-12-05 11:34:40.5+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.719200000,140.112300000,'エリアなかいち周辺でおしゃれなカフェ休憩','美味しいランチのあとは、市街地のおしゃれなスポット周辺を少しお散歩しました。途中で見つけた素敵なカフェに立ち寄り、秋田県産の素材を使ったスイーツとコーヒーを飲みながら、これからのドライブのルートについて楽しく作戦会議を行います。','2026-12-05','13:00','☕','0','',-1200,1,false,'2026-12-05 13:35:10.8+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.721200000,140.125600000,'ねぶり流し館で竿燈まつりの歴史に触れる','秋田の代名詞ともいえる「竿燈まつり」の熱気をいつでも体感できる施設を見学しました。実際に使われる巨大な竿燈の重さや、提灯の精巧な作りに驚かされます。お祭りの当日にここで夜空を揺らす光景を想像するだけで、すごくワクワクした気持ちになりました。','2026-12-05','14:30','🏮','0','',-600,1,false,'2026-12-05 14:38:20.15+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.851200000,140.351200000,'日本海沿いを北上する爽快ドライブロード','秋田市内を後にして、今度は日本海に面したルートへと車を走らせました。さえぎるもののない広大な水平線を左手に眺めながら、エンジンの心地よい音を聞きながら海岸線の道を気持ちよく駆け抜けます。ドライブの醍醐味が詰まった最高の時間です。','2026-12-05','16:00','🌊','0','',0,1,false,'2026-12-05 16:04:00+09','2026-08-01 10:46:13.873071+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.923400000,140.612300000,'内陸の山あいを縫って温泉郷へ向かう','海岸線から一転して、豊かな森が広がる内陸の山あいの道へと車を進めました。少しずつ辺りが夕暮れに染まり始め、木々の隙間から差し込む夕日がとても幻想的です。秘湯へと向かうワクワク感が高まっていくのを肌で感じながらハンドルを握ります。','2026-12-05','17:30','🌲','0','',0,1,false,'2026-12-05 17:34:12.3+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.901200000,140.781200000,'乳頭温泉郷の秘湯宿にチェックイン','今日の宿泊先である、乳頭温泉郷の風情ある温泉宿に到着しました。趣のある木造りの建物に一歩足を踏み入れると、タイムスリップしたかのような静寂と硫黄の香りに包まれます。さっそく自慢の乳白色の温泉に浸かり、旅の疲れを芯からじっくりと癒やしました。','2026-12-05','18:45','♨️','0','',-18000,1,false,'2026-12-05 18:48:50.22+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.901800000,140.782500000,'囲炉裏端で味わう山の幸と秋田の地酒','夜ご飯は風情ある囲炉裏の席で、山菜や川魚の囲炉裏焼き、そして名物の「きりたんぽ鍋」をいただきました。アツアツの出汁が染み込んだきりたんぽと鶏肉の旨みが体に染み渡り、キリッとした秋田の地酒を合わせると最高の一言に尽きます。夜遅くまで贅沢な時間を満喫しました。','2026-12-05','20:15','🍶','0','',0,1,false,'2026-12-05 20:20:15.4+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.734500000,140.712300000,'2日目の朝、神秘的な田沢湖へドライブ','2日目の朝は朝風呂ですっきりと目覚め、宿をあとにして日本一深い湖として知られる田沢湖へと車を走らせました。山道を抜けて目の前にパッと視界が開けた瞬間、言葉を失うほど美しくどこか切ない群青色の湖面が姿を現し、思わず車を停めて見入ってしまいました。','2026-12-06','09:15','✨','0','',0,1,false,'2026-12-06 09:18:15.12+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.751200000,140.691200000,'湖畔に佇む金色の子辰子像を見学','田沢湖のシンボルである、黄金色に輝く「たつこ像」の近くへと足を伸ばしました。澄み切った湖水と青空のコントラストが素晴らしく、湖畔を吹き抜ける風がとても心地よかったです。湖の周りを少しお散歩しながら、綺麗な景色を背景にたくさん写真を撮影しました。','2026-12-06','10:45','🗽','0','',0,1,false,'2026-12-06 10:48:40.5+09','2026-08-01 10:46:13.873071+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.818902000,132.871233000,'三次駅へ戻る','車で三次へ戻ると、朝と同じ穏やかな空気が広がっていた。庄原と三次をゆっくり巡った一日を思い返すと、心が自然と落ち着く旅だったと感じる。','2026-10-22','16:30','🚗','0000','',0,1,false,'2026-10-22 16:30:00+09','2026-10-22 16:30:00+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.601200000,140.451200000,'角館の武家屋敷通りをのんびりお散歩','「みちのくの小京都」と呼ばれる角館の武家屋敷通りへと移動しました。黒板塀の落ち着いた佇まいと立派な歴史的建造物が並ぶ街並みは、まるで江戸時代にタイムスリップしたかのような趣があります。風情ある通りをゆっくりと歩きながら、秋田の深い歴史を肌で感じました。','2026-12-06','12:30','⛩️','0','',0,1,false,'2026-12-06 12:35:20.15+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.603400000,140.456700000,'武家屋敷の老舗で名物の稲庭うどんを堪能','お昼ごはんは角館の歴史ある建物の中にあるお店で、ツルッとした喉ごしがたまらない「稲庭うどん」のセットをいただきました。透き通るように美しい平打ちの麺と上品なつけ汁が抜群の相性で、歩き疲れた体にスルスルと美味しく入っていき大満足のランチタイムになりました。','2026-12-06','13:45','🍜','0','',-1500,1,false,'2026-12-06 13:48:00+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.451200000,140.351200000,'道の駅で秋田のお土産をどっさり買い出し','秋田空港へ戻るルートの途中にある大きな道の駅に立ち寄り、旅の最後のお土産探しをしました。いぶりがっこや比内地鶏のスープ、ご当地のお菓子などを「これも美味しそう！」とカゴいっぱいに詰め込み、レジのお姉さんと方言まじりの温かい会話を楽しみました。','2026-12-06','15:30','🛍️','0','',-4500,1,false,'2026-12-06 15:34:12.3+09','2026-08-01 10:46:13.873071+09'),
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.718600000,140.102400000,'秋田空港に到着してレンタカーを無事に返却','たくさんの思い出とたくさんのお土産を車に積み込み、無事に秋田空港のレンタカー営業所へと戻って車を返却しました。大きなトラブルもなく快適に走ってくれた相棒に心の中で感謝しつつ、出発ロビーへと向かいます。','2026-12-06','17:00','🤝','0','',-6500,1,false,'2026-12-06 17:04:50.22+09','2026-08-01 10:46:13.873071+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.718600000,140.102400000,'空港のラウンジと売店で旅を締めくくる','保安検査場を通る直前、売店で最後の締めくくりにきりたんぽのカップスープを味わいながら旅の余韻に浸りました。「やっぱり秋田の温泉とご飯は最高だったね」と振り返りながら、帰りの飛行機へと乗り込んで充実した2日間の旅を終えました。','2026-12-06','18:00','✈️','0','',-800,0,false,'2026-12-06 18:03:50.22+09','2026-08-01 10:46:13.873071+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.461200000,138.851200000,'忍野八海の透明すぎる湧水池をのんびり散策','富士山の雪解け水が何十年もかけて湧き出るという「忍野八海」のエリアへと足を伸ばしました。底までハッキリと見えるほど透き通った青い湧水池や、昔ながらの茅葺き屋根の民家が並ぶ景色をのんびりと歩きながら巡ります。清らかな水面に心を洗われるような、とても穏やかな時間を過ごせました。','2026-09-10','13:45','💧','0','',-300,1,false,'2026-09-10 13:48:20.15+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.421200000,138.881200000,'山中湖のほとりで白鳥と富士山をカメラに収める','さらに東へと進み、富士五湖の中で最も大きい山中湖の湖畔へと車を停めました。水面を優雅に泳ぐ白鳥の群れと、その背景にそびえる富士山という絵画のような景色を狙ってカメラのシャッターを切ります。涼しい湖畔の風に吹かれながら、ドライブの心地よさを存分に満喫しました。','2026-09-10','15:30','🦢','0','',0,1,false,'2026-09-10 15:34:00+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.451200000,138.911200000,'三国山パノラマ台から夕暮れの富士山を狙う','日没が近づいてきたタイミングで、山中湖の少し高台にある「パノラマ台」へと車を走らせました。眼下に広がる山中湖と、その向こう側に夕日を浴びて少しずつ赤く染まっていく富士山のダイナミックなシルエットを撮影します。ドラマチックに移り変わる夕景の美しさに息を呑みました。','2026-09-10','17:15','🌇','0','',0,1,false,'2026-09-10 17:18:12.3+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.481200000,138.791200000,'河口湖畔の温泉ホテルにチェックイン','撮影をたっぷり楽しんだあとは、河口湖のほとりに佇む眺望抜群の温泉ホテルへとチェックインしました。部屋の窓からライトアップされた夜の富士山を眺めつつ、さっそく広い大浴場へと向かってドライブの疲れをじっくりと癒やします。贅沢なロケーションに心からリラックスできました。','2026-09-10','18:45','♨️','0','',-18000,1,false,'2026-09-10 18:48:50.22+09','2026-08-01 11:12:22.077634+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196944000,133.030833000,'大三島の道の駅で休憩','名物のじゃこ天を食べてエネルギー補給。地元の人の温かさを感じる場所。','2026-08-04','14:40','🙂','0000','',-300,1,false,'2026-08-04 14:40:00+09','2026-08-02 07:30:32.144728+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.482500000,138.793000000,'ホテル内のレストランで山梨の郷土料理を満喫','夜ご飯はホテル内の落ち着いたレストランで、山梨名物の「ほうとう鍋」や地元の新鮮な野菜を使った料理をいただきました。カボチャや根菜がたっぷり入ったアツアツの味噌仕立てのほうとうが体に染み渡り、山梨の美味しい赤ワインと一緒に味わうことで最高のディナータイムになりました。','2026-09-10','20:15','🍷','0','',0,1,false,'2026-09-10 20:20:15.4+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.471200000,138.711200000,'2日目の朝、西湖の静寂な湖畔をドライブ','2日目の朝は朝風呂ですっきりと目覚め、ホテルをあとにして少し落ち着いた雰囲気の「西湖」周辺へと車を走らせました。観光地の人混みも少なく、木々に囲まれた静かな湖面が鏡のように景色を映し出しています。朝の澄んだ空気の中を巡るドライブは、心から癒やされる素晴らしい時間でした。','2026-09-11','09:15','🌲','0','',0,1,false,'2026-09-11 09:18:15.12+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.481200000,138.651200000,'神秘的な青木ヶ原樹海の散策路を歩く','西湖のすぐ近くにある「青木ヶ原樹海」の整備された自然散策路へと足を踏み入れました。溶岩の上に力強く根を張る独特な森の木々と、苔むした神秘的な景色がどこか異世界のような雰囲気を醸し出しています。大自然の生命力を間近に感じながら、静かな森のなかを少しお散歩しました。','2026-09-11','10:45','🍃','0','',0,1,false,'2026-09-11 10:48:40.5+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.481200000,138.611200000,'本栖湖の展望スポットで千円札の裏の景色を確認','富士五湖の一つであり、かつて旧五千円札や現行千円札の裏面に描かれた富士山のモデルになった「本栖湖」のビューポイントに立ち寄りました。目の前に広がる湖面と富士山の構図が、まさにあの紙幣のデザインそのままで「おお、本物だ！」と感動しながら記念の写真を何枚も撮影しました。','2026-09-11','12:30','💵','0','',0,1,false,'2026-09-11 12:35:20.15+09','2026-08-01 11:12:22.077634+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.820144000,132.883291000,'旅の締め','駅前で深呼吸すると、広島県北部の静かな空気が胸に広がった。派手さはないが、心が落ち着く田舎旅となり、お年寄りでも安心して楽しめる一日だった。','2026-10-22','16:40','🌅','0000','',0,1,false,'2026-10-22 16:40:00+09','2026-10-22 16:40:00+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.491200000,138.601200000,'湖畔のロッジ風カフェでおしゃれなランチ','本栖湖の近くにあるおしゃれなロッジ風のカフェに入り、少し遅めのランチタイムにしました。富士山の伏流水を使って淹れられたこだわりのコーヒーと、地元食材をふんだんに使ったサンドイッチを味わいます。大きな窓から見える緑豊かな景色を眺めながら、ゆったりとした優雅な時間を過ごしました。','2026-09-11','13:45','☕','0','',-1600,1,false,'2026-09-11 13:48:00+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.531200000,138.551200000,'道の駅で山梨の美味しいお土産を爆買い','甲府へ戻るルートの途中にある大きな道の駅に立ち寄り、旅の最後のお土産の買い出しを行いました。山梨の名産であるシャインマスカットや、特製のワイン、ほうとうの乾麺などを「これも買っていこう」とカゴにたくさん詰め込みました。最後まで大満足のショッピングでした。','2026-09-11','15:30','🛍️','0','',-5500,1,false,'2026-09-11 15:34:12.3+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'甲府駅に戻りレンタカーを無事に返却','富士五湖の絶景と素晴らしい撮影スポットを巡った2日間のドライブ旅のフィナーレとして、甲府駅近くの営業所でレンタカーを無事に返却しました。たくさんの写真と楽しい思い出を車に積んで安全に走り切ってくれた相棒に感謝しつつ、駅へと向かいます。','2026-09-11','17:00','🤝','0','',-6500,1,false,'2026-09-11 17:04:50.22+09','2026-08-01 11:12:22.077634+09'),
	 (15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'駅ナカで最後の締めくくりビールを飲んで帰路へ','電車の発車時刻までの少しの時間、駅ビルのお店に入って冷えたビールで「最高の撮影ドライブだったな！」と乾杯しました。撮影した写真フォルダを振り返りながら心地よい余韻に浸り、充実感に包まれながら帰りの列車へと乗り込みました。','2026-09-11','18:00','🍻','0','',-1100,0,false,'2026-09-11 18:03:50.22+09','2026-08-01 11:12:22.077634+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.726000000,135.986000000,'4軒目：お昼のガッツリ系スタミナニンニクラーメン','お腹が空いたところで、ニンニクがガツンと効いたスタミナ系の限定ラーメンを全員で注文。スタミナ満点！','2026-10-11','12:30','🧄','0','',-1100,1,false,'2026-10-11 13:00:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.727000000,135.984000000,'浮島半島の海岸線を軽くドライブ＆散策','太平洋の荒波が打ち寄せる海岸線を散策。潮風を浴びながら、男子特有のバカ話でワイワイ楽しむ。','2026-10-11','14:00','🌊','0','',0,1,false,'2026-10-11 14:30:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.722000000,135.988000000,'5軒目：旅のフィナーレを飾る王道醤油ラーメン','帰りの新宮駅に向かう前に、地元で愛される王道の醤油ラーメンで今回のラーメン巡りを締めくくる。やっぱりこれだなと納得。','2026-10-11','16:30','🍜','0','',-900,1,false,'2026-10-11 17:00:00+09','2026-08-01 21:17:55.265904+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725696003,135.997524261,'2日目スタート：朝の爽やかな熊野川河川敷をドライブ','天気も良く、爽やかな朝の熊野川沿いをドライブ。車内では昔の思い出話や音楽の話で大盛り上がり。','2026-10-11','09:00','🎶','0','',0,1,false,'2026-10-11 09:30:00+09','2026-08-01 21:18:59.934855+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.718342948,135.989627838,'瀞峡（どのきょう）の圧倒的な大自然を体感','切り立った渓谷の美しい景観を間近で見学。自然のダイナミックさに男同士でも思わず「すげえ…」と声が漏れる。','2026-10-11','10:30','🛶','0','',-1500,1,false,'2026-10-11 11:00:00+09','2026-08-01 21:19:13.227821+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.731370989,135.986323357,'新宮の地酒や名産品をお土産ショップで物色','家族や自分へのお土産として、地元の日本酒や名産のお菓子などを男らしくまとめ買い。','2026-10-11','15:15','🛍️','0','',-3500,1,false,'2026-10-11 15:45:00+09','2026-08-01 21:19:30.858575+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.180556000,133.020833000,'大山祇神社を参拝','大きな木々に囲まれた神社で、空気が澄んでいて心が落ち着く。旅の安全を祈った。','2026-08-04','15:20','🙂','0000','',0,1,false,'2026-08-04 15:20:00+09','2026-08-02 07:30:32.144728+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.692820997,135.336644053,'アドベンチャーワールドで動物たちに癒やされる','パンダやたくさんの動物たちを見にアドベンチャーワールドへ。サファリワールドを車で回ったり、イルカショーを見て家族みんなが大はしゃぎ。','2026-09-12','14:00','🐼','0','',-12000,1,true,'2026-09-12 14:30:00+09','2026-08-01 21:05:34.850528+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.678854126,135.344781876,'千畳敷のダイナミックな景観に感動','波の浸食によってできた壮大な岩畳を見学。太平洋の水平線が広がり、夕暮れ時の景色が言葉を失うほど美しかった。','2026-09-12','17:30','🌅','0','',0,1,true,'2026-09-12 18:00:00+09','2026-08-01 21:05:34.850528+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.690100000,135.352100000,'白浜温泉の宿でゆったり温泉と会席料理','温泉に浸かって一日の運転の疲れをしっかりリフレッシュ。海の幸がふんだんに使われた豪華な夕食を家族で囲み、楽しい夜を過ごした。','2026-09-12','20:00','♨️','0','',-32000,1,true,'2026-09-12 20:30:00+09','2026-08-01 21:05:34.850528+09'),
	 (43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.836670000,134.691170000,'4軒目：隠れ家風の割烹居酒屋で味わう、瀬戸内海の新鮮な海の幸と播磨の地酒','夜のメインディッシュは、播磨の旬の食材が味わえるこだわりの割烹居酒屋へ。目の前の瀬戸内海で水揚げされたばかりの新鮮なお造りや、名物の穴子の天ぷらを堪能しながら、キリッとした辛口の播磨の地酒を合わせ、至福の晩酌タイムをしみじみと楽しむ。','2026-10-11','19:15','🍶','0','',-6500,1,false,'2026-10-11 20:30:00+09','2026-08-02 01:09:13.862814+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.502780000,135.373610000,'近畿百景の第1位！「五老スカイタワー」から一望する舞鶴湾の壮大なパノラマ','五老ヶ岳公園の山頂にそびえる展望タワー「五老スカイタワー」の最上階へ。目に前に広がる、複雑に入り組んだリアス式海岸の「舞鶴湾」と点在する緑の島々が織りなす息をのむほどに美しい絶景パノラマに、思わず言葉を失うほどの感動を覚える。','2027-04-10','15:30','🗼','0','',-500,1,false,'2027-04-10 16:15:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.461670000,135.319440000,'趣ある城下町・西舞鶴エリアへ移動、歴史を感じる「田辺城資料館」を見学','東舞鶴から西舞鶴へと移動し、かつて細川幽斎が築いた田辺城の跡地である資料館へ。歴史の変遷を伝える貴重な資料や武具の数々をじっくりと見学しながら、丹後田辺藩の城下町として栄えた古い歴史のロマンに思いを馳せる。','2027-04-10','17:00','🏯','0','',-400,1,false,'2027-04-10 17:45:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.464170000,135.398610000,'翌日、新鮮な海の特産品が並ぶ道の駅「舞鶴港とれとれセンター」でお買い物','旅行2日目は、日本海側最大級の海鮮市場である「舞鶴港とれとれセンター」へ。活気あふれる店内で、ずらりと並ぶ新鮮なカニや干物、お土産用の特産品をじっくりと吟味し、旅の思い出を彩る素敵なお土産をたくさん買い揃える。','2027-04-12','10:00','🛍️','0','',-3500,1,false,'2027-04-12 10:45:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.465000000,135.399440000,'市場のイートインコーナーで味わう、その場で選んだお魚の海鮮網焼きランチ','とれとれセンター内で、ずらりと並ぶ新鮮な魚介の中から自分の好きな食材を選んでその場で焼いてもらう海鮮網焼きランチ。香ばしい磯の香りとジューシーな魚の旨味が口いっぱいに広がり、旅の締めくくりにふさわしい最高に贅沢な味わいを楽しむ。','2027-04-12','11:30','🦐','0','',-2200,1,false,'2027-04-12 12:15:00+09','2026-08-02 01:20:50.513158+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.464170000,135.398610000,'「JR東舞鶴駅」に戻り、港町のたくさんの思い出と感動を胸に帰路につく','すべての観光行程を大満足で終えて再びJR東舞鶴駅へ戻る。「海の景色も、美味しい海鮮も、赤れんがの歴史も全部素晴らしかったね！」と笑顔で語り合いながら、たくさんの温かい思い出を胸に、帰路の特急列車へと乗り込む。','2027-04-12','14:00','👋','0','',0,1,false,'2027-04-12 14:30:00+09','2026-08-02 01:20:50.513158+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342566000,134.046549000,'高松駅に到着','四国旅のスタートは高松駅。瀬戸内の明るい空気が気持ちよくてワクワクが広がる。','2026-08-10','09:10','🚉','0000','',0,1,false,'2026-08-10 09:10:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.344143000,134.050210000,'高松港で海風を感じる','港の海風が心地よくて瀬戸内海の穏やかな景色に自然と笑顔になる。','2026-08-10','09:40','🌊','0000','',0,1,false,'2026-08-10 09:40:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343720000,134.046930000,'うどんで腹ごしらえ','香川名物のかけうどんをいただく。出汁の香りが最高で旅のテンションが上がる。','2026-08-10','10:00','🍜','0000','',-480,1,false,'2026-08-10 10:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.320030000,134.042430000,'栗林公園散策','庭園の緑が鮮やかで池の反射も美しい。歩くだけで気持ちが軽くなる。','2026-08-10','11:00','🌿','0000','',0,1,false,'2026-08-10 11:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.319310000,134.043010000,'茶屋で抹茶休憩','抹茶と和菓子を楽しみながら庭園を眺める贅沢な時間。心がふわっと明るくなる。','2026-08-10','11:40','🍵','0000','',-700,1,false,'2026-08-10 11:40:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350120000,134.056030000,'商店街をぶらぶら','アーケードが長くて歩きやすい。地元のお店を見て回るだけで楽しい気分になる。','2026-08-10','12:30','🛍️','0000','',0,1,false,'2026-08-10 12:30:00+09','2026-08-02 02:06:55.502943+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.465120000,134.813210000,'2軒目：温泉街で食べる地元の名物・カニだし塩ラーメン','温泉ですっきりとリフレッシュしたあと、湯上がりの体に最高の塩ラーメンを求めて路地裏の隠れ家的店へ。日本海で獲れたカニの出汁がこれでもかと効いたスープは、上品かつ深いコクがあり、ここでしか味わえない絶品の一杯だった。','2026-11-12','16:00','🍜','0','',-1100,1,false,'2026-11-12 16:30:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.459870000,134.809870000,'情緒あふれる川沿いの旅館で男だらけの大宴会','本日の宿である温泉旅館にチェックイン。夕食には日本海側の新鮮な海の幸や地元食材を使った料理がずらりと並び、冷えたビールで乾杯する。昔話や仕事の近況報告で大いに盛り上がり、夜遅くまで笑い声が途絶えない最高の夜となった。','2026-11-12','18:30','🍻','0','',-15000,1,false,'2026-11-12 19:00:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.461230000,134.810120000,'3軒目：夜の温泉街の締めくくる深夜の屋台風醤油ラーメン','宴会が一段落した深夜、どうしてもラーメンが食べたくなり、夜遅くまで開いているアットホームなラーメン店へこっそり抜け出す。シンプルな鶏ガラ醤油の味わいが、お酒を飲んだ後の胃袋に優しく染み入り、最高の締めくくりとなった。','2026-11-12','22:30','🌙','0','',-900,1,false,'2026-11-12 23:00:00+09','2026-08-01 21:36:37.140503+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.347820000,134.054720000,'骨付鳥ランチ','香川名物の骨付鳥がジューシーで最高。食べるたびに笑顔になる味。','2026-08-10','13:00','🍗','0000','',-1500,1,false,'2026-08-10 13:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350930000,134.060140000,'ことでん瓦町駅周辺散策','レトロな雰囲気が漂う街並み。地元の生活感があって歩いているだけで楽しい。','2026-08-10','14:00','🚋','0000','',0,1,false,'2026-08-10 14:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.013510000,134.586240000,'徳島駅に移動','電車で徳島へ。駅前の青空が広がっていて気持ちが明るくなる。','2026-08-10','15:20','🚉','0000','',0,1,false,'2026-08-10 15:20:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.067540000,134.559890000,'眉山ロープウェイ乗り場','ロープウェイで山頂へ。徳島の街並みが一望できて爽快感がすごい。','2026-08-10','15:50','🚡','0000','',0,1,false,'2026-08-10 15:50:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.068240000,134.559300000,'眉山山頂','山頂の風が気持ちよくて景色が最高。写真を何枚も撮ってしまう。','2026-08-10','16:10','📸','0000','',0,1,false,'2026-08-10 16:10:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.065900000,134.559900000,'阿波踊り会館見学','阿波踊りの歴史を知る展示が面白い。太鼓の音が心に響く。','2026-08-10','16:40','🥁','0000','',-600,1,false,'2026-08-10 16:40:00+09','2026-08-02 02:06:55.502943+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.467890000,134.812340000,'JR城崎温泉駅に到着、温泉街の男旅がスタート','いよいよ待ちに待った兵庫県北部の男旅が幕を開けた。城崎温泉駅に全員集合し、まずは駅舎の前で気合の記念撮影。これから始まる温泉と絶品ご当地グルメの食べ歩きに、早くもテンションが最高潮に達している。今日からの1泊2日、思い切り満喫するぞ！','2026-11-12','10:00','🚗','0','',0,1,false,'2026-11-12 10:05:12+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.613450000,134.814560000,'名勝「玄武洞」の圧倒的な自然の造形美に感動','国の天然記念物にも指定されている玄武洞を見学。マグマが冷えて固まった時にできた見事な柱状節理の断面が目の前に広がり、そのダイナミックで神秘的な光景に男同士でも思わず息をのむ。地球の歴史を感じる素晴らしいスポットだ。','2026-11-12','11:00','🗿','0','',0,1,false,'2026-11-12 11:30:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.534210000,134.823450000,'1軒目：豊岡市内の人気店で味わう濃厚鶏白湯ラーメン','観光の最初の腹ごしらえとして、地元で評判の鶏白湯ラーメン店へ駆け込む。じっくりと炊き出された濃厚でクリーミーなスープが、歩き疲れた体に染みわたる。麺との絡み具合も抜群で、全員がスープを完飲するほどの美味しさだった。','2026-11-12','12:30','🍜','0','',-950,1,false,'2026-11-12 13:00:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.462340000,134.811230000,'城崎温泉街の風情ある七つの外湯めぐり（一の湯）','浴衣に着替えて、城崎温泉の代名詞である外湯めぐりに繰り出す。まずは「一の湯」で旅の移動の疲れをじっくりと癒やす。風情ある温泉街の石畳をカランコロンと下駄を鳴らしながら歩く時間は、日本の情緒を感じられて実に心地よい。','2026-11-12','14:30','♨️','0','',-800,1,false,'2026-11-12 15:00:00+09','2026-08-01 21:36:37.140503+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.468900000,134.820120000,'朝の温泉街を散策しながら、温泉たまご作り体験','2日目の朝は爽やかな空気が漂う温泉街をのんびりとお散歩。源泉の熱を使って自分で温泉たまごを作る体験コーナーに挑戦する。程よい半熟具合に仕上がった卵をその場で食べると、朝から贅沢な気分を満喫できた。','2026-11-13','09:00','🥚','0','',-200,1,false,'2026-11-13 09:30:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.475640000,134.887650000,'円山川沿いをドライブして、のどかな景色を満喫','車窓から広がる美しい円山川の景色を眺めながら、爽快なリバーサイドドライブを楽しむ。車内ではお気に入りのプレイリストを流し、男同士ならではの気兼ねないトークで終始笑顔が絶えない移動時間となった。','2026-11-13','10:15','🚗','0','',0,1,false,'2026-11-13 10:45:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.547890000,134.901230000,'国の伝統的建造物群保存地区「出石の城下町」を散策','「但馬の小京都」と呼ばれる出石の城下町に到着。白壁の武家屋敷や歴史ある佇まいの街並みをのんびりと歩きながら、かつての城下町の面影をしみじみと感じ取る。歴史好きのメンバーも大満足の落ち着いたロケーションだ。','2026-11-13','11:30','🏯','0','',0,1,false,'2026-11-13 12:00:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.549120000,134.902340000,'4軒目：名物「出石皿そば」をみんなで何枚食べられるか勝負','出石といえばやっぱり出石皿そば！ 小皿に盛られた風味豊かなお蕎麦を次々とお代わりしていく。何枚食べたかを競い合う男気勝負を開催し、一番食べたメンバーには全員から拍手が送られるなど、最高に盛り上がるランチタイムとなった。','2026-11-13','12:45','🍜','0','',-1200,1,false,'2026-11-13 13:15:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.512340000,134.856780000,'かつて「天空の城」として知られる竹田城跡の麓へ','日本のマチュピチュとも称される竹田城跡のふもとに到着。遠くからでも威厳を放つ石垣の山城を眺め、その壮大なスケールに圧倒される。歴史のロマンに浸りつつ、記念の集合写真をパシャリと撮影。','2026-11-13','14:15','⛰️','0','',-500,1,false,'2026-11-13 14:45:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.514560000,134.858900000,'5軒目：麓の食堂で味わうホッとする懐かしの中華そば','竹田城跡の周辺を散策したあと、麓にあるレトロな雰囲気の食堂で遅めのお昼ご飯。鶏ガラベースの非常にシンプルでどこか懐かしい味わいの中華そばをすする。旅の終盤にふさわしい、心まで温まる一杯だった。','2026-11-13','15:30','🍜','0','',-850,1,false,'2026-11-13 16:00:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.398760000,134.834560000,'道の駅で但馬牛のコロッケをつまみ食い＆お土産選び','帰路の途中に立ち寄った道の駅にて、名物の但馬牛を使ったサクサクのコロッケをみんなで買い食い。さらに、家族や自分用のお土産として地元の特産品や日本酒をしっかりと買い込み、トランクケースがいっぱいになる。','2026-11-13','16:45','🛍️','0','',-2500,1,false,'2026-11-13 17:15:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.354320000,134.789010000,'旅のフィナーレ：北近畿の思い出を語り合う最後の休憩','今回の旅の全行程をほぼ完璧にこなし、名残惜しさを感じながら最後の休憩ポイントへ。2日間で巡った観光地や食べたラーメンの数々を振り返り、すっかり絆が深まった仲間たちと次回の旅行の計画について話し合う。','2026-11-13','18:00','☕','0','',0,1,false,'2026-11-13 18:30:00+09','2026-08-01 21:36:37.140503+09'),
	 (36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.351230000,134.785430000,'JRの駅にて解散、最高の兵庫男旅のエンディング','すべての旅程を無事に終え、電車の到着に合わせて笑顔で解散の挨拶を交わす。観光もラーメンも妥協なしで大満足し、それぞれの家路へとつく。また次の機会に向けて、それぞれの日常へと戻っていくのだった。','2026-11-13','19:00','👋','0','',0,1,false,'2026-11-13 19:30:00+09','2026-08-01 21:36:37.140503+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.158333000,133.006111000,'伯方島へ移動','海沿いの道が続き、潮風が心地よい。ゆったりした島時間を感じる。','2026-08-04','16:00','🙂','0000','',0,1,false,'2026-08-04 16:00:00+09','2026-08-02 07:30:32.144728+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.138333000,133.003611000,'伯方の塩ラーメンを食べる','名物の塩ラーメンはあっさりしていて美味しい。旅の疲れが少し取れた気がする。','2026-08-04','16:40','🤩','0000','',-900,1,false,'2026-08-04 16:40:00+09','2026-08-02 07:30:32.144728+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.115556000,132.990556000,'大島へ移動','橋を渡るたびに景色が変わり、旅がどんどん進んでいく感覚が楽しい。','2026-08-04','17:20','🙂','0000','',0,1,false,'2026-08-04 17:20:00+09','2026-08-02 07:30:32.144728+09'),
	 (65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.100556000,132.980556000,'来島海峡大橋を眺める','夕方の来島海峡大橋は美しくて、旅の締めくくりにふさわしい景色だった。','2026-08-04','18:00','🤩','0000','',0,1,false,'2026-08-04 18:00:00+09','2026-08-02 07:30:32.144728+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560300000,133.531900000,'高知城へ向かう','城下町の雰囲気が残る道を歩く。石垣が見えてくるとワクワクが高まる。','2026-08-11','13:00','🏯','0000','',0,1,false,'2026-08-11 13:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.558900000,133.533300000,'朝うどんで腹ごしらえ','高知名物の「田舎うどん」をいただく。素朴な味が朝の体に染みていく。','2026-08-04','10:00','🍜','0000','',-520,1,false,'2026-08-04 10:00:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.558600000,133.543900000,'路面電車で移動','高知名物の路面電車に乗車。レトロな車両が街に馴染んでいて、乗っているだけで楽しい。','2026-08-04','10:30','🚋','0000','',-210,1,false,'2026-08-04 10:30:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514350000,133.562870000,'桂浜へ到着','太平洋の広さに圧倒される桂浜。波の音が心地よくて、しばらく砂浜でぼーっとしてしまった。','2026-08-04','11:20','🌊','0000','',0,1,false,'2026-08-04 11:20:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.513900000,133.563900000,'坂本龍馬像を見学','龍馬像の迫力に感動。太平洋を見つめる姿がかっこよくて、写真を何枚も撮ってしまった。','2026-08-04','11:40','🗿','0000','',0,1,false,'2026-08-04 11:40:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514800000,133.561200000,'桂浜茶屋で休憩','名物のアイスクリンを食べながら海を眺める。軽い甘さが暑い体にちょうどいい。','2026-08-04','12:10','🍦','0000','',-350,1,false,'2026-08-04 12:10:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559300000,133.531700000,'高知市中心部へ戻る','バスで市街地へ戻る。街の明るい雰囲気が心地よくて、歩くだけで楽しい。','2026-08-04','13:00','🚌','0000','',0,1,false,'2026-08-04 13:00:00+09','2026-08-02 01:58:27.047402+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559000000,133.533600000,'ひろめ市場で昼食','カツオのたたきを豪快にいただく。藁焼きの香りが最高で、思わず「うまい！」と声が出た。','2026-08-04','13:30','🍣','0000','',-1600,1,false,'2026-08-04 13:30:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559200000,133.533900000,'市場内をぶらぶら','地元のお店が並んでいて見ているだけで楽しい。お土産の試食もあってテンションが上がる。','2026-08-04','14:00','🛍️','0000','',0,1,false,'2026-08-04 14:00:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560300000,133.531900000,'高知城へ向かう','城下町の雰囲気が残る道を歩く。石垣が見えてくるとワクワクがさらに高まる。','2026-08-04','14:40','🏯','0000','',0,1,false,'2026-08-04 14:40:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560040000,133.531430000,'高知城天守に登る','天守からの眺めが最高。高知の街並みと青空が広がっていて、気持ちが明るくなる景色。','2026-08-04','15:10','📸','0000','',0,1,false,'2026-08-04 15:10:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559500000,133.532200000,'城下で休憩','城下のカフェでアイスコーヒーを飲みながら写真を整理。旅の充実感がじんわり広がる。','2026-08-04','15:40','☕','0000','',-580,1,false,'2026-08-04 15:40:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559000000,133.533600000,'ひろめ市場でお土産購入','カツオ関連のお土産を購入。店員さんが気さくで、つい色々買ってしまった。','2026-08-04','16:20','🎁','0000','',-1400,1,false,'2026-08-04 16:20:00+09','2026-08-02 01:58:27.047402+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559705000,133.531110000,'高知駅で旅の締め','駅ナカで軽く休憩しながら今日の写真を見返す。明るく楽しい一日だった。','2026-08-04','17:00','🚉','0000','',0,1,false,'2026-08-04 17:00:00+09','2026-08-02 01:58:27.047402+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.694120000,135.191230000,'新神戸駅に到着、優雅な神戸マダム旅の始まり','都会的な洗練された空気が漂う新神戸駅に、仲良しのマダム仲間たちと優雅に集合。駅から一歩踏み出せば、海と山が織りなす美しい港町・神戸の景色が迎えてくれる。これから始まる極上のスイーツやおしゃれなスポット巡りに、胸が高鳴る贅沢な一日の幕開けです。','2026-12-04','10:00','✨','0','',0,1,false,'2026-12-04 10:05:12+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705670000,135.188900000,'「神戸布引ハーブ園」でロープウェイ空中散歩とハーブの香り','ロープウェイに揺られて、眼下に広がる神戸の街並みと港を眺めながら空中散歩を楽しむ。山頂駅に到着すると、季節のハーブや色鮮やかな花々が咲き誇る美しいガーデンがお出迎え。心地よい香りに包まれながら、優雅なハーブティーを味わい心からリフレッシュ。','2026-12-04','10:45','🌿','0','',-1800,1,false,'2026-12-04 11:15:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.701230000,135.185430000,'1軒目：北野坂のおしゃれな隠れ家カフェでランチ','北野坂の上品な雰囲気に溶け込む、隠れ家のような素敵なカフェでランチタイム。地元の新鮮な野菜をふんだんに使った彩り豊かなオープンサンドと、香り高い自家焙煎コーヒーをいただく。窓から差し込む柔らかな光の中で、楽しくおしゃべりに花が咲く。','2026-12-04','12:30','☕','0','',-1600,1,false,'2026-12-04 13:00:00+09','2026-08-01 21:41:37.27133+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.703450000,135.187890000,'異国情緒あふれる「北野異人館街」で歴史と建築美を鑑賞','かつての外国人の邸宅が立ち並ぶ北野異人館街を、ドレスコードを意識した装いでのんびりとお散歩。代表的な「風見鶏の館」や「萌黄の館」を見学し、明治・大正ロマンを感じさせるハイカラなインテリアや美しい洋風建築の数々にすっかり魅了される。どこを切り取っても絵になる空間。','2026-12-04','14:00','🏛️','0','',-650,1,false,'2026-12-04 14:30:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.691230000,135.190120000,'2軒目：北野の老舗パティスリーで絶品モンブラン','お散歩の途中で、神戸スイーツの代名詞とも言える超有名パティスリーに立ち寄る。目の前で絞り出される極上の和栗モンブランと香り高い紅茶のセットを堪能。上品な甘さと滑らかな口溶けに、一同「美味しいね」と自然と笑みがこぼれる至福のひととき。','2026-12-04','15:45','🍰','0','',-1400,1,false,'2026-12-04 16:15:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.690120000,135.194560000,'レトロモダンな「旧居留地」で洗練された街並み散策','かつての外国人生留地であり、現在は高級ブランドショップや洗練されたセレクトショップが並ぶ旧居留地エリアへ。ヨーロッパの街並みを思わせる重厚な石造りの近代建築が美しく、ウインドウショッピングをしながら歩くだけで、まるでパリやロンドンを旅しているような優雅な気分に浸れる。','2026-12-04','17:00','🛍️','0','',0,1,false,'2026-12-04 17:30:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.688900000,135.193450000,'3軒目：旧居留地の上質なフレンチレストランで優雅なティータイム','洗練されたインテリアが光る一軒家フレンチのサロンにて、美しいヴィンテージカップに入ったブレンドティーと焼き菓子のセットをいただく。静かで落ち着いた大人の空間の中で、これからの人生や趣味についてゆっくりと語り合う、大人の女性にふさわしい贅沢な時間。','2026-12-04','18:30','🍮','0','',-1800,1,false,'2026-12-04 19:00:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.687560000,135.195670000,'「東遊園地」の開放的な芝生広場で緑の癒やしを感じる','都会の真ん中にあるとは思えないほど緑豊かで美しい東遊園地をゆっくりとお散歩。手入れの行き届いた芝生やおしゃれな本棚を眺めながらベンチでひと休み。鳥のさえずりや木漏れ日を感じつつ、神戸の街の心地よい風を全身で受け止める。','2026-12-05','09:30','🌳','0','',0,1,false,'2026-12-05 10:00:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.684560000,135.187890000,'神戸モトマチショッピングストリートでこだわりの雑貨探し','歴史ある元町商店街へと足を延ばし、職人技が光る上質なバッグや神戸ならではのおしゃれなインポート雑貨を丁寧に見て回る。量販店にはない、作り手のこだわりが詰まった一点もののアイテムとの出会いに、ショッピング熱が心地よく刺激される。','2026-12-05','11:00','👜','0','',0,1,false,'2026-12-05 11:30:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685670000,135.189010000,'4軒目：元町の老舗洋食店で味わう伝統のビーフシチュー','夕暮れ時に、神戸マダムの間でもファンの多い老舗の洋食レストランへ。じっくりと何日も煮込まれてお肉がトロトロに溶け込んだ絶品のビーフシチューをいただく。深みのあるデミグラスソースの味わいに、長年愛され続けてきた本物の伝統の味を実感。','2026-12-05','12:45','🍽️','0','',-2400,1,false,'2026-12-05 13:15:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681230000,135.184560000,'「神戸ハーバーランドumie」で港町の美しい夕景を眺める','海沿いの開放的なハーバーランドエリアへ移動し、茜色に染まる神戸港の夕景を眺める。海風を感じながらボードウォークをのんびり歩き、赤レンガ倉庫のロマンチックな佇まいや、行き交う船の姿をカメラにおさめる。','2026-12-05','14:30','🌅','0','',0,1,false,'2026-12-05 15:00:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680120000,135.183450000,'「神戸ポートタワー」の洗練されたリニューアル姿を見上げる','美しくリニューアルされ、赤くしなやかなシルエットが際立つ神戸ポートタワーの真下へ。モダンに生まれ変わったタワーの圧倒的な存在感と、周囲の近代的なイルミネーションが織りなす神戸ならではの美しい夜景を贅沢に満喫する。','2026-12-05','16:00','🗼','0','',-1000,1,false,'2026-12-05 16:30:00+09','2026-08-01 21:41:37.27133+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632900000,139.880000000,'舞浜駅に戻り、帰路の電車へ','楽しかった一日に名残りを惜しみつつ、舞浜駅から帰りの電車へ。子どもたちは歩き疲れてぐっすり夢の中。充実感いっぱいの最高のディズニー旅だった！','2026-08-05','21:30','🌙','0','',0,1,false,'2026-08-05 21:35:00+09','2026-08-01 16:41:55.293734+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.682340000,135.185670000,'5軒目：モザイクの海側テラスで楽しむ夜カフェのデザート','海に面したおしゃれなカフェのテラス席に陣取り、ライトアップされた神戸の街並みと海面に映るイルミネーションを眺めながら夜カフェタイム。甘さ控えめの濃厚なショコラケーキとハーブティーで、今日一日の素晴らしい思い出をしみじみと振り返る。','2026-12-05','17:30','🌃','0','',-1300,1,false,'2026-12-05 18:00:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686780000,135.191230000,'老舗の高級デパ地下でこだわりの神戸土産を厳選','三宮に戻り、地元の有名ブランドが揃う老舗デパートの地下フロアへ。ご家族や自分へのご褒美として、職人手作りの上品な洋菓子や神戸限定の紅茶、上質な佃煮などを丁寧に吟味して買い求める。お土産選びの時間も旅の大切な楽しみのひとつ。','2026-12-05','18:45','🛍️','0','',-4000,1,false,'2026-12-05 19:15:00+09','2026-08-01 21:41:37.27133+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.766300000,'松山城ロープウェイ乗り場','ロープウェイで山頂へ。松山の街並みが一望できて爽快。','2026-08-12','09:30','🚡','0000','',0,1,false,'2026-08-12 09:30:00+09','2026-08-02 02:06:55.502943+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.692340000,135.193450000,'旅のフィナーレ：夜のバーラウンジでノンアルコールカクテル乾杯','宿泊するホテルの落ち着いた雰囲気のバーラウンジにて、旅の締めくくりとして色鮮やかな特製ノンアルコールカクテルで乾杯。2日間で巡った美しい景色や美味しいスイーツの思い出話が尽きず、優雅で充実した大人の女子旅の余韻に浸る。','2026-12-05','20:00','🍸','0','',-1500,1,false,'2026-12-05 20:30:00+09','2026-08-01 21:41:37.27133+09'),
	 (37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.693450000,135.192340000,'新神戸駅にて名残を惜しみつつ、それぞれの帰路へ','すべてのスケジュールを優雅かつ完璧にこなし、新神戸駅の改札前にてお互いに「また次の素敵な旅を計画しましょうね」と笑顔で挨拶を交わす。心身ともに満たされた素晴らしい神戸マダム旅のエンディングを迎え、それぞれの日常へと帰っていく。','2026-12-05','21:15','👋','0','',0,1,false,'2026-12-05 21:45:00+09','2026-08-01 21:41:37.27133+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.404170000,133.201390000,'「JR尾道駅」に到着、目の前に広がる青い瀬戸内海と島影に胸が高鳴る朝','千光寺山の緑と穏やかな瀬戸内海に挟まれた風情あるJR尾道駅に降り立つ。目に前にきらめく海原と、対岸に浮かぶ島々の美しい風景を眺めながら、これから始まる瀬戸内海の島々を巡る絶景ドライブ＆フェリー旅への期待感に胸を弾ませる。','2026-11-03','09:00','🚢','0','',0,1,false,'2026-11-03 09:30:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.405560000,133.199720000,'1軒目：尾道水道を望むレトロなカフェで味わう、自家製レモンスカッシュとモーニング','尾道水道を行き交う個性豊かな渡船を眺めながら、海沿いのスタイリッシュなカフェで朝のひととき。瀬戸内特産の爽やかなレモンをふんだんに使った自家製レモンスカッシュをいただき、心地よい海風を感じながら優雅で穏やかな朝の時間を満喫する。','2026-11-03','09:30','🍋','0','',-900,1,false,'2026-11-03 10:00:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.408330000,133.197500000,'「尾道本通商店街」をぶらりお散歩、ノスタルジックな昭和の面影に触れる','歴史ある寺社やおしゃれな雑貨店が立ち並ぶ、情緒あふれる尾道本通商店街をゆっくりとお散歩。昔ながらの看板建築や猫の細道へと続く路地裏の景色を楽しみながら、のんびりと流れる尾道ならではの温かい時間を肌で感じる。','2026-11-03','10:30','🐈','0','',0,1,false,'2026-11-03 11:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.410560000,133.203330000,'ロープウェイで一気に登る「千光寺公園展望台」から、瀬戸内海の絶景を一望','ロープウェイに揺られて一気に山頂の千光寺公園展望台へとアクセス。眼下に広がる尾道水道と、点在する島々を結ぶ尾道大橋の壮大なパノラマビューを目の当たりにし、あまりの美しさに時間を忘れて見入ってしまう。','2026-11-03','11:30','🚡','0','',-700,1,false,'2026-11-03 12:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.401110000,133.178330000,'「しまなみ海道」の起点・向島から、多島美の海峡を渡るドライブのスタート','車に乗り込み、いよいよサイクリストの聖地としても名高い「しまなみ海道」の島々へ。最初の島である向島から、幾重にも重なる青い海と美しい島影が織りなす「多島美」の絶景の中へと車を走らせ、爽快なドライブを楽しむ。','2026-11-03','13:00','🚗','0','',0,1,false,'2026-11-03 13:30:00+09','2026-08-02 01:11:59.76357+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.316670000,133.111110000,'2軒目：レモンの島・生口島「瀬戸田サンセットビーチ」で味わう名物ジェラート','レモンの生産量日本一を誇る生口島へ渡り、美しい白砂のビーチが広がる瀬戸田サンセットビーチに立ち寄る。地元の新鮮な柑橘やミルクをふんだんに使った絶品ジェラートを味わいながら、穏やかな波音を聞いて心からリフレッシュする。','2026-11-03','14:30','🍦','0','',-500,1,false,'2026-11-03 15:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.298610000,133.061390000,'「多々羅大橋」を渡り、空に浮かぶような斜張橋のダイナミックな造形美を体感','愛媛県と広島県を結ぶ日本屈指の美しさを誇る「多々羅大橋」を車で渡る。青い海と空の間に美しく架かる巨大な斜張橋の上からの眺めはまるで空を飛んでいるかのような爽快感があり、瀬戸内海のスケールの大きさに感動する。','2026-11-03','15:30','🌉','0','',-1000,1,false,'2026-11-03 16:00:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.300560000,133.058330000,'3軒目：多々羅しまなみ公園のレストランで味わう、新鮮な鯛の塩ラーメンのランチ','多々羅大橋のたもとにある道の駅のレストランで、遅めの贅沢なランチタイム。瀬戸内で水揚げされた新鮮な真鯛の旨味が凝縮された絶品の塩ラーメンをいただき、香ばしいスープの一滴まで残さず美味しく完食してお腹も大満足。','2026-11-04','12:00','🍜','0','',-950,1,false,'2026-11-04 12:45:00+09','2026-08-02 01:11:59.76357+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.013510000,134.586240000,'徳島駅で休憩','駅ナカのカフェでアイスコーヒー。今日の写真を見返しながら余韻に浸る。','2026-08-10','17:10','☕','0000','',-520,1,false,'2026-08-10 17:10:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559705000,133.531110000,'高知駅へ移動','電車で高知へ。南国の空気が広がっていて気持ちが明るくなる。','2026-08-11','09:00','🚉','0000','',0,1,false,'2026-08-11 09:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514350000,133.562870000,'桂浜へ到着','太平洋の広さに圧倒される桂浜。波の音が心地よくてしばらく砂浜でぼーっとする。','2026-08-11','10:00','🌊','0000','',0,1,false,'2026-08-11 10:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.513900000,133.563900000,'坂本龍馬像を見学','龍馬像の迫力に感動。太平洋を見つめる姿がかっこよくて写真を何枚も撮る。','2026-08-11','10:20','🗿','0','',0,1,false,'2026-08-11 10:20:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514800000,133.561200000,'桂浜茶屋で休憩','名物アイスクリンを食べながら海を眺める。軽い甘さが暑い体にちょうどいい。','2026-08-11','10:50','🍦','0','',-350,1,false,'2026-08-11 10:50:00+09','2026-08-02 02:06:55.502943+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559000000,133.533600000,'ひろめ市場で昼食','カツオのたたきを豪快にいただく。藁焼きの香りが最高でテンションが上がる。','2026-08-11','12:00','🍣','0000','',-1600,1,false,'2026-08-11 12:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.225000000,133.033330000,'「大三島・大山祇神社」を参拝、神聖なクスノキの巨樹からパワーを授かる','日本総鎮守として古くから信仰を集める大三島の「大山祇神社」に立ち寄る。境内を厳かに包み込む樹齢数千年のご神木の巨大なクスノキの姿に圧倒され、静寂に満ちた境内をゆっくりと歩きながら厳かなパワーをいただく。','2026-11-04','13:30','🌲','0','',0,1,false,'2026-11-04 14:15:00+09','2026-08-02 01:11:59.76357+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.404170000,133.201390000,'尾道市街地に戻り、夜の海風が心地よいウォーターフロントをナイトクルーズ','夕方再び尾道に戻り、ライトアップされた尾道大橋や夜の港を望むウォーターフロントへ。潮風を感じながらおだやかな海岸線をゆっくりと散策し、旅の1日目を締めくくる静かでロマンチックな夜のひとときを過ごす。','2026-11-04','16:30','🌙','0','',0,1,false,'2026-11-04 17:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.402780000,133.198330000,'尾道水道の絶景を間近に臨む、隠れ家的なリノベーションホテルにチェックイン','本日の宿泊先である、歴史ある古い倉庫を美しくリノベーションした洗練されたホテルにチェックイン。窓の外に広がる穏やかな尾道水道の夜景を眺めながら、旅の荷物を解いてほっと一息ついてリラックスする。','2026-11-04','17:30','宿','0','',-28000,1,false,'2026-11-04 18:00:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.403890000,133.200500000,'宿のメインダイニングにて、瀬戸内海の旬の海の幸と地野菜をふんだんに使った夕食','夕食は宿の美しいダイニングで、瀬戸内海の荒波にもまれた新鮮な魚介や地元の豊かな野菜をふんだんに使った創作コース料理を堪能。素材の持ち味を活かした繊細な味わいと、極上の地酒のマリアージュに心から酔いしれる。','2026-11-04','19:00','🍽️','0','',0,1,false,'2026-11-04 20:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839400000,132.765200000,'松山城天守','天守からの眺めが美しくて写真を何枚も撮る。風が気持ちいい。','2026-08-12','10:00','📸','0','',0,1,false,'2026-08-12 10:00:00+09','2026-08-02 02:06:55.502943+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.347500000,133.722220000,'翌日、フェリーを乗り継いで現代アートの聖地・直島へ向かう海の旅','旅行2日目は少し趣向を変えてフェリーに乗り込み、瀬戸内海に浮かぶ現代アートの聖地・直島へと海の旅へ向かう。波飛沫を上げながら進むフェリーの甲板から、青く輝く海と遠くに見える島々の美しい景色を眺める贅沢な移動時間。','2026-11-05','10:00','⛴️','0','',-1500,1,false,'2026-11-05 11:30:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.455560000,133.916670000,'「直島・地中美術館」のコンクリート建築と自然が融合した空間芸術に圧倒される','自然を損なわないよう地下に埋設された「地中美術館」に到着。建物そのものが巨大なアート作品となっている空間の中で、モネの睡蓮をはじめとする世界的名作の数々と静かに対峙し、これまでにない深い感動と知的刺激を受ける。','2026-11-05','13:00','🎨','0','',-2100,1,false,'2026-11-05 14:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.458330000,133.980560000,'4軒目：直島の美しい海岸沿いのおしゃれなカフェで、島レモンタルトのティータイム','アート巡りの合間に、海の見える開放的なカフェテラスに立ち寄る。甘酸っぱい島レモンの風味が口いっぱいに広がる特製レモンタルトと、こだわりのアイスコーヒーをいただきながら、目の前に広がる瀬戸内海の絶景を眺めてのんびりティータイム。','2026-11-05','15:00','🍰','0','',-1100,1,false,'2026-11-05 15:45:00+09','2026-08-02 01:11:59.76357+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839000000,132.765900000,'城下町散策','城下町の落ち着いた雰囲気が心地よくて歩くだけで楽しい。','2026-08-12','10:30','🌿','0000','',0,1,false,'2026-08-12 10:30:00+09','2026-08-02 02:06:55.502943+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.998503700,135.843200684,'JR大津駅前にてレンタサイクルを借りて、琵琶湖サイクリング出発','サイクリング日和の爽やかな青空の下、JR大津駅前に集合。整備されたスポーツタイプのレンタサイクルに跨がり、いよいよ日本最大の湖・琵琶湖を巡る大冒険の幕開け。湖風を心地よく感じながら、まずは湖岸道路を目指してペダルを軽快に踏み出していく。','2026-05-13','09:00','🚲','0','',-1500,1,false,'2026-05-13 09:15:00+09','2026-08-01 21:53:09.350587+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.004690717,135.874099731,'「琵琶湖疏水（浜大津付近）」の歴史的な水辺景観を眺める','琵琶湖から京都へと水を引いた歴史ある琵琶湖疏水の周辺をゆっくりと自転車で走る。水面に映る緑豊かな木々と、明治のロマンを感じさせるレンガ造りの水門が美しく調和しており、走り出しのウォームアップにぴったりの穏やかなスポット。','2026-05-13','09:45','🌊','0','',0,1,false,'2026-05-13 10:15:00+09','2026-08-01 21:53:17.822915+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013689179,135.942077637,'「びわ湖大津館」の美しいイングリッシュガーデンでひと休み','湖畔沿いに佇むクラシックな建築が印象的な、びわ湖大津館の庭園に到着。手入れの行き届いた色鮮やかなイングリッシュガーデンを眺めながら、湖面を渡る涼しい風を受けて深呼吸。サイクリングの疲れを癒やしつつ、早くも湖の壮大な景色に魅了される。','2026-05-13','11:00','🏡','0','',-400,1,false,'2026-05-13 11:30:00+09','2026-08-01 21:53:24.541851+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957300000,130.941900000,'神宮周辺を散策','神宮周辺の坂道を歩きながら、海と街が同時に見える景色に「ここめっちゃ好きかも」と友達がぽつり。写真を撮りながらゆっくり歩く時間が心地よくて、旅の中の静かなひとときになった。','2026-11-03','13:30','🌿','0000','',0,1,true,'2026-11-03 13:30:00+09','2026-08-02 02:38:00.798541+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.044051680,135.933151245,'1軒目：湖岸沿いの開放的なカフェで琵琶湖ブルーソーダ休憩','湖を間近に望むおしゃれなレイクサイドカフェに立ち寄り、最初の休憩タイム。青く澄んだ琵琶湖の水をモチーフにした鮮やかなブルーソーダと手作りマフィンをいただく。大きなガラス窓の向こうに広がる雄大なレイクビューを眺めながら、最高のティータイムを満喫。','2026-05-13','12:30','☕','0','',-1100,1,false,'2026-05-13 13:00:00+09','2026-08-01 21:53:34.627325+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.081848467,135.950660706,'琵琶湖大橋を渡り、西岸から東岸（湖東エリア）へ爽快ライド','全長約1.4キロを誇る琵琶湖大橋の自転車道へアプローチ。少し坂を登り切ると、左右に視界いっぱいの大パノラマが広がり、まるで湖の上を飛んでいるかのような爽快感抜群の空中サイクリングを体験。橋の上で吹き抜ける風が最高に気持ちいい。','2026-05-13','14:00','🌉','0','',-200,1,false,'2026-05-13 14:30:00+09','2026-08-01 21:53:42.969479+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.117381145,135.965423584,'「ウッディパル木戸」周辺ののどかな田園風景と並木道','東岸（湖東・湖西側）の整備されたサイクリングロードを北上し、緑豊かな並木道を抜けていく。車通りが少なく、道の両側に広がる黄金色の田園風景や遠くに見える鈴鹿山脈の山並みを眺めながら、ペダルを踏む足取りも自然と軽くなる。','2026-05-13','15:30','🌳','0','',0,1,false,'2026-05-13 16:00:00+09','2026-08-01 21:53:50.646825+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.138861770,136.041812897,'「八幡堀」の水郷地帯をめぐる伝統的な景観散策','かつて豊臣秀次によって開かれた八幡堀へ。石畳の小道と白壁の土蔵が続く美しい水郷の景色を、自転車を押し歩きながらのんびりと鑑賞する。江戸時代の面影を色濃く残す静寂で情緒あふれる空間に、心から癒やされるひととき。','2026-05-14','12:00','🛶','0','',0,1,false,'2026-05-14 12:30:00+09','2026-08-01 21:54:07.110638+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.711110000,138.258330000,'下山後の至福、山梨の温泉施設で汗を流す','登山バスを乗り継ぎ、下山後に立ち寄った地元の温浴施設へ。冷えた温泉に浸かった瞬間、凝り固まった筋肉がほぐれていく至福の感覚に「生き返る〜」と思わず声が漏れる。湯上がりには冷たい牛乳を飲み干し、最高の爽快感を味わう。','2026-08-09','16:00','♨️','0','',-800,1,false,'2026-08-09 16:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.703890000,138.256110000,'「芦安駐車場」に戻り、それぞれの日常へと帰る解散の時','すべての行程を終えて芦安駐車場に戻り、愛車に乗り込む前にお互いの健闘をたたえ合って三者三様の帰路につく。過酷で最高に楽しいオッサン三人組の南アルプス登山旅行の余韻に浸りながら、また次の冒険への活力を胸にハンドルを握る。','2026-08-09','21:00','🚗','0','',0,1,false,'2026-08-09 21:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.705000000,138.255560000,'打ち上げの居酒屋で甲州名物の馬刺しと地酒を堪能','旅の締めくくりは、地元の隠れ家的居酒屋での盛大な打ち上げ。新鮮な甲州名物の馬刺しやほうとうをつまみに、冷えたビールと地酒を次々と空けていく。「また来年もどこかの山に行こうぜ！」と熱い約束を交わし、笑いの絶えない夜を過ごす。','2026-08-09','18:30','🍺','0','',-5000,1,false,'2026-08-09 19:00:00+09','2026-08-01 22:13:19.75489+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.621940000,138.596670000,'「草津温泉バスターミナル」に到着、三世代みんな揃っての温泉旅の幕開け','心地よい硫黄の香りがふわりと漂う草津温泉バスターミナルに到着。元気いっぱいの孫たち、優しい笑顔の祖父母、そして頼もしい親世代の三世代全員が揃い、これから始まる家族みんなの温泉旅行への期待感に胸を弾ませる。記念すべき最初の家族写真をパシャリと撮影。','2026-09-12','10:00','🚌','0','',0,1,false,'2026-09-12 10:30:00+09','2026-08-01 22:16:06.610551+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.453060000,133.919440000,'海の玄関口・直島のフェリーターミナルにて、たくさんの感動を胸に帰路につく','すべての行程を大満足で終え、直島の海の玄関口である象徴的なフェリーターミナルへ。「青い海と島々、そして素晴らしいアートに出会えた最高の旅だったね」と笑顔で語り合いながら、思い出深い瀬戸内海の旅のフィナーレを迎える。','2026-11-05','16:30','👋','0','',0,1,false,'2026-11-05 17:15:00+09','2026-08-02 01:11:59.76357+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.613330000,135.021390000,'「淡路ハイウェイオアシス」に到着、青く輝く海と明石海峡大橋の絶景に大興奮','本州から海を渡り、爽快なドライブの途中で最初に立ち寄った淡路ハイウェイオアシス。目の前にパノラマで広がる真っ青な播磨灘と雄大な明石海峡大橋の姿に、思わずみんなで「わぁ、きれい！」と歓声を上げる。心地よい潮風を受けながら、最高の淡路島ドライブ旅がいよいよ元気にスタートする。','2026-12-04','09:00','🚗','0','',0,1,false,'2026-12-04 09:30:00+09','2026-08-02 01:16:03.346395+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.275670000,136.251230000,'国宝「彦根城」の雄大な天守と緑豊かなお堀端を巡る','白亜の美しい姿を誇る国宝・彦根城の周辺へ。緑豊かなお堀端の道を自転車で優雅に走り抜け、歴代の井伊家が治めた城下町の歴史的な雰囲気を肌で感じる。立派な石垣や歴史的建造物の前で記念の写真をパシャリと撮影。','2026-05-15','09:30','🏯','0','',-800,1,false,'2026-05-15 10:00:00+09','2026-08-01 21:51:14.14927+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.278900000,136.256780000,'4軒目：彦根城下の老舗甘味処で名物・ひこにゃんモチーフの和スイーツ','城下町のレトロな商店街にある老舗の甘味処に立ち寄り、甘いものでちょっと一息。宇治抹茶をふんだんに使った濃厚な抹茶パフェと、地元で愛される温かいお団子をいただく。疲れた体に優しい甘さがスーッと広がり、仲間との会話も弾む。','2026-05-15','11:00','🍡','0','',-1200,1,false,'2026-05-15 11:30:00+09','2026-08-01 21:51:14.14927+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.281230000,136.261230000,'「夢京橋キャッスルロード」の白壁の町並みをポタリング','江戸時代の城下町を再現した夢京橋キャッスルロードを、情緒を味わいながらのんびりポタリング（散走）。統一された切妻屋根や白壁の美しい町並みの中を自転車で走る姿は、まるでタイムスリップしたかのような非日常感を演出してくれる。','2026-05-15','12:30','🏮','0','',0,1,false,'2026-05-15 13:00:00+09','2026-08-01 21:51:14.14927+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.284560000,136.265670000,'5軒目：旅のフィナーレに味わう近江ちゃんぽんの温かい一杯','サイクリングのゴール地点の近くにある人気店にて、滋賀県民のソウルフードである「近江ちゃんぽん」を全員で食べる。黄金色の優しいお出汁と山盛りの野菜、お酢を入れてさっぱりと仕上げる味わいが、2日間ペダルを漕ぎ続けた体に最高の締めくくりとなる。','2026-05-15','13:45','🍜','0','',-950,1,false,'2026-05-15 14:15:00+09','2026-08-01 21:51:14.14927+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.286780000,136.267890000,'彦根のサイクリングステーションにて自転車を返却し、感動のゴール','無事にすべての行程を走り切り、ゴール地点のサイクリングステーションに到着して自転車を無事に返却。琵琶湖の大自然と美味しいグルメを全身で満喫した達成感に浸りながら、最高の笑顔で記念撮影をして旅の幕を閉じる。','2026-05-15','15:00','🎉','0','',0,1,false,'2026-05-15 15:30:00+09','2026-08-01 21:51:14.14927+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.130298278,136.004047394,'2軒目：近江八幡の古民家カフェで味わう近江牛コロッケランチ','歴史的な蔵が立ち並ぶ近江八幡エリアに到着し、古い町家を改装した趣のあるカフェでランチ。名物の近江牛を贅沢に使ったサクサクのコロッケと、地元の野菜がたっぷり入ったスーププレートをいただく。旅のエネルギーをしっかりとチャージ。','2026-05-14','10:30','🍽️','0','',-1600,1,false,'2026-05-14 11:00:00+09','2026-08-01 21:53:59.498237+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.178298352,136.068592072,'「長命寺港」の静かな湖岸ベンチで波の音に耳を傾ける','穏やかな波が打ち寄せる長命寺港のほとりで、自転車を止めて小休憩。目の前に広がる琵琶湖の広大さはまるで海のように感じられ、遠くを行き交う観光船や水鳥の姿を眺めながら、穏やかな湖畔の時間を贅沢に味わい尽くす。','2026-05-14','13:30','🌊','0','',0,1,false,'2026-05-14 14:00:00+09','2026-08-01 21:54:18.076948+09'),
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.209581390,136.069450378,'3軒目：湖岸の絶景テラスで食べる近江米おにぎりと豚汁','琵琶湖の絶景を特等席で眺められる湖畔の休憩スポットにて、地元のお米を使った手作りおにぎりとアツアツの豚汁でエネルギー補給。シンプルながらも素材の美味しさがダイレクトに伝わり、サイクリング中の体に染みわたる格別の美味しさ。','2026-05-14','15:00','🍙','0','',-800,1,false,'2026-05-14 15:30:00+09','2026-08-01 21:54:34.401506+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.220520595,136.147899628,'「彦根港」の開放的な景色と湖上のクルーズ船を眺める','歴史ある城下町・彦根の港エリアに到着。青空の下にきらめく湖面と、遠くに見える多景島のシルエットを眺めながら、港のボードウォークをゆっくりと流す。潮風ならぬ湖風を浴びながらの走行は、サイクリングならではの醍醐味。','2026-05-14','16:30','⚓','0','',0,1,false,'2026-05-14 17:00:00+09','2026-08-01 21:54:44.786595+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839700000,132.770300000,'道後温泉で入浴','湯がやわらかくて体が軽くなる。旅の疲れがすっと抜けていく感じが最高。','2026-08-12','11:30','♨️','0000','',-420,1,false,'2026-08-12 11:30:00+09','2026-08-02 02:06:55.502943+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.170910000,136.881550000,'「名古屋駅」に到着、食い倒れの名古屋グルメ旅の始まり','日本の中心・名古屋駅に到着し、これから始まる贅沢なグルメ巡りに胸が高鳴る。駅周辺の活気ある雰囲気を肌で感じながら、仲間たちと「まずは何を食べる？」と笑顔で計画を確認し合う。胃袋の準備を万端にして、いざ魅惑の名古屋めしの世界へ出発。','2026-06-11','09:00','🚅','0','',0,1,false,'2026-06-11 09:15:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.170650000,136.885600000,'1軒目：名駅地下街の老舗で味わう朝の極上「小倉トースト」','まずは名古屋の喫茶店文化を体験すべく、レトロな雰囲気が漂う地下街の老舗喫茶店へ。厚切りのこんがりトーストに、たっぷりのバターと甘さ控えめの自家製小倉あんをのせていただく。サクサクの食感と絶妙な甘じょっぱさが、朝の体に優しく染みわたる最高のスタート。','2026-06-11','09:30','🍞','0','',-850,1,false,'2026-06-11 10:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.181940000,136.906670000,'2軒目：金シャチ横丁で味わう絶品「名古屋コーチン親子丼」','名古屋城のふもとにある金シャチ横丁の人気店に立ち寄り、ランチタイム。ブランド地鶏「名古屋コーチン」を使った贅沢な親子丼をいただく。弾力のあるジューシーなお肉と、濃厚でトロトロの卵が絶妙に絡み合い、一口ごとに思わずうっとりしてしまう美味しさ。','2026-06-11','12:30','🍲','0','',-1600,1,false,'2026-06-11 13:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.319310000,134.043010000,'栗林公園の茶屋で休憩','抹茶と和菓子を楽しみながら庭園を眺める贅沢な時間。心がふわっと明るくなる。','2026-08-03','11:40','🍵','0000','',-700,1,true,'2026-08-03 11:40:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350120000,134.056030000,'商店街をぶらぶら','アーケードが長くて歩きやすい。地元のお店を見て回るだけで楽しい気分になる。','2026-08-03','12:30','🛍️','0000','',0,1,true,'2026-08-03 12:30:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.347820000,134.054720000,'骨付鳥ランチ','香川名物の骨付鳥がジューシーで最高。食べるたびに笑顔になる味。','2026-08-03','13:00','🍗','0000','',-1500,1,true,'2026-08-03 13:00:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350930000,134.060140000,'ことでん瓦町駅周辺散策','レトロな雰囲気が漂う街並み。地元の生活感があって歩いているだけで楽しい。','2026-08-03','14:00','🚋','0000','',0,1,true,'2026-08-03 14:00:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.286540000,134.146720000,'屋島山上へ移動','山上からの瀬戸内海の眺めが素晴らしくて、風がとても気持ちいい。明るい気分になる景色。','2026-08-03','15:10','⛰️','0000','',0,1,true,'2026-08-03 15:10:00+09','2026-08-02 02:10:39.052942+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.286010000,134.147520000,'屋島寺参拝','静かな境内で手を合わせる。心がすっと落ち着いて、気持ちが前向きになる。','2026-08-03','15:40','⛩️','0000','',0,1,true,'2026-08-03 15:40:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.286880000,134.148900000,'展望台で写真撮影','瀬戸内海の島々が一望できる絶景。明るい光に包まれて最高の写真が撮れた。','2026-08-03','16:00','📸','0000','',0,1,true,'2026-08-03 16:00:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342566000,134.046549000,'高松駅へ戻る','夕方の駅は活気があって、今日の写真を見返しながら余韻に浸る時間が心地よい。','2026-08-03','17:20','🚉','0000','',0,1,true,'2026-08-03 17:20:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.344143000,134.050210000,'港で夕暮れを眺める','夕日が海に沈む光景が美しくて、しばらく見入ってしまうほど心が明るくなる瞬間。','2026-08-03','18:10','🌅','0000','',0,1,true,'2026-08-03 18:10:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.347820000,134.054720000,'商店街でお土産購入','地元の和菓子とオリーブ製品を購入。店員さんの優しさにほっこりした気持ちになる。','2026-08-03','18:40','🎁','0000','',-1600,1,true,'2026-08-03 18:40:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342566000,134.046549000,'高松駅で旅の締め','駅ナカのカフェでアイスコーヒーを飲みながら今日の旅を振り返る。明るく楽しい一日だった。','2026-08-03','19:10','☕','0000','',-520,1,true,'2026-08-03 19:10:00+09','2026-08-02 02:10:39.052942+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957300000,130.941900000,'赤間神宮へ参拝','赤間神宮の鮮やかな赤い門が見えてきて「めっちゃ映えるやん」と4人で写真大会。境内は静かで、さっきまでの市場の賑やかさとは違う落ち着いた空気が広がっていた。旅の中でこういう緩急があるのが楽しい。','2026-11-03','13:00','⛩️','0000','',0,1,true,'2026-11-03 13:00:00+09','2026-08-02 02:38:00.798541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957850000,130.941900000,'フグ刺しを堪能','市場の別の店でフグ刺しを注文。透き通るような身が美しくて「これ写真撮らなあかんやつ」と全員で撮影大会。食べると歯ごたえが心地よくて、フグの奥深さを感じる味わいだった。大学生4人でこんな贅沢を味わえるのが嬉しかった。','2026-11-03','14:40','🐡','0000','',-1800,1,true,'2026-11-03 14:40:00+09','2026-08-02 02:38:00.798541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957900000,130.941200000,'海峡ゆめタワーへ移動','市場から歩いて海峡ゆめタワーへ。タワーが近づくにつれて「これ絶対景色やばいやつやん」とテンションが上がる。海沿いの風が気持ちよくて、歩いているだけで旅の楽しさが増していった。','2026-11-03','15:20','🏙️','0000','',0,1,true,'2026-11-03 15:20:00+09','2026-08-02 02:38:00.798541+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.161110000,136.903890000,'3軒目：栄の老舗洋食店で味わう芳醇な「味噌カツ」','名古屋グルメの定番であり、絶対外せない「味噌カツ」を味わいに老舗の専門店へ。サクサクに揚がった肉厚なトンカツに、じっくり煮込まれた濃厚で甘辛い特製八丁味噌ダレがたっぷりとかかっている。一口食べれば、コクのある深い味わいが口いっぱいに広がる。','2026-06-11','17:00','🥩','0','',-1500,1,false,'2026-06-11 17:30:00+09','2026-08-01 21:59:51.737518+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.158330000,136.901390000,'歴史とカルチャーが交差する「大須商店街」をレトロ散歩','古い歴史を持つ寺社とサブカルチャー、多国籍なショップが入り混じる活気あふれる大須商店街へ。下町の温かい雰囲気が漂うアーケードをのんびり歩きながら、地元の人々に愛される活気ある街の空気感を肌で感じる。','2026-06-12','10:00','🏮','0','',0,1,false,'2026-06-12 10:30:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.158060000,136.899720000,'4軒目：大須の行列のできる名店でアツアツの「みそかつ丼」','大須の路地裏にある地元民で賑わう名店に立ち寄り、名物のみそかつ丼を追加で堪能。揚げたてのカツとご飯、そして染み込んだ特製味噌のコンビネーションが抜群で、お腹いっぱいになりながらも箸が止まらない中毒性のある美味しさ。','2026-06-12','11:30','🍛','0','',-1200,1,false,'2026-06-12 12:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.153890000,136.896670000,'「オアシス21」の水の宇宙船で近未来的な空中散歩','ガラスの大屋根「水の宇宙船」が特徴的なオアシス21へ。地上から空中へ続く幻想的なフロアを歩き、ガラス越しにきらめく名古屋の街並みを眺めながら、心地よい夕方の風を感じて優雅なひとときを過ごす。','2026-06-12','13:30','🛸','0','',0,1,false,'2026-06-12 14:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.168330000,136.905560000,'5軒目：老舗うなぎ店で至福の極み「ひつまぶし」を堪能','旅のハイライトとして、名古屋が誇る最高峰グルメ「ひつまぶし」の名店へ。一杯目はそのまま香ばしい鰻とタレの味を楽しみ、二杯目は薬味を添えてさっぱりと、三杯目はお出汁をかけてお茶漬けでいただく。三段階の絶品の変化に感動の連続。','2026-06-12','15:00','🍱','0','',-4200,1,false,'2026-06-12 15:30:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.165280000,136.901390000,'「伏見地下街」の昭和レトロな空間でディープな街並み体験','かつての面影を色濃く残す、隠れ家的な伏見地下街のレトロな通路を歩く。現代のきらびやかな名古屋とは一味違う、昭和のノスタルジーが詰まった独特の空間に迷い込み、ディープな名古屋の歴史の奥行きをしみじみと味わう。','2026-06-12','16:45','🚪','0','',0,1,false,'2026-06-12 17:15:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.166940000,136.905280000,'6軒目：名古屋の夜を彩る名店でピリ辛「台湾ラーメン」','名古屋の夜の締めくくりとして、ピリッとした辛さがクセになる元祖「台湾ラーメン」のお店へ。たっぷりの挽き肉とニラ、特製唐辛子の効いたスープが麺によく絡み、汗をかきながらもスープを飲み干してしまうほどのやみつきになる旨さ。','2026-06-12','18:30','🍜','0','',-980,1,false,'2026-06-12 19:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.172220000,136.908330000,'「テレビ塔周辺の夜景」とライトアップされた街並みを眺める','夜の帳が下りた久屋大通公園に戻り、美しくライトアップされたタワーと周囲のモダンなビル群が織りなす幻想的な夜景を眺める。きらびやかな光に包まれた名古屋の夜の美しさに、今日一日食べた美味しい記憶がよみがえる。','2026-06-12','19:45','🌃','0','',0,1,false,'2026-06-12 20:15:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.171390000,136.883330000,'お土産選び：駅ナカの老舗ショップで絶品「手羽先唐揚げ」を調べる','旅の最後のお楽しみとして、名古屋駅ナカの充実したお土産フロアへ。ジューシーでスパイシーな香りが食欲をそそる有名店の「手羽先唐揚げ」や、ういろう、名古屋めしのお土産を丁寧に吟味して、家族や自分への最高の思い出の品を選ぶ。','2026-06-12','20:30','🛍️','0','',-2000,1,false,'2026-06-12 21:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.170830000,136.881940000,'「名古屋駅」にて大満足のグルメ旅のフィナーレと帰路','すべての行程を食べ尽くし、大満足の笑顔で名古屋駅の改札前に集合する。「また絶対に来たいね」とお互いに語り合いながら、心もお腹も極上に満たされた素晴らしい名古屋グルメ旅のエンディングを迎え、それぞれの帰路につく。','2026-06-12','21:15','👋','0','',0,1,false,'2026-06-12 21:45:00+09','2026-08-01 21:59:51.737518+09'),
	 (55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'道後温泉本館へ移動','レトロな建物が美しくてテンションが上がる。温泉街の雰囲気も最高。','2026-08-12','11:00','🏮','0000','',0,1,false,'2026-08-12 11:00:00+09','2026-08-02 02:06:55.502943+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.518330000,134.879170000,'海の幸とブランド肉の競演！淡路ビーフと新鮮魚介を味わう豪華リゾートディナー','お待ちかねの夕食は、南国リゾートの風がそよぐ明るいダイニングで豪華なディナータイム。きめ細やかな肉質でとろけるような甘みの「淡路ビーフ」のステーキや、瀬戸内海で獲れたピチピチの新鮮なお魚を堪能し、美味しいお酒とともに笑顔が絶えない賑やかな夜を過ごす。','2026-12-05','20:15','🍷','0','',0,1,false,'2026-12-05 21:30:00+09','2026-08-02 01:16:03.346395+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.453890000,139.596670000,'レトロな佇まいが美しい「日光金谷ホテル」の歴史的エントランス','日本最古のリゾートホテルとして知られる日光金谷ホテルのクラシックな外観を眺めながら坂道を登る。随所に西洋の伝統と日本の伝統美が融合した明治ロマンの香りが漂い、かつての貴人たちが愛した優雅な空気を肌で感じる素晴らしい散策スポット。','2026-07-08','10:45','🏛️','0','',0,1,false,'2026-07-08 11:15:00+09','2026-08-01 22:06:57.714791+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.391030000,132.453530000,'平和記念公園を散策','公園内を歩きながら、川沿いの静けさと広い空に少し気持ちが軽くなった。友達と「こういう場所に来ると考えること増えるよな」と話しながら、ゆっくりとした時間を過ごした。','2026-10-05','10:10','🌿','0000','',0,1,false,'2026-10-05 10:10:00+09','2026-08-02 02:22:32.157548+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.451940000,139.599170000,'鮮やかな朱色が目を引く世界遺産「神橋」の美しい姿を望む','大谷川の清流にかかる、神聖な朱塗りの美しい「神橋」のたもとに到着。古くから日光山の入口として崇められてきた神秘的な佇まいは、周囲の新緑や紅葉と見事なコントラストを描き、思わずカメラを向けたくなる絶景スポット。','2026-07-08','11:30','🌉','0','',-300,1,false,'2026-07-08 12:00:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455000000,139.599720000,'世界遺産「日光山輪王寺」の三仏堂で荘厳な仏像を拝観','徳川家ゆかりの天台宗の別格本山・輪王寺の「三仏堂」に足を踏み入れる。圧倒的なスケールを誇る金色の三体の仏像（千手観音像・阿弥陀如来像・馬頭観音像）の前に静かに佇み、心穏やかに手を合わせることで、深い安らぎと厳かな時間に包まれる。','2026-07-08','13:00','🛕','0','',-400,1,false,'2026-07-08 13:30:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.458330000,139.600560000,'国宝「日光東照宮」の絢爛豪華な陽明門と眠り猫に魅了される','いよいよ旅のハイライトである世界遺産・日光東照宮へ。幾重にも施された極彩色の彫刻や、一日中眺めていても飽きないと言われる「陽明門」、そして平和の象徴である「眠り猫」の精巧な芸術美をじっくりと見学し、江戸時代の圧倒的な職人技に深く感嘆する。','2026-07-08','14:15','🦁','0','',-1600,1,false,'2026-07-08 14:45:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.456670000,139.601390000,'徳川家康公の眠る神聖な奥宮へと続く「眠り猫の参道」を歩く','「眠り猫」のくぐり戸を抜け、207段の石段が続く杉木立の参道を一歩一歩静かに登る。鬱蒼と茂る巨大な杉の木が作り出す荘厳なトンネルの中を進むにつれて、俗世から離れた神聖な空間に心がどんどん澄んでいくのを感じる。','2026-07-08','15:45','🌲','0','',0,1,false,'2026-07-08 16:15:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.457500000,139.601940000,'2軒目：東照宮参道の老舗食堂で湯波（ゆば）蕎麦ランチ','参拝を終えた後は、日光名物である「湯波（ゆば）」をふんだんに使った名物の湯波蕎麦を老舗の落ち着いた食事処でいただく。出汁をたっぷりと吸い込んだジューシーな巻き湯波と香り高い手打ち蕎麦の組み合わせが、歩き疲れた体にたまらなく美味しい。','2026-07-09','11:00','🍲','0','',-1350,1,false,'2026-07-09 11:30:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455560000,139.598890000,'縁結びのパワースポット「日光二荒山神社」で旅の平穏を祈願','下野国の一宮として古くから信仰を集める日光二荒山神社へ。鮮やかな朱塗りの社殿が美しい境内をゆっくりと巡り、夫婦杉や化け燈籠といった見どころを散策。神聖なパワーが満ちる静かな境内で、旅の安全と日々の平穏を丁寧にお祈りする。','2026-07-09','12:30','⛩️','0','',0,1,false,'2026-07-09 13:00:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.453330000,139.595560000,'3軒目：日光の老舗洋菓子店でいただく極上の日光プリン','石畳の落ち着いた通りにある、こだわりの日光プリン専門店に立ち寄る。厳選された地元の牛乳と新鮮な卵を使い、なめらかな口溶けに仕上げられた濃厚なプリンを味わう。可愛いガラス瓶に入ったスイーツは、旅の疲れを吹き飛ばす甘いご褒美。','2026-07-09','13:45','🍮','0','',-450,1,false,'2026-07-09 14:15:00+09','2026-08-01 22:06:57.714791+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.442780000,139.491670000,'いろは坂のドラマチックなワインディングロードをバスで抜ける','中禅寺湖へと向かう、有名な「第二いろは坂」の急カーブが続くワインディングロードを進む。車窓から望むダイナミックな渓谷の絶景と、季節ごとに表情を変える豊かな山々の緑のパノラマに、思わず息をのむような迫力を味わう。','2026-07-09','15:00','🚌','0','',0,1,false,'2026-07-09 15:30:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.440280000,139.497500000,'「華厳の滝」の轟音としぶきを上げる圧倒的な大瀑布に感動','日本三大名瀑の一つである「華厳の滝」の観覧台へ。高さ97メートルの断崖絶壁を一気に流れ落ちる豪快な水流と、周囲に舞う水しぶきを間近で体感する。自然の生み出す圧倒的なスケールと轟音に、言葉を失うほどの感動を覚える。','2026-07-09','16:00','🌊','0','',-570,1,false,'2026-07-09 16:30:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.435000000,139.495000000,'4軒目：中禅寺湖畔のレトロな洋風カフェで湖を眺めるティータイム','男体山の麓に広がる美しい中禅寺湖のほとりに佇む、クラシックな洋風カフェへ。穏やかな湖面を渡る涼しい風を感じながら、自家焙煎のコーヒーと香ばしいアップルパイをいただく。静寂に包まれた湖畔での優雅なティータイムは、大人の旅にふさわしい贅沢なひととき。','2026-07-09','17:15','☕','0','',-1100,1,false,'2026-07-09 17:45:00+09','2026-08-01 22:06:57.714791+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343720000,134.046930000,'駅前うどん店で朝食','出汁の香りがふわっと広がるかけうどんが最高。旅のスタートにぴったりの一杯。','2026-08-03','10:00','🍜','0000','',-480,1,true,'2026-08-03 10:00:00+09','2026-08-02 02:10:39.052942+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.185560000,136.899170000,'「名古屋城」の荘厳な金のシャチホコと歴史あるお堀を散策','グルメの合間の腹ごしらえとして、名古屋のシンボルである名古屋城へ。青空に映える美しい大天守と、まばゆく輝く金のシャチホコを仰ぎ見ながら、緑豊かな本丸御殿の周辺をゆっくりとお散歩。贅沢な食事を心置きなく楽しむための良い運動になる。','2026-06-11','11:00','🏯','0','',-500,1,false,'2026-06-11 11:30:00+09','2026-08-01 21:59:51.737518+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.320030000,134.042430000,'栗林公園へ移動','庭園の緑が鮮やかで、歩くだけで気持ちが軽くなる。池の反射も美しい。','2026-08-03','11:00','🌿','0000','',0,1,true,'2026-08-03 11:00:00+09','2026-08-02 02:10:39.052942+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.453060000,139.597500000,'お土産選び：日光駅周辺の老舗店で「たまり漬け」と羊羹を吟味','再び日光駅周辺に戻り、旅の思い出となるお土産をじっくりと選び歩く。伝統の味を守り続ける老舗の「たまり漬け」や、上品な甘さの「日光羊羹」、職人手作りの民芸品などを丁寧に買い求め、充実した旅の最後を彩る。','2026-07-10','12:00','🛍️','0','',-2500,1,false,'2026-07-10 12:30:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455000000,139.600500000,'「東武日光駅」にて神社仏閣と大自然を巡る旅のエンディング','すべての行程を無事に巡り、情緒あふれる東武日光駅のホームに立つ。世界遺産の荘厳な社寺建築、奥日光の大自然、そして美味しい地元グルメの数々を深く堪能した心地よい達成感に浸りながら、笑顔で帰路の特急列車に乗り込む。','2026-07-10','13:30','👋','0','',0,1,false,'2026-07-10 14:00:00+09','2026-08-01 22:06:57.714791+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.703890000,138.256110000,'「芦安駐車場」に集合、三人揃って気合を入れ直す朝','早朝の芦安駐車場に、久々に集結したアラフォー・オッサン三人組。これから始まる南アルプス深部への過酷な縦走に向け、ザックの重さを確かめつつ、気合の入ったコーヒーで乾杯。山の天気も上々、男三人だけの熱い登山旅の幕開けに胸が高鳴る。','2026-08-08','05:30','🚙','0','',0,1,false,'2026-08-08 06:00:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.698330000,138.225560000,'南アルプスの急峻な山並みを駆け上がる登山口行きの乗り合いタクシー','マイカー規制の区間を乗り合いタクシーに揺られ、ガタゴトと林道を登っていく。窓の外に広がる深い緑の渓谷と、これから挑む峰々の険しさに圧倒されながら、車内では学生時代からの思い出話や最近の健康談義で早くも大盛り上がり。','2026-08-08','06:15','🚕','0','',-1200,1,false,'2026-08-08 06:45:00+09','2026-08-01 22:12:42.937175+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.392030000,132.454900000,'資料館を見学','展示を見ながら4人とも真剣な表情になり、言葉少なめに歩いた。出口付近で「来てよかったな」と自然に声が出て、大学生の旅らしい少し大人な時間になった。','2026-10-05','11:00','📘','0000','',-200,1,false,'2026-10-05 11:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.688890000,138.163330000,'日本屈指の高峰「北岳」への登り口、広河原山荘に到着','南アルプスの玄関口・広河原に到着し、いよいよ登山道へ足を踏み入れる。澄んだ沢のせせらぎを聞きながら、吊り橋を渡って登山スタート。最初は緩やかだった道も徐々に急勾配へと変わり、三人とも一言も話さず黙々と歩みを進める。','2026-08-08','07:30','⛺','0','',0,1,false,'2026-08-08 08:00:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.673060000,138.165000000,'息を切らしながら登る白根御池小屋のキツい急登区間','標高を上げるにつれて足取りが重くなり、名物の急登「草すべり」の手前で早くも息が上がる。重いザックに肩を食い込ませながら、「お前、最近運動不足じゃないか？」と軽口を叩き合い、お互いを鼓舞しながら一歩一歩足を前に出す。','2026-08-08','09:30','🥾','0','',0,1,false,'2026-08-08 10:00:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.671390000,138.156390000,'緑のなかに佇むオアシス「白根御池小屋」で冷えたビール休憩','ようやくたどり着いた白根御池小屋のテラスで、待ちに待った乾杯の瞬間。冷え切った缶ビールをグイッと煽ると、疲労困憊だった体に染み渡るような極上の美味さが広がる。目の前に広がる雄大な自然のなか、三人で声を揃えて至福のため息をもらす。','2026-08-08','11:30','🍺','0','',-700,1,false,'2026-08-08 12:00:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.678890000,138.146110000,'森林限界を抜けて一気に視界が開ける稜線歩きへ','樹林帯を抜け出し、一気に視界が開けた美しい稜線歩きが始まる。強めの風が火照った体を心地よくクールダウンしてくれる。眼下には雲海が広がり、遠く富士山や中央アルプスの峰々まで見渡せる絶景に、思わず三人で足を止めて見とれてしまう。','2026-08-08','13:00','⛰️','0','',0,1,false,'2026-08-08 13:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.670830000,138.140280000,'日本第2位の高峰「北岳」山頂に三人揃って登頂成功！','ついに標高3193メートルの北岳山頂に三人揃って登頂！ 日本屈指の高みから見下ろす360度の大パノラマと、自分たちの足で登り切ったという確かな達成感が全身を包み込む。肩を組み、満面の笑みで記念撮影をパチリ。','2026-08-08','15:00','🚩','0','',0,1,false,'2026-08-08 15:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.666940000,138.138890000,'雲上の避難所「北岳山荘」にチェックイン、夕暮れの赤く染まる峰々','本日の宿泊地である北岳山荘へ無事に到着。夕暮れ時、西の空に沈む夕日が南アルプスの山々を茜色に染め上げていくドラマチックなマジックアワーを眺める。冷たい風の中、温かい山小屋の食堂へと急ぎ足で滑り込む。','2026-08-08','17:00','🌅','0','',-10000,1,false,'2026-08-08 17:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.168060000,136.908330000,'日本一の繁華街・栄エリアで、大人のショッピング＆街歩き','名古屋の中心地である栄エリアへ移動し、洗練された商業施設やおしゃれなショップが立ち並ぶ大通りを散策。お腹を少し落ち着かせつつ、名古屋ならではのトレンドや活気ある街の雰囲気をたっぷりと満喫しながら、次のグルメスポットへと歩を進める。','2026-06-11','14:00','🛍️','0','',0,1,false,'2026-06-11 14:30:00+09','2026-08-01 21:59:51.737518+09'),
	 (39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.161390000,136.908060000,'「中部電力 MIRAI TOWER」のそびえ立つ美しい姿を見上げる','久屋大通公園に美しく佇む中部電力 MIRAI TOWER（旧・名古屋テレビ塔）の真下へ。都会の緑豊かなオアシスに優しく溶け込む近未来的なデザインを眺めながら、旅の記念にハイセンスな写真を撮影する。','2026-06-11','15:30','🗼','0','',0,1,false,'2026-06-11 16:00:00+09','2026-08-01 21:59:51.737518+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.667220000,138.139170000,'山小屋の夜、消灯までのオッサン三人による熱い夜の語らい','山小屋の食堂の一角で、温かい夕食を食べながら至福の晩酌タイム。缶ビールやウイスキーを傾けつつ、昔の馬鹿な思い出や仕事の愚痴、これからの人生プランまで、普段は言えない本音を夜遅くまで語り合う忘れられない時間。','2026-08-08','19:30','🥃','0','',-1500,1,false,'2026-08-08 20:00:00+09','2026-08-01 22:12:42.937175+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.659170000,138.144170000,'ご来光の瞬間を待ちわびる、朝の寒さと静寂に包まれた「間ノ岳」への縦走','まだ夜が明けきらぬ暗闇の中、ヘッドライトの灯りを頼りに「間ノ岳」へ向けて出発。身を切るような早朝の寒さの中、じっと東の空を見つめ、漆黒の闇から鮮やかなオレンジ色の太陽が昇る感動的なご来光の瞬間を共有する。','2026-08-09','04:30','✨','0','',0,1,false,'2026-08-09 05:00:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.656940000,138.145830000,'日本屈指のスケールを誇る「間ノ岳」山頂で記念撮影','なだらかな稜線を進み、日本百名山の一つである間ノ岳の山頂に到着。周囲の山々が朝日に照らされて黄金色に輝き、南アルプス南部の広大なスケール感を肌で実感する。達成感に満ちた男三人の表情が、朝の光に自然と映える。','2026-08-09','06:30','🏔️','0','',0,1,false,'2026-08-09 07:00:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.665000000,138.150000000,'下山路の途中、バテた足を励まし合う「農鳥小屋」周辺の難所','ここからの長い下山路、連日の疲労が蓄積して足の踏ん張りが利かなくなる。名物小屋主で知られる農鳥小屋の周辺を通過しながら、足の痛みをこらえ、お互いの荷物を少しずつ持ち合いながら慎重に急な斜面を下っていく。','2026-08-09','09:00','⚠️','0','',0,1,false,'2026-08-09 09:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.688890000,138.163330000,'無事に登山口の「広河原」へと生還、安堵の深呼吸','長い長い下りの末、ついにスタート地点である広河原へ無事に生還。無事故で全員が自分の足で戻ってこられた安堵感から、大きく息を吸い込んで「お疲れさん！」と固い握手を交わす。心地よい疲労感が全身を心地よく満たす。','2026-08-09','13:00','🎉','0','',0,1,false,'2026-08-09 13:30:00+09','2026-08-01 22:12:42.937175+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.571940000,134.981670000,'「ニジゲンノモリ」の広大な自然の中で、人気アニメの世界観を体感して大はしゃぎ','県立淡路島公園の中にある大人気のアニメパーク「ニジゲンノモリ」へ。木漏れ日がきらめく爽やかな森の中を歩きながら、ダイナミックなアトラクションや色鮮やかなキャラクターのモニュメントを見つけては大はしゃぎ。童心に帰って思いっきり体を動かし、笑顔があふれる楽しい時間。','2026-12-04','10:30','🌳','0','',-3500,1,false,'2026-12-04 11:30:00+09','2026-08-02 01:16:03.346395+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.436110000,134.873610000,'「あわじ花さじ敷」の丘一面に広がる、季節のカラフルな花畑と青空のコントラストに感動','見渡す限りの青い海と空に向かって広がる「あわじ花さじ敷」の美しい丘陵地帯へ。季節の鮮やかな花々が絨毯のように一面を埋め尽くす圧巻の景色の中をのんびりとお散歩。どこを切り取っても絵になる絶景ロケーションで、記念の写真を何枚もパシャリと楽しく撮影する。','2026-12-04','14:00','🌸','0','',0,1,false,'2026-12-04 14:45:00+09','2026-08-02 01:16:03.346395+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.498610000,134.872220000,'青い海に映えるポップな建物「HELLO KITTY SMILE」でキュートな世界に夢中','西海岸のキラキラした海沿いに佇む、乙女心をくすぐるキュートな施設「HELLO KITTY SMILE」に到着。全面ガラス張りのドームから見下ろすエメラルドグリーンの海と、遊び心あふれるプロジェクションマッピングや可愛い演出に、思わず時間を忘れてワクワクと夢中になってしまう。','2026-12-04','15:30','🎀','0','',-2300,1,false,'2026-12-04 16:15:00+09','2026-08-02 01:16:03.346395+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.392900000,132.457200000,'お好み村で昼食','お好み焼きを囲んで4人でワイワイ。「広島来たらこれやろ！」と盛り上がり、鉄板の音とソースの香りでテンションが一気に回復。大学生らしい賑やかな昼食になった。','2026-10-05','12:00','🍳','0000','',-1500,1,false,'2026-10-05 12:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.508330000,134.873610000,'3軒目：海風感じる「淡路シェフガーデン」で楽しむ、色とりどりのオープンエアランチ','目の前に瀬戸内海の絶景が広がる開放的なフードパーク「淡路シェフガーデン」に立ち寄る。個性豊かな屋台やコンテナショップが並ぶ賑やかな空間で、島食材を使ったバラエティ豊かな絶品グルメをみんなでシェアしながら、太陽の下でわいわいと楽しいランチタイムを満喫。','2026-12-05','12:00','🍴','0','',-1600,1,false,'2026-12-05 12:45:00+09','2026-08-02 01:16:03.346395+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632000000,139.880200000,'ワールドバザールでお土産ショッピング','閉園間際、お土産ショップへ駆け込んで大混雑の中お菓子やグッズを爆買い！レジの長蛇の列にヘトヘトになりながらも、楽しかったねと笑顔でカゴいっぱいに詰めた。','2026-08-05','20:15','🛍️','0','',-12500,0,true,'2026-08-05 20:20:05.1+09','2026-08-01 16:43:46.307334+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.150000000,135.210000000,'道の駅紀の川万葉の里でちょっとひと息','ドライブの締めくくり前に、地元農産物やフルーツが並ぶ道の駅に立ち寄り。冷たいみかんソフトクリームを食べて一息つく。','2026-09-13','16:00','🍦','0','',-800,1,false,'2026-09-13 16:30:00+09','2026-08-01 21:08:04.82446+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.444440000,134.891670000,'オレンジ色に染まる夕陽を眺めながら、西海岸のロマンチックな海岸線をドライブ','夕暮れ時になり、刻々と空と海の色がオレンジ色から茜色へと移り変わる淡路島の西海岸線を車で走らせる。水平線に沈んでいく美しい夕陽を横目に、お気に入りの音楽をかけながら心地よい風を感じる、最高にロマンチックでエモーショナルなドライブ時間。','2026-12-05','17:45','🌅','0','',0,1,false,'2026-12-05 18:30:00+09','2026-08-02 01:16:03.346395+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.519440000,134.880560000,'リゾート感満載の全室オーシャンビューのオシャレなホテルにチェックイン','本日の宿泊先である、南国ムード漂うスタイリッシュなリゾートホテルにチェックイン。窓一面に真っ青な海が広がる明るく爽やかな客室に通され、旅の荷物をほどいてリラックスしながら、これから始まる楽しい夜に胸を弾ませる。','2026-12-05','18:30','🏨','0','',-32000,1,false,'2026-12-05 19:00:00+09','2026-08-02 01:16:03.346395+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.522220000,134.881940000,'ホテルの大浴場と露天風呂で、きらめく星空を見上げながらのびのびリフレッシュ','夕食の前に、波の音が心地よく響くホテル自慢の開放的な露天風呂へと向かう。心地よいお湯にゆったりと体を預けながら、頭上に広がる満天の星空を眺めて一日の旅の疲れがすーっと溶けていくような極上のリラックスタイムを過ごす。','2026-12-05','19:15','✨','0','',0,1,false,'2026-12-05 20:00:00+09','2026-08-02 01:16:03.346395+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350097386,134.745941162,'大鳴門橋の真下にある「渦の道」の海上遊歩道で、足元の豪快な潮流をのぞき見','大鳴門橋の車道の下に設置された海上遊歩道「渦の道」へと歩みを進める。海上45メートルのガラス張りの床から真下を覗き込むと、轟音とともに激しくぶつかり合う日本海の潮の潮流がダイナミックに見え、スリルと爽快感が入り混じる不思議な空中散歩を楽しむ。','2026-12-05','14:30','🌉','0','',-510,1,false,'2026-12-05 15:15:00+09','2026-08-02 01:17:26.238461+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.340601305,134.745426178,'4軒目：道の駅うずしお周辺で味わう、濃厚で甘い「淡路島牛乳ソフトクリーム」','たくさん歩いてちょっぴり熱くなった体に嬉しい、ご当地グルメの淡路島牛乳ソフトクリームをゲット。搾り立てのミルクならではの濃厚なコクとなめらかな口溶けがたまらなく美味しく、甘いひんやりスイーツに思わず笑顔がこぼれる最高の休憩タイム。','2026-12-05','15:30','🍦','0','',-450,1,false,'2026-12-05 16:00:00+09','2026-08-02 01:17:33.930562+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623610000,138.597780000,'湯けむりとエメラルドグリーンの湯が美しい象徴「湯畑」を散策','草津のシンボルである「湯畑」へ移動し、もうもうと湯煙を上げるダイナミックな源泉の光景にみんなで歓声をあげる。エメラルドグリーンの美しい温泉が滝のように流れ落ちる様子を眺めながら、木製の歩道橋をのんびりとお散歩。温泉街ならではの活気ある雰囲気を肌で感じる。','2026-09-12','10:45','♨️','0','',0,1,false,'2026-09-12 11:15:00+09','2026-08-01 22:16:06.610551+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.330678877,134.734096527,'国の名勝「鳴門の渦潮」を間近で見るため、迫力満点の観潮船クルーズへ','島をさらに南下して、世界屈指のダイナミックな潮の流れを誇る鳴門海峡へ。真っ白な飛沫を上げて激しく渦巻く大迫力の「渦潮」を間近で見物できる観光船に乗り込み、船のデッキから「うわぁ、すごい！」と大興奮のスリル満点な海の冒険を体験する。','2026-12-05','13:30','🚢','0','',-2400,1,false,'2026-12-05 14:15:00+09','2026-08-02 01:17:40.817982+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.379004205,134.764137268,'「人形浄瑠璃館」にて、伝統芸能の華麗なパフォーマンスとユーモアある人形劇を鑑賞','淡路島に古くから伝わる伝統文化に触れるため、地元の人形浄瑠璃館へ足を運ぶ。三味線の音色に合わせて生き生きと動き回るダイナミックで繊細なお人形のパフォーマンスに引き込まれ、日本の伝統芸能の奥深さと面白さを楽しくたっぷりと堪能する。','2026-12-05','16:30','🎭','0','',-1000,1,false,'2026-12-05 17:15:00+09','2026-08-02 01:17:50.554017+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.586866879,135.009956360,'1軒目：絶景テラスカフェで味わう、淡路島特産タマネギの甘みたっぷりスープとモーニング','緑豊かな公園内にある開放的なテラスカフェで、きらめく海を眺めながらの朝のひととき。驚くほど甘みが強い淡路島産タマネギをじっくり煮込んだ特製オニオンスープを一口飲むと、優しい旨味が体にじんわりと広がり、今日の楽しい旅へのワクワク感が一段と高まっていく。','2026-12-04','09:30','🧅','0','',-800,1,false,'2026-12-04 10:00:00+09','2026-08-02 01:18:01.914823+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.621110000,138.595000000,'伝統の妙技に大盛り上がり！「熱乃湯」で湯もみ見学と体験','草津温泉の伝統文化である「湯もみ」のショーが開催される熱乃湯へ。威勢の良いかけ声とともに板で湯をかき混ぜるダイナミックなパフォーマンスを間近で鑑賞し、子どもたちは体験コーナーで実際に湯もみに挑戦して大はしゃぎ。家族みんなで大いに盛り上がる。','2026-09-12','13:00','🎭','0','',-2100,1,false,'2026-09-12 13:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.624720000,138.593890000,'2軒目：レトロ可愛いカフェで味わう草津名物の濃厚ソフトクリーム','温泉街の路地裏にある、おしゃれで落ち着いた雰囲気のカフェに立ち寄る。濃厚なミルクのコクと爽やかな甘さが絶品のソフトクリームをみんなでシェアして味わう。歩いて火照った体に冷たいスイーツが心地よく染みわたり、旅の会話が一層弾む。','2026-09-12','14:15','🍦','0','',-1200,1,false,'2026-09-12 14:45:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.619170000,138.591670000,'日本庭園の美しい温泉情緒あふれる「西の河原公園」をゆっくりお散歩','あちこちから温泉が湧き出す湯川沿いの「西の河原公園」へ足を延ばす。ゴロゴロとした岩の間から立ち上る湯気と、豊かな自然が織りなす幻想的な景色の中を、祖父母の手を優しく引きながら三世代でゆっくりと歩く。マイナスイオンに包まれて心が癒やされる。','2026-09-12','15:00','🌳','0','',0,1,false,'2026-09-12 15:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.396260000,132.459840000,'紙屋町をぶらぶら','街中を歩きながらカフェやショップを見て回る。友達が「この街めっちゃ好きかも」と言い、みんなでゆるい雰囲気を楽しんだ。都会すぎず落ち着いた感じが心地よかった。','2026-10-05','13:00','🛍️','0000','',0,1,false,'2026-10-05 13:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.616940000,138.589170000,'日本最大級の露天風呂「西の河原露天風呂」の広大な湯船に浸かる','大自然の開放感あふれる西の河原露天風呂に到着。遮るもののない広大な湯船にゆったりと体を沈めると、心地よい温泉が全身の疲れを優しく解きほぐしてくれる。木々の緑を眺めながら、世代を超えて並んでお湯に浸かる贅沢なひとときを噛みしめる。','2026-09-12','15:45','♨️','0','',-2100,1,false,'2026-09-12 16:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.625830000,138.595560000,'3軒目：温泉街の老舗食堂で楽しむ、名物・舞茸天ぷらうどんのランチ','お昼時は、地元で長く愛されるアットホームな老舗食堂で家族みんな揃ってランチタイム。サクサクに揚がった香ばしい地元の名物・舞茸の天ぷらと、出汁がしっかりと効いた温かいおうどんをいただき、お腹も心もすっかり満たされる。','2026-09-13','12:00','🥢','0','',-3500,1,false,'2026-09-13 12:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.630000000,138.592500000,'「草津熱帯圏」で珍しい動物や可愛いおサルさんたちとふれあい','子どもたちが大喜びすること間違いなしの草津熱帯圏へ。ドーム型の館内で、珍しい南国の動物たちや元気なサル、カピバラたちの愛らしい姿を間近で見学する。間近で見る動物たちに、孫たちは大興奮で家族みんなの笑顔があふれる楽しい時間。','2026-09-13','13:30','🐒','0','',-4200,1,false,'2026-09-13 14:15:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623890000,138.598330000,'お土産選び：伝統の「草津温泉の素」と特製お漬物を吟味','夕方になり、再び湯畑周辺の土産物店街に戻ってお土産選びの時間。草津の温泉気分を自宅でも味わえる「草津温泉の素」や、職人こだわりの特製お漬物、温泉たまごなどを丁寧に選び、家族それぞれに思い出の品を買い揃える。','2026-09-13','15:30','🛍️','0','',-5000,1,false,'2026-09-13 16:00:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622500000,138.601110000,'伝統と温もりあふれる老舗温泉宿にチェックイン、客室でほっと一息','本日の宿泊先である、歴史ある和風の温泉宿にチェックイン。上品なしつらえの広々とした和室の客室に通され、お茶菓子をいただきながら窓の外に広がる温泉街の景色を眺め、旅の疲れを癒やしてほっと一息つく。','2026-09-13','16:30','宿','0','',-60000,1,false,'2026-09-13 17:00:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622780000,138.601390000,'宿の大浴場にて、草津の誇る名湯「万代鉱源泉」の湯を満喫','夕食の前に、宿自慢の大浴場と風情ある露天風呂へ。草津の名湯の一つである「万代鉱源泉」の強力な酸性泉にゆったりと体を預け、日頃の疲れが嘘のように消えていく至福の湯あみを家族それぞれが存分に堪能する。','2026-09-13','17:15','♨️','0','',0,1,false,'2026-09-13 17:45:00+09','2026-08-01 22:16:06.610551+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622500000,138.601000000,'三世代みんなで囲む、上州牛のすき焼きと旬の会席料理の夕食','お待ちかねの夕食は、個室の食事処で三世代揃って華やかな会席料理を囲む。とろけるように柔らかい上州牛のすき焼きや、旬の川魚の塩焼きなど贅沢なご馳走に、祖父母も孫たちも「美味しいね！」と大喜びの賑やかな夜。','2026-09-13','18:30','🍽️','0','',0,1,false,'2026-09-13 19:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623330000,138.597500000,'夜のライトアップに彩られた幻想的な「湯畑」を夜のお散歩','夕食後、浴衣姿に丹前を羽織って夜の温泉街へお散歩に出かける。ライトアップされた幻想的な「湯畑」は昼間とは違ったムーディーな美しさがあり、湯けむりが夜空に浮かび上がる光景を眺めながら、家族仲良くのんびりと歩く。','2026-09-13','20:00','🌙','0','',0,1,false,'2026-09-13 20:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622500000,138.601110000,'4軒目：宿のロビーラウンジで味わう、湯上がりナイトデザート','お散歩から宿に戻った後は、温かいお部屋でくつろぎつつ、ロビーラウンジで用意された湯上がりの特製プリンや甘味をいただく。今日一日の楽しい思い出を家族みんなで語り合いながら、穏やかで温かい夜の時間がゆっくりと流れていく。','2026-09-13','21:00','🍮','0','',-800,1,false,'2026-09-13 21:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.621940000,138.596670000,'「草津温泉バスターミナル」にて、三世代の思い出深い旅のフィナーレ','翌日、すべての行程を温かい笑顔で終え、帰りのバスターミナルへ。「本当に楽しい旅行だったね、またみんなで来ようね」と祖父母と孫たちが手を振り合い、家族の絆が一段と深まった素晴らしい草津温泉・三世代旅行の幕を閉じる。','2026-09-14','10:00','👋','0','',0,1,false,'2026-09-14 10:30:00+09','2026-08-01 22:16:06.610551+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.442220000,135.353330000,'ホテルの大浴場と露天風呂で、日本海の潮風を感じながらゆったりリフレッシュ','夕食の前に、広大な日本海を一望できるホテル自門の開放的な露天風呂へと足を運ぶ。心地よい波の音に耳を傾けながら温かいお湯に身を委ね、旅のドライブや散策の疲れがすーっと癒やされていく極上のリラックスタイムを満喫する。','2027-04-11','17:30','✨','0','',0,1,false,'2027-04-11 18:15:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.441390000,135.351940000,'4軒目：日本海の旬の味覚！ブランド蟹や鮮魚の舟盛りを味わう豪華な海の幸ディナー','お待ちかねの夕食は、日本海の新鮮な海の幸をふんだんに使った豪華な会席料理を堪能。今が旬の極上の魚介の舟盛りや、香ばしい焼き魚を味わいながら、地元の美味しい地酒を合わせて心から贅沢で幸せな夜のひとときを過ごす。','2027-04-11','19:00','🦀','0','',0,1,false,'2027-04-11 20:30:00+09','2026-08-02 01:20:50.513158+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'広島駅に集合','大学の友達4人で広島駅に集合。久しぶりの旅行でテンションが上がり、駅前で「今日めっちゃ楽しもうな」と声を合わせた。荷物を軽くまとめて、まずは市内を歩きながら旅のスタートをゆっくり味わった。','2026-10-05','09:10','🚉','0000','',0,1,false,'2026-10-05 09:10:00+09','2026-08-02 02:22:32.157548+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.670000000,135.350000000,'崎の湯で温泉♨','海が見える露天風呂に家族全員感動。少し熱くて長湯できず。500円。','2026-08-20','12:20','♨','1','',-500,0,true,'2026-08-20 12:22:00+09','2026-08-01 20:07:48.570937+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.670500000,135.350500000,'湯上がりアイス🍦','風呂上がりのアイスが最高。家族で乾杯して笑いが止まらない。300円。','2026-08-20','12:50','🍦','1','',-300,1,true,'2026-08-20 12:52:00+09','2026-08-01 20:07:48.570937+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.391480000,132.452900000,'原爆ドームへ移動','駅から歩いて原爆ドームへ。静かな空気の中で4人とも自然と声が少なくなり、歴史の重さを感じながらゆっくり見学した。友達同士でもこういう時間を共有できるのが嬉しかった。','2026-10-05','09:40','🏛️','0000','',0,1,false,'2026-10-05 09:40:00+09','2026-08-02 02:22:32.157548+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'道後温泉に到着','家族で車を降りた瞬間にふわっと温泉街の香りがして「来たねえ」と声がそろった。レトロな建物が並ぶ道後の街は歩くだけで楽しくて、みかん色の提灯がゆらゆら揺れているのがかわいかった。旅の始まりにぴったりのやわらかい空気に包まれた。','2026-09-12','10:10','🏮','0000','',0,1,false,'2026-09-12 10:10:00+09','2026-08-02 02:17:15.278255+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.501390000,134.234720000,'鳥取市街地に戻り、今夜の宿泊先である天然温泉付きの和風リゾートホテルにチェックイン','一日の楽しい観光を終えて鳥取市街地へと戻り、本日の宿泊先である温かな和風リゾートホテルにチェックイン。広々とした家族向けの和室の客室に通され、心地よい畳の香りに包まれながら、旅の荷物をほどいてほっと一息リラックスする。','2027-05-16','15:00','🏨','0','',-28000,1,false,'2027-05-16 15:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.502780000,134.235560000,'ホテルの大浴場と露天風呂で、旅の疲れをほぐす極上の温泉リフレッシュタイム','夕食の前に、肌触りの優しい天然温泉が自慢のホテルの大浴場と露天風呂へ足を運ぶ。足を思いきり伸ばせる温かいお湯にゆったりと浸かりながら、「今日はいっぱい歩いて楽しかったね」と家族みんなで今日の思い出話に花を咲かせる。','2027-05-16','16:15','✨','0','',0,1,false,'2027-05-16 17:00:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.500560000,134.233330000,'4軒目：日本海の海の幸と鳥取牛が勢揃い！家族みんなで囲む豪華な夕食バイキング','お待ちかねの夕食は、広々としたレストランでの豪華なバイキング形式。日本海で獲れたピチピチの新鮮なお造りや、香ばしく焼き上げられた地元食材の数々を、子供たちも「どれにしようかな？」とワクワクしながらお皿いっぱいに選んで楽しく賑やかに味わう。','2027-05-16','18:30','🦀','0','',0,1,false,'2027-05-16 19:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.505560000,134.238890000,'翌日、活気あふれる鳥取の台所「賀露港・海鮮市場モルトフレア」でお買い物','旅行2日目は、新鮮な海の特産品がずらりと並ぶ地元の人気の海鮮市場「賀露港」へと車を走らせる。威勢のいい掛け声が行き交う活気あふれる店内で、大きなカニや干物などの特産品を楽しく吟味し、家族みんなでお土産をたくさん選び取る。','2027-05-17','10:00','🛍️','0','',-3000,1,false,'2027-05-17 10:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.506110000,134.239440000,'市場内の食堂で味わう、日本海の海の幸がてんこ盛りの豪華な「海鮮丼」のランチ','市場内にあるアットホームな食堂で、旅の締めくくりとなる贅沢なランチタイム。朝に水揚げされたばかりの新鮮なマグロや白身魚、いくらが贅沢に盛り付けられたボリューム満点の「海鮮丼」を頬張り、その美味しさに家族みんなが大感動する。','2027-05-17','11:30','🐟','0','',-2100,1,false,'2027-05-17 12:15:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.539720000,134.148610000,'神話の舞台としても有名な、縁結びのパワースポット「白兎神社」を参拝','白いウサギの神話が残る、可愛らしいウサギの石像があちこちに鎮座する「白兎神社」へ。境内へと続く参道を家族みんなでのんびりとお散歩しながら、ウサギのモチーフが施された可愛らしいお守りを探したり、旅の安全を仲良くみんなでお願いする。','2027-05-16','10:30','🐇','0','',0,1,false,'2027-05-16 11:15:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.538890000,134.149170000,'3軒目：白兎海岸の道の駅で味わう、濃厚でミルキーな「大山白バラ牛乳ソフト」','神話の舞台となった美しい白兎海岸を眺めながら、道の駅のテラスでひと休み。鳥取名物の濃厚な「大山白バラ牛乳」を使ったソフトクリームを家族みんなでシェアしていただき、ひんやり甘い美味しさに思わず「美味しいね！」と笑顔がこぼれる。','2027-05-16','11:30','🍦','0','',-450,1,false,'2027-05-16 12:15:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.530560000,134.225000000,'「JR鳥取駅」に到着、家族みんなのワクワクが止まらない鳥取旅行のスタート','家族みんなで特急列車に揺られ、いよいよ日本海側の街・JR鳥取駅に降り立つ。改札を出た瞬間から「どんなところかな？」と子供たちも目を輝かせ、これから始まる鳥取砂丘や美味しいグルメを巡る大満足の家族旅行への期待感に胸を弾ませる。','2027-05-15','09:00','🚂','0','',0,1,false,'2027-05-15 09:30:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.532220000,134.223890000,'1軒目：話題の「すなば珈琲」で、香ばしいこだわり珈琲と名物モーニング','鳥取名物としてすっかりおなじみとなったユニークな「すなば珈琲」の店舗へ立ち寄る。香ばしく香り高い特製ブレンドコーヒーを味わいながら、子供たちはサクサクのトーストと名物のホットケーキを頬張り、朝から家族みんなでにっこり笑顔が広がる。','2027-05-15','09:30','☕','0','',-1100,1,false,'2027-05-15 10:00:00+09','2026-08-02 01:24:12.650822+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.541670000,134.229170000,'「鳥取砂丘こどもの国」で、緑豊かな自然の中のびのびと思いっきり遊ぶ','日本海を望む広大な敷地を持つ「鳥取砂丘こどもの国」へ到着。大型のアスレチック遊具や広々とした芝生エリアで、子供たちは「見て見て、すごい高いよ！」と元気いっぱいに走り回り、家族みんなで汗を流しながら思い切り体を動かして楽しむ。','2027-05-15','10:30','🏃','0','',-500,1,false,'2027-05-15 11:15:00+09','2026-08-02 01:24:12.650822+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.455560000,134.891670000,'2軒目：海沿いの人気店でガブッとかぶりつく、ジューシーな「淡路島バーガー」のランチ','お昼時は、海沿いのオシャレなバーガーショップで大人気の「淡路島バーガー」をランチにチョイス。ふっくらジューシーな淡路牛パティと、ソテーされて甘みが凝縮された極厚の淡路島産タマネギが絶妙にマッチし、一口食べるごとに美味しさが口いっぱいに広がる最高のご馳走。','2026-12-04','12:30','🍔','0','',-1350,1,false,'2026-12-04 13:15:00+09','2026-08-02 01:16:03.346395+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.541940000,134.220560000,'2軒目：砂丘の目の前のおしゃれなお店で味わう、名物「砂丘らーめん」のランチ','お昼時は鳥取砂丘の近くにあるアットホームなレストランでランチタイム。スープの旨味がしっかりと効いたご当地の「砂丘らーめん」を注文し、ツルツルの麺とジューシーなチャーシューを夢中ですすりながら、お腹も心も大満足で満たされていく。','2027-05-15','12:00','🍜','0','',-950,1,false,'2027-05-15 12:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.545830000,134.222220000,'目の前に広がる壮大な大パノラマ！「鳥取砂丘」の馬の背を家族で登る','日本が誇る大自然の芸術・鳥取砂丘のメインエリアへ足を踏み入れる。どこまでも続く黄金色の砂の丘「馬の背」に向かって、足を砂に取られながらも「がんばれー！」と家族で声を掛け合わせながら一歩一歩力を合わせて頂上へと登りきる。','2027-05-15','13:30','🐪','0','',0,1,false,'2027-05-15 14:15:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.546940000,134.223330000,'「鳥取砂丘」の頂上から望む、日本海のどこまでも青い水平線と美しい風紋に感動','急な坂道を登りきった馬の背の頂上から、目の前に広がる日本海のどこまでも青く澄んだ海原を一望する。風が作り出す美しい砂の模様「風紋」の神秘的な美しさに、「うわぁ、きれい！」と子供たちも感動のあまり歓声を上げ、家族みんなで記念の写真をパシャリと撮影する。','2027-05-15','14:00','🌊','0','',0,1,false,'2027-05-15 14:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.543060000,134.218060000,'世界的にも珍しい砂の彫刻美術館「砂の美術館」で、圧倒的なスケールのアートを鑑賞','“砂で世界を旅行する”をコンセプトにした大人気の「砂の美術館」へ足を運ぶ。世界最高峰の砂像彫刻家たちが手掛けた、細部まで驚くほど精巧で巨大な砂のアート作品の数々を間近で眺め、「これ本当に砂でできているの！？」と家族みんなで驚きの声を上げる。','2027-05-15','16:00','🎨','0','',-1200,1,false,'2027-05-15 16:45:00+09','2026-08-02 01:24:12.650822+09'),
	 (47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.530560000,134.225000000,'「JR鳥取駅」に戻り、たくさんの楽しい思い出を胸にみんなで笑顔で帰路につく','すべての観光とグルメを家族みんなで大満足して、再び出発地のJR鳥取駅へ戻る。「砂丘の景色も、ラクダも、美味しいご飯も全部楽しかったね！」と満面の笑みで語り合いながら、温かい家族の思い出がぎっしりと詰まった特急列車に乗り込んで帰路につく。','2027-05-17','14:00','👋','0','',0,1,false,'2027-05-17 14:30:00+09','2026-08-02 01:24:12.650822+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839700000,132.770300000,'道後温泉でひと風呂','湯に浸かった瞬間に体がふわっと軽くなって家族みんなで「気持ちいい〜」と声が漏れた。湯上がりに飲んだみかん牛乳が驚くほど甘くて、子どもが「これ毎日飲みたい」と笑った。旅の疲れがすっと抜けていくようなやさしい時間だった。','2026-09-12','11:00','♨️','0000','',-420,1,false,'2026-09-12 11:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.770900000,'温泉街で昼食','道後の食堂で鯛めしをいただく。ふわっとした鯛の甘さが口いっぱいに広がって、家族みんなで「おいしい！」と声がそろった。窓から見える温泉街のゆるい雰囲気も心地よくて、旅の最初の食事として最高だった。','2026-09-12','12:00','🍚','0000','',-1400,1,false,'2026-09-12 12:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.853200000,132.786500000,'松山城へ向かうドライブ','坂道を車で登っていくと松山城が少しずつ見えてきて、子どもが「お城や！」と指をさして喜んだ。城下町の雰囲気が残る道を走るのは気持ちよくて、窓から入る風もやわらかかった。家族でのんびり景色を楽しむ時間になった。','2026-09-12','13:00','🚗','0000','',0,1,false,'2026-09-12 13:00:00+09','2026-08-02 02:17:15.278255+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839400000,132.765200000,'松山城天守に登る','天守から見える松山の街並みがとてもきれいで、家族みんなで「すごいねえ」と声がそろった。風が気持ちよくて、しばらく景色を眺めながらゆっくり過ごした。みかん色の屋根がちらほら見えるのも愛媛らしくてかわいかった。','2026-09-12','13:40','📸','0000','',0,1,false,'2026-09-12 13:40:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.860200000,132.708900000,'伊予市方面へドライブ','海沿いの道を走ると、窓から入ってくる風が少し甘いような気がして「みかんの匂いする？」と家族で笑った。道の両側に広がる畑がオレンジ色に染まっていて、走っているだけで気持ちが明るくなる道だった。','2026-09-12','14:20','🚗','0000','',0,1,false,'2026-09-12 14:20:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757900000,132.703400000,'道の駅ふたみ到着','海がすぐ目の前に広がっていて、家族みんなで「きれい！」と声がそろった。しぼりたてみかんジュースを飲んだら驚くほど濃くて、子どもが「これ本物の味や！」と笑った。海とみかんの香りが混じった風がとても気持ちよかった。','2026-09-12','15:00','🍊','0000','',-600,1,false,'2026-09-12 15:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757500000,132.703900000,'ふたみ海岸を散歩','夕方の海岸は光がやわらかくて、波の音が心地よかった。家族で並んで歩きながら「今日いろいろ楽しかったね」と話して、ゆっくりとした時間を過ごした。みかん畑が海の向こうに見えるのも愛媛らしくてかわいかった。','2026-09-12','16:00','🌅','0000','',0,1,false,'2026-09-12 16:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744200000,132.703800000,'宿へ向かうドライブ','海沿いの道をゆっくり走りながら、夕日がみかん色に染まっていくのを眺めた。家族で「きれいすぎる」と何度も言いながら、今日の思い出を話し合った。車内の空気がやわらかくて幸せな時間だった。','2026-09-12','17:00','🚗','0000','',0,1,false,'2026-09-12 17:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'海沿いの宿に到着','宿のロビーから見える海が夕日に染まっていて、家族みんなで「すごい…」と声を失った。波の音が静かに響いていて、今日の疲れがすっと抜けていくような気がした。みかんの香りのアメニティがかわいくてテンションが上がった。','2026-09-12','17:30','🏨','0000','',0,1,false,'2026-09-12 17:30:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'宿の夕食','夕食に出てきたみかんを使ったサラダが驚くほど爽やかで、家族みんなで「これ家でも作りたい」と話した。海の幸も新鮮で、旅の夜にぴったりのやさしい味だった。ゆっくり食べながら今日の思い出を振り返った。','2026-09-12','18:30','🍽️','0000','',-1800,1,false,'2026-09-12 18:30:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'家族で夜の海を眺める','宿のテラスから夜の海を眺めると、波の音が静かに響いていてとても落ち着いた。子どもが「また明日も海見たい」と言って、家族で笑いながらゆっくり過ごした。旅の夜らしいやわらかい時間だった。','2026-09-12','20:00','🌙','0000','',0,1,false,'2026-09-12 20:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'翌朝の海散歩','朝の海は光がきらきらしていて、家族みんなで「昨日よりきれいかも」と話しながら散歩した。潮風に少しみかんの香りが混じっているような気がして、愛媛らしい朝だなと感じた。','2026-09-13','07:00','🌤️','0000','',0,1,false,'2026-09-13 07:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757900000,132.703400000,'道の駅ふたみに再訪','昨日飲んだみかんジュースが忘れられなくて再訪。今日のジュースも濃くて甘くて、家族みんなで「やっぱりこれやな」と笑った。海も朝の光でとてもきれいだった。','2026-09-13','08:00','🍊','0000','',-600,1,false,'2026-09-13 08:00:00+09','2026-08-02 02:17:15.278255+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757500000,132.703900000,'海岸で写真撮影','朝の海岸は光がやわらかくて、家族写真を撮るのにぴったりだった。みかん畑が遠くに見えて、愛媛らしい一枚になった。子どもが「また来ようね」と言ってくれて嬉しかった。','2026-09-13','08:40','📸','0000','',0,1,false,'2026-09-13 08:40:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.860200000,132.708900000,'帰り道のドライブ','帰り道の海沿いの道は昨日より少し明るくて、家族で「また来たいね」と話しながら走った。みかん畑がキラキラしていて、旅の終わりにぴったりの景色だった。','2026-09-13','09:30','🚗','0000','',0,1,false,'2026-09-13 09:30:00+09','2026-08-02 02:17:15.278255+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.426390000,133.333330000,'「JR米子駅」に到着、山陰の活気ある街・米子でのワクワクする観光のスタート','山陰の交通の要所であり、妖怪ブロンズ像がお出迎えしてくれる活気あふれるJR米子駅に降り立つ。爽やかな日本海の風を感じながら、これから巡る歴史ある米子城跡や名湯・皆生温泉への期待に胸を膨らませ、元気いっぱいに駅舎をあとにして出発する。','2027-06-12','09:00','🚉','0','',0,1,false,'2027-06-12 09:30:00+09','2026-08-02 01:27:16.327071+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295130000,132.319690000,'宮島口へ移動','電車で宮島口へ向かう道中、4人で大学の話や最近の悩みをゆるく話しながら移動。旅の途中のこういう時間が一番楽しいかもしれないと思った。','2026-10-05','14:00','🚆','0000','',0,1,false,'2026-10-05 14:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.428330000,133.331110000,'1軒目：駅前のレトロな喫茶店で味わう、名物「米子珈琲」と香ばしいモーニング','旅の始まりは、米子駅の近くにある地元で愛され続ける落ち着いた雰囲気のレトロな喫茶店へ。じっくりと丁寧に淹れられた香り高いこだわり珈琲を一口飲むと、すっきりと目が覚め、バターが香るサクサクのトーストとともに心も体もホッと満たされる。','2027-06-12','09:30','☕','0','',-750,1,false,'2027-06-12 10:00:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.428610000,133.321670000,'天空の城とも称される名城「米子城跡」の石垣がそびえる山頂へと爽快に登る','かつて壮大な天守閣がそびえ立っていた歴史ある「米子城跡」の美しい石垣が残る遊歩道へ足を踏み入れる。木漏れ日の心地よい山道を一歩一歩のんびりと登りながら、かつての城主が眺めたであろう壮大な歴史のロマンに思いを馳せる。','2027-06-12','10:30','🏯','0','',0,1,false,'2027-06-12 11:15:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.428890000,133.321940000,'「米子城跡」の山頂から一望する、中海や弓ヶ浜、そして雄大な大山の絶景に感動','見事に組み上げられた米子城跡の山頂に登りきると、目の前には青く輝く中海や美しい弧を描く弓ヶ浜、そして頂上に雲をまとった雄大な大山の姿が広がる。360度の大パノラマが生み出す息をのむほどの絶景に、「うわぁ、すごい！」と思わず大きな歓声を上げる。','2027-06-12','11:15','⛰️','0','',0,1,false,'2027-06-12 12:00:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.425560000,133.315000000,'2軒目：城下町エリアの人気店で味わう、ジューシーなご当地「米子牛すじ丼」のランチ','歴史ある街並みが残るエリアの隠れ家的な食堂で、ボリューム満点のランチタイム。じっくりと柔らかく煮込まれた旨味たっぷりの牛すじがご飯の上に贅沢にのせられたご当地名物の丼を頬張り、その美味しさに思わず笑顔がこぼれて大満足する。','2027-06-12','12:30','丼','0','',-1100,1,false,'2027-06-12 13:15:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.431390000,133.342220000,'白砂青松の美しい海岸線が続く「弓ヶ浜」の海岸をのんびりとお散歩','“日本の白砂青松100選”にも選ばれている、見事な弧を描く美しい海岸線「弓ヶ浜」へと足を運ぶ。サラサラとした白い砂浜を歩きながら、打ち寄せる日本海の心地よい波の音に耳を傾け、どこまでも広がる青い海を眺めて穏やかなリラックスタイムを過ごす。','2027-06-12','14:00','🌊','0','',0,1,false,'2027-06-12 14:45:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.433330000,133.344440000,'3軒目：海の近くのオシャレなカフェでいただく、甘酸っぱい特製フルーツタルトと珈琲','弓ヶ浜の美しい景色を一望できる海沿いのスタイリッシュなカフェに立ち寄り、ティータイム。旬の瑞々しいフルーツがたっぷりと乗ったサクサクの特製タルトを味わいながら、窓の外に広がるきらめく海原を眺めて優雅で贅沢なひとときを堪能する。','2027-06-12','15:15','🍰','0','',-900,1,false,'2027-06-12 16:00:00+09','2026-08-02 01:27:16.327071+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.438890000,133.383330000,'日本海に面した全国屈指の名湯「皆生温泉」の情緒あふれる温泉街をそぞろ歩き','“日本の朝焼け100選”にも選ばれる美しい海岸沿いに広がる、塩の湯が自慢の「皆生温泉」の街並みへ。温泉情緒が漂うレトロな小道を家族や友達とのんびりとお散歩しながら、湯煙が立ち上る温泉街ならではの温かな雰囲気をたっぷりと楽しむ。','2027-06-12','16:30','♨️','0','',0,1,false,'2027-06-12 17:15:00+09','2026-08-02 01:27:16.327071+09'),
	 (42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623060000,138.599170000,'1軒目：湯畑のすぐそばで味わう、湯上がりアツアツの温泉まんじゅう','湯畑周辺の賑やかな商店街を歩きながら、湯気香る老舗の店先で名物の温泉まんじゅうを買い求める。ふかしたての柔らかい皮と、上品な甘さの漉し餡が絶妙なバランスで、歩き疲れた祖父母や子どもたちも「美味しいね」と満面の笑みを浮かべる。','2026-09-12','11:30','🍭','0','',-450,1,false,'2026-09-12 12:00:00+09','2026-08-01 22:16:34.875081+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.770900000,'温泉街でお土産購入','みかんゼリーやジュースを家族で選びながら「これおいしそう！」と盛り上がった。店員さんが優しくて、旅の最後にほっこりした気持ちになった。','2026-09-13','11:40','🎁','0000','',-1600,1,false,'2026-09-13 11:40:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'旅の締め','車に荷物を積みながら「楽しかったね」と家族で話した。みかん色の風景と海の音がずっと心に残る旅になった。また来たいと思えるやさしい1泊旅だった。','2026-09-13','12:00','🚗','0000','',0,1,false,'2026-09-13 12:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.460560000,135.318060000,'3軒目：城下町の隠れ家的名店でいただく、日本海の新鮮な海の幸丼の夕暮れ前ランチ','日本海の荒波が育んだ極上の魚介が味わえる西舞鶴の老舗食事処に立ち寄る。朝に水揚げされたばかりのピチピチのマグロやタイ、甘エビが贅沢に盛り付けられた「海鮮丼」を頬張り、新鮮な海の美味しさに心からうっとりとする。','2027-04-11','12:00','🤩','0','',-1900,1,false,'2027-04-11 12:45:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.452220000,135.313890000,'水上家屋が立ち並ぶノスタルジックな水郷風景「吉原の地区」をのんびりお散歩','まるで海の上に家が浮かんでいるかのような珍しい景観が広がる、西舞鶴の漁師町「吉原地区」へ。細い路地や水面に影を落とすレトロな家々の佇まいを眺めながら、どこか懐かしく時が止まったかのような静かなお散歩を楽しむ。','2027-04-11','13:30','🏘️','0','',0,1,false,'2027-04-11 14:15:00+09','2026-08-02 01:20:50.513158+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.441670000,135.352780000,'日本海に面した海沿いのリゾート感あふれるホテルにチェックイン','本日の宿泊先である、穏やかな日本海の波打ち際に佇む上質なホテルにチェックイン。窓の外に広がる夕暮れの美しい海の景色を眺めながら旅の荷物をほどき、一日の充実した観光の思い出に浸りながらほっと一息ついてくつろぐ。','2027-04-11','16:30','🏨','0','',-26000,1,false,'2027-04-11 17:15:00+09','2026-08-02 01:20:50.513158+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.439440000,133.384720000,'本日の宿泊先である、日本海の絶景を望む皆生温泉の上質なリゾートホテルにチェックイン','波の音がすぐ近くに聞こえる皆生温泉のオーシャンビューホテルに到着してチェックイン。窓一面に日本海の美しい水平線が広がる明るく広々とした客室に通され、旅の荷物をほどいてほっと一息つきながら、これからの温泉タイムに胸を弾ませる。','2027-06-12','17:30','🏨','0','',-29000,1,false,'2027-06-12 18:15:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.356940000,133.540280000,'5軒目：大山の中腹にある山小屋風カフェで味わう、濃厚な「大山乳業ソフトクリーム」','大山の豊かな自然を感じられる山小屋風のオシャレなカフェに立ち寄り、ご当地スイーツを堪能。地元の大山乳業のミルクをたっぷり使った濃厚でなめらかなソフトクリームを一口食べると、ミルクの優しい甘みが口いっぱいに広がり最高の笑顔になる。','2027-06-13','12:15','🍦','0','',-450,1,false,'2027-06-13 13:00:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.426390000,133.333330000,'「JR米子駅」に戻り、山陰の美しい景色と美味しい思い出を胸に笑顔で帰路につく','すべての観光とグルメを大満足で満喫し、再び出発地のJR米子駅へと戻る。「お城の景色も、皆生温泉も、美味しいご飯も全部最高だったね！」とみんなで元気よく笑顔で語り合いながら、山陰・米子の温かい思い出が詰まった特急列車に乗り込んで帰路につく。','2027-06-13','14:30','👋','0','',0,1,false,'2027-06-13 15:15:00+09','2026-08-02 01:27:16.327071+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401002110,132.685744880,'駅へ戻る道を歩く','駅へ戻る参道は夕方の光が差し込み、朝とは違う表情を見せていた。歩きながら今日の出来事を思い返すと、どれも穏やかで心に残るものばかりだった。出雲の空気が旅の終わりをやさしく包んでくれた。','2026-10-12','16:00','🚶','0000','',0,1,false,'2026-10-12 16:00:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401002110,132.685744880,'旅の締め','駅前で深呼吸すると、出雲の静かな空気が胸に広がった。縁結びの地を巡った一日は、心が自然と整うような穏やかな時間だった。お守りを手にしながら「また来たい」と思える旅になった。','2026-10-12','16:20','🌸','0000','',0,1,false,'2026-10-12 16:20:00+09','2026-08-02 02:40:53.40301+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676842110,131.792544880,'萩・石見空港に到着','萩・石見空港に降り立つと、周囲は静かな山々に囲まれていて、都市の空港とはまったく違う穏やかな空気が流れていた。ターミナルの外に出ると鳥の声が響き、遠くに日本海の気配が感じられる。まずは空港周辺を軽く歩きながら、今日の散策ルートを確認。観光地が少ない地域だからこそ、自然の中でゆっくり過ごす旅になりそうだと感じた。','2026-10-20','09:10','🛬','0000','',0,1,false,'2026-10-20 09:10:00+09','2026-08-02 02:49:26.637117+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.682144550,131.797744330,'空港展望台で離着陸を見る','空港の展望スペースに向かうと、滑走路が一望でき、山に囲まれた空港ならではの静かな景色が広がっていた。離陸する機体の音が山に反響し、どこか心地よい。観光地ではないが、石見らしい素朴な魅力が感じられる場所で、旅の始まりにふさわしい時間となった。','2026-10-20','09:40','🚶','0000','',0,1,false,'2026-10-20 09:40:00+09','2026-08-02 02:49:26.637117+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.302030000,132.319450000,'フェリーで宮島へ','フェリーに乗ると海風が気持ちよくて、4人で写真を撮りまくった。「大学生の旅って感じするな！」と笑いながら、海の上の短い時間を楽しんだ。','2026-10-05','14:30','⛴️','0000','',-500,1,false,'2026-10-05 14:30:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295490000,132.319690000,'宮島に上陸','鹿が近づいてきて4人で大騒ぎ。「かわいいけど近い近い！」と笑いながら写真を撮った。島の空気がゆっくりしていて、歩くだけで気持ちが軽くなる場所だった。','2026-10-05','15:00','🦌','0000','',0,1,false,'2026-10-05 15:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295450000,132.319230000,'厳島神社へ参拝','鳥居を見た瞬間「うわ、ほんまに来たんや」と4人で感動。海に浮かぶような景色が美しくて、しばらく無言で眺めてしまった。大学生の旅でもこういう瞬間は心に残る。','2026-10-05','15:30','⛩️','0000','',0,1,false,'2026-10-05 15:30:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295900000,132.319900000,'宮島商店街で食べ歩き','もみじ饅頭を食べながら「これうますぎん？」と盛り上がる。揚げもみじを初めて食べて感動し、4人でシェアしながら歩いた。商店街の賑やかさが楽しくてずっと笑っていた。','2026-10-05','16:00','🍡','0000','',-800,1,false,'2026-10-05 16:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295130000,132.319690000,'フェリーで帰路へ','夕方のフェリーは風が少し冷たくて、4人で「今日めっちゃ濃かったな」と話しながら帰った。海の色がゆっくり変わっていくのを眺める時間が心地よかった。','2026-10-05','17:00','⛴️','0000','',-500,1,false,'2026-10-05 17:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.396260000,132.459840000,'市内のカフェで休憩','歩き疲れてカフェに入り、4人で写真を見返しながら「これめっちゃいいやん」と盛り上がった。大学生らしいゆるい時間が心地よくて、旅の余韻をゆっくり味わった。','2026-10-05','18:00','☕','0000','',-700,1,false,'2026-10-05 18:00:00+09','2026-08-02 02:22:32.157548+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.392900000,132.457200000,'夜のお好み焼き屋へ','昼に続いて夜もお好み焼き。「広島来たら2回食べてもええやろ」と笑いながら、鉄板を囲んで大学生らしい賑やかな夜ごはんになった。','2026-10-05','19:00','🍳','0000','',-1800,1,false,'2026-10-05 19:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.396260000,132.459840000,'夜の紙屋町を散歩','夜の街は昼より少し静かで、4人でゆっくり歩きながら「今日めっちゃ良かったな」と話した。ライトに照らされた街並みがきれいで、旅の締めにぴったりの時間だった。','2026-10-05','20:00','🌙','0000','',0,1,false,'2026-10-05 20:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'広島駅へ戻る','駅に戻ると少し疲れが出てきたけど、4人で「また来たいな」と話しながらゆっくり歩いた。旅の終わりの静かな時間が心地よかった。','2026-10-05','20:40','🚉','0000','',0,1,false,'2026-10-05 20:40:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'駅でお土産購入','もみじ饅頭や広島限定のお菓子を選びながら「これ絶対うまいやつ」と盛り上がった。友達同士でお土産を選ぶ時間が楽しくて、旅の最後にいい思い出ができた。','2026-10-05','21:00','🎁','0000','',-1600,1,false,'2026-10-05 21:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'駅前で記念撮影','駅前の広場で4人並んで記念撮影。「今日めっちゃ良かったな」と笑いながら撮った写真は、大学生活の大事な思い出になりそうだった。','2026-10-05','21:20','📸','0000','',0,1,false,'2026-10-05 21:20:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'帰りの電車待ち','ホームで電車を待ちながら、4人で今日の写真を見返して「これSNSにあげよ」と盛り上がった。旅の終わりの少し寂しい感じも大学生らしくて良かった。','2026-10-05','21:40','🚆','0000','',0,1,false,'2026-10-05 21:40:00+09','2026-08-02 02:22:32.157548+09'),
	 (57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'広島旅の締め','電車に乗り込む前に「また4人でどっか行こな」と約束した。広島の景色と笑い声がずっと心に残る、大学生らしい最高の1日旅になった。','2026-10-05','22:00','🚉','0000','',0,1,false,'2026-10-05 22:00:00+09','2026-08-02 02:22:32.157548+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401544330,132.676544880,'浜辺で写真撮影','稲佐の浜の光はやわらかく、写真を撮るとどれも美しく写った。海風が心地よく、旅の思い出として残したい景色が広がっていた。静かな浜辺で過ごす時間は、出雲らしい穏やかさに満ちていた。','2026-10-12','14:30','📸','0000','',0,1,false,'2026-10-12 14:30:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401844550,132.685012330,'参道で甘味を楽しむ','参道の甘味処でぜんざいをいただく。温かい甘さが体に染みて、歩き疲れた体がほっと落ち着いた。店内は静かで、旅の途中の休憩として最適。出雲の優しい空気を感じられる時間だった。','2026-10-12','15:00','🍡','0000','',-800,1,false,'2026-10-12 15:00:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.400744220,132.686144550,'出雲大社前でお守り購入','出雲大社前の授与所で縁結びのお守りを選ぶ。白と赤の優しい色合いが美しく、手に取ると自然と気持ちが引き締まった。旅の記念として最適で、今日の体験が形として残る瞬間だった。','2026-10-12','15:30','🎁','0000','',-1500,1,false,'2026-10-12 15:30:00+09','2026-08-02 02:40:53.40301+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.685000000,135.340000000,'白良浜の真っ白な砂浜を少しお散歩','日が暮れる前の白良浜へ。足裏に心地よい真っ白な砂浜と透明度の高い海を眺めながら波打ち際を歩く。','2026-09-12','18:15','🏖️','0','',0,1,false,'2026-09-12 18:30:00+09','2026-08-01 21:08:04.82446+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489170000,134.171940000,'「土庄港」に到着、穏やかな瀬戸内海の青い海と島風に家族みんなで大はしゃぎ','フェリーに揺られて、瀬戸内海に浮かぶ美しい島・小豆島の玄関口である土庄港へ到着。船を降りた瞬間から、キラキラと輝く穏やかな海と爽やかな潮風に包まれ、「わぁ、綺麗な海！」と子供たちも大はしゃぎ。これから始まるワクワクの島内観光旅行がいよいよ元気にスタートする。','2027-09-18','09:00','🚢','0','',0,1,false,'2027-09-18 09:30:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.485830000,134.168060000,'1軒目：港近くの可愛いカフェで味わう、小豆島オリーブオイル香る絶品モーニング','土庄港の近くにある温かな雰囲気のカフェで、旅の始まりを祝う朝のひととき。小豆島特産の新鮮なオリーブオイルをたっぷりとかけたサクサクのトーストと、香り高いこだわり珈琲を味わいながら、家族みんなでにっこり笑顔が広がる最高のモーニングタイムを満喫する。','2027-09-18','09:30','☕','0','',-800,1,false,'2027-09-18 10:00:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.483330000,134.173610000,'潮の満ち引きで道が現れる神秘的な名所「エンジェルロード」を家族で手をつなぎ渡る','干潮時にだけ現れる砂の道「エンジェルロード」へと歩みを進める。“大切な人と手をつないで渡ると願いが叶うんだよ”と教え合いながら、貝殻を探したり波打ち際を歩いたりしながら、家族みんなで仲良く砂の道を歩いて渡りきる感動的な体験をする。','2027-09-18','10:30','✨','0','',0,1,false,'2027-09-18 11:15:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.482220000,134.172500000,'「エンジェルロード」を見下ろす丘の上の「約束の丘展望台」で幸せの鐘を鳴らす','エンジェルロードの美しい全景が一望できる高台の「約束の丘展望台」へと登る。青い海に囲まれた美しい小道の景色に感嘆の声を上げながら、家族みんなの健康とこれからの幸せを祈って、展望台にある可愛い「幸せの鐘」を元気いっぱいに鳴り響かせる。','2027-09-18','11:15','🔔','0','',0,1,false,'2027-09-18 12:00:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.520000000,134.331670000,'「小豆島オリーブ公園」で、白いギリシャ風風車をバックにほうきに跨って記念撮影','一面にオリーブの木が広がる美しい「小豆島オリーブ公園」へ到着。青空に向かってそびえる真っ白なギリシャ風風車の前で、映画の魔女のようにほうきを借りて空を飛んでいるかのようなポーズを取りながら、家族みんなで大爆笑しながら記念写真を何枚もパシャリと撮影する。','2027-09-18','12:30','🧹','0','',0,1,false,'2027-09-18 13:15:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.521390000,134.333330000,'2軒目：オリーブの緑に囲まれたオシャレなレストランで味わう「オリーブ牛」のランチ','園内にある開放的なレストランで、小豆島ブランドの「オリーブ牛」を贅沢に使ったランチタイム。きめ細やかな肉質で旨味がギュッと詰まったジューシーなステーキ丼を頬張り、「お肉がとっても柔らかくて美味しいね！」と家族全員が大満足の笑顔になる。','2027-09-18','13:15','🥩','0','',-2200,1,false,'2027-09-18 14:00:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.545830000,134.381940000,'昭和レトロな映画の世界にタイムスリップ「二十四の瞳映画村」をのんびりお散歩','木造の校舎や昔懐かしい昭和の街並みがそのまま残る「二十四の瞳映画村」へと足を運ぶ。ノスタルジックな雰囲気が漂うレトロな教室の椅子に座ってみたり、目の前に広がる穏やかな海沿いの道をのんびりとお散歩しながら、家族みんなでタイムスリップしたような不思議で温かい時間を過ごす。','2027-09-18','14:30','🏫','0','',-850,1,false,'2027-09-18 15:15:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.512220000,134.316670000,'伝統的な木桶が並ぶレトロな醤油蔵が立ち並ぶ「醤油の郷」の街並みをそぞろ歩き','島特産の醤油造りの歴史が息づく「醤油の郷」エリアへと車を走らせる。黒い焼き板の壁が続く情緒あふれる小道を歩くだけで、ふわりと香ばしい醤油の芳醇な香りが鼻腔をくすぐり、日本の伝統的な食文化の深さを肌でしみじみと感じ取る。','2027-09-18','15:45','🍶','0','',0,1,false,'2027-09-18 16:30:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.513330000,134.318060000,'3軒目：醤油蔵のカフェで味わう、甘じょっぱさがクセになる名物「醤油ソフトクリーム」','歴史ある醤油蔵をリノベーションしたおしゃれなカフェに立ち寄り、話題のご当地スイーツをゲット。コクのあるミルクソフトクリームに特製の諸味醤油が絶妙にマッチした、甘じょっぱくてクリーミーな「醤油ソフトクリーム」を味わい、子供たちも「これ美味しい！」と大喜び。','2027-09-18','16:30','🍦','0','',-450,1,false,'2027-09-18 17:15:00+09','2026-08-02 01:31:18.661244+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.508330000,134.291670000,'日本三大渓谷美の一つ！ロープウェイに乗って空中から眺める「寒霞渓」の雄大な大自然','秋の紅葉や新緑が美しい絶景スポット「寒霞渓」へと向かい、渓谷美を空から望むロープウェイに乗り込む。眼下に広がる奇岩や深い緑の山々と瀬戸内海の絶景パノラマに、「わぁ、すごい景色！」と息をのむほどのダイナミックな空中散歩を家族みんなで満喫する。','2027-09-19','10:00','🚠','0','',-1500,1,false,'2027-09-19 10:45:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.488890000,134.238890000,'本日の宿泊先である、瀬戸内海の絶景を一望する温泉リゾートホテルにチェックイン','穏やかな海を望む小豆島のリゾートホテルに到着し、温かな笑顔に出迎えられてチェックイン。窓一面に真っ青な海が広がる広々とした和洋室の客室に通され、旅の荷物をほどいてリラックスしながら、これから始まる島での夜に胸を弾ませる。','2027-09-19','12:00','🏨','0','',-32000,1,false,'2027-09-19 12:45:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489440000,134.239440000,'ホテルの大浴場と露天風呂で、瀬戸内海の潮風を感じながらのびのび温泉リフレッシュ','夕食の前に、美しい海を眺めながらゆったりと浸かれるホテルの温泉大浴場と露天風呂へ。心地よいお湯に体を預けて一日の観光の疲れをほぐしながら、「今日はたくさん歩いて楽しかったね」と家族みんなで温かな思い出話に花を咲かせる。','2027-09-19','13:00','♨️','0','',0,1,false,'2027-09-19 13:45:00+09','2026-08-02 01:31:18.661244+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'道後温泉街に戻る','旅の最後に道後温泉街をもう一度歩いた。昨日より人が多くて賑やかだったけど、みかん色の提灯がかわいくてやっぱり好きな場所だと思った。家族で「また来ようね」と話しながら歩いた。','2026-09-13','10:30','🏮','0000','',0,1,false,'2026-09-13 10:30:00+09','2026-08-02 02:17:15.278255+09'),
	 (56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839700000,132.770300000,'最後のひと風呂','帰る前にもう一度温泉へ。湯に浸かると昨日の疲れがすっと抜けていく感じがして、家族みんなで「やっぱり道後はいいね」と話した。湯上がりのみかん牛乳も最高だった。','2026-09-13','11:00','♨️','0000','',-420,1,false,'2026-09-13 11:00:00+09','2026-08-02 02:17:15.278255+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.440000000,133.386110000,'夜の温泉街を浴衣でそぞろ歩き、波の音を聞きながら星空を見上げるロマンチックな夜','夕食後、色鮮やかな浴衣に身を包んで夜の皆生温泉の海岸線をのんびりと散歩する。潮風に吹かれながら見上げる夜空には満天の星がきらめき、波の音が心地よく響く幻想的でロマンチックな夜の雰囲気に浸る。','2027-06-12','21:00','🌌','0','',0,1,false,'2027-06-12 21:45:00+09','2026-08-02 01:27:16.327071+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.488330000,134.238060000,'4軒目：瀬戸内海の新鮮な海の幸と島の恵みが詰まった豪華なバイキングディナー','お待ちかねの夕食は、瀬戸内海で獲れたピチピチのお造りや小豆島そうめん、オリーブ料理がずらりと並ぶ豪華なバイキング。子供たちも「どれにしようかな？」とワクワクしながらお皿いっぱいに美味しいお料理を選び、家族みんなで笑顔が絶えない賑やかなディナータイムを過ごす。','2027-09-19','18:00','🦀','0','',0,1,false,'2027-09-19 19:30:00+09','2026-08-02 01:31:18.661244+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.572466173,130.552425385,'西郷隆盛像を見学','鹿児島の象徴ともいえる西郷隆盛像。観光客が多く、写真スポットとして人気。歴史を感じる瞬間。','2026-10-12','17:30','🗿','0000','',0,1,false,'2026-10-12 17:30:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.559741396,130.556373596,'仙巌園へ移動','庭園は広くて美しく、桜島を背景にした景色が素晴らしい。ゆっくり歩きながら自然を楽しむ時間が心地よい。','2026-10-12','18:00','🌺','0000','',0,1,false,'2026-10-12 18:00:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.558333330,130.559444440,'仙巌園で夕景を眺める','夕方の仙巌園は静かで、桜島が夕日に染まる景色が美しい。旅の締めくくりにふさわしい時間となった。','2026-10-12','18:30','🌇','0000','',0,1,false,'2026-10-12 18:30:00+09','2026-08-02 16:24:03.081396+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.595833330,130.557222220,'鹿児島中央駅へ戻る','一日の旅を終えて駅へ戻る。桜島の迫力と街の賑わい、歴史と自然が混ざり合う鹿児島らしい旅になった。','2026-10-12','19:00','🚉','0000','',0,1,false,'2026-10-12 19:00:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.591915637,130.605812073,'フェリーで鹿児島へ戻る','帰りのフェリーは少し疲れが出てきて、海を眺めながらゆっくり過ごす。桜島の姿が遠ざかる景色が旅情を誘う。','2026-10-12','15:40','🌊','0000','',-200,1,false,'2026-10-12 15:40:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.591550083,130.581865311,'鹿児島港に到着','港に戻ると街の賑わいが感じられて、桜島の静けさとのギャップが面白い。次の目的地へ向かう準備をする。','2026-10-12','16:00','⚓','0000','',0,1,false,'2026-10-12 16:00:00+09','2026-08-02 16:24:03.081396+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957414280,130.940354910,'下関駅に到着','大学生4人で下関駅に集合。駅前の広場には朝の光がやわらかく差し込み、潮の香りがほんのり混じっていた。これから始まる「フグ食べつくし旅」への期待が自然と高まり、旅のスタートにふさわしい落ち着いた空気が流れていた。荷物を整えながら、まずは唐戸市場へ向かうルートを確認し、駅前の静かな雰囲気を楽しんだ。','2026-11-03','09:10','🚉','0000','',0,1,false,'2026-11-03 09:10:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.969612880,130.941912330,'火の山公園展望台','ロープウェイで火の山公園へ向かうと、展望台から関門海峡が一望できた。海と街が広がる景色は圧巻で、旅の中でも特に印象に残る瞬間となった。展望台の静けさが心地よく、食の旅に風景の魅力が加わった。','2026-11-03','12:00','📸','0000','',0,1,false,'2026-11-03 12:00:00+09','2026-08-02 02:35:22.146541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957410000,130.940350000,'下関駅へ戻る','駅へ戻る道中、4人で「今日めっちゃ食べたな」「フグってこんな種類あるんや」と話しながら歩いた。夕方の街は少し静かで、旅の終わりの落ち着いた空気が心地よかった。','2026-11-03','16:30','🚉','0000','',0,1,true,'2026-11-03 16:30:00+09','2026-08-02 02:38:00.798541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957410000,130.940350000,'旅の締め','駅前の広場で4人並んで記念撮影。「また来たいな」「次はどこ行く？」と話しながら、今日のフグ食べつくし旅を振り返った。下関の海と市場の賑やかさ、そしてフグの美味しさが忘れられない最高の大学生旅になった。','2026-11-03','17:00','🐡','0000','',0,1,true,'2026-11-03 17:00:00+09','2026-08-02 02:38:00.798541+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.348330000,134.048330000,'「JR高松駅」に到着、男同士の熱い「讃岐うどん食べつくスの旅」がいよいよ始動','讃岐うどんの本場・香川の玄関口であるJR高松駅に男同士で意気揚々と降り立つ。「何杯ハシゴできるか勝負だな！」と気合十分で熱い握手を交わし、これから始まる最高に贅沢で腹パンパン間違いなしのうどん巡り＆男旅のスタートにテンションが一気に最高潮へと跳ね上がる。','2027-10-09','09:00','🚂','0','',0,1,false,'2027-10-09 09:30:00+09','2026-08-02 01:35:25.086879+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.439720000,133.385280000,'ホテルの大浴場と塩の温泉が自慢の露天風呂で、日本海の波音を聞きながらリフレッシュ','夕食の前に、ミネラルたっぷりの皆生温泉が満たされたホテルの大浴場と開放的な露天風呂へ。潮風を感じながら温かい温泉にゆったりと体を預けると、一日のドライブや散策の疲れがすーっと溶けていくような極上の癒やし時間を満喫する。','2027-06-12','18:30','✨','0','',0,1,false,'2027-06-12 19:15:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.438610000,133.383890000,'4軒目：日本海の新鮮な海の幸と鳥取のブランド食材を味わう、豪華な会席ディナー','お待ちかねの夕食は、日本海の荒波が育んだ新鮮な魚介の舟盛りや、香ばしい山陰の味覚をふんだんに盛り込んだ豪華な会席料理。地元の美味しい日本酒とともに、素材本来の豊かな旨味を心ゆくまで堪能し、笑顔が絶えない贅沢な夜のひとときを過ごす。','2027-06-12','19:30','🦀','0','',0,1,false,'2027-06-12 21:00:00+09','2026-08-02 01:27:16.327071+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.358330000,133.541670000,'翌日、車を走らせて霊峰「大山」の麓に広がる豊かな自然スポットへと向かう','旅行2日目は、中国地方の最高峰であり神々が宿る美しい霊峰「大山」の麓へとドライブ。車窓から緑豊かな山々の美しい景色を眺めながら、鳥取が誇る雄大な自然に囲まれた爽やかなエリアへと軽快に車を進める。','2027-06-13','10:00','🚗','0','',0,1,false,'2027-06-13 10:45:00+09','2026-08-02 01:27:16.327071+09'),
	 (48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.361110000,133.538890000,'大山の美しい緑に囲まれた歴史ある「大山寺」の神秘的な境内をのんびり参拝','聖なる山として古くから信仰を集めてきた歴史ある「大山寺」の境内へと足を運ぶ。澄んだ山の空気に包まれた厳かな参道をゆっくりと歩き、苔むした石段や歴史あるお堂の佇まいを眺めながら、心洗われるような静寂と癒やしの時間を過ごす。','2027-06-13','11:00','⛩️','0','',-300,1,false,'2027-06-13 11:45:00+09','2026-08-02 01:27:16.327071+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.346940000,134.045560000,'1軒目：駅チカの朝から行列ができる有名店で、コシ抜群の「ぶっかけうどん」をすする','高松駅からすぐの場所にある、朝から地元の常連客や旅人で賑わう超人気うどん店へ突撃。目の前に運ばれてきた、ツヤツヤでエッジの立った麺に特製だしをぶっかけた一杯を豪快にかき込む。ガツンとくる強力なコシと小麦の香ばしさに「うまっ！」と声が漏れ、1軒目から大感動。','2027-10-09','09:30','🍜','0','',-600,1,false,'2027-10-09 10:00:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.283330000,134.013890000,'車を走らせて讃岐平野の中にある名店へ、のどかな田園風景の中をドライブ','高松市内からレンタカーを走らせて、讃岐平野に点在するディープな名店エリアへと移動する。車窓から広がるのどかな田園風景を眺めながら、「次の店は出汁が美味いらしいぞ」などと男同士でうどん談義に華を咲かせ、ドライブの爽快な風を全身に浴びながらテンポよく移動する。','2027-10-09','10:30','🚗','0','',0,1,false,'2027-10-09 11:15:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.279720000,134.010560000,'2軒目：行列必至の人気セルフ店で、自分で茹でるアツアツの「釜玉うどん」をガツンと喰らう','地元民でごった返す大人気のセルフうどん店に到着し、ワクワクしながら列に並ぶ。自分で麺をテボに入れて温め、生卵と特製醤油を絡めて豪快に掻き込む「釜玉うどん」を注文。濃厚な卵と熱々のうどんが絡み合う極上のジャンクな旨さに、男二人で思わず顔を見合わせて唸る。','2027-10-09','11:15','🔥','0','',-500,1,false,'2027-10-09 12:00:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.331670000,134.043330000,'日本三大庭園の一つ「栗林公園」の圧倒的な緑の中を男二人で歩いて腹ごなし','うどんの連続攻撃でお腹がいっぱいになったところで、国の特別名勝「栗林公園」の広大な庭園へ。見事な松の緑や美しい池の景色を眺めながら、男同士でこれまでの人生や仕事の熱い野望について語り合いながら、心地よい汗を流しつつ次のうどんへ向けて胃袋のスペースを空ける。','2027-10-09','12:30','🌳','0','',-410,1,false,'2027-10-09 13:30:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343330000,134.053890000,'3軒目：繁華街の隠れ家的名店で味わう、キリッとしたイリコ出汁が染みる「かけうどん」','高松市内の中心街に戻り、地元民に愛され続ける通好みの一軒へと足を踏み入れる。透明感のある黄金色のスープにイリコ出汁の香りがふわっと広がる「かけうどん」をすする。優しくも芯のある深い味わいに、歩き疲れた体に染み渡る最高の美味さを実感して思わず笑顔になる。','2027-10-09','14:00','🥢','0','',-450,1,false,'2027-10-09 14:45:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.345000000,134.055000000,'商店街の中の活気あるお土産処で、讃岐うどんの乾麺や出汁醤油を爆買い','日本一の長さを誇る高松中央商店街をぶらり歩きながら、厳選された讃岐うどんの特産品が並ぶショップへ。自宅や友人へのお土産として、職人のこだわりが詰まった極上の半生うどんや特製のいりこ出汁醤油を「どれが一番美味いか」と真剣に吟味して大量に買い込む。','2027-10-09','15:00','🛍️','0','',-3500,1,false,'2027-10-09 15:45:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.349170000,134.060000000,'4軒目：夕暮れ時に立ち寄る老舗の製麺所直営店で、豪快な「肉ぶっかけ」にかぶりつく','麺がなくなり次第終了という伝説の製麺所直営店に夕暮れ滑り込みセーフで到着。甘辛くじっくり煮込まれたボリューム満点的牛肉がどっさり乗った「肉ぶっかけ」を男らしく勢いよく平らげる。濃厚な肉汁とうどんのコシのハーモニーに、お腹が限界を迎えつつも箸が止まらない。','2027-10-09','16:30','🥩','0','',-750,1,false,'2027-10-09 17:15:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.344440000,134.052220000,'本日の宿泊先である、高松市街地の中心にあるモダンなビジネスホテルにチェックイン','一日中うどんを食べ歩いて大満足したところで、街の中心部にあるスタイリッシュなホテルにチェックイン。清潔感あふれるモダンな客室に通され、男二人で「今日何杯食べたっけ？」とスマホの万歩計や食べたうどんの数を振り返りながら、ベッドに倒れ込んで一息つく。','2027-10-09','18:00','🏨','0','',-12000,1,false,'2027-10-09 18:45:00+09','2026-08-02 01:35:25.086879+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.404144550,132.680544330,'古代出雲歴史博物館を見学','博物館では出雲の神話や歴史を深く知ることができ、展示の迫力に驚かされた。巨大な柱の復元模型は圧巻で、古代出雲の壮大さを感じられた。静かな展示室を歩くと、旅のテーマである「縁結び」がより意味深く感じられた。','2026-10-12','13:00','🏛️','0000','',-620,1,false,'2026-10-12 13:00:00+09','2026-08-02 02:40:53.40301+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.345280000,134.053060000,'ホテルの大浴場とサウナで、うどん巡りで歩き疲れた体を徹底的にリフレッシュ','夕食の前に、ホテルの最上階にある大浴場とサウナへと急ぐ。熱々のサウナでしっかりと汗を流し、キンキンに冷えた水風呂で一気に身体を引き締めたあと、足を思い切り伸ばせる大きなお湯に浸かりながら、最高の男旅の充実感に浸って心身ともに完全にリフレッシュする。','2027-10-09','19:00','♨️','0','',0,1,false,'2027-10-09 19:45:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343890000,134.051390000,'5軒目：香川の夜のもう一つの主役！香ばしすぎる名物「骨付鳥」にかぶりつく男の晩餐','うどんだけでは終わらない香川の夜、香ばしいスパイスの香りが漂う大人気の骨付鳥専門店へ。「親鳥」と「若鶏」をそれぞれ一本ずつ注文し、豪快にかぶりついてキンキンに冷えたビールをグイッと流し込む。ジューシーな肉汁とスパイシーな味付けがビールと最強に合いすぎて男二人で絶叫する。','2027-10-09','20:00','🍗','0','',-3500,1,false,'2027-10-09 21:30:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.346670000,134.057500000,'夜の繁華街のバーで、男同士で夢や今後の目標について熱く語り合うディープな夜','骨付鳥でお腹を満たしたあとは、隠れ家風のクールなバーへとハシゴしてしっぽりとお酒を傾ける。お酒の力を借りて、普段は照れくさくて言えないこれからの夢や仕事への熱い想いを男同士でぶつけ合い、忘れられない最高に濃い夜の時間を満喫する。','2027-10-09','21:30','🥃','0','',-4000,1,false,'2027-10-09 23:00:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.341390000,134.111110000,'翌日、絶景の源平合戦の舞台「屋島」の山頂へとレンタカーで駆け上がる','旅行2日目は、瀬戸内海の美しい島々を一望できる歴史の舞台「屋島」の山頂へと車を走らせる。ワインディングロードを軽快に駆け抜け、展望台へと到着すると目の前に広がる青い海と島々の圧倒的な大パノラマに男二人で「すげぇ…」と息を呑む。','2027-10-10','10:00','🚙','0','',0,1,false,'2027-10-10 10:45:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.340000000,134.108330000,'6軒目：屋島の絶景テラスにある絶品うどん店で、景色を肴に最後の「釜上げうどん」','屋島の絶景を一望できるロケーション抜群のうどん店で、旅のフィナーレを飾る一杯を注文。大きな桶に入った熱々の麺を特製出汁にくぐらせてすする「釜上げうどん」は格別の美味しさ。目の前に広がる絶景を眺めながら味わう最後のうどんに言葉を失う。','2027-10-10','11:00','🤤','0','',-650,1,false,'2027-10-10 11:45:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342220000,134.046390000,'高松市街に戻り、香川のソウルフードである「しょうゆ豆」などのお土産を総仕上げ','高松市街へと戻り、旅の最後に地元の老舗お土産店へ立ち寄る。香川の伝統的なおつまみである「しょうゆ豆」や、地酒、讃岐うどんの有名店セットをカゴいっぱいに詰め込み、男旅の完璧なお土産の買い出しをスピーディーかつ完璧に完了させる。','2027-10-10','13:00','🎁','0','',-2500,1,false,'2027-10-10 13:45:00+09','2026-08-02 01:35:25.086879+09'),
	 (50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.348330000,134.048330000,'「JR高松駅」に戻り、腹パンパンの大満足と最高の思い出を胸に帰路につく','全6軒のうどん巡りと骨付鳥制覇を成し遂げ、再び出発地のJR高松駅へと戻る。「想像以上に食いすぎて腹がちぎれそうだけど、最高すぎる男旅だったな！」と駅のホームで固い握手を交わし、忘れられない香川の熱い思い出を胸に帰路の列車へと乗り込む。','2027-10-10','14:30','👋','0','',0,1,false,'2027-10-10 15:15:00+09','2026-08-02 01:35:25.086879+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957900000,130.941200000,'展望台で絶景を眺める','展望台から見える関門海峡の景色が圧巻で「これ来てよかったな」と全員が感動。海と街が一望できて、今日の食べ歩きの思い出が一気に蘇るような景色だった。写真を撮りながらゆっくり景色を楽しんだ。','2026-11-03','15:50','📸','0000','',0,1,true,'2026-11-03 15:50:00+09','2026-08-02 02:38:00.798541+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401844550,132.685012330,'勢溜の大鳥居をくぐる','勢溜の大鳥居は想像以上に大きく、くぐった瞬間に空気が変わるような感覚があった。鳥居の向こうに続く参道は広く、ゆっくり歩くと心が落ち着いていく。朝の光が木々の間から差し込み、旅の始まりにふさわしい神聖な雰囲気が漂っていた。','2026-10-12','09:30','⛩️','0000','',0,1,false,'2026-10-12 09:30:00+09','2026-08-02 02:40:53.40301+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.402744220,132.684544110,'松の参道を歩く','勢溜から続く松の参道は、両側に立ち並ぶ松が美しく、歩くだけで気持ちが整う。砂利道の音が心地よく、ゆっくり進むと自然と背筋が伸びるような感覚があった。参拝前の時間として最適で、出雲らしい穏やかな空気が流れていた。','2026-10-12','09:50','🌿','0000','',0,1,false,'2026-10-12 09:50:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.403544990,132.684012880,'拝殿で参拝','拝殿の前に立つと、その大きさと美しさに自然と息をのんだ。二礼四拍手一礼でゆっくり参拝すると、心が静かに整っていく。周囲の空気は澄んでいて、参拝後には気持ちが軽くなるような感覚があった。出雲大社ならではの特別な時間だった。','2026-10-12','10:10','🙏','0000','',0,1,false,'2026-10-12 10:10:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.403944330,132.683544550,'本殿を参拝','本殿は厳かな雰囲気に包まれており、近づくほどに心が静かになる。木の香りがほのかに漂い、歴史の深さを感じられた。参拝を終えると、気持ちがすっと軽くなり、旅の目的である「縁結び」が自然と心に浮かんだ。','2026-10-12','10:30','🏯','0000','',0,1,false,'2026-10-12 10:30:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.404744880,132.683012440,'神楽殿で大しめ縄を見る','神楽殿の大しめ縄は圧倒的な存在感で、近くで見るとその迫力に驚かされる。太い縄の編み込みが美しく、写真では伝わらない重厚さがあった。参拝客の穏やかな声が響き、出雲らしいゆったりした時間が流れていた。','2026-10-12','10:50','📸','0000','',0,1,false,'2026-10-12 10:50:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.405544220,132.682544330,'御本殿裏の素鵞社へ','素鵞社は本殿裏にひっそりと佇み、静かな空気が流れていた。参拝すると心がすっと整い、出雲の神聖さをより深く感じられた。木々に囲まれた場所で、風の音が心地よく響いていた。','2026-10-12','11:10','🌲','0000','',0,1,false,'2026-10-12 11:10:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.405944990,132.681744880,'出雲そばで昼食','参道沿いのそば屋で出雲そばをいただく。黒めのそばは香りが強く、つゆとの相性が抜群だった。店内は落ち着いた雰囲気で、旅の途中の食事として最適。体がほっと温まり、午後の散策への活力が湧いた。','2026-10-12','12:00','🍜','0000','',-1200,1,false,'2026-10-12 12:00:00+09','2026-08-02 02:40:53.40301+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.402244110,132.677744220,'稲佐の浜へ移動','稲佐の浜は白い砂浜と青い海が広がり、神話の舞台らしい静けさが漂っていた。波の音が心地よく、歩くだけで気持ちが整う。弁天島を眺めながら深呼吸すると、旅の中でも特に印象に残る時間となった。','2026-10-12','14:00','🌊','0000','',0,1,false,'2026-10-12 14:00:00+09','2026-08-02 02:40:53.40301+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.748665166,131.873703003,'日本海の海岸線に到着','海岸線に出ると、荒々しい波が岩にぶつかり、迫力ある音が響いていた。観光地ではないが、石見らしい力強い海の景色が広がる。風が強く、海の匂いが濃く感じられた。しばらく波を眺めながら、自然の大きさを感じる時間となった。','2026-10-20','13:40','🌊','0000','',0,1,false,'2026-10-20 13:40:00+09','2026-08-02 02:51:13.863803+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.754588941,131.932411194,'海沿いの岩場で写真撮影','岩場に出ると、海の迫力がさらに増し、写真を撮るとどれも力強い景色になった。観光地ではないが、自然のままの海が広がり、旅の記録として残したい場所だった。','2026-10-20','16:10','📸','0000','',0,1,false,'2026-10-20 16:10:00+09','2026-08-02 02:52:39.622353+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.666110000,133.918060000,'「JR岡山駅」に到着、晴れの国・岡山の観光めぐりがいよいよ元気にスタート','新幹線を降り立った瞬間から爽やかな青空が広がる「晴れの国・岡山」の玄関口、JR岡山駅へ到着。「今日はどんな美味しいものに出会えるかな？」と胸をときめかせながら、これから始まる充実の岡山観光めぐりに向けて笑顔で元気いっぱいに出発する。','2027-11-12','09:00','🚅','0','',0,1,false,'2027-11-12 09:30:00+09','2026-08-02 01:37:59.550303+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.664440000,133.928890000,'1軒目：駅チカの老舗洋食店でサクサクの岡山名物「デミカツ丼」にかぶりつく','岡山駅のすぐ近くにある地元で愛され続ける老舗洋食店へ直行し、ランチタイム。揚げたてのサクサクなトンカツの上に、濃厚でコクのある特製デミグラスソースがたっぷりとかかった岡山名物「デミカツ丼」を頬張り、その美味しさに最初の一口目から大感動する。','2027-11-12','09:30','🍛','0','',-1100,1,false,'2027-11-12 10:15:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.667220000,133.936110000,'日本三名園の一つ、四季折々の美しい緑が広がる「岡山後楽園」をのんびりお散歩','路面電車に揺られて、日本三名園に数えられる広大な名勝「岡山後楽園」へと足を運ぶ。手入れが行き届いた見事な芝生や美しい池のまわりをゆったりと歩きながら、風情ある和の景色と穏やかな時間の流れに心から癒やされる贅沢なひとときを過ごす。','2027-11-12','11:00','🌳','0','',-410,1,false,'2027-11-12 11:45:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668890000,133.935000000,'「岡山後楽園」の橋を渡り、別名「烏城」と呼ばれる黒く美しい「岡山城」へ登城','後楽園の橋を渡ってすぐ目の前にある、漆黒の天守閣が圧倒的な存在感を放つ「岡山城（烏城）」へ。凛々しい佇まいの城内をじっくりと見学し、最上階の展望フロアからは旭川の流れと岡山の街並みを一望するダイナミックな景色を満喫して歴史のロマンに浸る。','2027-11-12','12:15','🏯','0','',-400,1,false,'2027-11-12 13:00:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.662220000,133.921670000,'2軒目：おしゃれなフルーツパーラーで、旬の果物が山盛りの絶品「岡山フルーツパフェ」','岡山駅前へと戻り、フルーツ王国として名高い岡山ならではの人気フルーツパーラーへ。グラスの上に瑞々しいシャインマスカットや桃などの旬の果物がこれでもかと贅沢にトッピングされた、美しすぎる特製フルーツパフェを味わい、甘くて爽やかな味わいに思わず笑顔がこぼれる。','2027-11-12','14:00','🍨','0','',-1500,1,false,'2027-11-12 14:45:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.601110000,133.775000000,'電車に乗って歴史ある白壁の街並みが残る「倉敷美観地区」へと風情ある移動','岡山駅から電車に揺られて約20分、白壁の蔵やなまこ壁が美しい伝統的建造物群保存地区「倉敷美観地区」へと到着する。一歩足を踏み入れた瞬間から、江戸時代からの歴史を感じさせる情緒あふれる美しい景観に包まれ、まるでタイムスリップしたかのような気分になる。','2027-11-12','15:30','🚃','0','',-330,1,false,'2027-11-12 16:15:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.598330000,133.774440000,'柳並木が続く倉敷川の川面を、伝統的な「倉敷川舟流し」の小舟でゆったりとお散歩','倉敷川の穏やかな水面に浮かぶ小さな木造船「川舟」に乗り込み、水上からの景色を楽しむ。船頭さんの心地よい竿さばきと解説を聞きながら、緑豊かな柳並木と美しい白壁の町並みを眺める優雅な船旅の風情を全身でたっぷりと味わい尽くす。','2027-11-12','16:15','🛶','0','',-700,1,false,'2027-11-12 17:00:00+09','2026-08-02 01:37:59.550303+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710245449,139.812623262,'東京ソラマチで早めのランチ','展望台を満喫したあとは、ソラマチのレストラン街でガッツリとランチ。みんなで違うメニューを頼んでシェアしながら、これまでの大学生活の思い出話で盛り上がる。','2026-03-15','12:30','😋','0','',-1600,1,false,'2026-03-15 12:35:10.8+09','2026-08-02 22:21:10.868408+09'),
	 (4,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.709452691,139.804984331,'隅田公園をのんびりお散歩','スカイツリーから浅草方面へ向かって、隅田川沿いの公園を歩く。春の暖かい日差しの中、川風を感じながらのんびりとおしゃべりしながら歩く時間がとても心地よい。','2026-03-15','15:15','🌿','0','',0,1,false,'2026-03-15 15:18:00+09','2026-08-02 22:21:10.868408+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489170000,134.171940000,'翌日、島の特産品が集まるお土産市場で、オリーブ製品や佃煮のお買い物','旅行2日目は、小豆島の美味しい特産品がたくさん揃う人気の大きなお土産市場へ立ち寄る。極上のオリーブオイルや、甘辛く煮込まれた名物の佃煮、可愛い小豆島グッズをじっくりと吟味し、旅の思い出を彩る素敵なお土産を家族みんなでたくさん選び取る。','2027-09-20','10:00','🎁','0','',0,1,false,'2027-09-20 10:45:00+09','2026-08-02 01:31:18.661244+09'),
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.486940000,134.169440000,'市場内の食堂で味わう、ツルツル食感がたまらない名物「小豆島そうめん」のランチ','お土産選びのあとは、市場内にあるアットホームな食堂で名物の「小豆島そうめん」をランチにいただく。手延べならではのコシの強さとツルッとなめらかな喉越しが抜群に美味しく、旅の締めくくりにふさわしい優しい味わいに心から癒やされる。','2027-09-20','11:30','🍜','0','',-900,1,false,'2027-09-20 12:15:00+09','2026-08-02 01:31:18.661244+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489170000,134.171940000,'「土庄港」に戻り、瀬戸内海のたくさんの温かい思い出を胸に笑顔で帰路につく','すべての観光とグルメを家族みんなで大満足して、再び出発地の土庄港へと戻る。“オリーブもエンジェルロードも、美味しいご飯も全部最高だったね！”と満面の笑みで語り合いながら、たくさんの温かい思い出がぎっしり詰まったフェリーに乗り込んで帰路につく。','2027-09-20','14:00','👋','0','',0,1,false,'2027-09-20 14:45:00+09','2026-08-02 01:31:18.661244+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.586943980,130.554828644,'照国神社を参拝','街中にある落ち着いた神社で、旅の安全を祈る。境内は静かで心が落ち着く。鹿児島らしい雰囲気が漂う。','2026-10-12','16:30','⛩️','0000','',0,1,false,'2026-10-12 16:30:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.581167751,130.549507141,'維新ふるさと館','幕末の歴史を学べる施設で、展示が分かりやすくて興味深い。鹿児島の歴史を知ることで旅がより深まる。','2026-10-12','17:00','📚','0000','',0,1,false,'2026-10-12 17:00:00+09','2026-08-02 16:24:03.081396+09'),
	 (35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728337238,135.994606018,'徐福公園で歴史散策とちょっとしたネタ写真撮影','秦の始皇帝の命を受けた徐福の伝説が残る公園。珍しいモニュメントの前でふざけたポーズを取りながら記念撮影。','2026-10-10','15:00','🗿','0','',-200,1,false,'2026-10-10 15:30:00+09','2026-08-01 21:19:23.105537+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.600000000,133.772780000,'3軒目：美観地区の古民家カフェで、名物の「ママカリの寿司」や地元のランチ','歴史ある古民家を丁寧にリノベーションした風情抜群のカフェに入り、ちょっと遅めのランチタイム。岡山ならではの郷土料理である「ママカリの寿司」や瀬戸内の海の幸を上品に味わい、レトロで落ち着いた店内で至福のグルメ時間をゆっくりと楽しむ。','2027-11-12','17:15','🍣','0','',-1400,1,false,'2027-11-12 18:00:00+09','2026-08-02 01:37:59.550303+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196000000,135.150000000,'加太の海辺散歩','海風が気持ちよくて最高。友達と写真を撮り合って盛り上がる。','2026-08-10','14:00','🤩','0','',0,1,false,'2026-08-10 14:02:00+09','2026-08-01 19:28:00.274263+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.832900000,'近鉄奈良駅に到着！古都めぐりの幕開け','近鉄奈良駅に到着し、いざ歴史と文化の街・奈良へ。駅からすぐに広がる古都の雰囲気に気分が高まる。','2026-07-01','09:30','🚅','0','',0,1,true,'2026-07-01 09:35:15.1+09','2026-08-01 17:15:34.285211+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196500000,135.147000000,'友ヶ島フェリー乗り場','時間が合わず友ヶ島は断念。少し残念だけど海が綺麗で気持ちは上向き。','2026-08-10','14:40','🙂','0','',0,0,false,'2026-08-10 14:42:00+09','2026-08-01 19:28:00.274263+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.195000000,135.152500000,'海辺のカフェで休憩','海を眺めながらアイスコーヒー。女子旅らしいゆったり時間。550円。','2026-08-10','15:20','🙂','0','',-550,1,false,'2026-08-10 15:22:00+09','2026-08-01 19:28:00.274263+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'和歌山駅へ戻る','帰りの電車に向けて移動。疲れはあるけど楽しい気持ちが勝っている。','2026-08-10','16:10','🙂','0','',0,1,false,'2026-08-10 16:12:00+09','2026-08-01 19:28:00.274263+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196000000,135.150000000,'加太へドライブ','海沿いの道が気持ちよくて窓を開けて走る。家族みんなご機嫌。','2026-08-15','11:30','🙂','0000','',0,1,true,'2026-08-15 11:32:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196500000,135.147000000,'加太の海辺で休憩','波の音が心地よくてしばらくぼーっとする。家族で砂浜を歩いてのんびり。','2026-08-15','12:10','🙂','0000','',0,1,true,'2026-08-15 12:12:00+09','2026-08-01 21:33:47.291888+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685300000,135.843000000,'東大寺の大仏様に圧倒される','世界最大級の木造建築である大仏殿へ。堂内に鎮座する高さ約15メートルの奈良の大仏の圧倒的なスケールに息をのむ。','2026-07-01','10:30','⛩️','0','',-600,2,true,'2026-07-01 10:35:20.2+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681100000,135.842700000,'奈良公園で鹿たちとふれあい','奈良公園の芝生エリアを散策。あちこちにいる鹿に鹿せんべいをあげたり、のんびりとした時間を楽しむ。','2026-07-01','12:00','🦌','0','',-200,3,true,'2026-07-01 12:05:10.5+09','2026-08-01 17:15:34.285211+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559000000,139.898000000,'駅ビルでお土産の冷凍餃子を物色','帰る前に駅ナカのお土産売り場へ。種類が多すぎてどれを買うかすごく迷う。レジの混雑に少し焦ったけれど、無事に人気の冷凍餃子を確保。','2026-08-05','20:20','🛍️','0','',-3500,0,false,'2026-08-05 20:25:00+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559400000,139.898300000,'宇都宮駅のホームで新幹線を待つ','お腹いっぱい＆お土産も買って大満足の状態でホームへ。心地よい疲労感に浸りながら、帰りの新幹線の時間を待つ。','2026-08-05','21:00','🌙','0','',0,1,false,'2026-08-05 21:05:22.4+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559400000,139.898300000,'新幹線車内でプチ反省会','発車した新幹線の座席で、今日撮った写真を見返す。食べすぎたねと笑い合いながら、最高の一日をしめくくる。','2026-08-05','21:30','✨','0','',0,1,false,'2026-08-05 21:35:11.1+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.681200000,139.767100000,'東京駅に無事到着','あっという間に東京駅へ戻ってきた。現実に戻る寂しさはあるけれど、クーラーの効いた快適な駅構内を足早に自宅へ向かう。','2026-08-05','22:20','🚅','0','',0,1,false,'2026-08-05 22:25:05.1+09','2026-08-01 16:47:54.502649+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.596670000,133.773390000,'倉敷アイビースクエアの赤レンガとツタが織りなすレトロモダンな空間を散策','明治時代の赤レンガ紡績工場を保存・活用した複合文化施設「倉敷アイビースクエア」へ立ち寄る。建物全体を覆う鮮やかな緑のツタと赤いレンガのコントラストが最高に美しく、どこを切り取っても絵になるおしゃれなレトロモダンな空間の中をのんびりと歩いて巡る。','2027-11-13','10:00','🧱','0','',0,1,false,'2027-11-13 10:45:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.595000000,133.771670000,'美観地区のこだわりのお土産ショップで、可愛い倉敷デニムやマスキングテープ選び','日本発祥のジーンズ文化が息づく倉敷ならではのショップや、種類豊富な可愛いマスキングテープが揃うお店へ。職人のこだわりが詰まったおしゃれなデニム雑貨や、お土産にぴったりのカラフルな文房具をじっくりと手にとってお気に入りの品を楽しく選び取る。','2027-11-13','11:00','🛍️','0','',-2000,1,false,'2027-11-13 11:45:00+09','2026-08-02 01:37:59.550303+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.481670000,133.805560000,'JRで南下し、瀬戸内海の美しい島々と巨大な橋が望める絶景スポット「鷲羽山」へ','さらに足を延ばして、瀬戸大橋の壮大なスケールと穏やかな多島美を一望できる「鷲羽山」の山頂エリアへ車を走らせる。展望台へと到着すると、眼下に広がる青い海と雄大な瀬戸大橋の絶景パノラマに「すごい大迫力！」と感動の声を上げる。','2027-11-13','12:30','🌉','0','',0,1,false,'2027-11-13 13:15:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.664440000,133.921110000,'本日の宿泊先である、岡山駅周辺の利便性抜群なアーバンホテルにチェックイン','観光を満喫したあとは、岡山駅のすぐ近くにあるスタイリッシュで快適なホテルへと戻りチェックイン。清潔感あふれる広々とした客室に通され、今日一日で巡ったたくさんの素敵な景色や美味しい思い出を振り返りながら、心地よいベッドでリラックスする。','2027-11-13','15:00','🏨','0','',-14000,1,false,'2027-11-13 15:45:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.665560000,133.919440000,'ホテルの大浴場とサウナで、一日中歩いて回った観光の疲れをすっきりと癒やす','夕食の前に、ホテル館内にある広々とした大浴場とリフレッシュサウナへ足を運ぶ。温かいお湯にゆっくりと体を沈めて一日の歩き疲れを芯からほぐしながら、「今日は本当に盛りだくさんで楽しかったね」と心身ともに完全にリラックスしてリフレッシュする。','2027-11-13','16:00','♨️','0','',0,1,false,'2027-11-13 16:45:00+09','2026-08-02 01:37:59.550303+09'),
	 (60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401002110,132.685744880,'出雲大社前駅に到着','出雲大社前駅に降り立つと、レトロな駅舎が迎えてくれた。空気がどこか澄んでいて、旅の始まりにふさわしい静けさが漂う。駅前の道はゆるやかに大社へ続いており、歩きながら「この土地は何か特別なものを持っている」と自然に感じられた。参道の石畳を踏みしめながら、今日の縁結び旅への期待が静かに高まった。','2026-10-12','09:10','🚉','0000','',0,1,false,'2026-10-12 09:10:00+09','2026-08-02 02:40:53.40301+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.595833330,130.557222220,'鹿児島中央駅に到着','旅の始まりは鹿児島中央駅。南国らしい暖かい空気が漂い、駅前の賑わいに気分が高まる。観光案内所で地図をもらい、今日のルートを軽く確認して出発する。','2026-10-12','09:10','📸','0000','',0,1,false,'2026-10-12 09:10:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.593611110,130.561944440,'天文館を散策','鹿児島の中心街である天文館は活気があり、地元の店が並んで歩くだけで楽しい。名物の白熊を見つけてテンションが上がる。','2026-10-12','09:40','🛍️','0000','',0,1,false,'2026-10-12 09:40:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.592222220,130.565833330,'白熊を味わう','天文館むじゃきで名物の白熊を注文。見た目のインパクトに驚きつつ、食べると優しい甘さで美味しい。観光客らしい体験ができて満足。','2026-10-12','10:10','🍧','0000','',-900,1,false,'2026-10-12 10:10:00+09','2026-08-02 16:24:03.081396+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957982110,130.941145770,'唐戸市場前に到着','駅からバスで唐戸市場へ向かうと、車窓から海がきらきらと光り、旅の目的が一気に現実味を帯びてきた。市場の建物が見えてくると、食べ歩きへの期待が自然と高まり、4人の表情が明るくなる。市場前の広場は活気に満ちており、下関の食文化を象徴する雰囲気が漂っていた。','2026-11-03','09:40','🚌','0000','',0,1,false,'2026-11-03 09:40:00+09','2026-08-02 02:35:22.146541+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.689500000,139.691700000,'自宅に到着して冷凍餃子を冷蔵庫へ','無事に帰宅完了！お土産の冷凍餃子を大切に冷蔵庫にしまい、充実感に包まれながらベッドへ直行。楽しい宇都宮の一日が終わった。','2026-08-05','23:10','🏠','0','',0,1,false,'2026-08-05 23:15:00+09','2026-08-01 16:47:54.502649+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.679000000,135.828000000,'奈良の郷土料理と地酒で夕食','夕食は地元の食材をふんだんに使った郷土料理と、奈良の地酒をゆっくり堪能。静かな夜の奈良をしみじみ味わう。','2026-07-01','19:30','🍶','0','',-4500,9,true,'2026-07-01 19:35:15.3+09','2026-08-01 17:15:34.285211+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680000000,135.825000000,'奈良市内の和風ホテルへチェックイン','古都の景観に溶け込む落ち着いた和風ホテルに到着。部屋で少し荷物を整理して、夜の街へ繰り出す準備をする。','2026-07-01','19:00','🏨','0','',-14000,9,true,'2026-07-01 19:05:20+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.679000000,135.828000000,'奈良の郷土料理と地酒で夕食','夕食は地元の食材をふんだんに使った郷土料理と、奈良の地酒をゆっくり堪能。静かな夜の奈良をしみじみ味わう。','2026-07-01','20:00','🍶','0','',-4500,10,true,'2026-07-01 20:05:15.3+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.675000000,135.820000000,'若草山の夕景を眺めるドライブ','（※朝の爽やかな風景として）若草山周辺の高台へ。奈良盆地の清々しい景色を眺めながら、穏やかな時間に浸る。','2026-07-02','09:00','🌅','0','',0,11,true,'2026-07-02 09:05:10+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686000000,135.830000000,'近鉄奈良駅ビルでお土産選び','駅に戻り、奈良のお土産売り場で柿の葉寿司や大仏プリン、鹿モチーフの可愛いお菓子などをたくさん買い込む。','2026-07-02','10:15','🛍️','0','',-3000,12,true,'2026-07-02 10:20:11.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.832900000,'近鉄奈良駅に到着！古都めぐりの幕開け','近鉄奈良駅に到着し、いざ歴史と文化の街・奈良へ。駅からすぐに広がる古都の雰囲気に気分が高まる。','2026-07-01','09:30','🚅','0','',0,1,true,'2026-07-01 09:35:15.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685300000,135.843000000,'東大寺の大仏様に圧倒される','世界最大級の木造建築である大仏殿へ。堂内に鎮座する高さ約15メートルの奈良の大仏の圧倒的なスケールに息をのむ。','2026-07-01','10:30','⛩️','0','',-600,2,true,'2026-07-01 10:35:20.2+09','2026-08-01 19:03:48.822924+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.225900000,135.167400000,'和歌山城へ向かう道','日差しが強くて汗ばむけどおしゃべりが楽しい。女子旅らしいテンション。','2026-08-10','10:00','😅','0','',0,0,false,'2026-08-10 10:02:00+09','2026-08-01 19:28:00.274263+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559400000,139.898300000,'JR宇都宮駅に到着！餃子の像がお出迎え','新幹線を降りて改札を出ると、さっそく名物の「餃子像」がお出迎え！駅のまわりからほのかに美味しそうな香りがしてきて、早くも食欲がそそられる。','2026-08-05','11:00','🥟','0','',0,1,false,'2026-08-05 11:05:15.1+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.558000000,139.897000000,'宇都宮パセオで1軒目の有名店へ直行','駅からすぐの商業施設内にある有名餃子店へ。焼き立ての餃子は皮がパリッパリ、中はジューシーで肉汁があふれ出す！ビールが欲しくなる最高の味。','2026-08-05','11:30','🍺','0','',-1200,1,false,'2026-08-05 11:35:20.2+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.552000000,139.893000000,'宇都宮二荒山神社で旅の安全祈願','街の中心にある風格漂う神社へ参拝。立派な楼門や静かな境内に心が落ち着く。これからの食べ歩きが無事に楽しめるようしっかりとお祈りした。','2026-08-05','13:15','⛩️','0','',0,1,false,'2026-08-05 13:20:00+09','2026-08-01 16:47:54.502649+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.550500000,139.891200000,'オリオン通り商店街でアイス休憩','レトロなアーケードが続く商店街を散策。歩き疲れて暑さもピークに達したため、喫茶店に入って冷たい宇都宮レモネードを飲んで生き返る。','2026-08-05','14:10','🥤','0','',-550,1,false,'2026-08-05 14:15:12.3+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.548000000,139.889000000,'行列のできる老舗餃子店にチャレンジ','ガイドブックにも載っている超有名老舗店へ到着。しかし想像以上の大行列で、蒸し暑い中40分以上並ぶ羽目に…。足も腰もクタクタになって少しぐったり。','2026-08-05','15:00','😫','2','',0,-1,false,'2026-08-05 15:05:40.1+09','2026-08-01 16:47:54.502649+09'),
	 (18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.548000000,139.889000000,'念願の老舗の「水餃子」に舌鼓','並んで食べた水餃子は、特製のスープとモチモチの皮が絶品！お酢とラー油をたっぷり入れて食べたら、並んだ苦労が吹き飛ぶほどの美味しさだった。','2026-08-05','16:00','🍲','0','',-950,1,false,'2026-08-05 16:05:20+09','2026-08-01 16:47:54.502649+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226200000,135.167000000,'和歌山城天守閣','天守閣からの景色が最高。写真を撮りまくって大盛り上がり。入館料410円。','2026-08-10','10:40','🤩','0','',-410,1,false,'2026-08-10 10:42:00+09','2026-08-01 19:28:00.274263+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.233000000,135.167200000,'ランチは和歌山ラーメン','女子旅でもラーメンは外せない。濃厚スープが美味しくて満足。900円。','2026-08-10','12:10','🤩','0','',-900,1,false,'2026-08-10 12:12:00+09','2026-08-01 19:28:00.274263+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.195400000,135.152000000,'加太へ移動','海が見えてテンション上がる。写真を撮りながらのんびり移動。','2026-08-10','13:20','🙂','0','',0,1,false,'2026-08-10 13:22:00+09','2026-08-01 19:28:00.274263+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957842330,130.941873220,'唐戸市場でフグ寿司','市場に入ると海鮮の香りと活気ある声が広がり、自然と気持ちが高まった。名物のフグ寿司を口に入れると、身がぷりっと弾むようで、旅の序盤から満足度が一気に上昇した。市場の賑やかさとフグの旨味が相まって、下関ならではの食体験が強く印象に残った。','2026-11-03','10:00','🍣','0000','',-900,1,false,'2026-11-03 10:00:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957765440,130.942102880,'市場横の海沿いデッキで休憩','市場横の海沿いデッキに出ると、関門海峡を渡る風が心地よく、食べ歩きの合間にぴったりの休憩時間になった。船が行き交う景色を眺めながら、フグ寿司の余韻を楽しむ。海の青さが広がり、旅の中にゆるやかな時間が流れた。','2026-11-03','10:30','🌊','0000','',0,1,false,'2026-11-03 10:30:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957050120,130.942600440,'みもすそ川公園で海峡を眺める','赤間神宮から坂を下ると、みもすそ川公園に到着。関門海峡が目の前に広がり、海風が心地よく体を冷ましてくれた。源平合戦の史跡が残る場所で、歴史と海の景色が同時に楽しめる。食べ歩きの合間に訪れるには最適のスポットだった。','2026-11-03','11:20','🌉','0000','',0,1,false,'2026-11-03 11:20:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.951122770,130.927744110,'長府城下町を散策','長府の城下町は静かで落ち着いた雰囲気が広がり、石畳の道を歩くだけで気持ちが整う。歴史的な建物が並び、下関の中心部とは違う魅力が感じられた。食べ歩きの合間に訪れると、旅の流れに心地よい変化が生まれた。','2026-11-03','13:00','🏯','0000','',0,1,false,'2026-11-03 13:00:00+09','2026-08-02 02:35:22.146541+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.950212110,130.928844770,'功山寺で静かな時間','功山寺の境内は深い静けさに包まれており、旅の喧騒から離れて心が落ち着く場所だった。歴史ある建物と木々の香りが心地よく、大学生4人の旅にも静かな時間が流れた。下関の多様な魅力を感じられるスポットだった。','2026-11-03','13:40','🌿','0000','',0,1,false,'2026-11-03 13:40:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.960744880,130.943544110,'ノーフォーク広場で休憩','海沿いのノーフォーク広場は風が心地よく、旅の合間にぴったりの場所だった。ベンチに座りながら海峡を眺めると、今日の食べ歩きの思い出が自然と蘇る。広場の穏やかな雰囲気が心地よかった。','2026-11-03','15:40','🌊','0000','',0,1,false,'2026-11-03 15:40:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.960144550,130.942244330,'海峡ゆめタワー展望室','海峡ゆめタワーの展望室からは、関門海峡と街並みが一望できた。夕方の光が差し込み、海が金色に輝く景色は圧巻だった。旅の締めにふさわしい絶景で、4人とも静かに景色を眺めていた。','2026-11-03','16:10','🏙️','0000','',0,1,false,'2026-11-03 16:10:00+09','2026-08-02 02:35:22.146541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.833656000,135.499700000,'今宮三丁目 (大阪府)','簡易メモ','2026-08-02','11:15','😀','0000','',0,1,true,'2026-08-02 11:39:21.489719+09','2026-08-02 12:59:41.923651+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.948744220,130.919544990,'長府毛利邸を見学','長府毛利邸は庭園が美しく、静かな時間が流れていた。歴史ある建物と手入れされた庭が印象的で、旅の中に落ち着いたひとときを与えてくれた。下関の多様な魅力を感じられるスポットだった。','2026-11-03','16:40','🏡','0000','',0,1,false,'2026-11-03 16:40:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.041280622,130.929565430,'角島大橋を歩く','角島大橋は海の上をまっすぐ伸びる絶景スポットで、4人とも自然と声を失った。海の青さが圧倒的で、写真を撮る手が止まらない。下関中心部から離れた場所だが、旅の中でも特に印象に残る体験となった。','2026-11-03','14:40','🌅','0000','',0,1,false,'2026-11-03 14:40:00+09','2026-08-02 02:36:14.823191+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.073137412,130.902099609,'角島灯台を見学','角島灯台は白い塔が美しく、海の青さとのコントラストが印象的だった。灯台周辺の散策路を歩くと、風が心地よく旅の疲れを癒してくれた。下関の食文化だけでなく、自然の魅力も感じられる時間となった。','2026-11-03','15:10','🌤️','0000','',0,1,false,'2026-11-03 15:10:00+09','2026-08-02 02:36:26.875366+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.053890000,134.305560000,'第11番札所「藤井寺」で次なる険しい山道に備え、夫婦でしっかりと気持ちを引き締める','次の難所である「焼山寺」へと続く遍路道の出発点でもある第11番札所「藤井寺」へ。これから始まる本格的な山岳霊場に向けて、「二人でしっかり足元に気をつけて歩こうね」と地図を確認し合いながら、気持ちをしっかりと引き締めてお参りをする。','2027-10-02','14:30','🗺️','0','',-500,1,false,'2027-10-02 15:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957410000,130.940350000,'下関駅に到着','大学の友達4人で下関駅に集合。駅前の空気がどこか潮の香りを含んでいて「ついに来たな、フグの聖地！」とテンションが一気に上がった。荷物を軽くまとめて、まずは駅前で今日のルートを確認しながらワイワイ話し合う。旅の始まり特有のワクワク感が全員の表情に出ていて、これからの“食べつくし旅”に期待が高まった。','2026-11-03','09:10','🚉','0000','',0,1,true,'2026-11-03 09:10:00+09','2026-08-02 02:38:00.798541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957900000,130.941200000,'唐戸市場へ移動','駅からバスで唐戸市場へ向かう道中、4人で「今日どれだけフグ食べられるかな」と盛り上がる。海沿いの景色が広がってきて、旅のテンションがさらに上昇。市場の建物が見えてくると「うわ、ここ絶対楽しいやつやん！」と声がそろった。食べ歩きの準備をしながらワクワクが止まらない。','2026-11-03','09:40','🚌','0000','',0,1,true,'2026-11-03 09:40:00+09','2026-08-02 02:38:00.798541+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342566000,134.046549000,'高松駅に到着','瀬戸内の明るい空気が気持ちよくて、駅に降りた瞬間に旅のワクワクが広がった。','2026-08-03','09:10','🚉','0000','',0,1,true,'2026-08-03 09:10:00+09','2026-08-02 02:10:39.052942+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.170560000,134.483890000,'第1番札所「霊山寺」に到着、夫婦二人で心を新たにするお遍路の旅がいよいよ始動','お遍路の始まりの地である第1番札所「霊山寺」に到着する。白衣に身を包み、夫婦二人で本堂と大師堂に丁寧にお参りをしてから、これから始まる全八十八ヶ所の長い道のりに向けて「二人で支え合って無事に結願しようね」と静かに誓い合い、記念すべき最初の一歩を踏み出す。','2027-10-01','08:30','🙏','0','',-1000,1,false,'2027-10-01 09:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.162780000,134.471670000,'第2番札所「極楽寺」の長寿杉を見上げ、夫婦の健康とこれからの穏やかな日々を祈願','静寂に包まれた境内が美しい第2番札所「極楽寺」へ。樹齢を重ねた見事な長寿杉の圧倒的な存在感に夫婦で深く感嘆しながら、これまでの人生を振り返りつつ、これからも健康で仲良く穏やかに歳を重ねていけますようにと心を込めて手を合わせ、境内をゆっくりと巡る。','2027-10-01','09:45','🌲','0','',-500,1,false,'2027-10-01 10:30:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.135000000,134.453330000,'第3番札所「金泉寺」で名物の「長寿湧水」に触れ、旅の無事と健勝を祈る','弘法大師が掘り当てたと伝えられる霊水が湧き出る第3番札所「金泉寺」へ到着。清らかな湧水に手を浸して身を清め、これからの長い道のりを元気に歩き抜くための体力と、夫婦二人で無事に結願を迎えられることを祈願しながら、お遍路旅ならではの厳かな雰囲気を肌で感じる。','2027-10-01','11:00','💧','0','',-500,1,false,'2027-10-01 11:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.120560000,134.460000000,'第4番札所「大日寺」の静かな境内で、二人並んで心を落ち着かせるお参り','緑豊かな木々に囲まれた落ち着いた佇まいの第4番札所「大日寺」へ足を運ぶ。静まり返った境内で、夫婦揃って並んでお線香とロウソクを奉納し、お経を唱える。日々の喧騒を離れ、二人だけの静かな時間を共有しながら心が穏やかに満たされていく贅沢なひとときを過ごす。','2027-10-01','12:30','🌿','0','',-500,1,false,'2027-10-01 13:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.116670000,134.433330000,'第5番札所「地蔵寺」の樹齢千年の大銀杏の下で、深まる秋の気配と歴史を感じる','境内にある圧倒的な大銀杏がシンボルとなっている第5番札所「地蔵寺」へ。歴史の重みを感じさせる厳かな境内で、お互いにこれまでの感謝の言葉をそっと交わしつつ、境内をゆっくりと散策しながら、夫婦の絆をさらに深める温かい時間をのんびりと楽しむ。','2027-10-01','14:00','🍂','0','',-500,1,false,'2027-10-01 14:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.110000000,134.398610000,'第6番札所「安楽寺」の美しい温泉湧出の歴史に触れ、旅の疲れを優しく癒やす','静かな山あいに佇む第6番札所「安楽寺」に到着し、お参りを済ませる。古くから温泉が湧き出たという境内のお寺の歴史に思いを馳せながら、ここまで歩んできた足の疲れを少しずつほぐし、明日からの長い道のりに向けて心身をしっかりとリラックスさせる。','2027-10-01','15:30','♨️','0','',-500,1,false,'2027-10-01 16:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957850000,130.941900000,'唐戸市場でフグ寿司','市場に入った瞬間、活気ある声と海鮮の香りが広がって「最高すぎる！」と全員のテンションが爆上がり。まずは名物のフグ寿司をゲット。プリッとした身が口の中でほどけて「え、これ本気でうまい」と4人で感動。市場の賑やかさとフグの旨味が相まって、旅の序盤から幸せが溢れた。','2026-11-03','10:00','🍣','0000','',-900,1,true,'2026-11-03 10:00:00+09','2026-08-02 02:38:00.798541+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.663330000,133.923890000,'4軒目：岡山の夜を彩る、瀬戸内海の新鮮な魚介と黄ニラなどのご当地グルメの晩餐','岡山の賑やかな繁華街にある人気の居酒屋に繰り出し、旅の夜を祝う豪華なディナータイム。瀬戸内海で獲れたピチピチのお造りや、岡山の名産である珍しい「黄ニラ」を使った絶品料理を味わい、美味しいお酒とともに最高に贅沢で楽しい夜を満喫する。','2027-11-13','18:30','🐟','0','',-4500,1,false,'2027-11-13 20:00:00+09','2026-08-02 01:37:59.550303+09'),
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.664720000,133.918890000,'翌日、駅ビルのお土産市場で、岡山名物の「きびだんご」やフルーツゼリーの総仕上げ','旅行最終日の2日目は、岡山駅ビルにある大きなお土産市場へと立ち寄る。パッケージも可愛い定番の「きびだんご」や、白桃やマスカットの贅沢なフルーツゼリーをカゴいっぱいに選び抜き、家族や友人への素敵なお土産の買い出しを完璧に済ませる。','2027-11-14','10:00','🎁','0','',-2500,1,false,'2027-11-14 10:45:00+09','2026-08-02 01:37:59.550303+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.666110000,133.918060000,'「JR岡山駅」に戻り、瀬戸内・岡山のたくさんの温かい思い出を胸に笑顔で帰路につく','すべての観光地巡りと美味しいグルメを大満足で終え、出発地点のJR岡山駅へと戻る。「後楽園も美観地区も、ご飯も全部最高だったね！」と満面の笑みで語り合いながら、素晴らしい思い出がぎっしり詰まった新幹線に乗り込んで帰路につく。','2027-11-14','11:30','👋','0','',0,1,false,'2027-11-14 12:15:00+09','2026-08-02 01:37:59.550303+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957144880,130.940744550,'下関駅前でお土産購入','駅前のショップでフグ関連のお土産を選びながら、今日の食べ歩きの思い出を振り返った。大学生4人の旅らしい賑やかな時間で、旅の終わりにふさわしい締めくくりとなった。','2026-11-03','17:00','🎁','0000','',-1600,1,false,'2026-11-03 17:00:00+09','2026-08-02 02:35:22.146541+09'),
	 (59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957414280,130.940354910,'旅の締め','駅前の広場で4人並んで記念撮影。下関の海と食文化、そしてフグの美味しさが強く印象に残る旅となった。「また来たい」と自然に言葉が出る、満足度の高い一日だった。','2026-11-03','17:20','🐡','0000','',0,1,false,'2026-11-03 17:20:00+09','2026-08-02 02:35:22.146541+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.594182040,130.643920898,'桜島港に到着','桜島港は静かで、火山の存在感がすぐ近くに感じられる。島の空気が独特で、歩くだけで楽しい。','2026-10-12','12:20','🌋','0000','',0,1,false,'2026-10-12 12:20:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.585833330,130.657777780,'烏島展望所へ','展望所からは桜島の荒々しい姿が見えて迫力満点。火山の力強さを感じる景色に圧倒される。','2026-10-12','13:00','🏔️','0000','',0,1,false,'2026-10-12 13:00:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.580833330,130.674444440,'湯之平展望所へ','桜島の中でも特に人気の展望所。山肌が近くに見えて、自然の迫力を感じる。写真映えするスポットが多い。','2026-10-12','13:40','📷','0000','',0,1,false,'2026-10-12 13:40:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.568333330,130.681111110,'桜島ビジターセンター','火山の歴史や噴火の資料が展示されていて興味深い。桜島の成り立ちを知ることで旅がより深くなる。','2026-10-12','14:10','🏛️','0000','',0,1,false,'2026-10-12 14:10:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.562154849,130.682287216,'桜島溶岩なぎさ公園','海沿いの足湯が気持ちよくて、旅の疲れが少し取れる。桜島を眺めながら入る足湯は特別な体験。','2026-10-12','14:40','🦶','0000','',0,1,false,'2026-10-12 14:40:00+09','2026-08-02 16:24:03.081396+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.586432176,130.644950867,'桜島港へ戻る','島の空気をたっぷり味わって港へ戻る。火山の迫力と穏やかな海の対比が印象的で、忘れられない景色になる。','2026-10-12','15:20','🌋','0000','',0,1,false,'2026-10-12 15:20:00+09','2026-08-02 16:24:03.081396+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.103890000,134.382220000,'第7番札所「十楽寺」の厳かな山門をくぐり、夫婦で心静かに合掌する','美しい山門が出迎えてくれる第7番札所「十楽寺」へ到着する。静寂に包まれた境内で、夫婦二人でゆっくりと階段を上がり、本尊に向かってこれまでの無事に感謝しつつ、これからの旅の安全と家族の健康を心を込めて祈りながら、丁寧にお参りをしっかりと行う。','2027-10-02','08:30','⛩️','0','',-500,1,false,'2027-10-02 09:15:00+09','2026-08-02 01:44:28.15501+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.229000000,135.167000000,'駅ナカでお土産選び','梅干しや和歌山限定のお菓子を購入。友達と盛り上がる。1200円。','2026-08-10','16:40','🤩','0','',-1200,1,false,'2026-08-10 16:42:00+09','2026-08-01 19:28:00.274263+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'夕食は駅ナカで','軽めの定食を食べてエネルギー補給。女子旅の締めにぴったり。980円。','2026-08-10','17:20','🙂','0','',-980,1,false,'2026-08-10 17:22:00+09','2026-08-01 19:28:00.274263+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'帰路へ','電車で今日の写真を見返して余韻に浸る。楽しい女子旅だった。','2026-08-10','18:00','🙂','0','',0,1,false,'2026-08-10 18:02:00+09','2026-08-01 19:28:00.274263+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.200000000,135.200000000,'阪和道 PAで最初の休憩とコーヒーブレイク','ドライブのスタート直後、サービスエリアに立ち寄ってリフレッシュ。これから始まる和歌山旅行への期待感が高まる。','2026-09-12','08:30','☕','0','',-600,1,false,'2026-09-12 08:35:12+09','2026-08-01 21:08:04.82446+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.100000000,134.341670000,'第8番札所「熊谷寺」の壮大な多宝塔を見上げ、歴史ある境内をしっとりとお散歩','見事な多宝塔や立派な仁王門が訪れる者を圧倒する第8番札所「熊谷寺」へ。緑豊かな境内を夫婦で並んで歩きながら、歴史ある建築美や季節の草花の美しさに目を奪われ、まるで時間がゆっくりと流れているような心地よい空間の中で穏やかなお参りを楽しむ。','2027-10-02','10:00','🏯','0','',-500,1,false,'2027-10-02 10:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.095000000,134.321110000,'第9番札所「法輪寺」の美しい庭園を眺め、お遍路の道中で心穏やかなひととき','落ち着いた雰囲気が漂う第9番札所「法輪寺」に到着。綺麗に手入れされた境内の庭園を夫婦二人で眺めながら、「ここまで順調に回れてよかったね」と優しく声を掛け合い、これまでの疲れを癒やしながら静かに手を合わせてお参りを済ませる。','2027-10-02','11:30','🌸','0','',-500,1,false,'2027-10-02 12:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.075000000,134.316670000,'第10番札所「切幡寺」の長い石段を二人で励まし合いながら一段ずつ登る','境内へと続く数百段の長い石段を前にして、夫婦で顔を見合わせながら気合を入れ直して登り始める。「一歩ずつゆっくり行こうね」と声を掛け合いながら励まし合って登り切り、達成感に包まれながら素晴らしい景色が広がる本堂でお参りを行う。','2027-10-02','13:00','🧗','0','',-500,1,false,'2027-10-02 13:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.027780000,134.238890000,'第12番札所「焼山寺」へ至至難の山道を車で慎重に登り、深い歴史と自然の神秘に感動','険しい山道を車で慎重に進み、難所として知られる第12番札所「焼山寺」の境内へ到着する。古い杉木立に囲まれた神秘的な雰囲気に包まれた本堂で、無事にたどり着けたことに心から感謝しながら、夫婦二人で深く頭を下げて丁寧にお参りをする。','2027-10-03','09:00','🚗','0','',-500,1,false,'2027-10-03 10:00:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.072220000,134.425000000,'第13番札所「大日寺」の穏やかな境内で、これまでの道中を振り返る','徳島市内の静かな住宅街と自然が調和する第13番札所「大日寺」へと到着する。ここまで順調に巡ってきたお遍路の旅を振り返りながら、「だんだんお参りの作法にも慣れてきたね」と夫婦で笑顔で語り合い、本堂に向かって静かに合掌する。','2027-10-03','11:00','🕊️','0','',-500,1,false,'2027-10-03 11:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.070000000,134.441670000,'第14番札所「常楽寺」で美しい庭園と静寂に包まれ、心洗われるお参り','美しい庭園と穏やかな空気が流れる第14番札所「常楽寺」へ。心地よい風が吹く境内で、夫婦揃って静かにお線香をあげ、日々の平穏とこれからの旅の無事を祈願する。二人で並んで過ごす時間が何よりも贅沢に感じられる素晴らしいひとときとなる。','2027-10-03','12:30','🍀','0','',-500,1,false,'2027-10-03 13:15:00+09','2026-08-02 01:44:28.15501+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.062500000,134.444440000,'第15番札所「国分寺」の歴史ある境内を歩き、阿波国の古刹の重みを感じ取る','阿波国分寺として長い歴史を誇る第15番札所「国分寺」へ到着する。落ち着いた佇まいの境内をゆっくりと歩きながら、古代から続くお寺の歴史の深さに思いを馳せ、夫婦二人でいつまでも健康で仲良く暮らせることを願いながら丁寧にお参りを行う。','2027-10-03','14:00','🏮','0','',-500,1,false,'2027-10-03 14:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.043330000,134.455000000,'第16番札所「観音寺」の温かい雰囲気に迎えられ、旅の疲れを優しく癒やす','アットホームで温かい雰囲気が漂う第16番札所「観音寺」へ到着する。境内を吹き抜ける爽やかな風を感じながら、夫婦二人でお互いの体調を気遣い合い、ここまで元気に歩けていることに感謝しながら心を込めてお参りを済ませる。','2027-10-03','15:30','☕','0','',-500,1,false,'2027-10-03 16:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.020560000,134.458330000,'第17番札所「井戸寺」の不思議な「お加持水」の伝説に夫婦で静かに感動する','境内に湧き出る井戸の伝説が残る第17番札所「井戸寺」へ。水面に自分の姿を映して吉凶を占ったという歴史ある井戸を覗き込みながら、神秘的な伝説に夫婦で感心し、本堂の前でこれからの道中の安全をしっかりと祈願する。','2027-10-04','08:30','🔮','0','',-500,1,false,'2027-10-04 09:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.978330000,134.461110000,'第18番札所「恩山寺」の急な山道を二人で支え合いながら登り切り、境内で一息','源義経の母にまつわる悲話が残る歴史的な第18番札所「恩山寺」の山門へと到着する。少し急な坂道を二人で声を掛け合いながら登り切ったあと、本堂の前で心地よい達成感に浸りながら、夫婦揃ってゆっくりと深呼吸をして休憩する。','2027-10-04','10:00','⛰️','0','',-500,1,false,'2027-10-04 10:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (5,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.123400000,142.351200000,'富良野のチーズ工房に立ち寄り','「お土産くらい買っていくか」とノリでチーズ工房へ。色んな種類の試食を片っ端から試して、一番美味しかったスモークチーズをみんなでお揃いで購入する。','2026-06-11','09:00','🧀','0','',-1200,1,false,'2026-06-11 09:04:40.5+09','2026-08-01 10:04:29.495627+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226000000,135.167500000,'和歌山城の天守閣と豊かな緑を散策','歴史ある和歌山城へ。天守閣からの眺めが素晴らしく、青空の下で城内の石垣や庭園を家族でのんびり歩いた。','2026-09-12','09:45','🏯','0','',-800,1,false,'2026-09-12 10:00:00+09','2026-08-01 21:08:04.82446+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.700500000,135.358200000,'黒潮市場で新鮮な海の幸ランチを満喫','紀州黒潮市場に到着。マグロの解体ショーを家族で間近で見学し、その場で買った海鮮丼やお寿司をみんなでシェアして食べた。','2026-09-12','12:00','🍣','0','',-4500,1,false,'2026-09-12 12:30:00+09','2026-08-01 21:08:04.82446+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.692200000,135.335100000,'アドベンチャーワールドでパンダに癒やされる','大人気のジャイアントパンダやたくさんの動物たちを見学。サファリワールドを車で回ったり、イルカショーを見て家族みんなが大はしゃぎ。','2026-09-12','14:00','🐼','0','',-12000,1,false,'2026-09-12 14:30:00+09','2026-08-01 21:08:04.82446+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.682300000,135.333100000,'千畳敷のダイナミックな景観に感動','波の浸食によってできた壮大な岩畳を見学。太平洋の水平線が広がり、夕暮れ時の景色が言葉を失うほど美しかった。','2026-09-12','17:30','🌅','0','',0,1,false,'2026-09-12 18:00:00+09','2026-08-01 21:08:04.82446+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.959308210,134.566040039,'第20番札所「鶴林寺」の険しい山深い杉木立の中を登り、圧倒的な自然美に浸る','標高の高い山奥に位置する難所の一つ、第20番札所「鶴林寺」へ車で慎重にアクセスする。古い杉木立に囲まれた荘厳な境内に足を踏み入れると、外界から切り離されたような圧倒的な静寂と自然の美しさに夫婦二人で深く感動する。','2027-10-04','13:30','🌲','0','',-500,1,false,'2027-10-04 14:15:00+09','2026-08-02 01:44:28.15501+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.916670000,134.577780000,'第21番札所「太龍寺」へロープウェイで空中散歩しながら、壮大な山岳霊場へ','西の高野山とも呼ばれる霊峰に位置する第21番札所「太龍寺」へ向かうためロープウェイに乗車する。空中から見下ろす壮大な山々の景色に「すごい絶景だね！」と夫婦で大興奮しながら、山上の荘厳な境内へと降り立って厳かにお参りする。','2027-10-05','09:00','🚠','0','',-2500,1,false,'2027-10-05 10:00:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.844440000,134.552780000,'第22番札所「平等寺」の清らかな湧き水に癒やされ、心身をリフレッシュする','美しい自然に囲まれた静かな第22番札所「平等寺」へと到着する。境内にある清らかな湧き水の手水舎でしっかりと身を清め、ここまで巡ってきた旅の疲れを心地よく癒やしながら、本堂の前で夫婦二人で穏やかに手を合わせる。','2027-10-05','11:00','💧','0','',-500,1,false,'2027-10-05 11:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.822220000,134.333330000,'第23番札所「薬王寺」に到着し、厄除けの階段を夫婦揃って一段ずつ慎重に登る','徳島県最後の札所であり、厄除けの寺として名高い第23番札所「薬王寺」へ。男女それぞれの厄坂と呼ばれる階段があり、「お互い健康で元気にここまで来られてよかったね」と話し合いながら、一段一段を大切に踏みしめて登り切る。','2027-10-05','13:30','⛩️','0','',-500,1,false,'2027-10-05 14:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.722220000,134.250000000,'徳島県から高知県へ！「最御崎寺」へと続く室戸岬の雄大な海岸線をドライブ','ついに徳島県を抜けて高知県へと突入し、太平洋の荒波が打ち寄せる室戸岬の絶景ロードをレンタカーで爽快に走る。車窓から広がるどこまでも青い海のパノラマに「いよいよ土佐に入ったね！」と夫婦で旅の盛り上がりを喜び合う。','2027-10-06','09:00','🌊','0','',0,1,false,'2027-10-06 09:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.719440000,134.175000000,'第24番札所「最御崎寺」の亜熱帯植物が広がる境内で、太平洋の絶景を眺める','室戸岬の先端近くの山上に位置する第24番札所「最御崎寺」へ到着する。境内を覆う珍しい亜熱帯植物の緑と、目の前に広がる真っ青な太平洋のコントラストが素晴らしく、荒波の音を聞きながら夫婦二人で雄大な景色に感動して手を合わせる。','2027-10-06','10:30','🌴','0','',-500,1,false,'2027-10-06 11:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.583330000,134.163890000,'第25番札所「津照寺」の港町を見下ろす高台の境内で、穏やかな海風を感じる','港町を一望する高台に佇む第25番札所「津照寺」へ。まるで船の形をした境内へと続く階段を登りながら、眼下に広がる穏やかな漁港の景色を眺め、海風を心地よく感じつつ、夫婦二人でゆっくりとお参りを済ませて次の目的地へと向かう。','2027-10-06','13:00','⚓','0','',-500,1,false,'2027-10-06 13:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.511110000,134.177780000,'第26番札所「金剛頂寺」の深い樹林に包まれた静寂の境内で、心を一つにしてお参り','豊かな自然林にすっぽりと包まれた第26番札所「金剛頂寺」の厳かな境内へ。木漏れ日が差し込む静かな参道を夫婦で並んでゆっくりと歩き、これまでの長旅の安全と無事に感謝を捧げながら、本堂の前で静かに心を一つにして合掌する。','2027-10-06','15:00','🌲','0','',-500,1,false,'2027-10-06 15:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.366670000,134.025000000,'第27番札所「神峯寺」の急な山道を登り切り、高知の海と空の大パノラマに息を呑む','「土佐の修行の道場」の険しい山道を登りきった先にある第27番札所「神峯寺」へ到着する。苦労して登った境内の展望が開けた場所から見渡す高知の海と空の大パノラマに、「本当にここまで頑張って来てよかったね」と夫婦で感動の涙ぐむ。','2027-10-07','10:00','⛰️','0','',-500,1,false,'2027-10-07 10:45:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.561110000,133.530560000,'高知市内の名店で、名物の「カツオの藁焼きタタキ」を夫婦で囲んで絶品の晩餐','お遍路の道中を一休みし、高知市内の活気ある名店へと繰り出して夕食タイム。香ばしい藁の香りがたまらない名物の「カツオの藁焼きタタキ」を厚切りで頬張り、「やっぱり本場の味は格別だね！」と地酒を少し傾けながら最高に幸せな夫婦の時間を満喫する。','2027-10-07','18:30','🐟','0','',-4500,1,false,'2027-10-07 20:00:00+09','2026-08-02 01:44:28.15501+09'),
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.591110000,133.560000000,'「高知駅」周辺の快適なホテルで一日の旅の疲れを癒やし、明日からの道のりへ英気を養う','快適なホテルのお部屋に戻り、今日巡ったたくさんの素晴らしい寺院や美しい景色の思い出をアルバムのように振り返る。「明日からも二人でゆっくり頑張ろうね」と優しく微笑み合いながら、心地よいベッドでしっかりと体を休めて明日への英気を養う。','2027-10-07','21:00','🏨','0','',-14000,1,false,'2027-10-07 21:45:00+09','2026-08-02 01:44:28.15501+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.945638453,134.515914917,'第19番札所「立江寺」で「関所寺」の厳かな雰囲気に触れ、身を引き締めてお参り','悪人を裁く関所であったという「関所寺」として知られる第19番札所「立江寺」へ。身が引き締まるような厳かな空気が漂う境内で、夫婦二人でこれまでの言動を静かに振り返り、清らかな気持ちで本堂に向かって丁寧にお参りをする。','2027-10-04','11:30','🛡️','0','',-500,1,false,'2027-10-04 12:15:00+09','2026-08-02 01:44:28.15501+09'),
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.593670276,130.605640411,'桜島へ渡るフェリー','フェリーから見る桜島は迫力があり、海の上を進む感覚が楽しい。写真を撮りながら景色を楽しむ。','2026-10-12','12:00','🌊','0000','',-200,1,false,'2026-10-12 12:00:00+09','2026-08-02 16:24:03.081396+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957850000,130.941900000,'フグ唐揚げを食べる','次はフグの唐揚げ。揚げたての香りがふわっと広がって、ひと口食べた瞬間「これ優勝やろ」と全員が叫んだ。外はカリッ、中はふわっとしていて、大学生4人のテンションが完全に最高潮。市場のベンチで海を眺めながら食べる時間が最高すぎた。','2026-11-03','10:40','🍗','0000','',-700,1,true,'2026-11-03 10:40:00+09','2026-08-02 02:38:00.798541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957850000,130.941900000,'フグ汁でほっと一息','市場の一角でフグ汁を注文。湯気の向こうから漂う香りがやさしくて、ひと口飲むと体の奥までじんわり染みる。「これ、朝から食べ歩きしてる体に効くわ」と友達が言い、みんなで頷きながらゆっくり味わった。市場の喧騒の中でほっと落ち着く時間になった。','2026-11-03','11:10','🍲','0000','',-600,1,true,'2026-11-03 11:10:00+09','2026-08-02 02:38:00.798541+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957850000,130.941900000,'市場で食べ歩き続行','フグ以外にも海鮮が豊富で、4人で「これも食べたい」「いやこっちも！」と大騒ぎ。結局フグ以外にもサーモンやウニをつまみながら、大学生らしい勢いで食べ歩きを満喫。市場の賑やかさに包まれながら、笑い声が止まらない時間になった。','2026-11-03','11:40','🦀','0000','',-1200,1,true,'2026-11-03 11:40:00+09','2026-08-02 02:38:00.798541+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676842110,131.792544880,'空港に戻り旅の締め','空港に戻ると、朝と同じ静かな空気が広がっていた。山と海を歩いた一日を思い返すと、派手さはないが心が落ち着く旅だったと感じる。石見の自然は素朴で、ゆっくり過ごす旅にぴったりだった。','2026-10-20','17:10','🛫','0000','',0,1,false,'2026-10-20 17:10:00+09','2026-08-02 02:49:26.637117+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.669217363,131.800231934,'空港北側の山道を散策','空港北側には小さな山道があり、歩き始めると木々の香りがふわっと広がった。舗装されていない道だが、鳥の声や風の音が心地よく、自然の中を歩く楽しさがある。観光地ではないが、静けさを求める旅にはぴったりの場所だった。','2026-10-20','10:20','🌲','0000','',0,1,false,'2026-10-20 10:20:00+09','2026-08-02 02:50:33.488346+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.692791545,131.821689606,'山の稜線から日本海を望む','山道をさらに進むと稜線に出て、日本海が遠くに見えた。荒々しい海の青さと山の緑が対照的で、石見らしい風景が広がる。観光地ではないが、こうした自然の景色が旅の印象を強くしてくれる。しばらく風を感じながら景色を眺めた。','2026-10-20','11:00','🌄','0000','',0,1,false,'2026-10-20 11:00:00+09','2026-08-02 02:50:41.060444+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.698860457,131.846752167,'山の麓の小さな神社を参拝','山を下る途中に小さな神社があり、苔むした鳥居が静かに佇んでいた。地元の人が守ってきた場所らしく、派手さはないが落ち着いた空気が流れている。旅の途中でこうした場所に出会うと、自然と気持ちが整う。','2026-10-20','11:40','⛩️','0000','',0,1,false,'2026-10-20 11:40:00+09','2026-08-02 02:50:50.11902+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.712831377,131.858940125,'山里の集落を歩く','山の麓には小さな集落があり、古い家屋が並んでいた。人の気配は少ないが、静かな生活の空気が感じられる。道端には季節の花が咲き、歩くだけで心が落ち着く。観光地ではないが、石見の素朴さがよく伝わる場所だった。','2026-10-20','12:20','🏡','0000','',0,1,false,'2026-10-20 12:20:00+09','2026-08-02 02:50:58.275774+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.718898820,131.866493225,'日本海側へ向かう山道を走る','集落を抜けて海へ向かう山道を歩くと、道の両側に広がる木々が風に揺れ、自然の音だけが響いていた。車通りもほとんどなく、石見の静けさを存分に味わえる。海が近づくにつれ、潮の香りが少しずつ混じってきた。','2026-10-20','13:00','🚶','0000','',0,1,false,'2026-10-20 13:00:00+09','2026-08-02 02:51:05.863725+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.757268605,131.871814728,'海沿いの小さな漁港を散策','海岸線を歩くと小さな漁港があり、漁船が静かに並んでいた。人の姿は少ないが、港特有のゆったりした空気が流れている。海風が心地よく、旅の途中の散策として最適だった。石見の素朴な海の暮らしを感じられる場所だった。','2026-10-20','14:10','⚓','0000','',0,1,false,'2026-10-20 14:10:00+09','2026-08-02 02:51:21.616115+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.757268605,131.877822876,'海沿いの展望地で休憩','漁港から少し歩くと小さな展望地があり、日本海が広く見渡せた。波の音が絶えず響き、風が強く吹き抜ける。観光地ではないが、石見の海の力強さを感じられる場所で、旅の印象を深めてくれた。','2026-10-20','14:40','🌅','0000','',0,1,false,'2026-10-20 14:40:00+09','2026-08-02 02:51:31.092418+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226000000,135.167500000,'阪和道を南下して和歌山市内を出発','家族みんなで車に乗り込み、和歌山に向けてドライブ出発！車内では好きな音楽をかけながら、わいわい楽しい雰囲気でスタート。','2026-09-12','08:30','🚗','0','',0,1,true,'2026-09-12 08:35:12+09','2026-08-01 21:05:34.850528+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.749934582,131.893787384,'海沿いの食堂で昼食','海沿いの小さな食堂に入り、地元の魚を使った定食をいただく。派手さはないが、丁寧に作られた味で体がほっと落ち着いた。窓から見える海の景色が心地よく、旅の途中の食事として最適だった。','2026-10-20','15:10','🚶','0000','',-1200,1,false,'2026-10-20 15:10:00+09','2026-08-02 02:51:37.704966+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.742882023,131.909065247,'山へ戻る道を歩く','海から山へ戻る道は静かで、風の音と鳥の声だけが響いていた。自然の中を歩く時間が長くなるほど、石見の素朴さが心に染みてくる。観光地ではないが、こうした静けさが旅の魅力になった。','2026-10-20','16:40','🌲','0000','',0,1,false,'2026-10-20 16:40:00+09','2026-08-02 02:51:47.571799+09'),
	 (61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.764742996,131.907691956,'海岸線をゆっくり歩く','昼食後、海岸線をゆっくり歩くと、風が少し弱まり、海の音がよりはっきり聞こえるようになった。岩場に打ち寄せる波を眺めながら歩く時間は、石見の自然を深く感じられる瞬間だった。','2026-10-20','15:40','🤩','0000','',0,1,false,'2026-10-20 15:40:00+09','2026-08-02 02:52:51.932522+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371240000,131.182760000,'長門市駅に到着','長門市駅に着くと、静かな港町らしい穏やかな空気が広がっていた。駅前で自転車を整えながら今日のルートを確認し、まずは仙崎方面へ向かうことにした。山と海が近い土地ならではの風が心地よく、サイクリング旅の始まりとして気持ちが引き締まる。観光地の喧騒とは無縁の、長門らしいゆったりした空気が流れていた。','2026-10-18','09:10','🚴','0000','',0,1,false,'2026-10-18 09:10:00+09','2026-10-18 09:10:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.406059882,131.207141876,'青海島・海岸線を走る','島の海岸線は変化に富んだ岩場が続き、走るたびに景色が変わる。断崖の上を走る区間では海が真下に広がり、風が強くて少し緊張するが、その分だけ達成感がある。観光地のような整備は少ないが、自然の迫力をそのまま感じられる道だった。','2026-10-18','10:40','🚴','0000','',0,1,false,'2026-10-18 10:40:00+09','2026-08-02 02:59:57.353561+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.403510505,131.200447083,'青海島入口に到着','仙崎から橋を渡ると青海島の入口に到着。海上アルプスと呼ばれる島らしく、遠くに見える岩肌が迫力を感じさせる。ここからは海沿いの道が続き、景色が一気に変わる。自転車で走ると風が強くなるが、その分だけ海の存在が近く感じられた。','2026-10-18','10:10','🌊','0000','',0,1,false,'2026-10-18 10:10:00+09','2026-08-02 03:01:01.596075+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.388460521,131.202464104,'仙崎港を走る','駅から北へ走ると仙崎港に入り、海の香りがふわっと漂ってきた。漁船が並ぶ港を横目に走ると、地元の生活の気配が感じられ、観光地とは違う素朴な魅力があった。道は平坦で走りやすく、海風が背中を押してくれるようだった。','2026-10-18','09:40','⚓','0000','',0,1,false,'2026-10-18 09:40:00+09','2026-08-02 03:01:46.164238+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.802686240,132.855767012,'三次駅に到着','三次駅に降り立つと、広島県北部らしい穏やかな空気が流れていた。駅前は静かで歩きやすく、ゆっくり旅を始めるにはちょうどよい雰囲気。まずは周辺を軽く散策しながら、今日の行き先を確認。遠くに見える山並みがやわらかく、都会の喧騒から離れた落ち着いた旅になりそうだと感じた。','2026-10-22','09:10','🚉','0000','',0,1,true,'2026-10-22 09:10:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.803540776,132.853814363,'三次本通り商店街を散策','駅からほど近い本通り商店街は昔ながらの店が並び、ゆっくり歩くとどこか懐かしい気持ちになる。お年寄りでも歩きやすい平坦な道で、地元の人の挨拶が心地よい。小さな和菓子店に立ち寄ると、優しい味の饅頭が旅の始まりを彩ってくれた。','2026-10-22','09:40','🍡','0000','',-300,1,true,'2026-10-22 09:40:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.806144000,132.857944000,'三次もののけミュージアム前','三次の新しい名所であるミュージアム前は広い歩道が整備されており、休憩ベンチも多い。館内に入らなくても周辺の散策だけで十分楽しめる。川沿いの風が心地よく、ゆっくり歩く旅にぴったりの場所だった。','2026-10-22','10:10','🏛️','0000','',0,1,true,'2026-10-22 10:10:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.810702667,132.856872082,'馬洗川沿いをゆっくり散歩','馬洗川沿いの遊歩道は平坦で歩きやすく、川の流れを眺めながらゆっくり進める。水面に映る空が美しく、心が落ち着く時間が流れる。途中にあるベンチでひと休みしながら、三次らしい穏やかな風景を楽しんだ。','2026-10-22','10:40','🌿','0000','',0,1,true,'2026-10-22 10:40:00+09','2026-08-02 07:05:41.107381+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.383810000,131.193310000,'仙崎の食堂で昼食','港町の食堂に入り、地元の魚を使った定食をいただく。派手さはないが、丁寧に作られた味で体がほっと落ち着いた。窓から見える港の景色が心地よく、サイクリングの途中の食事として最適だった。','2026-10-18','13:10','🤩','0000','',-1200,1,false,'2026-10-18 13:10:00+09','2026-10-18 13:10:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.380310000,131.189980000,'仙崎の海沿いをゆっくり走る','昼食後、海沿いの道をゆっくり走ると、風が心地よく、港町らしい穏やかな景色が広がっていた。自転車の速度を落として走ると、海の音がよりはっきり聞こえ、旅の中でも特に落ち着く時間となった。','2026-10-18','13:40','🌊','0000','',0,1,false,'2026-10-18 13:40:00+09','2026-10-18 13:40:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.374810000,131.184310000,'長門市街へ戻る道を走る','仙崎から長門市街へ戻る道は緩やかな坂が続き、海から山へ景色が変わっていく。風が少し強くなるが、走るほどに体が軽くなるような感覚があった。町が近づくにつれ、旅の終わりが見えてくる。','2026-10-18','14:10','🚴','0000','',0,1,false,'2026-10-18 14:10:00+09','2026-10-18 14:10:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371810000,131.182310000,'長門市街のカフェで休憩','市街地のカフェに入り、冷たい飲み物で体を落ち着かせる。サイクリングの疲れがすっと抜けていき、旅の途中の休憩として最適だった。窓から見える町の景色が穏やかで、青海島の迫力との対比が印象的だった。','2026-10-18','14:40','🤩','0000','',-700,1,false,'2026-10-18 14:40:00+09','2026-10-18 14:40:00+09'),
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668900000,135.501300000,'道頓堀・グリコサイン前','人の多さに圧倒されつつも、やっぱり大阪といえばここへ来ないと始まらない。橋の上から川沿いの派手な看板を眺める。観光客の熱気がすごくて、ちょっと圧倒されつつ記念撮影。','2026-08-01','16:00','😀','0','',0,1,false,'2026-08-01 16:02:10.8+09','2026-08-01 09:28:00.797366+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.672000000,135.498000000,'アメリカ村の路地裏','道頓堀の喧騒から少し離れて、アメ村の古着屋さんやストリートを散策。歩き疲れて足がパンパンになってきた。おしゃれなカフェを探して、ちょっと細い路地を入ったり迷ったりする。','2026-08-01','17:30','😌','0','',0,0,false,'2026-08-01 17:33:20.15+09','2026-08-01 09:28:00.797366+09'),
	 (1,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.671500000,135.495000000,'隠れ家カフェでひと休み','見つけた小さな喫茶店でアイスコーヒーとチーズケーキを注文。静かな店内で、今日撮った写真を見返しながらスマホをいじる。ようやく一息つけて、歩き疲れた身体が生き返る感覚。','2026-08-01','18:00','☕','0','',-850,1,false,'2026-08-01 18:05:00+09','2026-08-01 09:28:00.797366+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632900000,139.880000000,'舞浜駅に到着！いざ夢の国へ','朝早くから電車を乗り継いで、ついに舞浜駅に到着！子どもたちも「ディズニーだ！」と大はしゃぎで、一気にテンションがマックスに。ワクワクが止まらない。','2026-08-05','08:30','🤩','0','',0,1,false,'2026-08-05 08:32:15.1+09','2026-08-01 16:41:55.293734+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.598414848,135.943450928,'舞浜駅に到着！いざ夢の国へ','朝早くから新幹線と電車を乗り継いで、ついに舞浜駅に到着！子どもたちも「ディズニーだ！」と大はしゃぎで、一気にテンションがマックスに。ワクワクが止まらない。','2026-08-05','08:30','🤩','0','',0,1,true,'2026-08-05 08:32:15.1+09','2026-08-01 16:43:46.307334+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632300000,139.880400000,'東京ディズニーランド・エントランス','手荷物検査を抜けて、ついにワールドバザールへ！お馴染みの音楽とシンデレラ城が見えてきて大人も胸が熱くなる。まずはポップコーンバケットをゲットしに行こう！','2026-08-05','09:00','✨','0','',-3400,1,true,'2026-08-05 09:05:20.2+09','2026-08-01 16:43:46.307334+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.370210000,131.180810000,'長門市街をゆっくり走る','休憩後、市街地をゆっくり走ると、地元の生活の気配が感じられ、旅の終盤らしい落ち着いた時間が流れた。観光地ではないが、町の静けさが心地よく、サイクリング旅の締めにふさわしい時間となった。','2026-10-18','15:10','🚴','0000','',0,1,false,'2026-10-18 15:10:00+09','2026-10-18 15:10:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371240000,131.182760000,'長門市駅前でお土産購入','駅前の店で地元の海産物を使ったお土産を選びながら、今日のサイクリングを振り返る。青海島の迫力ある景色と仙崎の穏やかな港町が印象に残り、長門らしい旅になったと感じた。','2026-10-18','15:40','🎁','0000','',-1500,1,false,'2026-10-18 15:40:00+09','2026-10-18 15:40:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371240000,131.182760000,'旅の締め','駅前で自転車を返却し、深呼吸すると長門の静かな空気が胸に広がった。青海島の自然と港町の穏やかさを感じられる、満足度の高いサイクリング旅となった。','2026-10-18','16:00','🌅','0000','',0,1,false,'2026-10-18 16:00:00+09','2026-10-18 16:00:00+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.430275082,131.246452332,'青海島・岩場の絶景ポイント','遊歩道を進むと岩場の絶景ポイントに出た。海の青さと岩肌の迫力が目の前に広がり、写真を撮る手が止まらない。観光地のような案内はないが、自然そのままの景色が旅の印象を強くしてくれる。','2026-10-18','12:10','🌄','0000','',0,1,false,'2026-10-18 12:10:00+09','2026-08-02 02:59:36.769242+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.425177728,131.218471527,'青海島・遊歩道入口','展望地から少し走ると遊歩道の入口があり、自転車を置いて歩くことにした。木々に囲まれた道は静かで、鳥の声が響く。海岸線の迫力とは違う、青海島の穏やかな一面が感じられた。','2026-10-18','11:40','🌿','0000','',0,1,false,'2026-10-18 11:40:00+09','2026-08-02 02:59:43.665223+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.424469737,131.212635040,'青海島・千畳敷展望地','海岸線を進むと小さな展望地があり、岩場と海が一望できた。波が岩にぶつかる音が響き、自然の力強さを感じる。自転車を止めてしばらく景色を眺めると、旅の中でも特に印象に残る時間となった。','2026-10-18','11:10','📸','0000','',0,1,false,'2026-10-18 11:10:00+09','2026-08-02 02:59:50.532657+09'),
	 (62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.412008124,131.178131104,'仙崎へ戻る道を走る','島内を巡ったあと仙崎へ戻る道を走ると、海風が少し弱まり、走りやすくなった。港町が近づくにつれ、生活の気配が戻ってくる。自然の迫力を感じた後に町へ戻ると、旅の流れに心地よい緩急が生まれた。','2026-10-18','12:40','🚴','0000','',0,1,false,'2026-10-18 12:40:00+09','2026-08-02 03:00:10.6572+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.634800000,139.881200000,'ホーンテッドマンションでドキドキ体験','少し涼を求めてホーンテッドマンションへ。不気味だけどユーモラスな世界観に、子どもたちは怖がりつつも目をキラキラさせて楽しんでいた。','2026-08-05','13:40','👻','1','',0,1,true,'2026-08-05 13:45:15.3+09','2026-08-01 16:43:46.307334+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.635500000,139.882500000,'ファンタジーランドでアトラクション満喫','ピーターパンやダンボを乗り継ぎ。待ち時間が長くて後半は子どもたちの足が疲れてぐずり出し、なだめるのが大変だった。親の体力も限界に近づく…。','2026-08-05','15:30','😫','2','',0,-1,true,'2026-08-05 15:35:50.8+09','2026-08-01 16:43:46.307334+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633800000,139.883000000,'トゥーンタウンで可愛いチュロス休憩','甘い香りに誘われてミッキーチュロスを購入。可愛い見た目とサクサクの食感に、疲れが一気に吹き飛んだ！記念に家族みんなでパシャリ。','2026-08-05','17:00','😋','0','',-1600,1,true,'2026-08-05 17:05:10.2+09','2026-08-01 16:43:46.307334+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632500000,139.881000000,'シンデレラ城前でパレード鑑賞','夕暮れのシンデレラ城をバックに、大迫力のナイトパレードを鑑賞。光り輝くフロートとキャラクターの笑顔に、家族全員で感動の嵐。','2026-08-05','19:00','🎆','0','',0,1,true,'2026-08-05 19:05:22.4+09','2026-08-01 16:43:46.307334+09'),
	 (29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'和歌山駅に到着','大阪から電車で和歌山駅へ。友達と「女子旅スタート！」と写真撮影。カフェで朝食600円。','2026-08-10','09:20','🙂','0','',-600,1,false,'2026-08-10 09:22:00+09','2026-08-01 19:28:00.274263+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680300000,135.788100000,'法隆寺で世界最古の木造建築群を見学','翌朝は少し足を延ばして斑鳩町の法隆寺へ。飛鳥時代の息吹を感じさせる五重塔や金堂の建築美をじっくり見学する。','2026-07-02','09:30','🏛️','0','',-1500,10,true,'2026-07-02 09:35:50.8+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.629500000,135.717500000,'日本最古の神社・大神神社を参拝','三輪山の麓にある日本最古の神社「大神神社」へ。厳かな空気が漂う境内で、神聖なパワーを感じる。','2026-07-02','11:15','⛩️','0','',0,11,true,'2026-07-02 11:20:10.1+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.630000000,135.718000000,'三輪そうめんの老舗で名物ランチ','大神神社の近くで、本場の「三輪そうめん」をいただく。冷たくてコシのある喉ごし抜群のそうめんに大満足。','2026-07-02','12:30','🍜','0','',-1100,12,true,'2026-07-02 12:35:00+09','2026-08-01 17:15:34.285211+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685000000,135.835000000,'奈良町（ならまち）のレトロな街並みを散策','再び市内へ戻り、江戸時代の町家が残る「ならまち」へ。おしゃれな雑貨店やギャラリーを覗きながらのんびり歩く。','2026-07-02','14:30','🏡','0','',0,13,true,'2026-07-02 14:35:00+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.684000000,135.834000000,'老舗和菓子店で甘味休憩','ならまちの散策途中に見つけた老舗の和菓子店へ。できたての和菓子とお抹茶をいただきながら、旅の思い出を振り返る。','2026-07-02','15:45','🍵','0','',-800,14,true,'2026-07-02 15:50:22.4+09','2026-08-01 17:15:34.285211+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.832900000,'近鉄奈良駅から帰路へ','（※経由地として記録）たくさんの思い出とお土産をカバンに詰め込んで帰路につく。','2026-07-02','16:30','👋','0','',0,16,true,'2026-07-02 16:35:05.1+09','2026-08-01 19:03:48.822924+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.700000000,135.500000000,'新大阪駅で旅の締めくくりに一杯','新大阪駅に到着後、新幹線の出発まで少し時間があったので、駅構内の立ち飲み屋で奈良の旅を振り返りながらビールを一杯。','2026-07-02','19:30','🍻','0','',-800,17,true,'2026-07-02 19:35:00+09','2026-08-01 19:03:48.822924+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.805000000,'奈良駅に到着','新幹線と在来線を乗り継ぎ奈良駅へ。駅前の落ち着いた雰囲気に旅の期待が高まる。コーヒーを飲んでひと息つき450円。','2026-08-02','09:10','🙂','0000','',-450,1,false,'2026-08-02 09:12:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685300000,135.839900000,'奈良公園で鹿と遭遇','鹿せんべいを買って鹿と触れ合う。少し追いかけられて焦ったが楽しい時間。鹿せんべい200円。','2026-08-02','10:05','🤩','0000','',-200,1,false,'2026-08-02 10:06:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.688400000,135.839400000,'東大寺大仏殿の圧巻','大仏の迫力に思わず息をのむ。拝観料600円。静かな空気に心が落ち着いた。','2026-08-02','11:20','🙂','0000','',-600,1,false,'2026-08-02 11:22:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681400000,135.839000000,'二月堂への坂道','坂道が思ったより急で汗が噴き出す。景色は美しいが体力が少し削られた。','2026-08-02','12:05','😅','0000','',0,0,false,'2026-08-02 12:06:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676900000,135.832800000,'ならまちで昼食','古民家カフェでランチ。落ち着いた空間で疲れが癒えた。ランチ1280円。','2026-08-02','13:00','🙂','0000','',-1280,1,false,'2026-08-02 13:02:00+09','2026-08-01 19:13:30.384146+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676000000,135.829000000,'ならまち散策','細い路地を歩きながら雑貨屋を巡る。気に入った小物を購入して900円。','2026-08-02','14:10','🙂','0000','',-900,1,false,'2026-08-02 14:12:00+09','2026-08-01 19:13:30.384146+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.011800000,135.677000000,'古民家風の朝カフェでコーヒー','歩き出す前に、駅近くの小さなカフェで温かいカフェラテをテイクアウトした。<br>香ばしいコーヒーの香りに癒やされながら、並んで歩き始める。<br>朝の静かな街並みがとても心地よい。','2026-09-12','09:50','☕','0','',-900,1,false,'2026-09-12 09:53:40.5+09','2026-08-01 09:43:49.952679+09'),
	 (28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.683800000,135.804900000,'興福寺で静かな時間','五重塔を眺めながら休憩。観光客は多いが境内は落ち着いている。拝観料700円。','2026-08-02','15:00','🙂','0000','',-700,1,false,'2026-08-02 15:02:00+09','2026-08-01 19:13:30.384146+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728908305,135.354995728,'黒潮市場で新鮮な海の幸ランチ','紀州黒潮市場に到着。マグロの解体ショーを家族で間近で見学し、その場で買った海鮮丼やお寿司をみんなでシェアして食べた。','2026-09-12','12:00','🍣','0','',-4500,1,true,'2026-09-12 12:30:00+09','2026-08-01 21:05:34.850528+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.813544000,132.865744000,'三次の小さな神社を参拝','川沿いにある小さな神社は段差が少なく、お年寄りでも参拝しやすい。境内は静かで、木々の香りが心地よい。地元の人が大切にしてきた場所らしく、派手さはないが落ち着いた空気が流れていた。','2026-10-22','11:10','⛩️','0000','',0,1,true,'2026-10-22 11:10:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.825144000,132.870544000,'三次ワイナリーで休憩','三次ワイナリーは広い敷地で段差が少なく、ゆっくり歩ける場所。売店には地元産のジュースやお菓子が並び、軽い休憩にちょうどよい。外の芝生広場は風が気持ちよく、旅の途中に立ち寄るには最適だった。','2026-10-22','11:40','🍇','0000','',-800,1,true,'2026-10-22 11:40:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.804853395,132.867021561,'庄原方面へ移動','三次から庄原へ向かう道は緩やかな山並みが続き、車窓から見える田園風景が美しい。移動時間も旅の一部として楽しめる。庄原に近づくにつれ、より静かな空気が広がり、心が落ち着いていく。','2026-10-22','12:20','🚗','0000','',0,1,true,'2026-10-22 12:20:00+09','2026-08-02 07:05:41.107381+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.012300000,135.672500000,'天龍寺の境内と庭園を散策','世界遺産の天龍寺に立ち寄り、見事な雲龍図と美しい庭園を眺めた。<br>縁側に並んで腰掛け、池の周りを泳ぐ鯉をぼんやりと眺める。<br>心がすーっと洗われるような贅沢な時間を2人で共有できた。','2026-09-12','10:30','🌿','0','',-1200,1,false,'2026-09-12 10:35:10.8+09','2026-08-01 09:43:49.952679+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.015000000,135.670500000,'竹林の小径をのんびり歩く','観光客でにぎわう有名な竹林の小径へ足を踏み入れた。<br>天高くまっすぐ伸びる竹の隙間から、やわらかい木漏れ日が差し込んでいる。<br>風が吹くたびにサラサラと鳴る竹の葉の音がとても心地よかった。','2026-09-12','11:20','✨','0','',0,1,false,'2026-09-12 11:23:20.15+09','2026-08-01 09:43:49.952679+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.017800000,135.670000000,'野宮神社の縁結びスポット','竹林を抜けたところにある小さな神社にお参りした。<br>恋愛成就の御利益があるということで、2人でしっかりとお守りを授かる。<br>彼女が真剣な顔でおみくじを引いている姿が少し微笑ましかった。','2026-09-12','12:00','⛩️','0','',-600,1,false,'2026-09-12 12:04:00+09','2026-08-01 09:43:49.952679+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.016000000,135.673000000,'嵐山トロッコ駅周辺の隠れ家食堂','メインストリートから少し離れた、観光客の少ない穴場の食堂でランチにした。<br>湯豆腐と手打ち蕎麦のセットを頼んで、温かい出汁の味にホッと一息つく。<br>静かな場所だからこそ、ゆっくりといろんな話をすることができた。','2026-09-12','13:00','😋','0','',-2400,1,false,'2026-09-12 13:05:12.3+09','2026-08-01 09:43:49.952679+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.804912000,132.882144000,'三次駅に到着','三次駅に降り立つと、広島県北部らしい穏やかな空気が広がっていた。駅前は静かで歩きやすく、ゆっくり旅を始めるにはちょうどよい雰囲気。まずは周辺を軽く散策しながら今日の行き先を確認。遠くに見える山並みがやわらかく、都会の喧騒から離れた落ち着いた旅になりそうだと感じた。','2026-10-22','09:10','🚉','0000','',0,1,false,'2026-10-22 09:10:00+09','2026-10-22 09:10:00+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.809331000,132.866144000,'三次本通り商店街を散策','駅からほど近い本通り商店街は昔ながらの店が並び、ゆっくり歩くとどこか懐かしい気持ちになる。お年寄りでも歩きやすい平坦な道で、地元の人の挨拶が心地よい。小さな和菓子店に立ち寄ると、優しい味の饅頭が旅の始まりを彩ってくれた。','2026-10-22','09:40','🍡','0000','',-300,1,false,'2026-10-22 09:40:00+09','2026-10-22 09:40:00+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.812345000,132.864912000,'三次もののけミュージアム前','ミュージアム前は広い歩道が整備されており、休憩ベンチも多い。館内に入らなくても周辺の散策だけで十分楽しめる。川沿いの風が心地よく、ゆっくり歩く旅にぴったりの場所だった。','2026-10-22','10:10','🏛️','0000','',0,1,false,'2026-10-22 10:10:00+09','2026-10-22 10:10:00+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.815733000,132.857491000,'馬洗川沿いをゆっくり散歩','馬洗川沿いの遊歩道は平坦で歩きやすく、川の流れを眺めながらゆっくり進める。水面に映る空が美しく、心が落ち着く時間が流れる。途中にあるベンチでひと休みしながら、三次らしい穏やかな風景を楽しんだ。','2026-10-22','10:40','🌿','0000','',0,1,false,'2026-10-22 10:40:00+09','2026-10-22 10:40:00+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.857744000,132.880744000,'庄原市街を散策','庄原市街は道幅が広く、歩道も整備されていて歩きやすい。昔ながらの商店が並び、ゆっくり歩くとどこか懐かしい気持ちになる。地元の人の挨拶が温かく、旅の印象をやさしくしてくれた。','2026-10-22','12:50','🏘️','0000','',0,1,true,'2026-10-22 12:50:00+09','2026-08-02 07:05:41.107381+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.011000000,135.675000000,'渡月橋のたもとで川風を感じる','お腹が満たされたあとは、定番の渡月橋の周辺へと戻ってきた。<br>桂川を渡る涼しい風が心地よくて、思わず大きく深呼吸をする。<br>川面に映る山々の景色が絵画のように美しくて、しばらく言葉を失って見とれてしまった。','2026-09-12','14:30','🏞️','0','',0,1,false,'2026-09-12 14:33:40.9+09','2026-08-01 09:43:49.952679+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.010200000,135.678000000,'川沿いの人気カフェでスイーツ休憩','少し歩き疲れたので、川沿いにあるおしゃれなカフェのテラス席へ滑り込んだ。<br>濃厚な抹茶のモンブランとほう茶をシェアして食べる。<br>甘いものを食べて疲れが一気に吹き飛び、スマホで今日の写真を振り返って盛り上がる。','2026-09-12','15:45','🍰','0','',-1800,1,false,'2026-09-12 15:50:15.4+09','2026-08-01 09:43:49.952679+09'),
	 (3,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013000000,135.676500000,'お土産通りで京みやげを選ぶ','駅へ戻る道すがら、お土産物屋さんが並ぶ通りを端から端まで覗いて歩いた。<br>可愛い和雑貨や、一口サイズの生八ツ橋を家族や自分用にとカゴに入れていく。<br>お揃いのキーホルダーを「これ可愛いね」と見せ合って購入した。','2026-09-12','17:00','🎁','0','',-2100,1,false,'2026-09-12 17:04:50.22+09','2026-08-01 09:43:49.952679+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.636000000,139.882000000,'ファンタジーランドでアトラクション巡り','ピーターパンやダンボを乗り継ぎ。待ち時間が長くて後半は子どもたちの足が疲れてぐずり出し、なだめるのが大変だった。親の体力も限界に…。','2026-08-05','16:00','😫','2','',0,-1,false,'2026-08-05 16:05:50.8+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633800000,139.883000000,'トゥーンタウンで可愛いチュロス休憩','甘い香りに誘われてミッキーチュロスを購入。可愛い見た目とサクサクの食感に、疲れが一気に吹き飛んだ！記念に家族みんなでパシャリ。','2026-08-05','17:15','😋','0','',-1600,1,false,'2026-08-05 17:20:10.2+09','2026-08-01 16:41:55.293734+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633000000,139.881500000,'プラザパビリオンで早めの夕食','夜のパレード前に腹ごしらえ。ハンバーグプレートを食べてしっかりエネルギーを補給。お店が比較的空いていてゆっくり座れて助かった。','2026-08-05','18:15','🍽️','0','',-3600,1,false,'2026-08-05 18:20:00+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633500000,139.879000000,'グランマ・サラのキッチンでランチ','お昼ごはんはオムライスやハンバーグが食べられるレストランへ。可愛い店内でホッと一息つけるけれど、お昼時ですごい混雑していて席を探すのに苦労した。','2026-08-05','12:15','🍔','1','',-4800,0,false,'2026-08-05 12:20:40.1+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.635000000,139.879800000,'ビッグサンダー・マウンテンに挑戦','スリル満点のコースター系アトラクション！急降下するたびに子どもたちの絶叫と楽しそうな笑い声が響き渡り、大盛り上がりだった。','2026-08-05','13:30','🎢','0','',0,1,false,'2026-08-05 13:35:20+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.634800000,139.881200000,'ホーンテッドマンションで涼む','午後の暑さを避けてホーンテッドマンションへ。不気味だけどユーモラスな世界観に、子どもたちは怖がりつつも目をキラキラさせて楽しんでいた。','2026-08-05','14:45','👻','0','',0,1,false,'2026-08-05 14:50:15.3+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632000000,139.880500000,'夜のワールドバザールでウインドウショッピング','パレード終わりの華やかな雰囲気が漂うメインストリートをゆっくりお散歩。ライトアップされた街並みがとても綺麗でロマンチック。','2026-08-05','20:15','✨','0','',0,1,false,'2026-08-05 20:20:11.1+09','2026-08-01 16:41:55.293734+09'),
	 (17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632300000,139.880400000,'お土産ショップで爆買いタイム','閉園間際、お土産ショップへ駆け込んで大混雑の中お菓子やグッズを爆買い！レジの長蛇の列にヘトヘトになりながらもカゴいっぱいに詰めた。','2026-08-05','20:45','🛍️','0','',-12500,0,false,'2026-08-05 20:50:05.1+09','2026-08-01 16:41:55.293734+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.827441000,132.859744000,'三次の小さな神社を参拝','川沿いにある小さな神社は段差が少なく、お年寄りでも参拝しやすい。境内は静かで、木々の香りが心地よい。地元の人が大切にしてきた場所らしく、派手さはないが落ち着いた空気が流れていた。','2026-10-22','11:10','⛩️','0000','',0,1,false,'2026-10-22 11:10:00+09','2026-10-22 11:10:00+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838512000,132.861744000,'三次ワイナリーで休憩','三次ワイナリーは広い敷地で段差が少なく、ゆっくり歩ける場所。売店には地元産のジュースやお菓子が並び、軽い休憩にちょうどよい。外の芝生広場は風が気持ちよく、旅の途中に立ち寄るには最適だった。','2026-10-22','11:40','🍇','0000','',-800,1,false,'2026-10-22 11:40:00+09','2026-10-22 11:40:00+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.841902000,132.868331000,'庄原市街を散策','庄原市街は道幅が広く、歩道も整備されていて歩きやすい。昔ながらの商店が並び、ゆっくり歩くとどこか懐かしい気持ちになる。地元の人の挨拶が温かく、旅の印象をやさしくしてくれた。','2026-10-22','12:50','🏘️','0000','',0,1,false,'2026-10-22 12:50:00+09','2026-10-22 12:50:00+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.852291000,132.870912000,'上野公園を散策','庄原の上野公園は広く平坦で、お年寄りでも安心して歩ける。池の周りをゆっくり歩くと風が心地よく、鳥の声が響く。ベンチも多く、休憩しながら自然を楽しめる場所だった。','2026-10-22','14:00','🌳','0000','',0,1,false,'2026-10-22 14:00:00+09','2026-10-22 14:00:00+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.810561725,132.891483307,'庄原の食堂で昼食','庄原の食堂は落ち着いた雰囲気で、地元の野菜を使った定食が優しい味だった。量もほどよく、お年寄りでも食べやすい。窓から見える田園風景が心地よく、ゆっくりとした昼食時間になった。','2026-10-22','13:20','🚗','0000','',-1200,1,true,'2026-10-22 13:20:00+09','2026-08-02 07:05:41.107381+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.846291000,132.879512000,'庄原の集落を歩く','公園近くの集落は静かで、昔ながらの家屋が並んでいた。道は平坦で歩きやすく、ゆっくり歩くと地元の生活の気配が感じられる。観光地ではないが、こうした素朴な風景が旅の印象を深めてくれた。','2026-10-22','14:30','🚶','0000','',0,1,false,'2026-10-22 14:30:00+09','2026-10-22 14:30:00+09'),
	 (34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.716500000,135.378900000,'三段壁の洞窟探検でスリルを味わう','2日目の朝、地下深くへエレベーターで降りて波が打ち寄せる洞窟内部を見学。自然の迫力を間近で体感して子どもたちも大興奮。','2026-09-13','09:30','🌊','0','',-3000,1,false,'2026-09-13 10:00:00+09','2026-08-01 21:08:04.82446+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.003700000,135.770000000,'四条河原町のファッションビルでお買い物','甘いものを食べたあとは、少し歩いて河原町のショップへ。トレンドの服やアクセサリーを「これ似合いそう！」と見せ合いながらウィンドウショッピングを楽しむ。','2026-08-03','15:45','🛍️','0','',-3200,1,false,'2026-08-03 15:48:12.3+09','2026-08-01 09:37:37.584085+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.005000000,135.771500000,'鴨川デルタ付近でちょっと一息','歩き疲れたので、川風を感じながら少し休憩。川のせせらぎを聴きながら、さっき買ったお揃いの小物をバッグに入れてニヤニヤ。夕方の涼しい風が心地よい。','2026-08-03','17:00','😌','0','',0,1,false,'2026-08-03 17:03:40.9+09','2026-08-01 09:37:37.584085+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.001000000,135.768000000,'祇園四条の和紅茶専門店','最後に、ちょっと落ち着いた空間で温かいお茶が飲みたくなって小さな和紅茶専門店へ。抹茶ではなくあえての和紅茶とほうじ茶のブラウニーでほっと一息。','2026-08-03','17:45','🍵','0','',-1100,1,false,'2026-08-03 17:50:15.4+09','2026-08-01 09:37:37.584085+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.992000000,135.759000000,'京都駅に戻りお土産選び','バスで京都駅へ戻ってきた。駅ナカのショップで、可愛いパッケージの京ばあむや限定クッキー缶を吟味して購入。自分用にもしっかりご褒美スイーツを確保。','2026-08-03','19:00','🎁','0','',-2500,1,false,'2026-08-03 19:04:50.22+09','2026-08-01 09:37:37.584085+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.002000000,135.758000000,'新幹線改札前でお別れ','あっという間に楽しい日帰り旅行の時間が終了。名残惜しいけれど、それぞれのホームへ向かう改札前で「またすぐ遊ぼうね！」と笑顔でバイバイ。充実した一日だった。','2026-08-03','20:15','🥺','0','',0,0,false,'2026-08-03 20:18:10.88+09','2026-08-01 09:37:37.584085+09'),
	 (2,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.003000000,135.772000000,'大人気のフルーツパフェ専門店','今日のメインイベントの一つ、季節のフルーツをふんだんに使ったパフェのお店に到着。
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.985000000,144.381000000,'和商市場の名物「勝手丼」で腹ごしらえ','旅の最初の目的地は釧路の台所・和商市場。白ご飯のどんぶりを持って、お店を回りながら好きな海鮮（ウニやイクラ、カニ）を自分で乗せていく。自分だけの最高な海鮮丼に舌鼓を打つ。','2026-08-10','11:00','🦀','0','',-2800,1,false,'2026-08-10 11:04:40.5+09','2026-08-01 10:19:22.49106+09'),
	 (54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560820000,133.536900000,'高知駅前で朝の散歩','駅前広場を軽く散歩。青空が広がっていて、今日の旅が絶対楽しくなる予感がした。','2026-08-04','09:40','🌞','0000','',0,1,false,'2026-08-04 09:40:00+09','2026-08-02 01:58:27.047402+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957850000,130.941900000,'唐戸市場に戻る','「もう一回フグ食べたいよな？」と誰かが言い、全員一致で市場に戻ることに。昼過ぎでも活気があって、再びフグ寿司を食べながら「やっぱりこれ最強やな」と笑った。大学生らしい勢いのある旅になってきた。','2026-11-03','14:00','🍣','0000','',-900,1,true,'2026-11-03 14:00:00+09','2026-08-02 02:38:00.798541+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.831912000,132.872044000,'道の駅たかので休憩','道の駅は広く段差が少ないため、お年寄りでも安心して利用できる。地元の野菜やお菓子が並び、旅の途中の休憩にぴったり。外のベンチで風を感じながらゆっくり過ごした。','2026-10-22','15:00','🛍️','0000','',-600,1,false,'2026-10-22 15:00:00+09','2026-10-22 15:00:00+09'),
	 (45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.613330000,135.021390000,'旅のフィナーレ：「淡路ハイウェイオアシス」で楽しかった思い出を胸に笑顔で出発地へ','翌日、すべての行程を太陽のような満面の笑顔で大満喫し、再び淡路ハイウェイオアシスへ。「美味しいものも絶景も全部最高だったね、また絶対に遊びに来ようね！」とみんなで元気よく手を振り合い、明るく温かい思い出がいっぱいに詰まった最高の淡路島旅行の幕を閉じる。','2026-12-06','10:00','👋','0','',0,1,false,'2026-12-06 10:30:00+09','2026-08-02 01:16:03.346395+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.464170000,135.398610000,'「JR東舞鶴駅」に到着、歴史ある港町・舞鶴でのワクワクする観光の幕開け','かつて海軍の鎮守府として栄えた歴史の香りが漂うJR東舞鶴駅に降り立つ。ひんやりと心地よい潮風を感じながら、これから巡る歴史ある赤れんがの街並みや日本海に面した美しい景色への期待に胸を膨らませ、元気いっぱいに駅舎をあとにする。','2027-04-10','09:00','🚢','0','',0,1,false,'2027-04-10 09:30:00+09','2026-08-02 01:20:50.513158+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455280000,139.600830000,'「東武日光駅」に到着、厳かな神域・日光への旅の始まり','歴史と神話が息づく静謐な空気の中、東武日光駅に到着。これから始まる世界遺産・日光の社寺巡りと美しい自然を巡る旅に、心が一気に引き締まるような高揚感を覚える。駅舎を出ると、遠くの山々から吹き抜ける澄んだ風が心地よく迎えてくれる。','2026-07-08','09:00','⛩️','0','',0,1,false,'2026-07-08 09:15:00+09','2026-08-01 22:06:57.714791+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.438890000,139.498610000,'「中禅寺（立木観音）」の神秘的な千手観音像を参拝','中禅寺湖のほとりに建つ、日光山輪王寺の別院である「中禅寺」を訪れる。生木の根元に彫られたと伝わる神秘的な「立木観音像」の美しさと気高さに静かに向き合い、厳かな境内で心の内を整える静かな祈りの時間を過ごす。','2026-07-10','10:00','🙏','0','',-500,1,false,'2026-07-10 10:30:00+09','2026-08-01 22:06:57.714791+09'),
	 (46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.468060000,135.390560000,'1軒目：駅チカの老舗食堂で味わう、スパイシーで懐かしい「海軍カレー」のランチ','舞鶴の海上自衛隊の歴史にちなんだ名物グルメである「海軍カレー」を味わいに、地元の温かな食堂へ。じっくり煮込まれたコクのあるルーとゴロゴロとした具材が絶妙にマッチし、一口食べるごとに深い味わいが広がって心も体もポカポカと温まる。','2027-04-10','09:30','🍛','0','',-1100,1,false,'2027-04-10 10:00:00+09','2026-08-02 01:20:50.513158+09'),
	 (40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.452780000,139.598610000,'1軒目：駅前のおしゃれなカフェでいただく日光天然氷のかき氷','旅の無事を祈りつつ、まずは駅近くの人気カフェにて日光の豊かな自然が生んだ「天然氷」を使った特製かき氷を味わう。ふわふわとした雪のように軽い口溶けと、甘酸っぱい特製イチゴシロップの味わいが、旅の疲れを優しく癒やしてくれる最高のウォーミングアップ。','2026-07-08','09:30','🍧','0','',-1000,1,false,'2026-07-08 10:00:00+09','2026-08-01 22:06:57.714791+09');
INSERT INTO public.t_memo_detail_1 (archive_id,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,del_flg,create_tim,update_tim) VALUES
	 (67,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.593333330,130.580833330,'桜島フェリー乗り場へ','フェリー乗り場は観光客で賑わっていて、桜島へ渡るワクワク感が高まる。海風が心地よくて気分が良い。','2026-10-12','11:40','⛴️','0000','',0,1,false,'2026-10-12 11:40:00+09','2026-08-02 16:24:03.081396+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.872744000,132.890744000,'上野公園を散策','庄原の上野公園は広く平坦で、お年寄りでも安心して歩ける。池の周りをゆっくり歩くと風が心地よく、鳥の声が響く。ベンチも多く、休憩しながら自然を楽しめる場所だった。','2026-10-22','14:00','🌳','0000','',0,1,true,'2026-10-22 14:00:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.880744000,132.895744000,'庄原の小さな集落を歩く','公園近くの集落は静かで、昔ながらの家屋が並んでいた。道は平坦で歩きやすく、ゆっくり歩くと地元の生活の気配が感じられる。観光地ではないが、こうした素朴な風景が旅の印象を深めてくれた。','2026-10-22','14:30','🚶','0000','',0,1,true,'2026-10-22 14:30:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.823668246,132.941780090,'庄原の道の駅で休憩','道の駅は広く段差が少ないため、お年寄りでも安心して利用できる。地元の野菜やお菓子が並び、旅の途中の休憩にぴったり。外のベンチで風を感じながらゆっくり過ごした。','2026-10-22','15:00','🛍️','0000','',-600,1,true,'2026-10-22 15:00:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.829304818,132.951736450,'庄原の田園を眺める','道の駅近くの田園は広く、風が通り抜ける音が心地よい。ゆっくり歩きながら景色を眺めると、庄原らしい穏やかな時間が流れる。旅の終盤にふさわしい静かな場所だった。','2026-10-22','15:30','🌾','0000','',0,1,true,'2026-10-22 15:30:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.857744000,132.880744000,'庄原市街へ戻る','市街へ戻る道は平坦で歩きやすく、ゆっくり進むと今日の出来事が自然と頭に浮かんだ。庄原の静けさと三次の町並みが心に残り、落ち着いた旅になったと感じた。','2026-10-22','16:00','🚶','0000','',0,1,true,'2026-10-22 16:00:00+09','2026-08-02 07:05:41.107381+09'),
	 (0,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.803214820,132.856518030,'旅の締め','三次駅へ戻り、ゆっくりと深呼吸すると広島県北部の穏やかな空気が胸に広がった。派手さはないが、心が落ち着く田舎旅となり、お年寄りでも安心して楽しめる一日だった。','2026-10-22','16:30','🌅','0000','',0,1,true,'2026-10-22 16:30:00+09','2026-08-02 07:05:41.107381+09'),
	 (64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.844512000,132.858733000,'庄原の食堂で昼食','庄原の食堂は落ち着いた雰囲気で、地元の野菜を使った定食が優しい味だった。量もほどよく、お年寄りでも食べやすい。窓から見える田園風景が心地よく、ゆっくりとした昼食時間になった。','2026-10-22','13:20','🌿','0000','',-1200,1,false,'2026-10-22 13:20:00+09','2026-10-22 13:20:00+09');
