INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (67,1041,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.595833330,130.557222220,'鹿児島中央駅に到着','旅の始まりは鹿児島中央駅。南国らしい暖かい空気が漂い、駅前の賑わいに気分が高まる。観光案内所で地図をもらい、今日のルートを軽く確認して出発する。','2026-10-12','09:10','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1042,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.593611110,130.561944440,'天文館を散策','鹿児島の中心街である天文館は活気があり、地元の店が並んで歩くだけで楽しい。名物の白熊を見つけてテンションが上がる。','2026-10-12','09:40','🛍️','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1043,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.592222220,130.565833330,'白熊を味わう','天文館むじゃきで名物の白熊を注文。見た目のインパクトに驚きつつ、食べると優しい甘さで美味しい。観光客らしい体験ができて満足。','2026-10-12','10:10','🍧','0000','',-900,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1044,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.600833330,130.571111110,'城山展望台へ移動','城山展望台へ向かう道は緑が多くて気持ちが良い。展望台からは桜島が大きく見えて、鹿児島らしい景色に感動する。','2026-10-12','11:00','🌄','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (69,1,'f2dfd247-bd9c-4757-a366-7a93a30ae11a'::uuid,34.833671586,135.499748329,'今宮三丁目 (大阪府)','出発','2026-08-11','06:31','🤔','0000','',0,0,0,0,0,0,false,'2026-08-22 11:21:55.514604+09','2026-08-22 11:21:55.514604+09','{}'),
	 (69,2,'f2dfd247-bd9c-4757-a366-7a93a30ae11a'::uuid,34.833278591,135.498636570,'箕面摂津線 (箕面市)','バス停','2026-08-11','06:43','😀','0000','',0,0,0,0,0,0,false,'2026-08-22 11:21:55.514604+09','2026-08-22 11:21:55.514604+09','{}'),
	 (67,1045,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.593333330,130.580833330,'桜島フェリー乗り場へ','フェリー乗り場は観光客で賑わっていて、桜島へ渡るワクワク感が高まる。海風が心地よくて気分が良い。','2026-10-12','11:40','⛴️','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1046,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.593670276,130.605640411,'桜島へ渡るフェリー','フェリーから見る桜島は迫力があり、海の上を進む感覚が楽しい。写真を撮りながら景色を楽しむ。','2026-10-12','12:00','🌊','0000','',-200,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (37,550,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.680120000,135.183450000,'「神戸ポートタワー」の洗練されたリニューアル姿を見上げる','美しくリニューアルされ、赤くしなやかなシルエットが際立つ神戸ポートタワーの真下へ。モダンに生まれ変わったタワーの圧倒的な存在感と、周囲の近代的なイルミネーションが織りなす神戸ならではの美しい夜景を贅沢に満喫する。','2026-12-05','16:00','🗼','0','',-1000,1,1,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,551,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.682340000,135.185670000,'5軒目：モザイクの海側テラスで楽しむ夜カフェのデザート','海に面したおしゃれなカフェのテラス席に陣取り、ライトアップされた神戸の街並みと海面に映るイルミネーションを眺めながら夜カフェタイム。甘さ控えめの濃厚なショコラケーキとハーブティーで、今日一日の素晴らしい思い出をしみじみと振り返る。','2026-12-05','17:30','🌃','0','',-1300,1,1,1,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}');
