	 (69,16,'f2dfd247-bd9c-4757-a366-7a93a30ae11a'::uuid,34.546714107,133.355820566,'国道486号 (福山市)','到着','2026-08-12','13:59','😀','0000','',0,0,0,0,0,0,false,'2026-08-22 11:21:55.514604+09','2026-08-22 11:21:55.514604+09','{}'),
	 (67,1051,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.562154849,130.682287216,'桜島溶岩なぎさ公園','海沿いの足湯が気持ちよくて、旅の疲れが少し取れる。桜島を眺めながら入る足湯は特別な体験。','2026-10-12','14:40','🦶','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1052,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.586432176,130.644950867,'桜島港へ戻る','島の空気をたっぷり味わって港へ戻る。火山の迫力と穏やかな海の対比が印象的で、忘れられない景色になる。','2026-10-12','15:20','🌋','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1053,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.591915637,130.605812073,'フェリーで鹿児島へ戻る','帰りのフェリーは少し疲れが出てきて、海を眺めながらゆっくり過ごす。桜島の姿が遠ざかる景色が旅情を誘う。','2026-10-12','15:40','🌊','0000','',-200,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1054,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.591550083,130.581865311,'鹿児島港に到着','港に戻ると街の賑わいが感じられて、桜島の静けさとのギャップが面白い。次の目的地へ向かう準備をする。','2026-10-12','16:00','⚓','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1047,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.594182040,130.643920898,'桜島港に到着','桜島港は静かで、火山の存在感がすぐ近くに感じられる。島の空気が独特で、歩くだけで楽しい。','2026-10-12','12:20','🌋','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1048,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.585833330,130.657777780,'烏島展望所へ','展望所からは桜島の荒々しい姿が見えて迫力満点。火山の力強さを感じる景色に圧倒される。','2026-10-12','13:00','🏔️','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (67,1055,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.586943980,130.554828644,'照国神社を参拝','街中にある落ち着いた神社で、旅の安全を祈る。境内は静かで心が落ち着く。鹿児島らしい雰囲気が漂う。','2026-10-12','16:30','⛩️','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1056,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.581167751,130.549507141,'維新ふるさと館','幕末の歴史を学べる施設で、展示が分かりやすくて興味深い。鹿児島の歴史を知ることで旅がより深まる。','2026-10-12','17:00','📚','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1049,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.580833330,130.674444440,'湯之平展望所へ','桜島の中でも特に人気の展望所。山肌が近くに見えて、自然の迫力を感じる。写真映えするスポットが多い。','2026-10-12','13:40','📷','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1057,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.572466173,130.552425385,'西郷隆盛像を見学','鹿児島の象徴ともいえる西郷隆盛像。観光客が多く、写真スポットとして人気。歴史を感じる瞬間。','2026-10-12','17:30','🗿','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1058,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.559741396,130.556373596,'仙巌園へ移動','庭園は広くて美しく、桜島を背景にした景色が素晴らしい。ゆっくり歩きながら自然を楽しむ時間が心地よい。','2026-10-12','18:00','🌺','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1050,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.568333330,130.681111110,'桜島ビジターセンター','火山の歴史や噴火の資料が展示されていて興味深い。桜島の成り立ちを知ることで旅がより深くなる。','2026-10-12','14:10','🏛️','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1059,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.558333330,130.559444440,'仙巌園で夕景を眺める','夕方の仙巌園は静かで、桜島が夕日に染まる景色が美しい。旅の締めくくりにふさわしい時間となった。','2026-10-12','18:30','🌇','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (67,1060,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,31.595833330,130.557222220,'鹿児島中央駅へ戻る','一日の旅を終えて駅へ戻る。桜島の迫力と街の賑わい、歴史と自然が混ざり合う鹿児島らしい旅になった。','2026-10-12','19:00','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 17:41:36.930386+09','2026-08-02 17:41:36.930386+09','{}'),
	 (4,40,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.711500000,139.813000000,'ソラマチ商店街でお土産探し','キャラクターショップやおしゃれな雑貨店が並ぶエリアをみんなでブラブラ。お互いに「これ似合いそう」などと言い合いながら、記念にお揃いのキーホルダーを購入した。','2026-03-15','14:00','🛍️','0','',-1500,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,41,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710000000,139.805000000,'隅田公園をのんびりお散歩','スカイツリーから浅草方面へ向かって、隅田川沿いの公園を歩く。春の暖かい日差しの中、川風を感じながらのんびりとおしゃべりしながら歩く時間がとても心地よい。','2026-03-15','15:15','🌿','0','',0,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (4,42,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.711800000,139.796300000,'浅草寺と雷門の定番スポット','言わずと知れた観光名所の雷門に到着。圧倒的な提灯の大きさに改めて感動しつつ、仲見世通りで人形焼きを買ってその場でパクつく。すごい人混みだけどそれもまた楽しい。','2026-03-15','16:10','🏮','0','',-500,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,43,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.712500000,139.795000000,'浅草のレトロな老舗喫茶店','歩き疲れて足がパンパンになったので、昔ながらの雰囲気漂う喫茶店で休憩。名物のクリームソーダを頼んで、学生時代のバカだったエピソードを振り返りながら大笑いする。','2026-03-15','17:20','☕','0','',-850,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,44,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710000000,139.802000000,'夕暮れの吾妻橋からスカイツリーを望む','すっかり日も傾いてきて、夕暮れに染まる空とライトアップが始まったスカイツリーを眺める。昼間とは違う幻想的な景色に、みんな少ししんみりしつつも写真を撮りまくる。','2026-03-15','18:30','🌇','0','',0,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,45,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710500000,139.810000000,'ソラマチに戻り最後の夜ご飯','再びスカイツリーの足元に戻り、夕飯はちょっとお高めの焼肉で打ち上げ。4年間一緒に頑張ってきた仲間と食べるお肉は格別に美味しくて、お酒も進んで最高に盛り上がる。','2026-03-15','19:30','🍻','0','',-4500,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,46,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710000000,139.810700000,'押上駅で解散・それぞれの道へ','楽しかった卒業旅行もついに終わりの時間。最寄りの駅からそれぞれの家に帰る電車のホームで、「社会人になってもまた集まろうな」と約束して笑顔で手を振って別れた。','2026-03-15','21:30','🥺','0','',0,0,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (7,85,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.985000000,144.381000000,'和商市場の名物「勝手丼」で腹ごしらえ','旅の最初の目的地は釧路の台所・和商市場。白ご飯のどんぶりを持って、お店を回りながら好きな海鮮（ウニやイクラ、カニ）を自分で乗せていく。自分だけの最高な海鮮丼に舌鼓を打つ。','2026-08-10','11:00','🦀','0','',-2800,1,1,1,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,88,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.431200000,144.531200000,'阿寒のワインディングロードを駆け抜ける','北へ向けて車を走らせると、緑深い森の中を縫うようなワインディングロードに入る。エンジンの心地よい唸りを聞きながら、お気に入りの音楽をかけてドライブを全力で楽しむ。','2026-08-10','16:00','🎵','0','',0,1,0,0,1,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (66,1029,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.261836191,131.355843544,'湯布院駅に到着','朝の湯布院駅は霧が少し残っていて幻想的。女子旅の始まりにぴったりの雰囲気で、駅前の可愛い看板を見つけて友達と写真を撮りまくる。山並みが見えてテンションが上がる。','2026-09-10','10:05','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1030,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.260939070,131.360864639,'由布見通りを散策','由布見通りは小さな雑貨屋やカフェが並んでいて歩くだけで楽しい。友達と「これ可愛い」と言いながら店を巡る時間が最高。湯布院らしい落ち着いた空気が心地よい。','2026-09-10','10:40','🛍️','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1031,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.256883969,131.356101036,'カフェでプリン休憩','湯布院の人気カフェでプリンを注文。濃厚でしっかりした味わいが美味しくて、友達と「これ当たり」と盛り上がる。店内の雰囲気も可愛くて女子旅感が増す。','2026-09-10','11:20','🍮','0000','',-900,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (66,1032,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.259073029,131.343955994,'金鱗湖へ向かう道','金鱗湖へ向かう途中の道は木々が多くて、光が差し込む感じがとても綺麗。写真映えするスポットが多くて、歩くたびに立ち止まって撮影会になる。','2026-09-10','12:00','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1033,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.260651989,131.334300041,'金鱗湖を散策','湖面に映る景色が美しくて、友達と何枚も写真を撮る。静かな空気が心地よくて、都会では味わえないゆったりした時間が流れる。湖畔のベンチで少し休憩。','2026-09-10','12:35','🌅','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1034,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.265388699,131.326446533,'湖畔カフェで昼食','湖畔のカフェでパスタを注文。窓から見える景色が綺麗で、食事がより美味しく感じる。女子旅らしく写真を撮りながらゆっくりランチを楽しむ。','2026-09-10','13:10','🍝','0000','',-1500,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1035,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.270017507,131.323313713,'宿にチェックイン','少し高台にある宿に到着。ロビーから見える由布岳が美しくて、友達と「やばい景色」と感動。部屋も綺麗で女子旅にぴったりの雰囲気。','2026-09-10','14:00','🏨','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1036,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.270833330,131.318333330,'露天風呂でゆったり','宿の露天風呂は景色が最高で、由布岳を眺めながら入る温泉は格別。湯気と風が気持ちよくて、友達とゆっくり話す時間が幸せ。','2026-09-10','15:00','♨️','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1037,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.270914535,131.321167946,'ラウンジで休憩','温泉後にラウンジでアイスティーを飲みながら休憩。静かで落ち着いた空間が心地よくて、旅の疲れが少し取れた気がする。','2026-09-10','16:00','🫖','0000','',-600,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1038,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.268366952,131.322069168,'宿の夕食を楽しむ','地元食材を使った料理が並び、どれも美味しくて感動。女子旅らしく写真を撮りながら楽しい夕食時間。デザートまでしっかり堪能した。','2026-09-10','18:00','🍽️','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1039,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.269586931,131.320137978,'夜の湯布院を散歩','夜の湯布院は静かで幻想的。街灯に照らされた道を歩くと昼とは違う雰囲気で、友達と「夜の方が好きかも」と話しながら散歩を楽しむ。','2026-09-10','19:30','🌙','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (66,1040,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.267577546,131.320695877,'朝の由布岳を眺める','翌朝、宿のテラスから見る由布岳は美しくて、女子旅の締めくくりにふさわしい景色だった。朝の空気が澄んでいて深呼吸したくなる。','2026-09-11','07:30','🌄','0000','',0,1,0,0,0,0,false,'2026-08-02 22:32:51.598812+09','2026-08-02 22:32:51.598812+09','{}'),
	 (17,234,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632900000,139.880000000,'舞浜駅に到着！いざ夢の国へ','朝早くから電車を乗り継いで、ついに舞浜駅に到着！子どもたちも「ディズニーだ！」と大はしゃぎで、一気にテンションがマックスに。ワクワクが止まらない。','2026-08-05','08:30','🤩','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (3,34,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.010200000,135.678000000,'川沿いの人気カフェでスイーツ休憩','少し歩き疲れたので、川沿いにあるおしゃれなカフェのテラス席へ滑り込んだ。<br>濃厚な抹茶のモンブランとほう茶をシェアして食べる。<br>甘いものを食べて疲れが一気に吹き飛び、スマホで今日の写真を振り返って盛り上がる。','2026-09-12','15:45','🍰','0','',-1800,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,35,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013000000,135.676500000,'お土産通りで京みやげを選ぶ','駅へ戻る道すがら、お土産物屋さんが並ぶ通りを端から端まで覗いて歩いた。<br>可愛い和雑貨や、一口サイズの生八ツ橋を家族や自分用にとカゴに入れていく。<br>お揃いのキーホルダーを「これ可愛いね」と見せ合って購入した。','2026-09-12','17:00','🎁','0','',-2100,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,36,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013500000,135.677500000,'夕暮れの嵐山駅で名残惜しいお別れ','楽しかったデートの時間もあっという間に過ぎて、夕暮れの駅ホームに到着した。<br>名残惜しい気持ちでいっぱいになりながらも、今日の楽しかった思い出を振り返る。<br>「また次も色んなところに出かけようね」と笑顔で手を振って帰路についた。','2026-09-12','18:15','🥺','0','',0,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (2,17,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.003700000,135.760000000,'京都駅で待ち合わせ','朝、京都駅の烏丸口で無事に合流！今日のルートを確認しながら、テンション高めで地下鉄に乗り込む。天気も良くて最高の女子旅日和になりそう。','2026-08-03','10:00','👯‍♀️','0','',0,1,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (2,18,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.004000000,135.768100000,'烏丸御池のおしゃれ文房具店','最初の目的地は、洗練されたセレクト雑貨や文房具が集まるお店。お互いに可愛いマスキングテープやレターセットを見つけて、さっそくお揃いでお買い上げ。','2026-08-03','10:45','✨','0','',-1400,1,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (2,19,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.008000000,135.765000000,'三条の隠れ家カフェで早めのランチ','町家をリノベーションした素敵なカフェでランチ。アボカドとサーモンのオープンサンドをシェアして食べた。店内の雰囲気が落ち着いていて、おしゃべりに花が咲く。','2026-08-03','12:00','🥑','0','',-1850,1,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (2,20,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.005000000,135.771000000,'木屋町の路地裏を散策','高瀬川沿いの道をのんびりお散歩。柳並木とレトロな建物が並んでいて、どこを切り取っても写真映えする景色。歩きながら次に行くパフェのお店をスマホで再確認。','2026-08-03','13:30','🌿','0','',0,1,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (2,21,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.003000000,135.772000000,'大人気のフルーツパフェ専門店','今日のメインイベントの一つ、季節のフルーツをふんだんに使ったパフェのお店に到着。
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (2,24,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.001000000,135.768000000,'祇園四条の和紅茶専門店','最後に、ちょっと落ち着いた空間で温かいお茶が飲みたくなって小さな和紅茶専門店へ。抹茶ではなくあえての和紅茶とほうじ茶のブラウニーでほっと一息。','2026-08-03','17:45','🍵','0','',-1100,1,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (2,25,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.992000000,135.759000000,'京都駅に戻りお土産選び','バスで京都駅へ戻ってきた。駅ナカのショップで、可愛いパッケージの京ばあむや限定クッキー缶を吟味して購入。自分用にもしっかりご褒美スイーツを確保。','2026-08-03','19:00','🎁','0','',-2500,1,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (2,26,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.002000000,135.758000000,'新幹線改札前でお別れ','あっという間に楽しい日帰り旅行の時間が終了。名残惜しいけれど、それぞれのホームへ向かう改札前で「またすぐ遊ぼうね！」と笑顔でバイバイ。充実した一日だった。','2026-08-03','20:15','🥺','0','',0,0,0,0,0,0,false,'2026-08-01 09:57:06.469171+09','2026-08-01 09:57:06.469171+09','{}'),
	 (1,7,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.652500000,135.506300000,'新世界・通天閣周辺','新幹線と電車を乗り継いで、ようやく大阪に到着！通天閣の下はすごい活気で、一気に大阪らしい雰囲気にテンションが上がる。まずは名物の串カツの匂いに誘われて、お腹の虫が鳴り始める。','2026-08-01','12:30','🤩','0','',-1200,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,8,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.665500000,135.501500000,'日本橋の電気街・オタロード','お腹を満たしたあとは、食後の散歩がてら日本橋のサブカルチャーエリアをブラブラ。ずらっと並び立つショップや独特の賑わいを見ているだけでも結構面白い。思わず限定グッズを衝動買い。','2026-08-01','14:15','😆','0','',-2400,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,9,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668900000,135.501300000,'道頓堀・グリコサイン前','人の多さに圧倒されつつも、やっぱり大阪といえばここへ来ないと始まらない。橋の上から川沿いの派手な看板を眺める。観光客の熱気がすごくて、ちょっと圧倒されつつ記念撮影。','2026-08-01','16:00','😀','0','',0,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,10,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.672000000,135.498000000,'アメリカ村の路地裏','道頓堀の喧騒から少し離れて、アメ村の古着屋さんやストリートを散策。歩き疲れて足がパンパンになってきた。おしゃれなカフェを探して、ちょっと細い路地を入ったり迷ったりする。','2026-08-01','17:30','😌','0','',0,0,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,11,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.671500000,135.495000000,'隠れ家カフェでひと休み','見つけた小さな喫茶店でアイスコーヒーとチーズケーキを注文。静かな店内で、今日撮った写真を見返しながらスマホをいじる。ようやく一息つけて、歩き疲れた身体が生き返る感覚。','2026-08-01','18:00','☕','0','',-850,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,12,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.667000000,135.504000000,'難波のホテルにチェックイン','夕方にホテルへ戻ってチェックイン。少し部屋のベッドで横になったら、そのままウトウトしてしまいそうになる。夜ご飯に向けて、少し体力回復を優先して部屋でゴロゴロ。','2026-08-01','20:00','😴','0','',0,0,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,13,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686300000,135.520000000,'大阪城公園の早朝散歩','2日目の朝。少し早起きして、ホテルから地下鉄で移動し大阪城公園へ。朝の澄んだ空気の中でお堀の周りを歩く地元の人たちとすれ違う。天守閣が朝日に照らされていてとても綺麗。','2026-08-02','08:30','🌿','0','',0,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (1,14,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702400000,135.495900000,'梅田の地下街でランチ','大阪城から梅田へ移動。複雑怪奇な梅田の地下街（ウメダ地下迷宮）にやっぱり少し迷う。なんとかたどり着いたお店で、絶品のどて焼き定食をいただく。味が染み込んでいて最高。','2026-08-02','12:00','😋','0','',-1100,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,15,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705000000,135.498000000,'中崎町のレトロな雑貨屋巡り','梅田のすぐ近くとは思えない、落ち着いた古民家が並ぶ中崎町へ。おしゃれな雑貨屋さんやギャラリーをのんびり覗き歩く。時間に追われない、こういうマイペースな散策が一番落ち着く。','2026-08-02','14:00','✨','0','',-500,1,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (1,16,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702500000,135.495000000,'大阪駅（帰路へ）','楽しかった1泊2日のひとり旅もあっという間に終わり。お土産の豚まんをしっかりリュックに詰め込んで、新大阪へ向かう電車のホームで少し寂しさを感じつつ帰路につく。','2026-08-02','17:00','🥺','0','',-1500,0,0,0,0,0,false,'2026-08-01 09:57:16.145371+09','2026-08-01 09:57:16.145371+09','{}'),
	 (5,47,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'新千歳空港でレンタカーを借りる','飛行機を降りてすぐレンタカーの手続きを済ませ、ワゴン車に乗り込む。「どこ行く？」「とりあえず北へ向かおうぜ！」と、完全ノープランで男4人の珍道中がスタートする。','2026-06-10','09:30','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,48,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.923400000,141.572100000,'道央道を北上しながら最初の休憩','走り出してすぐに北海道のスケールのデカさにテンションが上がる。運転を交代しながら、とりあえずサービスエリアで北海道限定のソフトクリームを食べて気合を入れる。','2026-06-10','10:45','🍦','0','',-450,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,49,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.342100000,141.782300000,'岩見沢の田園風景ロードで寄り道','高速を降りて一般道に入ると、どこまでも続く水平線のような田園風景が広がる。車を路肩に止めて、あまりの開放感に全員で大の字になって写真を撮りまくる。','2026-06-10','12:00','🌾','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,50,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.541200000,142.213400000,'旭川ラーメンでガッツリ昼食','「昼はやっぱりラーメンだろ」と、看板を見つけて飛び込んだ地元のラーメン店。濃厚な味噌ラーメンとチャーハンを頼んで、空腹だった胃袋が一気に満たされる。','2026-06-10','13:30','🍜','0','',-1100,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,51,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.432100000,142.451200000,'美瑛のパッチワークの路をドライブ','なだらかな丘陵地帯が続く美瑛の景色の中を車で駆け抜ける。雑誌で見たような絶景が次々と現れて、助手席の奴が「うわ、すげえ！」と窓から身を乗り出す。','2026-06-10','15:00','📷','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,52,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.411200000,142.632100000,'青い池で幻想的な景色に感動','観光客に混じって噂の青い池に立ち寄る。本当に絵の具を溶かしたような鮮やかな青色をしていて、男4人で「おぉ…」と妙に感心してしばらく眺めてしまった。','2026-06-10','16:15','✨','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,53,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.441200000,142.651200000,'白ひげの滝でマイナスイオンを浴びる','青い池のすぐ近くにある滝にも足を延ばす。轟音とともに勢いよく水が流れ落ちていて、ドライブの疲れが一気に吹き飛ぶような爽快感を味わう。','2026-06-10','17:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (5,54,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.342100000,142.751200000,'十勝岳望岳台で夕日を眺める','少し標高の高いところまで車を走らせたら、雲の上から夕日が沈む最高のロケーションに遭遇。寒風の中、男4人で並んで沈む夕日を眺めるシュールな絵面になる。','2026-06-10','18:10','🌇','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,55,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.351200000,142.851200000,'富良野の温泉宿に駆け込みチェックイン','すっかり暗くなった山道を抜けて、今夜の宿である温泉街へ到着。予約なしだったが運よく空きがあり、冷えた体を温めるべく即座に大浴場へ直行する。','2026-06-10','20:00','♨️','0','',-8500,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (65,1024,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.180556000,133.020833000,'大山祇神社を参拝','大きな木々に囲まれた神社で、空気が澄んでいて心が落ち着く。旅の安全を祈った。','2026-08-04','15:20','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (5,56,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.352000000,142.853000000,'宿の居酒屋で北海道の夜を満喫','温泉のあとは浴衣のまま食堂に集まり、ジンギスカンとビールで盛大な宴会がスタート。明日どこに行くかも決めずに、昔のバカ話で夜遅くまで盛り上がり続ける。','2026-06-10','21:30','🍺','0','',-4000,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,57,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.341200000,142.381200000,'富良野の早朝コンビニで朝食調達','2日目の朝。寝ぼけ眼で宿をチェックアウトし、近くのセイコーマート（セコマ）に駆け込む。ホットシェフのおにぎりとザンギを買って、車のなかで頬張る。','2026-06-11','07:30','🍙','0','',-700,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,58,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.123400000,142.351200000,'富良野のチーズ工房に立ち寄り','「お土産くらい買っていくか」とノリでチーズ工房へ。色んな種類の試食を片っ端から試して、一番美味しかったスモークチーズをみんなでお揃いで購入する。','2026-06-11','09:00','🧀','0','',-1200,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,59,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.981200000,142.281200000,'山岳ワインディングロードを快走','南下しながら、車通りの少ない気持ちいいワインディングロードを進む。エンジンの唸りを聞きながら、音楽を大音量にかけてドライブの醍醐味を全力で満喫する。','2026-06-11','10:30','🎵','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (19,264,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578000000,136.648000000,'金沢駅に到着！鼓門がお出迎え','北陸新幹線で金沢駅に到着。立派な「鼓門」の前で記念撮影をして、ゆったりとした温泉旅行のスタートに心が弾む。','2026-08-05','10:30','📸','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (5,60,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.812300000,142.151200000,'道の駅でご当地グルメを買い食い','ドライブの定番、道の駅を発見して迷わずピットイン。特大のメロンパンと、その場で焼いたホタテの串焼きをシェアして食べる。これが想像以上の美味さでテンションが上がる。','2026-06-11','12:00','🍈','0','',-900,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,61,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.612300000,141.951200000,'日勝峠の展望スペースで絶景堪能','険しい峠道を登りきったところにある展望スペース。眼下に広がる十勝平野の圧倒的なパノラマビューに、男4人揃って「すげぇ……」と言葉を失って見入ってしまう。','2026-06-11','13:30','⛰️','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (15,210,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'甲府駅でレンタカーを借りて富士山麓へ出発','登らない贅沢な富士山周辺の撮影・散策ドライブ旅をスタートさせるため、朝の甲府駅前でレンタカーを借り受けて出発しました。車窓から見える遠くの山並みと青空にワクワクしながら、ハンドルを握って富士五湖エリアを目指して高速道路を軽快に飛ばします。','2026-09-10','09:00','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (5,63,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.821200000,141.512300000,'千歳市内の大型ショッピングモール','そろそろ旅の終わりが近づき、お土産の買い出しのために大きめの施設へピットイン。家族や自分用に大量のバターサンドや海鮮スナックをカゴに放り込んでいく。','2026-06-11','16:15','🛍️','0','',-3500,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,64,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.801200000,141.651200000,'旅の最後のガソリンスタンド','レンタカーを返却する直前、満タン返しのためにスタンドへ滑り込む。大量に走り抜けたメーターの数値を見て、「めちゃくちゃ走ったな！」と謎の達成感を分かち合う。','2026-06-11','17:30','⛽','0','',-6500,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,65,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'新千歳空港でレンタカー返却','無事にトラブルもなくレンタカーを返却完了。車体にこびりついた虫の跡すらも勲章のように見えながら、空港のロビーへと足を進める。','2026-06-11','18:15','🤝','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,66,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.821400000,141.671200000,'空港のスープカレーで締めくくり','保安検査場に入る前、最後の最後でどうしてもスープカレーが食べたくなり滑り込み。スパイスの効いた熱々のカレーを食べて、最高だった北海道ドライブ旅を締めくくる。','2026-06-11','19:00','🍛','0','',-1600,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:06:52.934296+09','{}'),
	 (5,62,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.639767817,141.785087585,'夕張のメロン城跡地付近を通過','かつての観光名所の前を車で通り過ぎる。「おお、ここがメロン城か！」と謎の感動を覚えつつ、車内で夕張メロンの歌を適当に大合唱しながら通り抜ける。','2026-06-11','14:45','🎶','0','',0,1,0,0,0,0,false,'2026-08-01 10:06:52.934296+09','2026-08-01 10:08:54.435135+09','{}'),
	 (6,69,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'新千歳空港で家族みんなが合流','待ちに待った家族旅行のスタート。空港に到着してさっそくレンタカーを手配し、チャイルドシートを確認して車に乗り込む。子どもたちもワクワクした様子で後部座席ではしゃぎ出す。','2026-07-20','09:30','👨‍👩‍👧‍👦','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,70,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.981200000,141.451200000,'北広島の大型アウトレットで寄り道','札幌へ向かう道中で、ちょっと寄り道してショッピングモールへ。家族それぞれにお揃いの帽子や夏服を選んだり、さっそく北海道のソフトクリームを食べて休憩する。','2026-07-20','11:00','🍦','0','',-2400,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,71,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.031200000,141.381200000,'札幌市内のスープカレーでランチ','お昼ごはんは、やっぱり本場のスープカレーを食べようと有名店へ。ゴロゴロ入った野菜と柔らかいチキンに家族みんな大満足。子ども用のマイルドな辛さもあって完食。','2026-07-20','12:30','🍛','0','',-4200,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,72,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.051200000,141.351200000,'大通公園の噴水広場でひと遊び','札幌中心部に戻り、大通公園の緑豊かな芝生や噴水の周りを家族でのんびりお散歩。子どもたちが水遊びをしたがるので、濡れないようにハラハラしつつ見守る。','2026-07-20','14:00','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (6,73,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.055000000,141.348000000,'札幌市時計台の前で記念撮影','せっかくなので観光の定番である時計台へ立ち寄る。みんなで並んで「はい、チーズ！」と記念写真をパシャリ。レトロな建物の前で家族の素敵な思い出が形に残る。','2026-07-20','15:00','📷','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (65,1026,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.138333000,133.003611000,'伯方の塩ラーメンを食べる','名物の塩ラーメンはあっさりしていて美味しい。旅の疲れが少し取れた気がする。','2026-08-04','16:40','🤩','0000','',-900,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (6,74,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.045000000,141.312000000,'円山動物園で動物たちを間近で見る','少し移動して、緑に囲まれた円山動物園へ。ホッキョクグマ館やゾウのエリアなどを見て回り、子どもたちが目を輝かせて大喜びしている姿を見て親としても嬉しくなる。','2026-07-20','16:00','🦁','0','',-2500,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,75,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.012000000,141.341200000,'定山渓温泉の温泉宿にチェックイン','夕方に車を走らせて、札幌の奥座敷である定山渓温泉へ到着。広々とした和室の部屋に荷物を置き、旅の疲れを癒やすためにさっそく家族みんなで温泉の大浴場へ向かう。','2026-07-20','18:00','♨️','0','',-28000,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,76,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.013000000,141.343000000,'宿のバイキングで北海道の味覚を満喫','夜ご飯はホテル内の豪華なバイキング。カニや新鮮なお寿司、目の前で焼いてくれるステーキなどをお腹いっぱい食べる。子どもたちもデザートのケーキに大満足の様子。','2026-07-20','19:30','🦀','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,77,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.012000000,141.341200000,'温泉街の夜をのんびりお散歩','夕食のあとは、浴衣を着て家族一緒に温泉街の川沿いを少しお散歩。夜風がとても心地よく、ライトアップされた渓流の景色を眺めながらゆったりとした時間を過ごす。','2026-07-20','21:00','🌙','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,78,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.021200000,141.321200000,'翌朝、定山渓の自然の中をドライブ出発','2日目の朝。朝風呂ですっきり目覚めたあと、宿をチェックアウトして再び車に乗り込む。窓から見える木々の緑と綺麗な川の景色に癒やされながら車を走らせる。','2026-07-21','09:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,79,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.031200000,141.251200000,'白い恋人パークでお菓子作り見学','子どもたちのリクエストで「白い恋人パーク」に到着。お菓子の甘い香りに包まれながら、工場見学をしたり可愛い中庭の景色を見て回る。お土産のチョコレートもたくさん買う。','2026-07-21','10:30','🍫','0','',-1800,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,80,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.081200000,141.371200000,'サッポロビール園で名物ランチ','お昼はちょっと贅沢にサッポロビール園の大きなホールへ。ジューシーなジンギスカンをみんなでワイワイ焼きながら食べる。お肉が柔らかくて箸が止まらない。','2026-07-21','12:30','🍖','0','',-5500,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,83,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.787500000,141.681400000,'家族みんなで笑顔で帰路へ','レンタカーを無事に返却し、出発ロビーへ。たくさん遊んで少し疲れた子どもたちがウトウトし始める中、「また来年も家族みんなで来ようね」と話し合って飛行機に乗り込む。','2026-07-21','18:30','✈️','0','',0,0,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (7,84,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.042547207,144.193153381,'釧路空港でレンタカーを借りて出発','朝の釧路空港に到着し、さっそくレンタカーの手続きを済ませる。窓の外のどこかひんやりとした空気に「いよいよ道東に来たぞ」と実感が湧き、テンションが上がってエンジンをかける。','2026-08-10','09:30','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,86,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.081200000,144.451200000,'釧路湿原展望台でスケールの大きさに圧倒される','車を走らせて日本最大の湿原へ。見渡す限り果てしなく広がる緑の大地に、男2人で「うわ、すげえ……」とただただ圧倒される。風が吹き抜けていく音が心地よい。','2026-08-10','13:00','🌿','0','',-500,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,87,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.151200000,144.512300000,'細岡展望台から蛇行する釧路川を望む','湿原の反対側にある細岡展望台へも移動。眼下に蛇行しながら流れる釧路川の景色がまるで絵画のようで、しばらく言葉を失ってカメラのシャッターを切りまくる。','2026-08-10','14:30','📷','0','',0,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,89,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.441200000,144.431200000,'阿寒湖温泉の宿にチェックイン','夕方に阿寒湖のほとりにある温泉宿へ到着。広めの和室に荷物を放り込み、さっそく冷えた体を温めるために硫黄の香りが漂う大浴場へ向かう。','2026-08-10','18:00','♨️','0','',-12000,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,90,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.442000000,144.433000000,'湖畔の居酒屋でワカサギと地酒を堪能','夜ご飯は温泉街の居酒屋へ繰り出す。阿寒湖で採れたワカサギの天ぷらと地元の日本酒を合わせながら、明日のルートについて地図を広げて熱く語り合う。','2026-08-10','20:00','🍶','0','',-4500,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (15,211,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.512300000,138.761200000,'河口湖畔に到着し見事な富士山の姿に感動','車を走らせて最初の目的地である河口湖のほとりへと到着しました。雲ひとつない青空の下、湖の向こう側にドンとそびえ立つ美しい富士山の姿が目の前に飛び込んできて、男2人で「うわ、すげぇ綺麗だな…！」と思わず歓声を上げました。湖畔の風がとても心地よい最高のロケーションです。','2026-09-10','10:30','🗻','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (7,92,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.631200000,144.612300000,'硫黄山で地球の息吹を間近で感じる','あたり一面に黄色い硫黄の結晶が広がり、あちこちからゴゴゴと音を立てて白煙が噴き出しているスポットへ。ダイナミックな大地のエネルギーを肌でひしひしと感じる。','2026-08-11','10:30','🌋','0','',-500,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,93,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.791200000,144.681200000,'屈斜路湖の砂湯で足湯体験','湖畔の砂を少し掘ると温かいお湯が湧き出てくる「砂湯」に立ち寄る。冷たい湖風を受けながら、足湯に浸かってのんびり小休憩。白鳥の親子も近くを泳いでいて和む。','2026-08-11','12:00','🦆','0','',0,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,94,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.841200000,144.821200000,'美幌峠の頂上から屈斜路湖を一望','峠道を一気に登りきった美幌峠の展望台へ。眼下に広がる日本最大のカルデラ湖・屈斜路湖のパノラマビューが文字通り「絶景」の一言で、缶コーヒー片手にしばらく見入ってしまう。','2026-08-11','13:30','⛰️','0','',-200,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,95,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.981200000,144.912300000,'オホーツク海に面した網走市街へ到着','山道を抜けてオホーツク海側へと一気に北上。海の匂いを感じながら網走の街に入り、遅めの昼食として地元で人気の海鮮食堂へ駆け込む。','2026-08-11','15:30','🌊','0','',-1800,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (7,96,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.021200000,145.012300000,'知床半島の入り口・ウトロへドライブ','さらに東へ、知床の入り口であるウトロ漁港の周辺まで車を走らせる。険しい断崖絶壁が海に落ち込むワイルドな景色に変わり、いよいよ秘境感が増してくる。','2026-08-11','17:15','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,97,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.061200000,145.001200000,'知床の岬の見える温泉宿にチェックイン','3日目の拠点となる知床の宿に到着。夕暮れのオホーツク海を窓から眺めながら、旅の疲れをほぐすために再び温泉へと向かう。夕日が海に沈むグラデーションが最高。','2026-08-11','19:00','🌇','0','',-14000,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,98,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.101200000,145.112300000,'世界遺産・知床五郷の地上遊歩道へ','3日目の朝。ガイドの案内を聞きながら、原生林に囲まれた知床五湖の地上遊歩道を散策する。野生のシカに遭遇したり、手つかずの大自然の空気を胸いっぱいに吸い込む。','2026-08-12','09:30','🦌','0','',-2500,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,100,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.912300000,144.281200000,'北見市内で名物の焼肉ランチ','内陸へ戻りながら、焼肉の街として知られる北見市へ。地元で有名な肉屋に飛び込み、サガリやホルモンを香ばしく焼き上げてガッツリと昼食をとる。これが驚くほどの美味さ。','2026-08-12','13:30','🥩','0','',-2200,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,101,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.812300000,144.151200000,'女満別空港へ向けてラストスパート','旅の終盤、どこまでも続くまっすぐな道（メルヘンの丘付近）を車窓から眺めながら空港へと車を走らせる。「あっという間の3日間だったな」と、車内で思い出話に花が咲く。','2026-08-12','15:30','🌾','0','',0,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,102,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.881200000,144.161200000,'女満別空港でレンタカーを返却','無事にトラブルもなく女満別空港に到着し、レンタカーを返却する。大量に走り抜けたメーターの数値に驚きつつ、出発ロビーへと足を進めてお土産の買い出しへ。','2026-08-12','16:45','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,103,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.883000000,144.163000000,'空港のラーメンで道東旅を締めくくる','保安検査場を通る直前、最後の締めくくりに空港内の食堂でコクのある味噌ラーメンを食べる。「また絶対に道東に来ようぜ」と誓い合い、帰りの飛行機へと乗り込む。','2026-08-12','17:30','🍜','0','',-1100,0,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:20:41.969234+09','{}'),
	 (7,91,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.579831265,144.554736614,'神秘の湖・摩周湖の第1展望台へ','2日目の朝。霧が多いことで有名な摩周湖だが、この日は奇跡的に雲ひとつない快晴。どこまでも深く濃い青色をした「摩周ブルー」の湖面に感動する。','2026-08-11','09:00','✨','0','',-500,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:21:47.225504+09','{}'),
	 (7,99,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,44.081200000,145.151200000,'知床の有名スポット・オシンココの滝','轟音を立てて豪快に流れ落ちる「オシンココの滝」に立ち寄る。マイナスイオンを全身に浴びて、近くの売店で売っていた名物の網走産ホタテ焼きをその場で頬張る。','2026-08-12','11:30','🌊','0','',-600,1,0,0,0,0,false,'2026-08-01 10:20:41.969234+09','2026-08-01 10:23:00.513788+09','{}'),
	 (8,104,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅に到着して食いしん坊旅スタート','朝の新幹線で盛岡駅に無事に3人集合。改札を出た瞬間から「お昼は何食べる？」と食のことで頭がいっぱいの3人。テンション高めでレンタカーに乗り込む。','2026-09-05','09:30','🚅','0','',0,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (8,105,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.701000000,141.152000000,'盛岡城跡公園をのんびりお散歩','最初の目的地として、緑豊かな盛岡城跡公園の石垣を眺めながらお散歩。これからの食べ歩きに備えて、まずはしっかり歩いてお腹のスペースを空けておく。','2026-09-05','10:30','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,106,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.703000000,141.141000000,'老舗の盛岡冷麺でランチ','お昼ごはんはやっぱり外せない盛岡冷麺の有名店へ。透き通るコシのある麺とコクのあるスープ、別盛りのキムチを少しずつ入れながら、その美味しさに3人とも無言で夢中になる。','2026-09-05','12:00','🍜','0','',-3300,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,107,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.704000000,141.143000000,'おしゃれなレトロカフェでデザート休憩','冷麺のあとはすぐ近くの古民家カフェへ移動。自家製の季節のフルーツタルトとカフェラテを頼み、甘いものは別腹と言いながらペロリと完食して女子トークに花を咲かせる。','2026-09-05','13:45','🍰','0','',-2100,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,108,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.706000000,141.161000000,'盛岡の名所・石割桜を見物','大きな岩の割れ目から力強く育っている天然記念物の石割桜を見学。自然の生命力に感動しつつ、記念にお互いの写真を撮り合ってワイワイ楽しむ。','2026-09-05','15:15','🌸','0','',0,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,109,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.701500000,141.138000000,'福わらしなどの可愛い雑貨屋さん巡り','中心街に戻り、可愛い民芸品や地元の作家さんの雑貨が並ぶお店を覗く。お揃いの南部鉄器の小さな小皿や、可愛いキーホルダーを見つけてみんなでお買い上げ。','2026-09-05','16:30','🛍️','0','',-2500,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,110,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702500000,141.137000000,'盛岡市内の温泉付きホテルにチェックイン','今日の宿泊先であるホテルに到着。すっきりと綺麗なお部屋に荷物を置いて、夜のメインイベントに向けて少し早めに温泉に入ってさっぱりリフレッシュする。','2026-09-05','18:00','♨️','0','',-18000,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,111,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.703500000,141.139000000,'牛タンと県産牛の炭火焼き専門店で夕食','待ちに待った夜ご飯！厚切りでジューシーな牛タンの炭火焼きと、とろけるような岩手県産牛のステーキを贅沢にオーダー。香ばしい匂いと抜群の美味しさに3人とも大興奮。','2026-09-05','19:30','🥩','0','',-7500,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,112,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702500000,141.137000000,'夜の繁華街で地酒を軽く一杯','夕食のあともおしゃべりが止まらず、隠れ家風のバーへ移動。岩手の地酒やおしゃれなカクテルを飲みながら、今日の楽しかった出来事を振り返って夜遅くまで笑い合う。','2026-09-05','21:30','🥂','0','',-3000,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (65,1027,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.115556000,132.990556000,'大島へ移動','橋を渡るたびに景色が変わり、旅がどんどん進んでいく感覚が楽しい。','2026-08-04','17:20','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (11,162,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.718600000,140.102400000,'秋田空港に到着してレンタカーを無事に返却','たくさんの思い出とたくさんのお土産を車に積み込み、無事に秋田空港のレンタカー営業所へと戻って車を返却しました。大きなトラブルもなく快適に走ってくれた相棒に心の中で感謝しつつ、出発ロビーへと向かいます。','2026-12-06','17:00','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (15,212,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.503400000,138.755000000,'新倉山浅間公園で定番の五重塔と富士山を撮影','外国人観光客にも大人気の撮影スポットである新倉山浅間公園の階段を登り、展望デッキへとやってきました。朱色の五重塔と雄大な富士山が同じフレームに収まる日本らしい絶景をカメラでバッチリ撮影します。完璧な構図の写真が撮れて大満足の撮影タイムになりました。','2026-09-10','12:00','📷','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (8,113,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.323000000,141.123000000,'平泉・中尊寺の金色堂へ向けてドライブ','2日目の朝。ホテルをチェックアウトして車を南下させ、世界遺産の平泉へ。少しひんやりとした朝の空気の中、緑深い参道を3人でおしゃべりしながら歩く。','2026-09-06','09:30','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,114,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.324000000,141.109000000,'中尊寺の金色堂を見学','荘厳な雰囲気に包まれた金色堂へ到着。金ピカに輝く堂内の美しさに圧倒されながら、「すごいね……」と思わず静かに見入ってしまう。歴史のロマンを肌で感じる。','2026-09-06','10:30','⛩️','0','',-800,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,115,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.321000000,141.115000000,'平泉レストハウスでご当地おやつ','たくさん歩いて小腹が空いたので、平泉のレストハウスへ立ち寄る。名物の「餅パフェ」や、香ばしい胡麻だれがかかったお餅を3人でシェアして食べる。これが想像以上の美味しさ。','2026-09-06','12:00','🍡','0','',-1200,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,116,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.482300000,141.123400000,'道の駅で岩手のお土産を大量買い出し','盛岡へ戻る道中、大きめの道の駅にピットイン。ずらりと並んだ新鮮な野菜や、ごまのクッキー、りんごを使ったお菓子などを「これ美味しそう！」とカゴにどんどん入れていく。','2026-09-06','14:00','🛍️','0','',-4000,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,117,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅ビルで最後の名物ランチ','旅の締めくくりとして盛岡駅ビルへ戻り、最後のランチは「じゃじゃ麺」に挑戦。最後に卵を割ってスープを入れる「チータンタン」までしっかり完食して大満足。','2026-09-06','16:00','🍳','0','',-1500,1,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (8,118,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅から名残惜しく帰路へ','レンタカーを無事に返却し、お土産の詰まった大きな紙袋を抱えて新幹線のホームへ。あっという間の2日間を振り返り、「また次の食いしん坊旅も絶対計画しようね！」と笑顔で手を振って別れた。','2026-09-06','18:00','👋','0','',0,0,0,0,0,0,false,'2026-08-01 10:29:47.564774+09','2026-08-01 10:29:47.564774+09','{}'),
	 (9,119,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.824300000,140.740000000,'青森空港に到着してレンタカーで出発','待ちに待った青森への家族旅行がいよいよスタートしました。飛行機を降りてすぐにレンタカーの手続きを済ませ、チャイルドシートに子どもたちを乗せて出発進行。車窓から見える景色がいつもと違う北国の雰囲気で、家族みんなのテンションが一気に上がっていきます。','2026-10-10','09:30','🍎','0','',0,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,120,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.832000000,140.735000000,'青森市内の市場で名物の海鮮丼朝食','朝早くから移動してお腹がペコペコだったので、地元の活気ある市場へ立ち寄りました。新鮮なホタテやマグロがこれでもかと乗った贅沢な海鮮丼を家族みんなで注文し、一口食べるごとに「美味しいね！」と笑顔がこぼれます。朝から大満足の最高の食べ始めになりました。','2026-10-10','11:00','🦀','0','',-4500,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,121,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.607000000,140.463000000,'弘前市へ向かうドライブとリンゴ並木','青森市内から車を走らせて、りんごの街として知られる弘前市周辺へと移動しました。道路の両側に広がる果樹園には、真っ赤に色づいたたくさんのりんごがたわわに実っており、窓を開けるとふんわりと甘い香りが漂ってきてドライブが一層楽しくなります。','2026-10-10','12:30','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (9,122,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.598000000,140.472000000,'弘前観光の定番・弘前公園をのんびり散策','立派な石垣と豊かな緑に囲まれた弘前公園を家族みんなでのんびりとお散歩しました。お堀の水面に映る美しい景色を眺めながら歩いていると心地よい秋風が吹き抜けていき、歴史あるお城の雰囲気を肌で感じながらリフレッシュできる素晴らしい時間を過ごせました。','2026-10-10','14:00','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,123,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.601000000,140.465000000,'おしゃれなカフェで弘前アップルパイを堪能','歩き疲れたので、街で見つけたレトロでおしゃれなカフェへと滑り込みました。青森といえばやっぱりアップルパイということで、サクサクのパイ生地と甘酸っぱいリンゴのコンポートが絶妙な一品を注文。温かい紅茶とともに味わい、家族みんなで「今まで食べた中で一番美味しいね」と大絶賛でした。','2026-10-10','15:30','🥧','0','',-2400,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,124,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.585000000,140.455000000,'津軽藩ねぷた村で文化体験と大きなお土産選び','伝統的なねぷたの山車がずらりと展示されている津軽藩ねぷた村に立ち寄りました。迫力あるお祭りの雰囲気を間近で感じられたほか、子どもたちは可愛いリンゴの形をした民芸品や地元の特産品に夢中になっていました。お土産のコーナーでもたくさんのりんごお菓子をカゴに入れて大満足の様子でした。','2026-10-10','16:45','🏮','0','',-1800,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (65,1028,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.100556000,132.980556000,'来島海峡大橋を眺める','夕方の来島海峡大橋は美しくて、旅の締めくくりにふさわしい景色だった。','2026-08-04','18:00','🤩','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (9,125,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.630000000,140.300000000,'岩木山のふもとにある温泉宿にチェックイン','夕方に車を走らせて、雄大な岩木山のふもとにひっそりと佇む温泉宿に到着しました。広々とした和室の客室に荷物を置き、旅の疲れをしっかりと癒やすために家族みんなで大浴場へ直行しました。温かい温泉にゆっくり浸かると、日頃の忙しさがすーっと溶けていくような最高の心地よさを味わえました。','2026-10-10','18:30','♨️','0','',-32000,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,126,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.631000000,140.302000000,'宿の豪華な郷土料理とリンゴを使った夕食','夜ご飯はホテル内のレストランで、青森の美味しい食材をふんだんに使った豪華な夕食をいただきました。郷土料理の貝焼き味噌や新鮮なお刺身はもちろん、デザートや料理の隠し味に使われたリンゴの風味を存分に楽しみました。家族でお酒やジュッチを片手に、今日一日楽しかった思い出を語り合いながら最高な夜を過ごしました。','2026-10-10','20:00','🥂','0','',0,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (10,140,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.278900000,141.912300000,'大船渡の海辺にある温泉宿にチェックイン','夕暮れ時に今日の宿泊先である大船渡の温泉ホテルに到着しました。お部屋に荷物を放り出し、冷えた体を温めるためにさっそくオーシャンビューの大浴場へ向かいます。窓の外に広がる夕暮れの海を眺めながら浸かる温泉は格別の心地よさでした。','2026-11-05','18:15','♨️','0','',-16000,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (9,127,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.620000000,140.350000000,'2日目の朝、岩木山を眺める爽快ドライブ','2日目の朝は朝風呂ですっきりと目覚め、宿をチェックアウトして再び車に乗り込みました。目の前にそびえ立つ美しい岩木山の姿を眺めながら、整備された気持ちの良い農免道路をドライブします。澄んだ朝の空気がとても美味しくて、車内では子どもたちも元気いっぱいに歌を歌っていました。','2026-10-11','09:00','⛰️','0','',0,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,128,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.590000000,140.380000000,'観光農園で待ちに待ったりんご狩り体験','今回の旅行の最大メインイベントである観光農園でのリンゴ狩りにやってきました。農園のおじさんに美味しい品種の見分け方を教わりながら、木に実った真っ赤なリンゴを自分の手で丁寧に収穫します。太陽の光をたっぷり浴びた採れたてのリンゴをその場でかじると、シャキッとした食感と濃厚な果汁が口いっぱいに広がって感動しました。','2026-10-11','10:30','🍏','0','',-2500,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,129,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.610000000,140.450000000,'りんご公園で大きなすべり台とピクニック','収穫のあとは、たくさんのリンゴの木が植えられた広大な「弘前アップル公園」へ移動しました。広い芝生の上で子どもたちは思い切り走り回り、リンゴをモチーフにした遊具やすべり台で大はしゃぎです。青空の下で食べるおやつもいつもより格別に美味しく感じられ、家族みんなの笑顔がたくさんあふれる時間になりました。','2026-10-11','12:00','🏃‍♂️','0','',0,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (9,130,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.605000000,140.468000000,'弘前市内の老舗洋食店でご当地ランチ','お昼ごはんは、地元で長く愛されているレトロな洋食屋さんに入って少し早めのランチにしました。デミグラスソースがたっぷりとかかったハンバーグや、青森の食材を使ったボリューム満点のメニューをお腹いっぱい堪能しました。お店の温かい雰囲気も含めて、とても居心地が良くて大満足のランチタイムでした。','2026-10-11','13:30','🍛','0','',-3800,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,131,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.750000000,140.580000000,'道の駅でさらなるお土産と限定ジュースを調達','青森空港へ戻る道すがら、大きな道の駅に立ち寄って最後のお土産の買い出しを行いました。ずらりと並んだ色々な種類の100%リンゴジュースの飲み比べパックや、家族や友人向けのお菓子をカゴいっぱいに詰め込みました。レジのおばちゃんとの方言まじりの温かいやり取りにも、旅の良さをしみじみと感じました。','2026-10-11','15:00','🛍️','0','',-5000,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,132,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.824000000,140.738000000,'青森空港へ戻りレンタカーを無事に返却','楽しかった1泊2日のドライブ旅行もいよいよ終盤となり、無事に青森空港のレンタカー営業所へと車を返却しました。車体にたくさん思い出を乗せて走ってくれた車にお礼を言いながら、お土産がぎっしり詰まった重たい荷物を持って出発ロビーへと向かいました。あっという間の時間で名残惜しさがこみ上げます。','2026-10-11','16:45','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (9,133,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.824300000,140.740000000,'保安検査場を通り家族みんなで帰路へ','最後に空港の売店で名残惜しくソフトクリームを食べたあと、保安検査場を通って帰りの飛行機へと乗り込みました。たくさん遊んで少し疲れた子どもたちがすぐにウトウト眠り始める中、スマホの写真フォルダを見返しつつ「また来年も家族で青森のりんごを食べに来ようね」と優しく話しながら帰路につきました。','2026-10-11','17:30','✈️','0','',0,0,0,0,0,0,false,'2026-08-01 10:37:09.112769+09','2026-08-01 10:37:09.112769+09','{}'),
	 (10,134,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅でレンタカーを借りて三陸へ出発','美味しい魚介を腹一杯食べるために、男2人で仙台駅に集合しました。さっそくレンタカーの手続きを済ませて、今日からの爆食ドライブ旅行に向けてエンジンを始動させます。車内では「まずは何の海鮮を食べるか」の話題で最初から大盛り上がりです。','2026-11-05','09:00','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,135,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.411200000,141.101200000,'日本三景・松島海岸で海風を浴びる','太平洋側のルートを進み、まずは日本三景の松島に立ち寄りました。美しい島々が浮かぶ湾の景色を眺めながら、海の香りが漂う海岸沿いを少しお散歩します。これからの食い倒れ旅に向けて、まずは景勝地でしっかりと気分を高めておきます。','2026-11-05','10:30','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,136,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.512300000,141.312300000,'石巻の市場で豪快な海鮮丼の昼食','お昼どきに合わせて石巻の市場周辺に到着し、地元で人気の海鮮食堂へ飛び込みました。丼からはみ出るほど分厚いマグロや新鮮な旬の地魚が乗った特製海鮮丼を注文し、男2人で夢中になってかき込みます。一口食べるごとに感動の歓声が漏れるほどの絶品でした。','2026-11-05','12:15','🐟','0','',-2600,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,137,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.745600000,141.456700000,'南三陸の海沿いワインディングロードを疾走','さらに北へと車を走らせ、三陸のリアス式海岸が続くダイナミックな道路へと入っていきました。青い海をすぐ右手に見下ろしながら、心地よいエンジンの音を響かせてワインディングロードを駆け抜けます。ドライブ好きの血が騒ぐ最高のシチュエーションです。','2026-11-05','14:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,138,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.901200000,141.678900000,'気仙沼の魚市場で活気ある雰囲気を満喫','水揚げ量で有名な気仙沼の魚市場周辺に立ち寄りました。港町ならではの活気に満ちた雰囲気を肌で感じつつ、水産加工品のお店を覗いてお土産の目星をつけます。海を知り尽くした街の力強さに男2人で圧倒されました。','2026-11-05','15:30','⚓','0','',0,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,139,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.027185424,141.813840866,'三陸の海岸線を望む絶景スポットへ寄り道','ドライブの途中で見つけた見晴らしの良い展望台に車を停めました。切り立った崖とどこまでも広がる太平洋の水平線を眺め、大自然のスケールの大きさに思わず息を呑みます。男同士で並んで海風に吹かれながら、贅沢なコーヒーブレイクを楽しみました。','2026-11-05','16:45','☕','0','',-300,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (55,863,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839000000,132.765900000,'城下町散策','城下町の落ち着いた雰囲気が心地よくて歩くだけで楽しい。','2026-08-12','10:30','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (10,141,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.279500000,141.913500000,'三陸の海の幸を肴に地酒で熱い夜宴会','お待ちかねの夕食は、三陸で獲れたアワビやホタテ、カキなどの豪華な網焼きと刺身の舟盛りが登場しました。地元のキリッとした日本酒を片手に、海の男たちの豪快な料理を次々と平らげていきます。これまでの仕事のことやこれからの人生について、男同士で夜遅くまで語り合いました。','2026-11-05','20:00','🍶','0','',-7500,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,142,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.468203628,141.950397491,'2日目の朝、釜石の海沿いを快走ドライブ','2日目の朝もスッキリと目覚め、ホテルを後にしてさらに北上を続けます。朝の澄んだ空気の中、道路のすぐ脇に広がる穏やかな海の景色を相棒に車を走らせます。車の少ない早朝の海岸線ドライブは、開放感抜群で最高の気分転換になりました。','2026-11-06','09:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,143,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.629490256,141.966705322,'道の駅で名物のホタテとウニをその場で実食','途中で立ち寄った海沿いの大きな道の駅で、朝ごはんに匹敵するサブランチを狙いました。店頭の網でジュージューと香ばしい音を立てて焼かれている巨大なホタテ焼きと、新鮮なウニの串焼きをその場でオーダー。一口食べた瞬間に広がる磯の香りと濃厚な旨みに、男2人で思わず唸ってしまいました。','2026-11-06','10:30','🐚','0','',-1800,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,144,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.646212929,141.977949142,'浄土ヶ浜の透き通る青さと白い岩肌に感動','宮古市にある名勝・浄土ヶ浜へと足を伸ばしました。鋭く白い流紋岩と、底まで透けて見えるほど透明度の高いエメラルドグリーンの海のコントラストが美しすぎます。言葉を失うほどの絶景を目の前にして、しばらく2人で波の音に耳を傾けていました。','2026-11-06','11:45','✨','0','',0,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,145,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.812300000,141.956700000,'宮古市内の老舗食堂で磯ラーメンをすする','お昼ごはんは地元で長年愛されているローカル食堂に入り、名物の「磯ラーメン」を注文しました。ウニやワカメ、フノリといった海の幸のダシがこれでもかと効いた黄金色の塩スープが体に染み渡ります。麺と一緒に海の風味を余すところなくすすり上げて大満足のランチでした。','2026-11-06','13:15','🍜','0','',-1200,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,146,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,40.123400000,141.812300000,'久慈の道の駅で海の特産品を爆買い','さらに北上して、あまちゃんの舞台としても知られる久慈市の道の駅へピットインしました。新鮮な海の珍味や、瓶詰めのウニ、地元の海苔などを「これは絶対うまいやつだ」とカゴにどんどん放り込んでいきます。旅の終わりに向けてお土産の荷物がすごいことになりました。','2026-11-06','15:00','🛍️','0','',-5500,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,147,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'盛岡駅へ戻りレンタカーを無事に返却','三陸海岸を大満喫したあとは内陸へ抜けて盛岡駅近くの営業所へ戻り、レンタカーを無事に返却しました。たくさんの思い出と大量の海鮮土産を積んで無事故で走り切ってくれた相棒に感謝しつつ、新幹線の改札へと向かいます。','2026-11-06','17:30','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (10,148,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.702000000,141.135000000,'駅ナカで最後の締めくくりに一杯やって帰路へ','新幹線の発車時刻まで少し時間があったので、駅ビルのお店で最後のお疲れ様ビールと地元の旬の刺身を少しだけつまむ。「やっぱり三陸の魚は最高だったな」と振り返りながら、心地よい疲労感に包まれて帰りの新幹線へと乗り込みました。','2026-11-06','18:30','🍻','0','',-2100,0,0,0,0,0,false,'2026-08-01 10:42:05.139316+09','2026-08-01 10:42:05.139316+09','{}'),
	 (11,149,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.718600000,140.102400000,'秋田空港に到着してレンタカーで出発','秋田でのドライブ旅行をスタートさせるため、飛行機を降りてすぐにレンタカーの手続きを済ませました。車に乗り込み、これから始まる東北の旅に胸を躍らせながらアクセルを踏み込みます。車窓から見える穏やかな田園風景が、旅情をグッと盛り上げてくれます。','2026-12-05','09:30','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (11,150,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.716700000,140.116700000,'秋田市内で名物の比内地鶏ランチ','最初の目的地として秋田市内の老舗料理店に立ち寄り、日本三大地鶏のひとつである比内地鶏の親子丼を注文しました。香ばしく焼き上げられた鶏肉と、とろとろの濃厚な卵が絶妙に絡み合い、一口食べた瞬間に思わず笑顔がこぼれるほどの美味しさでした。','2026-12-05','11:30','🐔','0','',-1800,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (64,1008,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.846291000,132.879512000,'庄原の集落を歩く','公園近くの集落は静かで、昔ながらの家屋が並んでいた。道は平坦で歩きやすく、ゆっくり歩くと地元の生活の気配が感じられる。観光地ではないが、こうした素朴な風景が旅の印象を深めてくれた。','2026-10-22','14:30','🚶','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (11,151,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.719200000,140.112300000,'エリアなかいち周辺でおしゃれなカフェ休憩','美味しいランチのあとは、市街地のおしゃれなスポット周辺を少しお散歩しました。途中で見つけた素敵なカフェに立ち寄り、秋田県産の素材を使ったスイーツとコーヒーを飲みながら、これからのドライブのルートについて楽しく作戦会議を行います。','2026-12-05','13:00','☕','0','',-1200,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,152,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.721200000,140.125600000,'ねぶり流し館で竿燈まつりの歴史に触れる','秋田の代名詞ともいえる「竿燈まつり」の熱気をいつでも体感できる施設を見学しました。実際に使われる巨大な竿燈の重さや、提灯の精巧な作りに驚かされます。お祭りの当日にここで夜空を揺らす光景を想像するだけで、すごくワクワクした気持ちになりました。','2026-12-05','14:30','🏮','0','',-600,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,153,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.851200000,140.351200000,'日本海沿いを北上する爽快ドライブロード','秋田市内を後にして、今度は日本海に面したルートへと車を走らせました。さえぎるもののない広大な水平線を左手に眺めながら、エンジンの心地よい音を聞きながら海岸線の道を気持ちよく駆け抜けます。ドライブの醍醐味が詰まった最高の時間です。','2026-12-05','16:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,154,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.923400000,140.612300000,'内陸の山あいを縫って温泉郷へ向かう','海岸線から一転して、豊かな森が広がる内陸の山あいの道へと車を進めました。少しずつ辺りが夕暮れに染まり始め、木々の隙間から差し込む夕日がとても幻想的です。秘湯へと向かうワクワク感が高まっていくのを肌で感じながらハンドルを握ります。','2026-12-05','17:30','🌲','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,155,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.901200000,140.781200000,'乳頭温泉郷の秘湯宿にチェックイン','今日の宿泊先である、乳頭温泉郷の風情ある温泉宿に到着しました。趣のある木造りの建物に一歩足を踏み入れると、タイムスリップしたかのような静寂と硫黄の香りに包まれます。さっそく自慢の乳白色の温泉に浸かり、旅の疲れを芯からじっくりと癒やしました。','2026-12-05','18:45','♨️','0','',-18000,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,156,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.901800000,140.782500000,'囲炉裏端で味わう山の幸と秋田の地酒','夜ご飯は風情ある囲炉裏の席で、山菜や川魚の囲炉裏焼き、そして名物の「きりたんぽ鍋」をいただきました。アツアツの出汁が染み込んだきりたんぽと鶏肉の旨みが体に染み渡り、キリッとした秋田の地酒を合わせると最高の一言に尽きます。夜遅くまで贅沢な時間を満喫しました。','2026-12-05','20:15','🍶','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,157,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.734500000,140.712300000,'2日目の朝、神秘的な田沢湖へドライブ','2日目の朝は朝風呂ですっきりと目覚め、宿をあとにして日本一深い湖として知られる田沢湖へと車を走らせました。山道を抜けて目の前にパッと視界が開けた瞬間、言葉を失うほど美しくどこか切ない群青色の湖面が姿を現し、思わず車を停めて見入ってしまいました。','2026-12-06','09:15','✨','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,158,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.751200000,140.691200000,'湖畔に佇む金色の子辰子像を見学','田沢湖のシンボルである、黄金色に輝く「たつこ像」の近くへと足を伸ばしました。澄み切った湖水と青空のコントラストが素晴らしく、湖畔を吹き抜ける風がとても心地よかったです。湖の周りを少しお散歩しながら、綺麗な景色を背景にたくさん写真を撮影しました。','2026-12-06','10:45','🗽','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (11,159,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.601200000,140.451200000,'角館の武家屋敷通りをのんびりお散歩','「みちのくの小京都」と呼ばれる角館の武家屋敷通りへと移動しました。黒板塀の落ち着いた佇まいと立派な歴史的建造物が並ぶ街並みは、まるで江戸時代にタイムスリップしたかのような趣があります。風情ある通りをゆっくりと歩きながら、秋田の深い歴史を肌で感じました。','2026-12-06','12:30','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,160,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.603400000,140.456700000,'武家屋敷の老舗で名物の稲庭うどんを堪能','お昼ごはんは角館の歴史ある建物の中にあるお店で、ツルッとした喉ごしがたまらない「稲庭うどん」のセットをいただきました。透き通るように美しい平打ちの麺と上品なつけ汁が抜群の相性で、歩き疲れた体にスルスルと美味しく入っていき大満足のランチタイムになりました。','2026-12-06','13:45','🍜','0','',-1500,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,161,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.451200000,140.351200000,'道の駅で秋田のお土産をどっさり買い出し','秋田空港へ戻るルートの途中にある大きな道の駅に立ち寄り、旅の最後のお土産探しをしました。いぶりがっこや比内地鶏のスープ、ご当地のお菓子などを「これも美味しそう！」とカゴいっぱいに詰め込み、レジのお姉さんと方言まじりの温かい会話を楽しみました。','2026-12-06','15:30','🛍️','0','',-4500,1,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (11,163,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,39.718600000,140.102400000,'空港のラウンジと売店で旅を締めくくる','保安検査場を通る直前、売店で最後の締めくくりにきりたんぽのカップスープを味わいながら旅の余韻に浸りました。「やっぱり秋田の温泉とご飯は最高だったね」と振り返りながら、帰りの飛行機へと乗り込んで充実した2日間の旅を終えました。','2026-12-06','18:00','✈️','0','',-800,0,0,0,0,0,false,'2026-08-01 10:49:50.192536+09','2026-08-01 10:49:50.192536+09','{}'),
	 (12,164,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅でレンタカーを借りて南下旅スタート','東北を南へ下るドライブ旅行の拠点として、朝の仙台駅に男2人で集合しました。手際よくレンタカーの手続きを済ませ、今日から始まる宮城のグルメと絶景巡りに向けてエンジンを始動させます。車内では「まずは何を食べるか」の話題で最初からテンションが最高潮です。','2026-09-01','09:00','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,165,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.371200000,141.061200000,'日本三景・松島海岸で潮風を感じるお散歩','車を走らせて最初の目的地である日本三景・松島へと到着しました。無数の島々が浮かぶ穏やかな湾の景色を眺めながら、松の木が並ぶ海岸線をのんびりと歩きます。朝の爽やかな潮風を全身に浴びながら、これから始まる旅の無事を祈ってまずはしっかりと景色を目に焼き付けました。','2026-09-01','10:30','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,166,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.373400000,141.065600000,'松島の名物グルメ・焼きカキをその場で堪能','松島に来たら外せない海の幸ということで、海岸沿いの炭火焼きのお店に立ち寄りました。目の前で豪快にジュージューと焼かれる大ぶりのカキを注文し、熱々を一口で頬張ります。口いっぱいに広がる濃厚な磯の旨みと香ばしさに、男2人で「これはたまらん…」と思わず顔を見合わせて感動しました。','2026-09-01','11:45','🦪','0','',-1500,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,167,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.151200000,140.751200000,'内陸へ向けて緑豊かなロードを快走ドライブ','松島をあとにして、今度は西側の内陸部である蔵王エリアへ向けて車を走らせました。徐々に街並みから豊かな緑の山あいへと景色が変わり、緩やかなカーブが続く走りやすい道路を心地よい音楽をかけながら駆け抜けます。ドライブ好きの血が騒ぐ最高の移動時間になりました。','2026-09-01','13:15','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,168,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.121200000,140.451200000,'蔵王エコーラインを登りダイナミックな景色へ','さらに標高をぐんぐん上げていき、宮城と山形を繋ぐ本格的な山岳道路「蔵王エコーライン」へと突入しました。幾重にも重なる山々の大パノラマや、急勾配を力強く登っていくエンジンの唸り音にワクワクが止まりません。標高が高くなるにつれて空気がひんやりとしてきて一気に涼しくなります。','2026-09-01','14:45','⛰️','0','',0,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,169,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.141200000,140.441200000,'蔵王のシンボル・神秘の「御釜」を見学','山頂近くの駐車場に車を停めて、エメラルドグリーンの美しい火口湖「御釜」を見に行きました。荒々しい岩肌の中にぽっかりと浮かぶ神秘的なエメラルドの湖面を目の当たりにして、大自然の生み出した芸術的な絶景にしばらくと言葉を失って見入ってしまいました。','2026-09-01','16:00','✨','0','',-500,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (16,232,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632500000,139.881000000,'シンデレラ城前でパレード鑑賞','夕暮れのシンデレラ城をバックに、大迫力のナイトパレードを鑑賞。光り輝くフロートとキャラクターの笑顔に、家族全員で感動の嵐。','2026-08-05','19:00','🎆','0','',0,1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (12,170,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.131200000,140.481200000,'遠刈田温泉の風情ある温泉宿にチェックイン','山を下りて、今日の宿泊地である遠刈田温泉の温泉街へと到着しました。昔ながらの湯の街情緒が残る素敵な温泉宿にチェックインし、広めの和室に荷物を置いて一息つきます。さっそく名物の源泉掛け流しの大浴場へ向かい、ドライブの冷えと疲れをじっくりと芯から癒やしました。','2026-09-01','18:00','♨️','0','',-16000,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,171,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.132500000,140.483000000,'温泉街の居酒屋で宮城の地酒と美食を堪能','夜ご飯は温泉街を少し歩いて、地元で人気の隠れ家風居酒屋へ繰り出しました。宮城の新鮮なお刺身や地元の食材を使ったおつまみを頼みつつ、辛口でキリッとした宮城の銘酒を次々と合わせます。仕事の話やこれからの人生計画について、男同士で夜遅くまでグラスを傾けながら熱く語り合いました。','2026-09-01','19:45','🍶','0','',-5500,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,172,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.051200000,140.691200000,'2日目の朝、豊かな田園風景を眺めながら南下','2日目の朝は朝風呂ですっきりと目覚め、宿をあとにしてさらに南の白石エリアへと車を走らせました。見渡す限りの黄金色の田園風景が広がる農免道路を、朝の澄んだ空気を感じながら気持ちよく走ります。車の流れもスムーズで、最高の朝のドライブタイムを満喫しました。','2026-09-02','09:15','🌾','0','',0,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,173,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.081200000,140.621200000,'歴史ある白石城の白亜の天守閣を見学','伊達政宗の重臣・片倉小十郎の居城として知られる白石城に立ち寄りました。綺麗に復元された美しい白亜の天守閣を見上げながら、歴史のロマンに思いを馳せます。最上階からの眺望も素晴らしく、周辺の城下町の様子を一望しながら静かな時間を過ごしました。','2026-09-02','10:45','🏯','0','',-600,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,174,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'再び仙台市内に戻りお昼は本場の牛タンランチ','再び車を北へ走らせて仙台市内の中心街へと戻り、旅のメインの一つである本場の牛タンを食べるために有名店へ飛び込みました。分厚くカットされながらも驚くほど柔らかくジューシーな炭火焼き牛タンと、麦飯、テールスープの王道セットを夢中で平らげます。「やっぱり仙台の牛タンは格別だな」と大満足でした。','2026-09-02','13:00','🥩','0','',-2800,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,175,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.251200000,140.861200000,'仙台のシンボル・青葉城址で伊達政宗公像と対面','ランチのあとは、仙台市街を一望できる青葉城址（仙台城跡）へと足を伸ばしました。馬に跨ったお馴染みの伊達政宗公の銅像の前に立ち、眼下に広がる広大な仙台の街並みを眺めます。かつての伊達60万石の威厳を肌で感じつつ、青空の下で記念写真を撮影して思い出をしっかりと残しました。','2026-09-02','14:30','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,176,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.261200000,140.871200000,'市内の老舗お土産店でずんだスイーツを堪能','帰りの新幹線の時間まで少し余裕があったので、仙台名物の「ずんだ」を味わうために甘味処へ立ち寄りました。つぶつぶとした枝豆の風味豊かな特製ずんだシェイクと、甘さ控えめのずんだ餅を注文して小休憩。最後まで宮城のローカルグルメを徹底的に満喫して、お腹もすっかり大満足です。','2026-09-02','15:45','🍵','0','',-900,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (12,177,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅に戻りレンタカーを無事に返却','2日間のドライブ旅行もいよいよフィナーレとなり、仙台駅近くの営業所へ戻ってレンタカーを無事に返却しました。大きなトラブルもなく快適に走り切ってくれた相棒に感謝しつつ、お土産の詰まった重たい荷物を持って駅のコンコースへと向かいます。あっという間の充実した時間でした。','2026-09-02','17:00','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (14,209,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'駅ナカで最後の乾杯をして特急で帰路へ','電車の発車時刻までの間、駅ビルのお店に入って冷えたビールで「富士山登頂お疲れ様！」の乾杯をしました。全身の筋肉痛と心地よい疲労感に包まれながら、スマホの写真フォルダを見返して大興奮のまま特急列車に乗り込みました。','2026-08-06','19:45','🍻','0','',-1500,0,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (12,178,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'駅ビルで最後の締めくくりビールを飲んで帰路へ','新幹線の発車時刻の直前、駅ナカのお店で最後のお疲れ様ビールを軽く一杯引っ掛けました。「次はさらに南の福島あたりまで足を伸ばしてみるか」と次の計画に思いを馳せながら、心地よい疲労感に包まれて帰りの新幹線へと乗り込みました。','2026-09-02','18:00','🍻','0','',-1100,0,0,0,0,0,false,'2026-08-01 10:54:55.138732+09','2026-08-01 10:54:55.138732+09','{}'),
	 (13,180,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.915000000,139.835000000,'日本海側の酒田港に到着して横断旅スタート','日本海と太平洋を横断する今回のドライブ旅の起点として、庄内・酒田エリアに男2人で降り立ちました。まずは地元のレンタカー営業所で手続きを済ませ、目の前に広がる日本海を眺めながらエンジンを始動させます。山脈を越えて太平洋側まで走り抜く壮大な計画に、朝から胸が高鳴ります。','2026-10-05','09:00','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,181,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.922000000,139.841000000,'酒田の海鮮市場で朝獲れ日本海の魚介を堪能','旅の最初のイベントとして、酒田港のすぐ近くにある海鮮市場へと駆け込みました。日本海の荒波が育てた新鮮な甘エビや旬の白身魚がたっぷり乗った豪快な朝昼兼用の海鮮丼を注文します。一口食べた瞬間に広がる濃厚な甘みと弾力のある歯ごたえに、男2人で「やっぱり日本海の魚はレベルが違う…」と唸りました。','2026-10-05','10:30','🐟','0','',-2200,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,182,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.751200000,139.951200000,'庄内の平野部を抜けて内陸の山あいへ進む','日本海側の海岸線をあとにして、いよいよ本州の中央を縦断する奥羽山脈のふもとへと車を進めました。どこまでも広がる庄内平野の黄金色の田園風景を右手に眺めながら、徐々に勾配がきつくなる山道へとハンドルを切っていきます。ここから本格的な横断ドライブの幕開けです。','2026-10-05','12:00','🌾','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,183,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.651200000,140.051200000,'新庄エリアの山あいでローカルコーヒー休憩','山越えの本格的なワインディングロードに突入する前に、山あいの静かなスポットで少し小休憩を取りました。途中で見つけた趣のある小さなカフェに立ち寄り、マスターこだわりのブレンドコーヒーをテイクアウトします。ひんやりとした山の空気を吸い込みながら、これからの険しい山越えに向けて気合を入れ直しました。','2026-10-05','13:30','☕','0','',-600,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,184,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.451200000,140.351200000,'奥羽山脈を横断する峠道をダイナミックに疾走','山形と宮城の県境を跨ぐダイナミックな山岳道路へと突入しました。幾重にも折り重なる急カーブを、マニュアル感覚のシフトチェンジで力強くクリアしながら標高を上げていきます。窓の外には見渡す限りの深い原生林が広がり、エンジンの心地よいエキゾーストノートが山々に響き渡る最高のドライビングロードです。','2026-10-05','15:00','⛰️','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,185,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.351200000,140.651200000,'山を越えて太平洋側・鳴子峡の絶景に感動','険しい峠道を無事に抜け出し、ついに太平洋側の宮城サイドへと突入しました。東北屈指の紅葉名所としても知られる「鳴子峡」の巨大なV字谷の展望スポットに車を停め、目の前に広がる大迫力の断崖絶壁と深い谷底の景色に圧倒されます。日本海から太平洋へと本当にやってきたんだという実感が湧いてきました。','2026-10-05','16:30','✨','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,186,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.741200000,140.721200000,'鳴子温泉郷の歴史ある温泉宿にチェックイン','山越えのドライブで心地よい疲労感を覚えつつ、今日の宿泊先である鳴子温泉郷の老舗宿に到着しました。木造りの風情ある佇まいに迎えられ、さっそく硫黄の香りが漂う名湯の大浴場へ向かいます。横断を成し遂げた達成感を味わいながら、熱めのお湯にじっくりと体を浸して最高のリフレッシュタイムを過ごしました。','2026-10-05','18:15','♨️','0','',-17000,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,187,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.742500000,140.723000000,'温泉街の居酒屋で日本海と太平洋の酒を飲み比べる','夜ご飯は温泉街の隠れ家的な居酒屋に繰り出しました。日本海側の山形の銘酒と、太平洋側の宮城の銘酒を両方揃えてもらい、それぞれの味わいの違いを男2人で熱く語り合いながら宮城の美味しい郷土料理を次々と平らげます。横断成功の乾杯のグラスが何度も鳴り響く、最高に熱い夜宴会になりました。','2026-10-05','20:00','🍶','0','',-6000,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,188,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.561200000,141.051200000,'2日目の朝、一気に太平洋側へ南下ドライブ','2日目の朝は朝風呂でシャキッと目覚め、宿をあとにして今度は宮城の太平洋側を目指して南東方向へ車を走らせました。なだらかな丘陵地帯を抜けて、徐々に海の気配が近づいてくる道をリズミカルに走ります。車窓を流れる景色が日本海側から太平洋側へと完全に切り替わっていくのが面白いです。','2026-10-06','09:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (13,189,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.371200000,141.061200000,'日本三景・松島海岸の太平洋ビューを満喫','太平洋側のハイライトとして、日本三景・松島海岸のエリアへと到着しました。昨日眺めていた日本海の荒々しい海とは打って変わって、穏やかな内海にたくさんの小島が浮かぶ静かな太平洋の景色を眺めながら、海沿いの遊歩道をのんびりと歩いて横断の旅情をしみじみとかみしめました。','2026-10-06','10:30','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (16,226,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632300000,139.880400000,'東京ディズニーランド・エントランス','手荷物検査を抜けて、ついにワールドバザールへ！お馴染みの音楽とシンデレラ城が見えてきて大人も胸が熱くなる。まずはポップコーンバケットをゲットしに行こう！','2026-08-05','09:00','✨','0','',-3400,1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (16,227,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.631200000,139.878200000,'アドベンチャーランドでジャングルクルーズ','最初の アトラクションはジャングルクルーズ！船長さんの楽しいトークに子どもたちが大爆笑。リアルな動物の動きにみんなで大興奮した。','2026-08-05','10:15','🥳','0','',0,1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (16,228,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633500000,139.879000000,'ウエスタンランドのレストランでランチ','お昼ごはんはハンバーガーとチキンレッグにかぶりつく！ボリューム満点で美味しいけれど、お昼時ですごい混雑していて席を探すのに一苦労した。','2026-08-05','12:00','🍔','1','',-4500,0,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (13,190,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.373400000,141.065600000,'松島の海鮮処で太平洋のカキ焼きを実食','日本海側の魚介と食べ比べるために、松島の海岸沿いにあるお店で名物のカキ焼きを再びオーダーしました。目の前で香ばしく焼かれた大ぶりのカキを口に含むと、太平洋ならではの濃厚でクリーミーな旨みが一気に広がります。「どちらの海もそれぞれの良さがあって最高だな」と男2人で深く納得しながら完食しました。','2026-10-06','12:00','🦪','0','',-1600,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,191,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台市内に戻り旅のフィナーレへ向かう','松島をあとにして車をさらに南西へ走らせ、今回の横断ドライブのゴール地点となる仙台市内の中心街へと戻ってきました。都会的なビル街の景色に変わり、無事にここまで走り抜けてくれた相棒の車にお疲れ様と言いながら大通りを進みます。旅の終わりが近づいて少し名残惜しい気持ちになります。','2026-10-06','13:30','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,192,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.269200000,140.875000000,'仙台市内の名店で本場の厚切り牛タンランチ','横断旅の最後の晩餐（お昼ごはん）として、仙台市内の大人気牛タン専門店へ飛び込みました。分厚くカットされて炭火で香ばしく焼き上げられたジューシーな牛タンと、お代わり必須の麦飯を夢中になって平らげます。この旅ですっかり肥えたお腹と心に、最高の形でガツンとご馳走が染み渡りました。','2026-10-06','14:45','🥩','0','',-2900,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (13,193,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'仙台駅でレンタカーを無事に返却','日本海側を出発し、奥羽山脈を越えて太平洋側まで見事に走り抜いた2日間の横断ドライブの全日程が終了し、仙台駅近くの営業所でレンタカーを無事に返却しました。大きなトラブルもなく、たくさんの絶景と美食を運んでくれた相棒の車に心から感謝しました。','2026-10-06','16:30','🤝','0','',-7000,1,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}'),
	 (14,208,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'甲府駅周辺へ戻りレンタカーを無事に返却','富士山登頂の過酷で素晴らしい挑戦をともに乗り越えた相棒のレンタカーを、甲府駅近くの営業所へ無事に返却しました。車体にたくさんの思い出と旅の埃を乗せて走り切ってくれた車に心から感謝しつつ、駅のコンコースへと向かいました。','2026-08-06','19:00','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (13,194,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.268800000,140.881700000,'駅ビルで最後の乾杯をして新幹線で帰路へ','新幹線の発車時刻まで少し時間があったので、駅構内のお店で最後のお疲れ様ビールを軽く一杯引っ掛けました。「日本海から太平洋への横断、本当に最高のルートだったな」と地図を広げながら振り返り、心地よい疲労感と大きな達成感に包まれながら帰りの新幹線へと乗り込みました。','2026-10-06','17:30','🍻','0','',-1200,0,0,0,0,0,false,'2026-08-01 11:00:38.510079+09','2026-08-01 11:00:38.510079+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (15,213,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.461200000,138.851200000,'忍野八海の透明すぎる湧水池をのんびり散策','富士山の雪解け水が何十年もかけて湧き出るという「忍野八海」のエリアへと足を伸ばしました。底までハッキリと見えるほど透き通った青い湧水池や、昔ながらの茅葺き屋根の民家が並ぶ景色をのんびりと歩きながら巡ります。清らかな水面に心を洗われるような、とても穏やかな時間を過ごせました。','2026-09-10','13:45','💧','0','',-300,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,214,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.421200000,138.881200000,'山中湖のほとりで白鳥と富士山をカメラに収める','さらに東へと進み、富士五湖の中で最も大きい山中湖の湖畔へと車を停めました。水面を優雅に泳ぐ白鳥の群れと、その背景にそびえる富士山という絵画のような景色を狙ってカメラのシャッターを切ります。涼しい湖畔の風に吹かれながら、ドライブの心地よさを存分に満喫しました。','2026-09-10','15:30','🦢','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,215,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.451200000,138.911200000,'三国山パノラマ台から夕暮れの富士山を狙う','日没が近づいてきたタイミングで、山中湖の少し高台にある「パノラマ台」へと車を走らせました。眼下に広がる山中湖と、その向こう側に夕日を浴びて少しずつ赤く染まっていく富士山のダイナミックなシルエットを撮影します。ドラマチックに移り変わる夕景の美しさに息を呑みました。','2026-09-10','17:15','🌇','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,216,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.481200000,138.791200000,'河口湖畔の温泉ホテルにチェックイン','撮影をたっぷり楽しんだあとは、河口湖のほとりに佇む眺望抜群の温泉ホテルへとチェックインしました。部屋の窓からライトアップされた夜の富士山を眺めつつ、さっそく広い大浴場へと向かってドライブの疲れをじっくりと癒やします。贅沢なロケーションに心からリラックスできました。','2026-09-10','18:45','♨️','0','',-18000,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,217,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.482500000,138.793000000,'ホテル内のレストランで山梨の郷土料理を満喫','夜ご飯はホテル内の落ち着いたレストランで、山梨名物の「ほうとう鍋」や地元の新鮮な野菜を使った料理をいただきました。カボチャや根菜がたっぷり入ったアツアツの味噌仕立てのほうとうが体に染み渡り、山梨の美味しい赤ワインと一緒に味わうことで最高のディナータイムになりました。','2026-09-10','20:15','🍷','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,218,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.471200000,138.711200000,'2日目の朝、西湖の静寂な湖畔をドライブ','2日目の朝は朝風呂ですっきりと目覚め、ホテルをあとにして少し落ち着いた雰囲気の「西湖」周辺へと車を走らせました。観光地の人混みも少なく、木々に囲まれた静かな湖面が鏡のように景色を映し出しています。朝の澄んだ空気の中を巡るドライブは、心から癒やされる素晴らしい時間でした。','2026-09-11','09:15','🌲','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,219,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.481200000,138.651200000,'神秘的な青木ヶ原樹海の散策路を歩く','西湖のすぐ近くにある「青木ヶ原樹海」の整備された自然散策路へと足を踏み入れました。溶岩の上に力強く根を張る独特な森の木々と、苔むした神秘的な景色がどこか異世界のような雰囲気を醸し出しています。大自然の生命力を間近に感じながら、静かな森のなかを少しお散歩しました。','2026-09-11','10:45','🍃','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,220,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.481200000,138.611200000,'本栖湖の展望スポットで千円札の裏の景色を確認','富士五湖の一つであり、かつて旧五千円札や現行千円札の裏面に描かれた富士山のモデルになった「本栖湖」のビューポイントに立ち寄りました。目の前に広がる湖面と富士山の構図が、まさにあの紙幣のデザインそのままで「おお、本物だ！」と感動しながら記念の写真を何枚も撮影しました。','2026-09-11','12:30','💵','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,221,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.491200000,138.601200000,'湖畔のロッジ風カフェでおしゃれなランチ','本栖湖の近くにあるおしゃれなロッジ風のカフェに入り、少し遅めのランチタイムにしました。富士山の伏流水を使って淹れられたこだわりのコーヒーと、地元食材をふんだんに使ったサンドイッチを味わいます。大きな窓から見える緑豊かな景色を眺めながら、ゆったりとした優雅な時間を過ごしました。','2026-09-11','13:45','☕','0','',-1600,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,222,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.531200000,138.551200000,'道の駅で山梨の美味しいお土産を爆買い','甲府へ戻るルートの途中にある大きな道の駅に立ち寄り、旅の最後のお土産の買い出しを行いました。山梨の名産であるシャインマスカットや、特製のワイン、ほうとうの乾麺などを「これも買っていこう」とカゴにたくさん詰め込みました。最後まで大満足のショッピングでした。','2026-09-11','15:30','🛍️','0','',-5500,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (15,223,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'甲府駅に戻りレンタカーを無事に返却','富士五湖の絶景と素晴らしい撮影スポットを巡った2日間のドライブ旅のフィナーレとして、甲府駅近くの営業所でレンタカーを無事に返却しました。たくさんの写真と楽しい思い出を車に積んで安全に走り切ってくれた相棒に感謝しつつ、駅へと向かいます。','2026-09-11','17:00','🤝','0','',-6500,1,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (15,224,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.591200000,138.561200000,'駅ナカで最後の締めくくりビールを飲んで帰路へ','電車の発車時刻までの少しの時間、駅ビルのお店に入って冷えたビールで「最高の撮影ドライブだったな！」と乾杯しました。撮影した写真フォルダを振り返りながら心地よい余韻に浸り、充実感に包まれながら帰りの列車へと乗り込みました。','2026-09-11','18:00','🍻','0','',-1100,0,0,0,0,0,false,'2026-08-01 11:13:10.404712+09','2026-08-01 11:13:10.404712+09','{}'),
	 (14,195,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401200000,138.801200000,'富士スバルラインを登り五合目へ到着','日本最高峰の富士山登頂に挑むため、男2人でレンタカーを走らせて富士スバルラインを登り、登山の拠点となる富士山五合目へと到着しました。標高が一気に上がり、ひんやりとした澄んだ空気の中で登山靴の紐をしっかりと締め直します。これから始まる過酷で最高な挑戦に向けて、胸の高鳴りが最高潮に達しました。','2026-08-05','08:30','🚙','0','',-2100,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,196,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.361200000,138.731200000,'吉田口の登山道からいよいよアタック開始','準備を万全にして、いよいよ吉田口の登山口から本格的な登山道へと足を踏み入れました。最初はなだらかな樹林帯を進みつつ、徐々に傾斜がきつくなっていく道のりを一歩一歩確実に進んでいきます。すれ違う下山者と「こんにちは！」と声を掛け合いながら、男2人で気合を入れてペースを維持します。','2026-08-05','09:45','🥾','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,197,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.365000000,138.735000000,'急な岩場を登り七合目の山小屋で小休憩','標高が上がり、周囲が火山性のゴツゴツとした岩場に変わってきたところで、七合目の山小屋に到着しました。少し冷えてきた体を休めるために小屋のベンチで温かいお湯を飲み、標高の高さによる息切れを整えつつ、目の前に広がり始めた見事な雲海の景色を眺めてエネルギーを補給しました。','2026-08-05','12:30','⛰️','0','',-800,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,198,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.363000000,138.729000000,'八合目の山小屋に到着して一時待機と夕食','夕方に八合目の山小屋へ無事に到着し、明日の早朝アタックに向けた体力温存と高所順応のための小休止を取りました。簡易的な夕食をかき込みながら、窓の外に沈む幻想的な夕日と、眼下に広がる街の明かりを眺めます。標高3000メートルを超える圧倒的なスケール感に、男2人で静かに感動しました。','2026-08-05','17:00','🌅','0','',-8500,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (18,253,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.550500000,139.891200000,'オリオン通り商店街でアイス休憩','レトロなアーケードが続く商店街を散策。歩き疲れて暑さもピークに達したため、喫茶店に入って冷たい宇都宮レモネードを飲んで生き返る。','2026-08-05','14:10','🥤','0','',-550,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,254,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.548000000,139.889000000,'行列のできる老舗餃子店にチャレンジ','ガイドブックにも載っている超有名老舗店へ到着。しかし想像以上の大行列で、蒸し暑い中40分以上並ぶ羽目に…。足も腰もクタクタになって少しぐったり。','2026-08-05','15:00','😫','2','',0,-1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,255,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.548000000,139.889000000,'念願の老舗の「水餃子」に舌鼓','並んで食べた水餃子は、特製のスープとモチモチの皮が絶品！お酢とラー油をたっぷり入れて食べたら、並んだ苦労が吹き飛ぶほどの美味しさだった。','2026-08-05','16:00','🍲','0','',-950,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,256,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.545000000,139.899000000,'宇都宮城址公園でお腹を休める','食後の運動を兼ねて、綺麗に整備された城址公園を散歩。復元された美しいお城や広大な芝生を眺めながら、ベンチでまったり休憩。','2026-08-05','17:00','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (18,257,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.552000000,139.895000000,'隠れ家カフェでコーヒーブレイク','夕暮れ時の街を眺めながら、おしゃれな個人カフェへ。甘いチーズケーキとブラックコーヒーで、お口の中をさっぱりリセット。','2026-08-05','18:00','🍰','0','',-850,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,258,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.557000000,139.897500000,'餃子テーマパークで最後の食べ比べ','夜の部は複数の専門店が集まる人気スポットへ。揚げ餃子やシソ餃子など、バラエティ豊かな味を少しずつ欲張って食べ比べ！','2026-08-05','19:15','🥳','0','',-1600,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,259,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559000000,139.898000000,'駅ビルでお土産の冷凍餃子を物色','帰る前に駅ナカのお土産売り場へ。種類が多すぎてどれを買うかすごく迷う。レジの混雑に少し焦ったけれど、無事に人気の冷凍餃子を確保。','2026-08-05','20:20','🛍️','0','',-3500,0,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,260,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559400000,139.898300000,'宇都宮駅のホームで新幹線を待つ','お腹いっぱい＆お土産も買って大満足の状態でホームへ。心地よい疲労感に浸りながら、帰りの新幹線の時間を待つ。','2026-08-05','21:00','🌙','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,261,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559400000,139.898300000,'新幹線車内でプチ反省会','発車した新幹線の座席で、今日撮った写真を見返す。食べすぎたねと笑い合いながら、最高の一日をしめくくる。','2026-08-05','21:30','✨','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,262,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.681200000,139.767100000,'東京駅に無事到着','あっという間に東京駅へ戻ってきた。現実に戻る寂しさはあるけれど、クーラーの効いた快適な駅構内を足早に自宅へ向かう。','2026-08-05','22:20','🚅','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (14,199,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.360600000,138.727400000,'真夜中の山小屋を出発し山頂アタック開始','まだ辺りが真っ暗な夜中、ヘッドライトの灯りを頼りに八合目の山小屋を出発して最後の山頂アタックへ踏み出しました。一歩一歩足元を確認しながら急勾配の九十九折を進みます。満天の星空と眼下に広がる街の夜景の美しさが、過酷な登攀のつらさを忘れさせてくれる最高の励みになりました。','2026-08-06','02:00','✨','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,200,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.360600000,138.727400000,'ついに富士山剣ヶ峰の山頂へ登頂成功','過酷な登りを耐え抜き、ついに日本最高峰である富士山頂（剣ヶ峰）へと足を踏み入れました。東の空からゆっくりと昇ってくる神々しい「ご来光」を目の当たりにし、言葉を失うほどの感動が全身を包み込みます。「やり遂げたな！」と男2人で固い握手を交わし、忘れられない最高の瞬間を噛み締めました。','2026-08-06','04:45','☀️','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,201,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.361000000,138.730000000,'山頂の売店で温かいカップ麺をすする','登頂の達成感に浸りながら、山頂にある売店で販売されている名物の温かいカップ麺を注文しました。標高3776メートルの極寒の空気の中で食べるアツアツの汁物が、疲労した体に染み渡るように美味しくて感動します。こんな贅沢な食事はほかにありません。','2026-08-06','05:30','🍜','0','',-800,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,202,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.362000000,138.732000000,'火山灰の続く道を慎重に下山開始','山頂での感動的な時間を満喫したあとは、足元に気をつけながら長い下山道へと入りました。砂走りやザクザクとした火山灰の斜面をバランスを取りながら慎重に下っていきます。疲労がピークに達した足に鞭を打ちつつ、声を掛け合って一歩ずつ着実に下を目指しました。','2026-08-06','06:45','🥾','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (14,203,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401200000,138.801200000,'無事に五合目へ下山しレンタカーに乗り込む','長い下山路をようやく歩ききり、出発地点である五合目の登山口へと無事に戻ってきました。無事に登頂を果たして戻ってきた愛車を見た瞬間、心地よい達成感と安堵感が一気にこみ上げてきます。重いザックをトランクに積み込み、麓の温泉街へと車を発進させました。','2026-08-06','11:30','🤝','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,204,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.451200000,138.781200000,'麓の温泉施設で登山の手足を徹底的に癒やす','山を下りて河口湖周辺にある日帰り温泉施設へ直行しました。広々とした露天風呂から富士山の姿を眺めながら、登山でパンパンに張った筋肉と疲れた体をゆっくりとほぐしていきます。「本当によく頑張ったな」と湯船に浸かりながら男2人でしみじみと語り合う、至福の回復タイムになりました。','2026-08-06','13:00','♨️','0','',-1200,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,205,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.501200000,138.761200000,'富士吉田の老舗で名物の吉田うどんを食らう','お腹がペコペコになった状態で、コシが強くて有名な富士吉田のローカルうどん店に入りました。力強い手打ち麺とキャベツや馬肉が入った濃厚なスープの「吉田のうどん」を夢中ですすり上げます。登山で疲労した体に塩分と炭水化物がガツンとダイレクトに染み渡り、最高のエネルギーチャージになりました。','2026-08-06','14:45','🍲','0','',-900,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,206,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.503400000,138.755000000,'新倉山浅間公園で五重塔と富士山の絶景を撮影','登頂の記念と記録を兼ねて、世界的に有名な絶景スポットである新倉山浅間公園へと立ち寄りました。階段を少し登った先にある展望デッキから、朱色の五重塔と雄大な富士山が綺麗に重なる圧巻の景色をカメラに収めます。自分たちがさっきまであのてっぺんにいたんだという実感が再び湧いてきました。','2026-08-06','16:15','📷','0','',0,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (14,207,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.491200000,138.771200000,'道の駅で山梨の特産品とぶどうジュースを購入','帰路につく前に、地元の大きな道の駅に立ち寄って家族や自分向けのお土産を選びました。山梨ならではの新鮮な桃や、濃厚な果汁100%のぶどうジュースを「これは絶対うまいやつだ」とカゴに放り込みます。旅の終わりを感じながらも充実感に浸る楽しいショッピングタイムでした。','2026-08-06','17:30','🛍️','0','',-4500,1,0,0,0,0,false,'2026-08-01 11:13:20.035139+09','2026-08-01 11:13:20.035139+09','{}'),
	 (16,229,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.634800000,139.881200000,'ホーンテッドマンションでドキドキ体験','少し涼を求めてホーンテッドマンションへ。不気味だけどユーモラスな世界観に、子どもたちは怖がりつつも目をキラキラさせて楽しんでいた。','2026-08-05','13:40','👻','1','',0,1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (16,230,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.635500000,139.882500000,'ファンタジーランドでアトラクション満喫','ピーターパンやダンボを乗り継ぎ。待ち時間が長くて後半は子どもたちの足が疲れてぐずり出し、なだめるのが大変だった。親の体力も限界に近づく…。','2026-08-05','15:30','😫','2','',0,-1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (16,231,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633800000,139.883000000,'トゥーンタウンで可愛いチュロス休憩','甘い香りに誘われてミッキーチュロスを購入。可愛い見た目とサクサクの食感に、疲れが一気に吹き飛んだ！記念に家族みんなでパシャリ。','2026-08-05','17:00','😋','0','',-1600,1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (16,233,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632000000,139.880200000,'ワールドバザールでお土産ショッピング','閉園間際、お土産ショップへ駆け込んで大混雑の中お菓子やグッズを爆買い！レジの長蛇の列にヘトヘトになりながらも、楽しかったねと笑顔でカゴいっぱいに詰めた。','2026-08-05','20:15','🛍️','0','',-12500,0,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (17,235,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632300000,139.880400000,'東京ディズニーランド・エントランス','手荷物検査を抜けて、ついにワールドバザールへ！お馴染みの音楽とシンデレラ城が見えてきて大人も胸が熱くなる。まずはポップコーンバケットをゲット！','2026-08-05','09:00','✨','0','',-3400,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (17,236,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.631200000,139.878200000,'アドベンチャーランドでジャングルクルーズ','最初の アトラクションはジャングルクルーズ！船長さんの楽しいトークに子どもたちが大爆笑。リアルな動物の動きにみんなで大興奮した。','2026-08-05','09:45','🥳','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,237,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.630500000,139.877000000,'カリブの海賊で涼みながら冒険','ひんやりした洞窟を進むカリブの海賊へ。迫力ある砲撃音にびっくりしつつも、スリリングなボートの雰囲気を家族みんなで満喫した。','2026-08-05','10:30','🏴‍☠️','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,238,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.631800000,139.878500000,'ウエスタンランドでスナック休憩','ちょっと小腹が空いたので、スモークターキーレッグを買い食い。ジューシーでスパイシーな肉汁がたまらない！パパと半分こして食べた。','2026-08-05','11:15','🍖','1','',-900,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,239,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633500000,139.879000000,'グランマ・サラのキッチンでランチ','お昼ごはんはオムライスやハンバーグが食べられるレストランへ。可愛い店内でホッと一息つけるけれど、お昼時ですごい混雑していて席を探すのに苦労した。','2026-08-05','12:15','🍔','1','',-4800,0,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,240,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.635000000,139.879800000,'ビッグサンダー・マウンテンに挑戦','スリル満点のコースター系アトラクション！急降下するたびに子どもたちの絶叫と楽しそうな笑い声が響き渡り、大盛り上がりだった。','2026-08-05','13:30','🎢','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,241,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.634800000,139.881200000,'ホーンテッドマンションで涼む','午後の暑さを避けてホーンテッドマンションへ。不気味だけどユーモラスな世界観に、子どもたちは怖がりつつも目をキラキラさせて楽しんでいた。','2026-08-05','14:45','👻','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,242,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.636000000,139.882000000,'ファンタジーランドでアトラクション巡り','ピーターパンやダンボを乗り継ぎ。待ち時間が長くて後半は子どもたちの足が疲れてぐずり出し、なだめるのが大変だった。親の体力も限界に…。','2026-08-05','16:00','😫','2','',0,-1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,243,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633800000,139.883000000,'トゥーンタウンで可愛いチュロス休憩','甘い香りに誘われてミッキーチュロスを購入。可愛い見た目とサクサクの食感に、疲れが一気に吹き飛んだ！記念に家族みんなでパシャリ。','2026-08-05','17:15','😋','0','',-1600,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,244,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.633000000,139.881500000,'プラザパビリオンで早めの夕食','夜のパレード前に腹ごしらえ。ハンバーグプレートを食べてしっかりエネルギーを補給。お店が比較的空いていてゆっくり座れて助かった。','2026-08-05','18:15','🍽️','0','',-3600,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,245,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632500000,139.881000000,'シンデレラ城前でエレクトリカルパレード','夕暮れのシンデレラ城をバックに、大迫力のナイトパレードを鑑賞。光り輝くフロートとキャラクターの笑顔に、家族全員で感動の嵐。','2026-08-05','19:30','🎆','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (17,246,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632000000,139.880500000,'夜のワールドバザールでウインドウショッピング','パレード終わりの華やかな雰囲気が漂うメインストリートをゆっくりお散歩。ライトアップされた街並みがとても綺麗でロマンチック。','2026-08-05','20:15','✨','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,247,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632300000,139.880400000,'お土産ショップで爆買いタイム','閉園間際、お土産ショップへ駆け込んで大混雑の中お菓子やグッズを爆買い！レジの長蛇の列にヘトヘトになりながらもカゴいっぱいに詰めた。','2026-08-05','20:45','🛍️','0','',-12500,0,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (17,248,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.632900000,139.880000000,'舞浜駅に戻り、帰路の電車へ','楽しかった一日に名残りを惜しみつつ、舞浜駅から帰りの電車へ。子どもたちは歩き疲れてぐっすり夢の中。充実感いっぱいの最高のディズニー旅だった！','2026-08-05','21:30','🌙','0','',0,1,0,0,0,0,false,'2026-08-01 16:44:23.443369+09','2026-08-01 16:44:23.443369+09','{}'),
	 (16,225,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.598414848,135.943450928,'舞浜駅に到着！いざ夢の国へ','朝早くから新幹線と電車を乗り継いで、ついに舞浜駅に到着！子どもたちも「ディズニーだ！」と大はしゃぎで、一気にテンションがマックスに。ワクワクが止まらない。','2026-08-05','08:30','🤩','0','',0,1,0,0,0,0,true,'2026-08-01 16:39:18.998165+09','2026-08-01 16:44:43.266097+09','{}'),
	 (18,249,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559400000,139.898300000,'JR宇都宮駅に到着！餃子の像がお出迎え','新幹線を降りて改札を出ると、さっそく名物の「餃子像」がお出迎え！駅のまわりからほのかに美味しそうな香りがしてきて、早くも食欲がそそられる。','2026-08-05','11:00','🥟','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,250,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.558000000,139.897000000,'宇都宮パセオで1軒目の有名店へ直行','駅からすぐの商業施設内にある有名餃子店へ。焼き立ての餃子は皮がパリッパリ、中はジューシーで肉汁があふれ出す！ビールが欲しくなる最高の味。','2026-08-05','11:30','🍺','0','',-1200,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (18,251,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.555000000,139.895000000,'市内をのんびりお散歩しながら移動','次の目的地に向けて、宇都宮の街並みを眺めながらぶらぶら歩き。夏の暑さで少し汗ばんできたけれど、緑豊かな通りが気持ちいい。','2026-08-05','12:45','🚶‍♂️','1','',0,0,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (29,414,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226200000,135.167000000,'和歌山城天守閣','天守閣からの景色が最高。写真を撮りまくって大盛り上がり。入館料410円。','2026-08-10','10:40','🤩','0','',-410,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (18,252,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.552000000,139.893000000,'宇都宮二荒山神社で旅の安全祈願','街の中心にある風格漂う神社へ参拝。立派な楼門や静かな境内に心が落ち着く。これからの食べ歩きが無事に楽しめるようしっかりとお祈りした。','2026-08-05','13:15','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (28,399,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.805000000,'奈良駅に到着','新幹線と在来線を乗り継ぎ奈良駅へ。駅前の落ち着いた雰囲気に旅の期待が高まる。コーヒーを飲んでひと息つき450円。','2026-08-02','09:10','🙂','0000','',-450,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (18,263,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.689500000,139.691700000,'自宅に到着して冷凍餃子を冷蔵庫へ','無事に帰宅完了！お土産の冷凍餃子を大切に冷蔵庫にしまい、充実感に包まれながらベッドへ直行。楽しい宇都宮の一日が終わった。','2026-08-05','23:10','🏠','0','',0,1,0,0,0,0,false,'2026-08-01 16:49:50.805668+09','2026-08-01 16:49:50.805668+09','{}'),
	 (22,320,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.960000000,138.360000000,'ご当地グルメのお蕎麦でランチ休憩','佐渡産のそば粉を使ったこだわりのお蕎麦屋さんで、コシの強い手打ちそばと山菜の天ぷらを味わう。素朴で味わい深い美味しさ。','2026-06-02','14:00','🍜','0','',-1100,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,321,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.010000000,138.420000000,'トキの森公園で本物のトキを見学','国の特別天然記念物「トキ」を保護・飼育しているトキの森公園へ。間近で観察できる朱鷺資料館で、優雅な姿のトキに魅了される。','2026-06-02','15:30','🐦','0','',-400,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,322,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.065358564,138.427133560,'両津港のお土産市場で特産品を爆買い','両津港に戻り、ターミナルのお土産売り場で佐渡のお米や「おけさ柿」のお菓子、日本酒などを大量に買い込む。','2026-06-02','17:00','🛍️','0','',-3500,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,323,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.083300000,138.433300000,'両津港からフェリーに乗り、佐渡島をあとに','思い出いっぱいの荷物を抱えてフェリーに乗船。甲板から遠ざかる佐渡島を眺めながら、充実感に浸りつつ帰路につく。','2026-06-02','18:00','👋','0','',0,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (27,387,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.652500000,135.506300000,'新世界・通天閣周辺','新幹線と電車を乗り継いで、ようやく大阪に到着！通天閣の下はすごい活気で、一気に大阪らしい雰囲気にテンションが上がる。まずは名物の串カツの匂いに誘われて、お腹の虫が鳴り始める。','2026-08-01','12:30','🤩','0','',-1200,1,0,0,0,0,false,'2026-08-01 19:02:38.640345+09','2026-08-01 19:02:38.640345+09','{}'),
	 (27,388,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.656000000,135.504500000,'元祖串かつでソース二度漬け禁止を体験','サクサクの衣と特製ソースが絶品！二度漬け禁止のルールを守りつつ、ビールと串カツの最高の組み合わせを満喫した。','2026-08-01','13:15','🍻','0','',-2400,1,0,0,0,0,false,'2026-08-01 19:02:38.640345+09','2026-08-01 19:02:38.640345+09','{}'),
	 (19,265,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.561000000,136.656500000,'近江町市場で新鮮な海の幸ランチ','お昼ごはんは活気あふれる近江町市場へ。ノドグロや甘エビがたっぷり乗った海鮮丼を味わう。新鮮でとろける美味しさに思わず笑みがこぼれる。','2026-08-05','12:00','丼','0','',-3800,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,266,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.562200000,136.662000000,'金沢城公園の広大な敷地をのんびり散策','白亜の美しい石川門や復元された長屋を見学。よく手入れされた広大な芝生と歴史ある建造物を、自分のペースでゆっくり歩いて見て回った。','2026-08-05','13:45','🏯','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,267,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.561300000,136.663700000,'兼六園の日本庭園で緑に癒やされる','日本三名園の一つ、兼六園へ。樹齢数百年の松や美しい霞ヶ池を眺めながらそぞろ歩き。風情ある景色に心がすっきりと洗われるような心地よさ。','2026-08-05','15:00','🌲','0','',-650,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (19,268,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.560000000,136.660000000,'老舗茶屋で金箔入り抹茶休憩','歩き疲れたので、伝統的な日本家屋の茶屋でひと休み。きらびやかな金箔が乗った抹茶と和菓子をいただき、上品な甘さに旅の疲れが癒やされる。','2026-08-05','16:20','🍵','0','',-1200,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,269,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'山代温泉の老舗旅館に到着','夕方に金沢から特急と送迎バスを乗り継ぎ、加賀温泉郷の山代温泉へ。趣のある純和風の温泉宿にチェックインし、仲居さんの温かいお出迎えにホッとする。','2026-08-05','17:40','🏨','0','',-35000,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,270,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.321000000,136.351000000,'名湯・山代温泉の源泉かけ流しを満喫','夕食前に大浴場へ。歴史ある名湯にゆっくりと体を沈めると、一日の歩き疲れがじんわりとほぐれていく。肌触りの優しいお湯に大満足。','2026-08-05','18:30','♨️','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,271,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'お部屋で加賀懐石の豪華な夕食','お部屋食で、北陸の旬の食材を使った懐石料理を堪能。カニや加賀野菜の煮物など、見た目も美しく上品な味付けに夫婦で感動しながら味わう。','2026-08-05','19:45','🦀','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,272,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'心地よい布団で早めの就寝','美味しい食事と温泉ですっかりリラックス。夜は静かなお部屋で早めに床につき、ぐっすりと心地よい眠りにつく。','2026-08-05','21:30','🌙','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,273,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.321000000,136.351000000,'朝風呂で清々しい一日の始まり','翌朝は早起きして再び温泉へ。朝日が差し込む大浴場で朝風呂を楽しみ、体の芯からすっきりと目覚める。','2026-08-06','07:00','☀️','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,274,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320000000,136.350000000,'旅館の和朝食でしっかり栄養補給','焼き魚や温泉卵、手作りの豆腐など体に優しい和朝食をいただく。炊き立ての白ご飯が美味しくて、ついついおかわりしてしまう。','2026-08-06','08:15','🍚','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,275,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.320500000,136.352000000,'温泉街の総湯周辺を朝のお散歩','チェックアウト前に、山代温泉の総湯周辺をのんびりお散歩。昔ながらの共同浴場やレトロな街並みを眺めながら、のどかな雰囲気を満喫した。','2026-08-06','09:30','🚶‍♀️','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,276,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578000000,136.648000000,'金沢駅に戻りお土産選び','送迎バスと特急を乗り継いで金沢駅へ戻ってきた。駅ナカの大きなお土産処で、加賀棒茶や金沢銘菓のきんつばを家族や自分用にじっくり選んで購入。','2026-08-06','11:30','🛍️','0','',-4500,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (19,277,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578000000,136.648000000,'駅構内のお店で名物のお寿司を軽く堪能','新幹線の発車時刻まで余裕があったので、駅ビル内で名物の回転寿司に立ち寄る。職人さんが握る北陸の白身魚が絶品で、旅の締めくくりにふさわしい味。','2026-08-06','13:00','🍣','0','',-2400,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (19,278,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.000000000,135.000000000,'最寄り駅に到着して無事に帰路へ','新幹線と在来線を乗り継いで、夕方に地元の最寄り駅へ到着。大きな怪我や体調不良もなく、温泉と美食に癒やされた大満足の1泊2日旅行となった。','2026-08-06','17:30','🚉','0','',0,1,0,0,0,0,false,'2026-08-01 16:54:23.807989+09','2026-08-01 16:54:23.807989+09','{}'),
	 (21,294,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578100000,136.648000000,'金沢駅の鼓門前で卒業旅行スタート！','大学の仲良しグループ4人で金沢駅に集合！シンボルの「鼓門」を背景に、これから始まる北陸・金沢の卒業旅行へ出発の記念撮影。','2026-03-01','09:30','🎒','0','',0,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,295,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.562300000,136.662500000,'日本三名園・兼六園をゆったり散策','バスで移動して兼六園へ。雪吊りが残る美しい庭園の景色を眺めながら、池の周りをのんびりお散歩。歴史ある雰囲気に感動。','2026-03-01','10:30','🌳','0','',-320,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,296,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.564500000,136.661000000,'金沢城公園の広大な敷地を探検','兼六園から橋を渡ってすぐの金沢城公園へ。白亜の美しい石川門や復元された長屋を見上げながら、殿様気分で城内を歩き回る。','2026-03-01','12:00','🏯','0','',0,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (29,415,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.230100000,135.165000000,'公園でひと休み','木陰で休憩。風が気持ちよくて少し元気が戻る。','2026-08-10','11:20','🙂','0','',0,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (21,297,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.561500000,136.657500000,'近江町市場で海の幸ドカ盛り海鮮丼ランチ','金沢の台所「近江町市場」へ移動。新鮮な甘エビやカニ、ウニがこれでもかと乗った贅沢な海鮮丼をみんなで頬張る。美味しさに言葉を失う！','2026-03-01','13:30','丼','0','',-2800,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,298,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.560800000,136.655800000,'金沢21世紀美術館で現代アート体験','話題の「スイミング・プール」をはじめ、ユニークな現代アートの展示を体験。水面を下から覗き込んだり、不思議な空間で大はしゃぎ。','2026-03-01','15:00','🎨','0','',-1200,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,299,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.570000000,136.671500000,'ひがし茶屋街のレトロな町並みと金箔ソフト','伝統的な出格子が続く情緒あふれるひがし茶屋街へ。ピカピカの「金箔ソフトクリーム」をみんなで買って食べ歩き。写真映えもバッチリ！','2026-03-01','16:45','🍦','0','',-900,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,300,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.571000000,136.672000000,'急な日本海の雨に降られてカフェに駆け込む','夕暮れ時に雨がパラついてきて、町家を改装したおしゃれな隠れ家カフェへ避難。温かい加賀棒茶を飲みながら外の雨を眺めてまったり。','2026-03-01','18:15','☕','0','',-800,-1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,301,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.579000000,136.650000000,'駅ナカで金沢おでんと地酒の夕食','金沢駅に戻り、地元で大人気の「金沢おでん」の店へ。車麩やカニ面といったご当地おでんに舌鼓を打ちつつ、北陸の地酒で乾杯！','2026-03-01','20:00','🍢','0','',-3500,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (21,302,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.581000000,136.652000000,'ホテルでの夜更かしトーク','駅前のホテルにチェックイン。ベッドに転がりながら、これまでの大学生活の思い出や将来の夢について夜遅くまで語り合う。','2026-03-01','22:00','🌙','0','',-7000,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,303,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.559000000,136.649000000,'長町武家屋敷跡の土塀小路を朝散歩','朝食を済ませ、土塀と石畳が続く長町武家屋敷跡を散策。静寂に包まれた朝の落ち着いた街並みが、昨晩の賑やかさとは違った良さを醸し出す。','2026-03-02','08:30','📷','0','',0,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,304,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.557000000,136.648000000,'老舗工房で金沢箔貼り体験','伝統工芸の街ならではの体験として、小さなお皿への「金箔貼り」に挑戦。慎重に金箔をピンセットで扱いながら、世界に一つの記念品を手作り。','2026-03-02','10:00','✨','0','',-2200,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,305,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.545000000,136.658000000,'にし茶屋街でほっこり和スイーツ休憩','少し足を伸ばして「にし茶屋街」へ。趣のある通りにある人気甘味処で、もっちりした特製わらび餅を食べてひと息つく。','2026-03-02','11:45','🍡','0','',-950,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,306,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.563000000,136.650000000,'香林坊でお土産ショッピング','金沢の中心街・香林坊エリアの商業施設に戻り、加賀棒茶やきんつばなどの定番お土産をみんなで吟味して大量買い！','2026-03-02','13:30','🛍️','0','',-4000,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,307,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.580000000,136.651000000,'金沢駅の百番街で最後のシメランチ','金沢駅の商業施設「金沢百番街」に入り、ご当地の能登牛を使った贅沢なローストビーフ丼を旅の最後のランチとして味わう。','2026-03-02','15:00','🥩','0','',-2400,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (21,308,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.578100000,136.648000000,'金沢駅に戻り、それぞれの道へ解散','再び金沢駅の鼓門前に戻り、「絶対にまた旅行しよう！」と固い握手を交わしてそれぞれの帰路へ。最高の北陸・金沢の思い出が完成。','2026-03-02','16:30','👋','0','',0,1,0,0,0,0,false,'2026-08-01 17:02:57.135352+09','2026-08-01 17:02:57.135352+09','{}'),
	 (22,309,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.083300000,138.433300000,'両津港に到着！佐渡島観光の幕開け','ジェットフォイルで両津港に到着！潮風を感じながら、これから始まる佐渡島一周の大冒険にワクワクが止まらない。','2026-06-01','09:30','🚢','0','',0,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,310,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.026400000,138.254200000,'佐渡金山で歴史のロマンを体感','世界文化遺産に登録された「佐渡金山」へ移動。江戸時代の採掘跡（道遊の割戸など）を見学し、当時のスケールの大きさに圧倒される。','2026-06-01','11:00','⛏️','0','',-900,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,311,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.031000000,138.245000000,'相川の町並みで名物グルメランチ','相川エリアのレトロな街並みの中にある食堂で、佐渡の海の幸を使った「ブリカツ丼」をガッツリ食べる。サクサクで美味しい！','2026-06-01','12:30','🍽️','0','',-1400,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (22,312,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.016700000,138.233300000,'北沢浮遊選鉱場で幻想的な近代遺跡を見学','まるで「ラピュタ」のようだと言われる北沢浮遊選鉱場跡へ。巨大なコンクリートの廃墟が緑に覆われた神秘的な光景にカメラが止まらない。','2026-06-01','14:00','📸','0','',0,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,313,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.216700000,138.450000000,'佐渡の最北端・大野亀の絶景へ','車で一気に北上し、ミシュラン・グリーンガイドで2つ星を獲得した「大野亀」へ。巨大な一枚岩と日本海のダイナミックな青さに息をのむ。','2026-06-01','16:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,314,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.150000000,138.400000000,'突然のにわか雨！海岸沿いのカフェへ避難','北東部の海岸線をドライブ中に雨がパラついてきて、おしゃれな海沿いのカフェに駆け込む。雨の日本海を眺めながら温かいコーヒーでひと息。','2026-06-01','17:30','☕','0','',-600,-1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,315,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.070000000,138.360000000,'真野湾の夕日を眺めながら温泉宿へチェックイン','島の中央部へ戻り、真野湾に沈む美しい夕日を車窓から眺めながら温泉旅館に到着。旅の疲れを癒やす極上の温泉へ。','2026-06-01','19:00','🌅','0','',-12000,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,316,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,38.070000000,138.360000000,'新鮮な海の幸と佐渡の地酒で宴会','夕食は大皿に盛られた佐渡の旬の魚介と、キリッとした佐渡の地酒を堪能。楽しかった一日の思い出話で夜遅くまで盛り上がる。','2026-06-01','20:30','🍶','0','',0,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (29,416,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.233000000,135.167200000,'ランチは和歌山ラーメン','女子旅でもラーメンは外せない。濃厚スープが美味しくて満足。900円。','2026-08-10','12:10','🤩','0','',-900,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (22,317,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.858591416,138.391513824,'小木港へ移動して名物のたらい舟体験','翌朝は南部の小木エリアへドライブ。矢島・経島（やじま・きょうじま）で、エメラルドグリーンの入江をゆく名物の「たらい舟」を体験！','2026-06-02','09:00','🛶','0','',-600,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,318,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.874311385,138.412799835,'宿根木の風情ある船大工の町並みを散策','国の重要伝統的建造物群保存地区である「宿根木（しゅくねぎ）」の細い路地を散策。板壁の民家が密集する独特のノスタルジックな風景に感動。','2026-06-02','10:30','🏡','0','',-500,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (22,319,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,37.950000000,138.350000000,'佐渡西三川ゴールドパークで砂金採り体験','今度は自分で金を見つけるため「西三川ゴールドパーク」へ。川の水の中で砂金をすくい、キラリと光る金が見つかると大歓声があがる。','2026-06-02','12:30','✨','0','',-900,1,0,0,0,0,false,'2026-08-01 17:10:03.732736+09','2026-08-01 17:10:03.732736+09','{}'),
	 (27,389,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.662000000,135.502000000,'日本橋の家電・カルチャー街を散策','オタロードや電子パーツ店が並ぶエリアをぶらり。夏の暑さで少しバテつつも、ディープな雰囲気を楽しむ。','2026-08-01','14:45','🥵','1','',-850,0,0,0,0,0,false,'2026-08-01 19:02:38.640345+09','2026-08-01 19:02:38.640345+09','{}');
