	 (27,395,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.702500000,135.495900000,'梅田スカイビル・空中庭園展望台','大阪の夜景を一望するためにビルへ。エレベーターから見る景色が最高で気分爽快！','2026-08-02','14:00','🏙️','0','',-2000,1,0,0,0,0,false,'2026-08-01 19:02:38.640345+09','2026-08-01 19:02:38.640345+09','{}'),
	 (27,396,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705500000,135.498300000,'大阪駅前ビル地下のディープな居酒屋で昼飲み','レトロで昭和感あふれるビル地下の居酒屋へ潜入。安くて美味いホルモン焼きとハイボールを満喫。','2026-08-02','16:00','🥳','0','',-3100,1,0,0,0,0,false,'2026-08-01 19:02:38.640345+09','2026-08-01 19:02:38.640345+09','{}'),
	 (27,397,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.733600000,135.500100000,'新大阪駅ナカで最後の豚まん＆お土産チェック','新幹線の発車時刻まで時間調整。有名店の豚まんを買って、満足感に浸りながら帰りの新幹線に乗り込んだ。','2026-08-02','18:00','🚄','0','',-1950,1,0,0,0,0,false,'2026-08-01 19:02:38.640345+09','2026-08-01 19:02:38.640345+09','{}'),
	 (28,400,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685300000,135.839900000,'奈良公園で鹿と遭遇','鹿せんべいを買って鹿と触れ合う。少し追いかけられて焦ったが楽しい時間。鹿せんべい200円。','2026-08-02','10:05','🤩','0000','',-200,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,401,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.688400000,135.839400000,'東大寺大仏殿の圧巻','大仏の迫力に思わず息をのむ。拝観料600円。静かな空気に心が落ち着いた。','2026-08-02','11:20','🙂','0000','',-600,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}');
