	 (28,402,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681400000,135.839000000,'二月堂への坂道','坂道が思ったより急で汗が噴き出す。景色は美しいが体力が少し削られた。','2026-08-02','12:05','😅','0000','',0,0,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,403,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676900000,135.832800000,'ならまちで昼食','古民家カフェでランチ。落ち着いた空間で疲れが癒えた。ランチ1280円。','2026-08-02','13:00','🙂','0000','',-1280,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,404,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676000000,135.829000000,'ならまち散策','細い路地を歩きながら雑貨屋を巡る。気に入った小物を購入して900円。','2026-08-02','14:10','🙂','0000','',-900,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,405,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.683800000,135.804900000,'興福寺で静かな時間','五重塔を眺めながら休憩。観光客は多いが境内は落ち着いている。拝観料700円。','2026-08-02','15:00','🙂','0000','',-700,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,406,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.682200000,135.803000000,'猿沢池でひと休み','池のほとりで風が心地よく、歩き疲れた足が少し回復。','2026-08-02','15:40','🙂','0000','',0,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,407,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668700000,135.785000000,'奈良町にぎわいの家','古い町家の展示を見学。歴史を感じる空間で気持ちが落ち着く。入館料500円。','2026-08-02','16:20','🙂','0000','',-500,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,408,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.669500000,135.784000000,'甘味処で休憩','かき氷を食べて涼む。歩き疲れた体に甘さが染みる。かき氷850円。','2026-08-02','17:00','🤩','0000','',-850,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,409,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.805000000,'奈良駅へ戻る道','夕暮れの街を歩きながら駅へ。少し疲れが出てきたが満足感が大きい。','2026-08-02','18:00','🙂','0000','',0,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (28,410,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685100000,135.805000000,'駅ナカで夕食','駅ナカの食堂で軽い夕食。疲れた体に温かい料理が染みる。夕食1100円。','2026-08-02','18:40','🙂','0000','',-1100,1,0,0,0,0,false,'2026-08-01 19:19:41.402213+09','2026-08-01 19:19:41.402213+09','{}'),
	 (29,412,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'和歌山駅に到着','大阪から電車で和歌山駅へ。友達と「女子旅スタート！」と写真撮影。カフェで朝食600円。','2026-08-10','09:20','🙂','0','',-600,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (29,413,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.225900000,135.167400000,'和歌山城へ向かう道','日差しが強くて汗ばむけどおしゃべりが楽しい。女子旅らしいテンション。','2026-08-10','10:00','😅','0','',0,0,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (29,419,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196500000,135.147000000,'友ヶ島フェリー乗り場','時間が合わず友ヶ島は断念。少し残念だけど海が綺麗で気持ちは上向き。','2026-08-10','14:40','🙂','0','',0,0,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (29,420,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.195000000,135.152500000,'海辺のカフェで休憩','海を眺めながらアイスコーヒー。女子旅らしいゆったり時間。550円。','2026-08-10','15:20','🙂','0','',-550,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (29,421,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'和歌山駅へ戻る','帰りの電車に向けて移動。疲れはあるけど楽しい気持ちが勝っている。','2026-08-10','16:10','🙂','0','',0,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (29,422,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.229000000,135.167000000,'駅ナカでお土産選び','梅干しや和歌山限定のお菓子を購入。友達と盛り上がる。1200円。','2026-08-10','16:40','🤩','0','',-1200,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (29,423,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'夕食は駅ナカで','軽めの定食を食べてエネルギー補給。女子旅の締めにぴったり。980円。','2026-08-10','17:20','🙂','0','',-980,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (29,424,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.228400000,135.167500000,'帰路へ','電車で今日の写真を見返して余韻に浸る。楽しい女子旅だった。','2026-08-10','18:00','🙂','0','',0,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (34,475,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.200000000,135.200000000,'阪和道 PAで最初の休憩とコーヒーブレイク','ドライブのスタート直後、サービスエリアに立ち寄ってリフレッシュ。これから始まる和歌山旅行への期待感が高まる。','2026-09-12','08:30','☕','0','',-600,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,476,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.226000000,135.167500000,'和歌山城の天守閣と豊かな緑を散策','歴史ある和歌山城へ。天守閣からの眺めが素晴らしく、青空の下で城内の石垣や庭園を家族でのんびり歩いた。','2026-09-12','09:45','🏯','0','',-800,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,477,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.700500000,135.358200000,'黒潮市場で新鮮な海の幸ランチを満喫','紀州黒潮市場に到着。マグロの解体ショーを家族で間近で見学し、その場で買った海鮮丼やお寿司をみんなでシェアして食べた。','2026-09-12','12:00','🍣','0','',-4500,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (55,855,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514800000,133.561200000,'桂浜茶屋で休憩','名物アイスクリンを食べながら海を眺める。軽い甘さが暑い体にちょうどいい。','2026-08-11','10:50','🍦','0','',-350,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (34,478,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.692200000,135.335100000,'アドベンチャーワールドでパンダに癒やされる','大人気のジャイアントパンダやたくさんの動物たちを見学。サファリワールドを車で回ったり、イルカショーを見て家族みんなが大はしゃぎ。','2026-09-12','14:00','🐼','0','',-12000,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,479,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.682300000,135.333100000,'千畳敷のダイナミックな景観に感動','波の浸食によってできた壮大な岩畳を見学。太平洋の水平線が広がり、夕暮れ時の景色が言葉を失うほど美しかった。','2026-09-12','17:30','🌅','0','',0,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,480,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.685000000,135.340000000,'白良浜の真っ白な砂浜を少しお散歩','日が暮れる前の白良浜へ。足裏に心地よい真っ白な砂浜と透明度の高い海を眺めながら波打ち際を歩く。','2026-09-12','18:15','🏖️','0','',0,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,481,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.690100000,135.352100000,'白浜温泉の宿でゆったり温泉と会席料理','温泉に浸かって一日の運転の疲れをしっかりリフレッシュ。海の幸がふんだんに使われた豪華な夕食を家族で囲み、楽しい夜を過ごした。','2026-09-12','20:00','♨️','0','',-32000,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,482,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.716500000,135.378900000,'三段壁の洞窟探検でスリルを味わう','2日目の朝、地下深くへエレベーターで降りて波が打ち寄せる洞窟内部を見学。自然の迫力を間近で体感して子どもたちも大興奮。','2026-09-13','09:30','🌊','0','',-3000,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,483,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725000000,135.385000000,'円月島（高月島）の景色をドライブ中に眺める','海にぽっかり浮かぶ円月島の丸い穴に沈む夕日は見られなかったが、青い海と美しいコントラストをなす昼間の姿を車窓から満喫。','2026-09-13','11:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,484,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.800000000,135.420000000,'とれとれ市場でお土産の海産物を物色','新鮮な魚介類や紀州の特産品が並ぶ巨大な市場へ。家族それぞれが気になるお土産や乾物を楽しそうに選んで買い込んだ。','2026-09-13','12:00','🛍️','0','',-4200,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,485,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.733300000,135.466700000,'南部梅林の近くのドライブロードを爽快走行','心地よい海風と山あいの緑を感じながら、快適な海岸線沿いのドライブを楽しむ。車内での家族の会話も弾む。','2026-09-13','13:30','🎶','0','',0,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,486,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.032100000,135.195000000,'紀州梅の里でたくさんの梅干しをお土産に購入','道の駅でバラエティ豊かな紀州南高梅の梅干しや梅ジュースを試食してお気に入りを発見。自宅用と親戚用にたくさん買い込んだ。','2026-09-13','14:45','🍊','0','',-5000,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (34,487,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.150000000,135.210000000,'道の駅紀の川万葉の里でちょっとひと息','ドライブの締めくくり前に、地元農産物やフルーツが並ぶ道の駅に立ち寄り。冷たいみかんソフトクリームを食べて一息つく。','2026-09-13','16:00','🍦','0','',-800,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,488,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.180000000,135.230000000,'紀ノ川SAで旅の最後の夕日を眺める','高速道路に乗る前の最後のSA。夕暮れに染まる紀ノ川の景色を眺めながら、今回の楽しいドライブ旅行の思い出を家族で語り合った。','2026-09-13','17:30','🌆','0','',-1200,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,489,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.250000000,135.300000000,'阪和道の上りPAで最後のトイレ休憩','帰路の途中、夜の高速道路を安全運転しながら最後のパーキングエリアでリフレッシュ。','2026-09-13','19:00','🚗','0','',-500,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (34,490,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350000000,135.400000000,'大阪府境手前の最後のルート確認ポイント','和歌山エリアでの充実したドライブ旅を終え、いよいよ県境を越えて北上する最後のスポット。','2026-09-13','19:45','✨','0','',0,1,0,0,0,0,false,'2026-08-01 21:15:14.872737+09','2026-08-01 21:15:14.872737+09','{}'),
	 (35,507,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728000000,135.985000000,'新宮駅に到着、レンタカーで男子会旅スタート','仲間たちとテンション高く新宮駅に集合。レンタカーに乗り込んで、男だらけの熱い1泊2日旅行がついに出発！','2026-10-10','10:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,508,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.729000000,135.992000000,'熊野速玉大社で旅の安全と男の勝負祈願','世界遺産に登録されている熊野速玉大社を参拝。鮮やかな朱色の社殿を見学し、今後の健闘をみんなで祈る。','2026-10-10','10:45','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,509,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.723000000,135.989000000,'1軒目：新宮名物の濃厚豚骨ラーメンで腹ごしらえ','観光の前に腹ペコの胃袋を満たすべく、地元で評判の濃厚ラーメン店へ。ガツンとくるスープが男ウケ抜群の美味さ。','2026-10-10','12:00','🍜','0','',-950,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,510,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.721000000,135.991000000,'神倉神社の急な石段（538段）に男気チャレンジ','ゴツゴツした険しい538段の石段を全員で息を切らしながら登り切る。登頂した時の達成感と街並みの絶景が最高。','2026-10-10','13:30','🧗','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,511,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728337238,135.994606018,'徐福公園で歴史散策とちょっとしたネタ写真撮影','秦の始皇帝の命を受けた徐福の伝説が残る公園。珍しいモニュメントの前でふざけたポーズを取りながら記念撮影。','2026-10-10','15:00','🗿','0','',-200,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,512,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725000000,135.987000000,'2軒目：あっさり系中華そばでラーメン食べ比べ','少し歩いたところで、先ほどとは対照的なあっさりスープの中華そばをみんなでシェア。味の違いを語り合う。','2026-10-10','16:30','🍜','0','',-850,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (35,513,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.720000000,135.980000000,'新宮市内的ビジネスホテルにチェックイン','男旅らしくリーズナブルなホテルにチェックイン。荷物を置いて、夜の宴会とさらなるラーメンに向けて準備。','2026-10-10','18:00','🏨','0','',-8000,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,514,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.724000000,135.988000000,'3軒目：夜の〆に食べる絶品こってり豚骨ラーメン','居酒屋で盛り上がった後の深夜、男子会の定番である「〆のラーメン」を求めて深夜営業の店へ。背脂たっぷりがたまらない。','2026-10-10','22:00','🍻','0','',-1000,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,515,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.725696003,135.997524261,'2日目スタート：朝の爽やかな熊野川河川敷をドライブ','天気も良く、爽やかな朝の熊野川沿いをドライブ。車内では昔の思い出話や音楽の話で大盛り上がり。','2026-10-11','09:00','🎶','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,516,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.718342948,135.989627838,'瀞峡（どのきょう）の圧倒的な大自然を体感','切り立った渓谷の美しい景観を間近で見学。自然のダイナミックさに男同士でも思わず「すげえ…」と声が漏れる。','2026-10-11','10:30','🛶','0','',-1500,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,517,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.726000000,135.986000000,'4軒目：お昼のガッツリ系スタミナニンニクラーメン','お腹が空いたところで、ニンニクがガツンと効いたスタミナ系の限定ラーメンを全員で注文。スタミナ満点！','2026-10-11','12:30','🧄','0','',-1100,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,518,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.727000000,135.984000000,'浮島半島の海岸線を軽くドライブ＆散策','太平洋の荒波が打ち寄せる海岸線を散策。潮風を浴びながら、男子特有のバカ話でワイワイ楽しむ。','2026-10-11','14:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,519,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.731370989,135.986323357,'新宮の地酒や名産品をお土産ショップで物色','家族や自分へのお土産として、地元の日本酒や名産のお菓子などを男らしくまとめ買い。','2026-10-11','15:15','🛍️','0','',-3500,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,520,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.722000000,135.988000000,'5軒目：旅のフィナーレを飾る王道醤油ラーメン','帰りの新宮駅に向かう前に、地元で愛される王道の醤油ラーメンで今回のラーメン巡りを締めくくる。やっぱりこれだなと納得。','2026-10-11','16:30','🍜','0','',-900,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,521,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728000000,135.985000000,'新宮駅前にてレンタカー返却前の最終ミーティング','楽しかった2日間の思い出を振り返りながら、駅前でレンタカーを返却する直前のひとコマ。','2026-10-11','17:45','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}'),
	 (35,522,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.728500000,135.985500000,'新宮駅ホームで特急電車の到着を待つ','たくさんの観光地とラーメンを制覇した満足感に浸りながら、帰りの特急電車のホームで旅の終わりを惜しむ。','2026-10-11','18:30','🚄','0','',0,1,0,0,0,0,false,'2026-08-01 21:33:11.610839+09','2026-08-01 21:33:11.610839+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (36,523,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.467890000,134.812340000,'JR城崎温泉駅に到着、温泉街の男旅がスタート','いよいよ待ちに待った兵庫県北部の男旅が幕を開けた。城崎温泉駅に全員集合し、まずは駅舎の前で気合の記念撮影。これから始まる温泉と絶品ご当地グルメの食べ歩きに、早くもテンションが最高潮に達している。今日からの1泊2日、思い切り満喫するぞ！','2026-11-12','10:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,524,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.613450000,134.814560000,'名勝「玄武洞」の圧倒的な自然の造形美に感動','国の天然記念物にも指定されている玄武洞を見学。マグマが冷えて固まった時にできた見事な柱状節理の断面が目の前に広がり、そのダイナミックで神秘的な光景に男同士でも思わず息をのむ。地球の歴史を感じる素晴らしいスポットだ。','2026-11-12','11:00','🗿','0','',0,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,525,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.534210000,134.823450000,'1軒目：豊岡市内の人気店で味わう濃厚鶏白湯ラーメン','観光の最初の腹ごしらえとして、地元で評判の鶏白湯ラーメン店へ駆け込む。じっくりと炊き出された濃厚でクリーミーなスープが、歩き疲れた体に染みわたる。麺との絡み具合も抜群で、全員がスープを完飲するほどの美味しさだった。','2026-11-12','12:30','🍜','0','',-950,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,526,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.462340000,134.811230000,'城崎温泉街の風情ある七つの外湯めぐり（一の湯）','浴衣に着替えて、城崎温泉の代名詞である外湯めぐりに繰り出す。まずは「一の湯」で旅の移動の疲れをじっくりと癒やす。風情ある温泉街の石畳をカランコロンと下駄を鳴らしながら歩く時間は、日本の情緒を感じられて実に心地よい。','2026-11-12','14:30','♨️','0','',-800,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,527,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.465120000,134.813210000,'2軒目：温泉街で食べる地元の名物・カニだし塩ラーメン','温泉ですっきりとリフレッシュしたあと、湯上がりの体に最高の塩ラーメンを求めて路地裏の隠れ家的店へ。日本海で獲れたカニの出汁がこれでもかと効いたスープは、上品かつ深いコクがあり、ここでしか味わえない絶品の一杯だった。','2026-11-12','16:00','🍜','0','',-1100,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,528,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.459870000,134.809870000,'情緒あふれる川沿いの旅館で男だらけの大宴会','本日の宿である温泉旅館にチェックイン。夕食には日本海側の新鮮な海の幸や地元食材を使った料理がずらりと並び、冷えたビールで乾杯する。昔話や仕事の近況報告で大いに盛り上がり、夜遅くまで笑い声が途絶えない最高の夜となった。','2026-11-12','18:30','🍻','0','',-15000,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,529,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.461230000,134.810120000,'3軒目：夜の温泉街の締めくくる深夜の屋台風醤油ラーメン','宴会が一段落した深夜、どうしてもラーメンが食べたくなり、夜遅くまで開いているアットホームなラーメン店へこっそり抜け出す。シンプルな鶏ガラ醤油の味わいが、お酒を飲んだ後の胃袋に優しく染み入り、最高の締めくくりとなった。','2026-11-12','22:30','🌙','0','',-900,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,530,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.468900000,134.820120000,'朝の温泉街を散策しながら、温泉たまご作り体験','2日目の朝は爽やかな空気が漂う温泉街をのんびりとお散歩。源泉の熱を使って自分で温泉たまごを作る体験コーナーに挑戦する。程よい半熟具合に仕上がった卵をその場で食べると、朝から贅沢な気分を満喫できた。','2026-11-13','09:00','🥚','0','',-200,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,531,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.475640000,134.887650000,'円山川沿いをドライブして、のどかな景色を満喫','車窓から広がる美しい円山川の景色を眺めながら、爽快なリバーサイドドライブを楽しむ。車内ではお気に入りのプレイリストを流し、男同士ならではの気兼ねないトークで終始笑顔が絶えない移動時間となった。','2026-11-13','10:15','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (68,1061,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.833656000,135.499700000,'今宮三丁目 (大阪府)','簡易メモ','2026-08-02','11:15','😀','0000','',0,1,0,0,0,0,true,'2026-08-02 12:57:54.2251+09','2026-08-02 12:58:04.807905+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (36,532,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.547890000,134.901230000,'国の伝統的建造物群保存地区「出石の城下町」を散策','「但馬の小京都」と呼ばれる出石の城下町に到着。白壁の武家屋敷や歴史ある佇まいの街並みをのんびりと歩きながら、かつての城下町の面影をしみじみと感じ取る。歴史好きのメンバーも大満足の落ち着いたロケーションだ。','2026-11-13','11:30','🏯','0','',0,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,533,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.549120000,134.902340000,'4軒目：名物「出石皿そば」をみんなで何枚食べられるか勝負','出石といえばやっぱり出石皿そば！ 小皿に盛られた風味豊かなお蕎麦を次々とお代わりしていく。何枚食べたかを競い合う男気勝負を開催し、一番食べたメンバーには全員から拍手が送られるなど、最高に盛り上がるランチタイムとなった。','2026-11-13','12:45','🍜','0','',-1200,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,534,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.512340000,134.856780000,'かつて「天空の城」として知られる竹田城跡の麓へ','日本のマチュピチュとも称される竹田城跡のふもとに到着。遠くからでも威厳を放つ石垣の山城を眺め、その壮大なスケールに圧倒される。歴史のロマンに浸りつつ、記念の集合写真をパシャリと撮影。','2026-11-13','14:15','⛰️','0','',-500,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,535,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.514560000,134.858900000,'5軒目：麓の食堂で味わうホッとする懐かしの中華そば','竹田城跡の周辺を散策したあと、麓にあるレトロな雰囲気の食堂で遅めのお昼ご飯。鶏ガラベースの非常にシンプルでどこか懐かしい味わいの中華そばをすする。旅の終盤にふさわしい、心まで温まる一杯だった。','2026-11-13','15:30','🍜','0','',-850,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,536,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.398760000,134.834560000,'道の駅で但馬牛のコロッケをつまみ食い＆お土産選び','帰路の途中に立ち寄った道の駅にて、名物の但馬牛を使ったサクサクのコロッケをみんなで買い食い。さらに、家族や自分用のお土産として地元の特産品や日本酒をしっかりと買い込み、トランクケースがいっぱいになる。','2026-11-13','16:45','🛍️','0','',-2500,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,537,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.354320000,134.789010000,'旅のフィナーレ：北近畿の思い出を語り合う最後の休憩','今回の旅の全行程をほぼ完璧にこなし、名残惜しさを感じながら最後の休憩ポイントへ。2日間で巡った観光地や食べたラーメンの数々を振り返り、すっかり絆が深まった仲間たちと次回の旅行の計画について話し合う。','2026-11-13','18:00','☕','0','',0,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (36,538,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.351230000,134.785430000,'JRの駅にて解散、最高の兵庫男旅のエンディング','すべての旅程を無事に終え、電車の到着に合わせて笑顔で解散の挨拶を交わす。観光もラーメンも妥協なしで大満足し、それぞれの家路へとつく。また次の機会に向けて、それぞれの日常へと戻っていくのだった。','2026-11-13','19:00','👋','0','',0,1,0,0,0,0,false,'2026-08-01 21:37:58.010195+09','2026-08-01 21:37:58.010195+09','{}'),
	 (37,539,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.694120000,135.191230000,'新神戸駅に到着、優雅な神戸マダム旅の始まり','都会的な洗練された空気が漂う新神戸駅に、仲良しのマダム仲間たちと優雅に集合。駅から一歩踏み出せば、海と山が織りなす美しい港町・神戸の景色が迎えてくれる。これから始まる極上のスイーツやおしゃれなスポット巡りに、胸が高鳴る贅沢な一日の幕開けです。','2026-12-04','10:00','✨','0','',0,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (54,827,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.558600000,133.543900000,'路面電車で移動','高知名物の路面電車に乗車。レトロな車両が街に馴染んでいて、乗っているだけで楽しい。','2026-08-04','10:30','🚋','0000','',-210,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (37,542,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.703450000,135.187890000,'異国情緒あふれる「北野異人館街」で歴史と建築美を鑑賞','かつての外国人の邸宅が立ち並ぶ北野異人館街を、ドレスコードを意識した装いでのんびりとお散歩。代表的な「風見鶏の館」や「萌黄の館」を見学し、明治・大正ロマンを感じさせるハイカラなインテリアや美しい洋風建築の数々にすっかり魅了される。どこを切り取っても絵になる空間。','2026-12-04','14:00','🏛️','0','',-650,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (37,543,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.691230000,135.190120000,'2軒目：北野の老舗パティスリーで絶品モンブラン','お散歩の途中で、神戸スイーツの代名詞とも言える超有名パティスリーに立ち寄る。目の前で絞り出される極上の和栗モンブランと香り高い紅茶のセットを堪能。上品な甘さと滑らかな口溶けに、一同「美味しいね」と自然と笑みがこぼれる至福のひととき。','2026-12-04','15:45','🍰','0','',-1400,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,544,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.690120000,135.194560000,'レトロモダンな「旧居留地」で洗練された街並み散策','かつての外国人生留地であり、現在は高級ブランドショップや洗練されたセレクトショップが並ぶ旧居留地エリアへ。ヨーロッパの街並みを思わせる重厚な石造りの近代建築が美しく、ウインドウショッピングをしながら歩くだけで、まるでパリやロンドンを旅しているような優雅な気分に浸れる。','2026-12-04','17:00','🛍️','0','',0,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,545,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.688900000,135.193450000,'3軒目：旧居留地の上質なフレンチレストランで優雅なティータイム','洗練されたインテリアが光る一軒家フレンチのサロンにて、美しいヴィンテージカップに入ったブレンドティーと焼き菓子のセットをいただく。静かで落ち着いた大人の空間の中で、これからの人生や趣味についてゆっくりと語り合う、大人の女性にふさわしい贅沢な時間。','2026-12-04','18:30','🍮','0','',-1800,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,546,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.687560000,135.195670000,'「東遊園地」の開放的な芝生広場で緑の癒やしを感じる','都会の真ん中にあるとは思えないほど緑豊かで美しい東遊園地をゆっくりとお散歩。手入れの行き届いた芝生やおしゃれな本棚を眺めながらベンチでひと休み。鳥のさえずりや木漏れ日を感じつつ、神戸の街の心地よい風を全身で受け止める。','2026-12-05','09:30','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,547,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.684560000,135.187890000,'神戸モトマチショッピングストリートでこだわりの雑貨探し','歴史ある元町商店街へと足を延ばし、職人技が光る上質なバッグや神戸ならではのおしゃれなインポート雑貨を丁寧に見て回る。量販店にはない、作り手のこだわりが詰まった一点もののアイテムとの出会いに、ショッピング熱が心地よく刺激される。','2026-12-05','11:00','👜','0','',0,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,548,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.685670000,135.189010000,'4軒目：元町の老舗洋食店で味わう伝統のビーフシチュー','夕暮れ時に、神戸マダムの間でもファンの多い老舗の洋食レストランへ。じっくりと何日も煮込まれてお肉がトロトロに溶け込んだ絶品のビーフシチューをいただく。深みのあるデミグラスソースの味わいに、長年愛され続けてきた本物の伝統の味を実感。','2026-12-05','12:45','🍽️','0','',-2400,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,549,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.681230000,135.184560000,'「神戸ハーバーランドumie」で港町の美しい夕景を眺める','海沿いの開放的なハーバーランドエリアへ移動し、茜色に染まる神戸港の夕景を眺める。海風を感じながらボードウォークをのんびり歩き、赤レンガ倉庫のロマンチックな佇まいや、行き交う船の姿をカメラにおさめる。','2026-12-05','14:30','🌅','0','',0,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,552,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.686780000,135.191230000,'老舗の高級デパ地下でこだわりの神戸土産を厳選','三宮に戻り、地元の有名ブランドが揃う老舗デパートの地下フロアへ。ご家族や自分へのご褒美として、職人手作りの上品な洋菓子や神戸限定の紅茶、上質な佃煮などを丁寧に吟味して買い求める。お土産選びの時間も旅の大切な楽しみのひとつ。','2026-12-05','18:45','🛍️','0','',-4000,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (54,828,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514350000,133.562870000,'桂浜へ到着','太平洋の広さに圧倒される桂浜。波の音が心地よくて、しばらく砂浜でぼーっとしてしまった。','2026-08-04','11:20','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (37,553,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.692340000,135.193450000,'旅のフィナーレ：夜のバーラウンジでノンアルコールカクテル乾杯','宿泊するホテルの落ち着いた雰囲気のバーラウンジにて、旅の締めくくりとして色鮮やかな特製ノンアルコールカクテルで乾杯。2日間で巡った美しい景色や美味しいスイーツの思い出話が尽きず、優雅で充実した大人の女子旅の余韻に浸る。','2026-12-05','20:00','🍸','0','',-1500,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (37,554,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.693450000,135.192340000,'新神戸駅にて名残を惜しみつつ、それぞれの帰路へ','すべてのスケジュールを優雅かつ完璧にこなし、新神戸駅の改札前にてお互いに「また次の素敵な旅を計画しましょうね」と笑顔で挨拶を交わす。心身ともに満たされた素晴らしい神戸マダム旅のエンディングを迎え、それぞれの日常へと帰っていく。','2026-12-05','21:15','👋','0','',0,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (38,555,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.998503700,135.843200684,'JR大津駅前にてレンタサイクルを借りて、琵琶湖サイクリング出発','サイクリング日和の爽やかな青空の下、JR大津駅前に集合。整備されたスポーツタイプのレンタサイクルに跨がり、いよいよ日本最大の湖・琵琶湖を巡る大冒険の幕開け。湖風を心地よく感じながら、まずは湖岸道路を目指してペダルを軽快に踏み出していく。','2026-05-13','09:00','🚲','0','',-1500,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,556,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.004690717,135.874099731,'「琵琶湖疏水（浜大津付近）」の歴史的な水辺景観を眺める','琵琶湖から京都へと水を引いた歴史ある琵琶湖疏水の周辺をゆっくりと自転車で走る。水面に映る緑豊かな木々と、明治のロマンを感じさせるレンガ造りの水門が美しく調和しており、走り出しのウォームアップにぴったりの穏やかなスポット。','2026-05-13','09:45','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,557,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013689179,135.942077637,'「びわ湖大津館」の美しいイングリッシュガーデンでひと休み','湖畔沿いに佇むクラシックな建築が印象的な、びわ湖大津館の庭園に到着。手入れの行き届いた色鮮やかなイングリッシュガーデンを眺めながら、湖面を渡る涼しい風を受けて深呼吸。サイクリングの疲れを癒やしつつ、早くも湖の壮大な景色に魅了される。','2026-05-13','11:00','🏡','0','',-400,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,558,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.044051680,135.933151245,'1軒目：湖岸沿いの開放的なカフェで琵琶湖ブルーソーダ休憩','湖を間近に望むおしゃれなレイクサイドカフェに立ち寄り、最初の休憩タイム。青く澄んだ琵琶湖の水をモチーフにした鮮やかなブルーソーダと手作りマフィンをいただく。大きなガラス窓の向こうに広がる雄大なレイクビューを眺めながら、最高のティータイムを満喫。','2026-05-13','12:30','☕','0','',-1100,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,559,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.081848467,135.950660706,'琵琶湖大橋を渡り、西岸から東岸（湖東エリア）へ爽快ライド','全長約1.4キロを誇る琵琶湖大橋の自転車道へアプローチ。少し坂を登り切ると、左右に視界いっぱいの大パノラマが広がり、まるで湖の上を飛んでいるかのような爽快感抜群の空中サイクリングを体験。橋の上で吹き抜ける風が最高に気持ちいい。','2026-05-13','14:00','🌉','0','',-200,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,560,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.117381145,135.965423584,'「ウッディパル木戸」周辺ののどかな田園風景と並木道','東岸（湖東・湖西側）の整備されたサイクリングロードを北上し、緑豊かな並木道を抜けていく。車通りが少なく、道の両側に広がる黄金色の田園風景や遠くに見える鈴鹿山脈の山並みを眺めながら、ペダルを踏む足取りも自然と軽くなる。','2026-05-13','15:30','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,561,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.130298278,136.004047394,'2軒目：近江八幡の古民家カフェで味わう近江牛コロッケランチ','歴史的な蔵が立ち並ぶ近江八幡エリアに到着し、古い町家を改装した趣のあるカフェでランチ。名物の近江牛を贅沢に使ったサクサクのコロッケと、地元の野菜がたっぷり入ったスーププレートをいただく。旅のエネルギーをしっかりとチャージ。','2026-05-14','10:30','🍽️','0','',-1600,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,562,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.138861770,136.041812897,'「八幡堀」の水郷地帯をめぐる伝統的な景観散策','かつて豊臣秀次によって開かれた八幡堀へ。石畳の小道と白壁の土蔵が続く美しい水郷の景色を、自転車を押し歩きながらのんびりと鑑賞する。江戸時代の面影を色濃く残す静寂で情緒あふれる空間に、心から癒やされるひととき。','2026-05-14','12:00','🛶','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,563,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.178298352,136.068592072,'「長命寺港」の静かな湖岸ベンチで波の音に耳を傾ける','穏やかな波が打ち寄せる長命寺港のほとりで、自転車を止めて小休憩。目の前に広がる琵琶湖の広大さはまるで海のように感じられ、遠くを行き交う観光船や水鳥の姿を眺めながら、穏やかな湖畔の時間を贅沢に味わい尽くす。','2026-05-14','13:30','🌊','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (38,564,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.209581390,136.069450378,'3軒目：湖岸の絶景テラスで食べる近江米おにぎりと豚汁','琵琶湖の絶景を特等席で眺められる湖畔の休憩スポットにて、地元のお米を使った手作りおにぎりとアツアツの豚汁でエネルギー補給。シンプルながらも素材の美味しさがダイレクトに伝わり、サイクリング中の体に染みわたる格別の美味しさ。','2026-05-14','15:00','🍙','0','',-800,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,565,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.220520595,136.147899628,'「彦根港」の開放的な景色と湖上のクルーズ船を眺める','歴史ある城下町・彦根の港エリアに到着。青空の下にきらめく湖面と、遠くに見える多景島のシルエットを眺めながら、港のボードウォークをゆっくりと流す。潮風ならぬ湖風を浴びながらの走行は、サイクリングならではの醍醐味。','2026-05-14','16:30','⚓','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,566,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.275670000,136.251230000,'国宝「彦根城」の雄大な天守と緑豊かなお堀端を巡る','白亜の美しい姿を誇る国宝・彦根城の周辺へ。緑豊かなお堀端の道を自転車で優雅に走り抜け、歴代の井伊家が治めた城下町の歴史的な雰囲気を肌で感じる。立派な石垣や歴史的建造物の前で記念の写真をパシャリと撮影。','2026-05-15','09:30','🏯','0','',-800,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,567,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.278900000,136.256780000,'4軒目：彦根城下の老舗甘味処で名物・ひこにゃんモチーフの和スイーツ','城下町のレトロな商店街にある老舗の甘味処に立ち寄り、甘いものでちょっと一息。宇治抹茶をふんだんに使った濃厚な抹茶パフェと、地元で愛される温かいお団子をいただく。疲れた体に優しい甘さがスーッと広がり、仲間との会話も弾む。','2026-05-15','11:00','🍡','0','',-1200,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,568,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.281230000,136.261230000,'「夢京橋キャッスルロード」の白壁の町並みをポタリング','江戸時代の城下町を再現した夢京橋キャッスルロードを、情緒を味わいながらのんびりポタリング（散走）。統一された切妻屋根や白壁の美しい町並みの中を自転車で走る姿は、まるでタイムスリップしたかのような非日常感を演出してくれる。','2026-05-15','12:30','🏮','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,569,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.284560000,136.265670000,'5軒目：旅のフィナーレに味わう近江ちゃんぽんの温かい一杯','サイクリングのゴール地点の近くにある人気店にて、滋賀県民のソウルフードである「近江ちゃんぽん」を全員で食べる。黄金色の優しいお出汁と山盛りの野菜、お酢を入れてさっぱりと仕上げる味わいが、2日間ペダルを漕ぎ続けた体に最高の締めくくりとなる。','2026-05-15','13:45','🍜','0','',-950,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (38,570,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.286780000,136.267890000,'彦根のサイクリングステーションにて自転車を返却し、感動のゴール','無事にすべての行程を走り切り、ゴール地点のサイクリングステーションに到着して自転車を無事に返却。琵琶湖の大自然と美味しいグルメを全身で満喫した達成感に浸りながら、最高の笑顔で記念撮影をして旅の幕を閉じる。','2026-05-15','15:00','🎉','0','',0,1,0,0,0,0,false,'2026-08-01 21:55:52.096418+09','2026-08-01 21:55:52.096418+09','{}'),
	 (39,571,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.170910000,136.881550000,'「名古屋駅」に到着、食い倒れの名古屋グルメ旅の始まり','日本の中心・名古屋駅に到着し、これから始まる贅沢なグルメ巡りに胸が高鳴る。駅周辺の活気ある雰囲気を肌で感じながら、仲間たちと「まずは何を食べる？」と笑顔で計画を確認し合う。胃袋の準備を万端にして、いざ魅惑の名古屋めしの世界へ出発。','2026-06-11','09:00','🚅','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,572,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.170650000,136.885600000,'1軒目：名駅地下街の老舗で味わう朝の極上「小倉トースト」','まずは名古屋の喫茶店文化を体験すべく、レトロな雰囲気が漂う地下街の老舗喫茶店へ。厚切りのこんがりトーストに、たっぷりのバターと甘さ控えめの自家製小倉あんをのせていただく。サクサクの食感と絶妙な甘じょっぱさが、朝の体に優しく染みわたる最高のスタート。','2026-06-11','09:30','🍞','0','',-850,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,573,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.185560000,136.899170000,'「名古屋城」の荘厳な金のシャチホコと歴史あるお堀を散策','グルメの合間の腹ごしらえとして、名古屋のシンボルである名古屋城へ。青空に映える美しい大天守と、まばゆく輝く金のシャチホコを仰ぎ見ながら、緑豊かな本丸御殿の周辺をゆっくりとお散歩。贅沢な食事を心置きなく楽しむための良い運動になる。','2026-06-11','11:00','🏯','0','',-500,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (39,574,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.181940000,136.906670000,'2軒目：金シャチ横丁で味わう絶品「名古屋コーチン親子丼」','名古屋城のふもとにある金シャチ横丁の人気店に立ち寄り、ランチタイム。ブランド地鶏「名古屋コーチン」を使った贅沢な親子丼をいただく。弾力のあるジューシーなお肉と、濃厚でトロトロの卵が絶妙に絡み合い、一口ごとに思わずうっとりしてしまう美味しさ。','2026-06-11','12:30','🍲','0','',-1600,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,575,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.168060000,136.908330000,'日本一の繁華街・栄エリアで、大人のショッピング＆街歩き','名古屋の中心地である栄エリアへ移動し、洗練された商業施設やおしゃれなショップが立ち並ぶ大通りを散策。お腹を少し落ち着かせつつ、名古屋ならではのトレンドや活気ある街の雰囲気をたっぷりと満喫しながら、次のグルメスポットへと歩を進める。','2026-06-11','14:00','🛍️','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,576,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.161390000,136.908060000,'「中部電力 MIRAI TOWER」のそびえ立つ美しい姿を見上げる','久屋大通公園に美しく佇む中部電力 MIRAI TOWER（旧・名古屋テレビ塔）の真下へ。都会の緑豊かなオアシスに優しく溶け込む近未来的なデザインを眺めながら、旅の記念にハイセンスな写真を撮影する。','2026-06-11','15:30','🗼','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,577,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.161110000,136.903890000,'3軒目：栄の老舗洋食店で味わう芳醇な「味噌カツ」','名古屋グルメの定番であり、絶対外せない「味噌カツ」を味わいに老舗の専門店へ。サクサクに揚がった肉厚なトンカツに、じっくり煮込まれた濃厚で甘辛い特製八丁味噌ダレがたっぷりとかかっている。一口食べれば、コクのある深い味わいが口いっぱいに広がる。','2026-06-11','17:00','🥩','0','',-1500,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,578,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.158330000,136.901390000,'歴史とカルチャーが交差する「大須商店街」をレトロ散歩','古い歴史を持つ寺社とサブカルチャー、多国籍なショップが入り混じる活気あふれる大須商店街へ。下町の温かい雰囲気が漂うアーケードをのんびり歩きながら、地元の人々に愛される活気ある街の空気感を肌で感じる。','2026-06-12','10:00','🏮','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,579,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.158060000,136.899720000,'4軒目：大須の行列のできる名店でアツアツの「みそかつ丼」','大須の路地裏にある地元民で賑わう名店に立ち寄り、名物のみそかつ丼を追加で堪能。揚げたてのカツとご飯、そして染み込んだ特製味噌のコンビネーションが抜群で、お腹いっぱいになりながらも箸が止まらない中毒性のある美味しさ。','2026-06-12','11:30','🍛','0','',-1200,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,580,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.153890000,136.896670000,'「オアシス21」の水の宇宙船で近未来的な空中散歩','ガラスの大屋根「水の宇宙船」が特徴的なオアシス21へ。地上から空中へ続く幻想的なフロアを歩き、ガラス越しにきらめく名古屋の街並みを眺めながら、心地よい夕方の風を感じて優雅なひとときを過ごす。','2026-06-12','13:30','🛸','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,581,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.168330000,136.905560000,'5軒目：老舗うなぎ店で至福の極み「ひつまぶし」を堪能','旅のハイライトとして、名古屋が誇る最高峰グルメ「ひつまぶし」の名店へ。一杯目はそのまま香ばしい鰻とタレの味を楽しみ、二杯目は薬味を添えてさっぱりと、三杯目はお出汁をかけてお茶漬けでいただく。三段階の絶品の変化に感動の連続。','2026-06-12','15:00','🍱','0','',-4200,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,582,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.165280000,136.901390000,'「伏見地下街」の昭和レトロな空間でディープな街並み体験','かつての面影を色濃く残す、隠れ家的な伏見地下街のレトロな通路を歩く。現代のきらびやかな名古屋とは一味違う、昭和のノスタルジーが詰まった独特の空間に迷い込み、ディープな名古屋の歴史の奥行きをしみじみと味わう。','2026-06-12','16:45','🚪','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,583,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.166940000,136.905280000,'6軒目：名古屋の夜を彩る名店でピリ辛「台湾ラーメン」','名古屋の夜の締めくくりとして、ピリッとした辛さがクセになる元祖「台湾ラーメン」のお店へ。たっぷりの挽き肉とニラ、特製唐辛子の効いたスープが麺によく絡み、汗をかきながらもスープを飲み干してしまうほどのやみつきになる旨さ。','2026-06-12','18:30','🍜','0','',-980,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (39,584,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.172220000,136.908330000,'「テレビ塔周辺の夜景」とライトアップされた街並みを眺める','夜の帳が下りた久屋大通公園に戻り、美しくライトアップされたタワーと周囲のモダンなビル群が織りなす幻想的な夜景を眺める。きらびやかな光に包まれた名古屋の夜の美しさに、今日一日食べた美味しい記憶がよみがえる。','2026-06-12','19:45','🌃','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,585,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.171390000,136.883330000,'お土産選び：駅ナカの老舗ショップで絶品「手羽先唐揚げ」を調べる','旅の最後のお楽しみとして、名古屋駅ナカの充実したお土産フロアへ。ジューシーでスパイシーな香りが食欲をそそる有名店の「手羽先唐揚げ」や、ういろう、名古屋めしのお土産を丁寧に吟味して、家族や自分への最高の思い出の品を選ぶ。','2026-06-12','20:30','🛍️','0','',-2000,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (39,586,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.170830000,136.881940000,'「名古屋駅」にて大満足のグルメ旅のフィナーレと帰路','すべての行程を食べ尽くし、大満足の笑顔で名古屋駅の改札前に集合する。「また絶対に来たいね」とお互いに語り合いながら、心もお腹も極上に満たされた素晴らしい名古屋グルメ旅のエンディングを迎え、それぞれの帰路につく。','2026-06-12','21:15','👋','0','',0,1,0,0,0,0,false,'2026-08-01 22:03:08.867343+09','2026-08-01 22:03:08.867343+09','{}'),
	 (40,587,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455280000,139.600830000,'「東武日光駅」に到着、厳かな神域・日光への旅の始まり','歴史と神話が息づく静謐な空気の中、東武日光駅に到着。これから始まる世界遺産・日光の社寺巡りと美しい自然を巡る旅に、心が一気に引き締まるような高揚感を覚える。駅舎を出ると、遠くの山々から吹き抜ける澄んだ風が心地よく迎えてくれる。','2026-07-08','09:00','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,588,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.452780000,139.598610000,'1軒目：駅前のおしゃれなカフェでいただく日光天然氷のかき氷','旅の無事を祈りつつ、まずは駅近くの人気カフェにて日光の豊かな自然が生んだ「天然氷」を使った特製かき氷を味わう。ふわふわとした雪のように軽い口溶けと、甘酸っぱい特製イチゴシロップの味わいが、旅の疲れを優しく癒やしてくれる最高のウォーミングアップ。','2026-07-08','09:30','🍧','0','',-1000,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,589,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.453890000,139.596670000,'レトロな佇まいが美しい「日光金谷ホテル」の歴史的エントランス','日本最古のリゾートホテルとして知られる日光金谷ホテルのクラシックな外観を眺めながら坂道を登る。随所に西洋の伝統と日本の伝統美が融合した明治ロマンの香りが漂い、かつての貴人たちが愛した優雅な空気を肌で感じる素晴らしい散策スポット。','2026-07-08','10:45','🏛️','0','',0,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,590,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.451940000,139.599170000,'鮮やかな朱色が目を引く世界遺産「神橋」の美しい姿を望む','大谷川の清流にかかる、神聖な朱塗りの美しい「神橋」のたもとに到着。古くから日光山の入口として崇められてきた神秘的な佇まいは、周囲の新緑や紅葉と見事なコントラストを描き、思わずカメラを向けたくなる絶景スポット。','2026-07-08','11:30','🌉','0','',-300,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,591,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455000000,139.599720000,'世界遺産「日光山輪王寺」の三仏堂で荘厳な仏像を拝観','徳川家ゆかりの天台宗の別格本山・輪王寺の「三仏堂」に足を踏み入れる。圧倒的なスケールを誇る金色の三体の仏像（千手観音像・阿弥陀如来像・馬頭観音像）の前に静かに佇み、心穏やかに手を合わせることで、深い安らぎと厳かな時間に包まれる。','2026-07-08','13:00','🛕','0','',-400,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,592,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.458330000,139.600560000,'国宝「日光東照宮」の絢爛豪華な陽明門と眠り猫に魅了される','いよいよ旅のハイライトである世界遺産・日光東照宮へ。幾重にも施された極彩色の彫刻や、一日中眺めていても飽きないと言われる「陽明門」、そして平和の象徴である「眠り猫」の精巧な芸術美をじっくりと見学し、江戸時代の圧倒的な職人技に深く感嘆する。','2026-07-08','14:15','🦁','0','',-1600,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,593,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.456670000,139.601390000,'徳川家康公の眠る神聖な奥宮へと続く「眠り猫の参道」を歩く','「眠り猫」のくぐり戸を抜け、207段の石段が続く杉木立の参道を一歩一歩静かに登る。鬱蒼と茂る巨大な杉の木が作り出す荘厳なトンネルの中を進むにつれて、俗世から離れた神聖な空間に心がどんどん澄んでいくのを感じる。','2026-07-08','15:45','🌲','0','',0,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (40,594,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.457500000,139.601940000,'2軒目：東照宮参道の老舗食堂で湯波（ゆば）蕎麦ランチ','参拝を終えた後は、日光名物である「湯波（ゆば）」をふんだんに使った名物の湯波蕎麦を老舗の落ち着いた食事処でいただく。出汁をたっぷりと吸い込んだジューシーな巻き湯波と香り高い手打ち蕎麦の組み合わせが、歩き疲れた体にたまらなく美味しい。','2026-07-09','11:00','🍲','0','',-1350,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,595,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455560000,139.598890000,'縁結びのパワースポット「日光二荒山神社」で旅の平穏を祈願','下野国の一宮として古くから信仰を集める日光二荒山神社へ。鮮やかな朱塗りの社殿が美しい境内をゆっくりと巡り、夫婦杉や化け燈籠といった見どころを散策。神聖なパワーが満ちる静かな境内で、旅の安全と日々の平穏を丁寧にお祈りする。','2026-07-09','12:30','⛩️','0','',0,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,596,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.453330000,139.595560000,'3軒目：日光の老舗洋菓子店でいただく極上の日光プリン','石畳の落ち着いた通りにある、こだわりの日光プリン専門店に立ち寄る。厳選された地元の牛乳と新鮮な卵を使い、なめらかな口溶けに仕上げられた濃厚なプリンを味わう。可愛いガラス瓶に入ったスイーツは、旅の疲れを吹き飛ばす甘いご褒美。','2026-07-09','13:45','🍮','0','',-450,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,597,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.442780000,139.491670000,'いろは坂のドラマチックなワインディングロードをバスで抜ける','中禅寺湖へと向かう、有名な「第二いろは坂」の急カーブが続くワインディングロードを進む。車窓から望むダイナミックな渓谷の絶景と、季節ごとに表情を変える豊かな山々の緑のパノラマに、思わず息をのむような迫力を味わう。','2026-07-09','15:00','🚌','0','',0,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,598,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.440280000,139.497500000,'「華厳の滝」の轟音としぶきを上げる圧倒的な大瀑布に感動','日本三大名瀑の一つである「華厳の滝」の観覧台へ。高さ97メートルの断崖絶壁を一気に流れ落ちる豪快な水流と、周囲に舞う水しぶきを間近で体感する。自然の生み出す圧倒的なスケールと轟音に、言葉を失うほどの感動を覚える。','2026-07-09','16:00','🌊','0','',-570,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,599,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.435000000,139.495000000,'4軒目：中禅寺湖畔のレトロな洋風カフェで湖を眺めるティータイム','男体山の麓に広がる美しい中禅寺湖のほとりに佇む、クラシックな洋風カフェへ。穏やかな湖面を渡る涼しい風を感じながら、自家焙煎のコーヒーと香ばしいアップルパイをいただく。静寂に包まれた湖畔での優雅なティータイムは、大人の旅にふさわしい贅沢なひととき。','2026-07-09','17:15','☕','0','',-1100,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,600,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.438890000,139.498610000,'「中禅寺（立木観音）」の神秘的な千手観音像を参拝','中禅寺湖のほとりに建つ、日光山輪王寺の別院である「中禅寺」を訪れる。生木の根元に彫られたと伝わる神秘的な「立木観音像」の美しさと気高さに静かに向き合い、厳かな境内で心の内を整える静かな祈りの時間を過ごす。','2026-07-10','10:00','🙏','0','',-500,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,601,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.453060000,139.597500000,'お土産選び：日光駅周辺の老舗店で「たまり漬け」と羊羹を吟味','再び日光駅周辺に戻り、旅の思い出となるお土産をじっくりと選び歩く。伝統の味を守り続ける老舗の「たまり漬け」や、上品な甘さの「日光羊羹」、職人手作りの民芸品などを丁寧に買い求め、充実した旅の最後を彩る。','2026-07-10','12:00','🛍️','0','',-2500,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (40,602,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.455000000,139.600500000,'「東武日光駅」にて神社仏閣と大自然を巡る旅のエンディング','すべての行程を無事に巡り、情緒あふれる東武日光駅のホームに立つ。世界遺産の荘厳な社寺建築、奥日光の大自然、そして美味しい地元グルメの数々を深く堪能した心地よい達成感に浸りながら、笑顔で帰路の特急列車に乗り込む。','2026-07-10','13:30','👋','0','',0,1,0,0,0,0,false,'2026-08-01 22:08:36.289704+09','2026-08-01 22:08:36.289704+09','{}'),
	 (41,603,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.703890000,138.256110000,'「芦安駐車場」に集合、三人揃って気合を入れ直す朝','早朝の芦安駐車場に、久々に集結したアラフォー・オッサン三人組。これから始まる南アルプス深部への過酷な縦走に向け、ザックの重さを確かめつつ、気合の入ったコーヒーで乾杯。山の天気も上々、男三人だけの熱い登山旅の幕開けに胸が高鳴る。','2026-08-08','05:30','🚙','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (41,604,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.698330000,138.225560000,'南アルプスの急峻な山並みを駆け上がる登山口行きの乗り合いタクシー','マイカー規制の区間を乗り合いタクシーに揺られ、ガタゴトと林道を登っていく。窓の外に広がる深い緑の渓谷と、これから挑む峰々の険しさに圧倒されながら、車内では学生時代からの思い出話や最近の健康談義で早くも大盛り上がり。','2026-08-08','06:15','🚕','0','',-1200,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,605,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.688890000,138.163330000,'日本屈指の高峰「北岳」への登り口、広河原山荘に到着','南アルプスの玄関口・広河原に到着し、いよいよ登山道へ足を踏み入れる。澄んだ沢のせせらぎを聞きながら、吊り橋を渡って登山スタート。最初は緩やかだった道も徐々に急勾配へと変わり、三人とも一言も話さず黙々と歩みを進める。','2026-08-08','07:30','⛺','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,606,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.673060000,138.165000000,'息を切らしながら登る白根御池小屋のキツい急登区間','標高を上げるにつれて足取りが重くなり、名物の急登「草すべり」の手前で早くも息が上がる。重いザックに肩を食い込ませながら、「お前、最近運動不足じゃないか？」と軽口を叩き合い、お互いを鼓舞しながら一歩一歩足を前に出す。','2026-08-08','09:30','🥾','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,607,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.671390000,138.156390000,'緑のなかに佇むオアシス「白根御池小屋」で冷えたビール休憩','ようやくたどり着いた白根御池小屋のテラスで、待ちに待った乾杯の瞬間。冷え切った缶ビールをグイッと煽ると、疲労困憊だった体に染み渡るような極上の美味さが広がる。目の前に広がる雄大な自然のなか、三人で声を揃えて至福のため息をもらす。','2026-08-08','11:30','🍺','0','',-700,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,608,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.678890000,138.146110000,'森林限界を抜けて一気に視界が開ける稜線歩きへ','樹林帯を抜け出し、一気に視界が開けた美しい稜線歩きが始まる。強めの風が火照った体を心地よくクールダウンしてくれる。眼下には雲海が広がり、遠く富士山や中央アルプスの峰々まで見渡せる絶景に、思わず三人で足を止めて見とれてしまう。','2026-08-08','13:00','⛰️','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,609,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.670830000,138.140280000,'日本第2位の高峰「北岳」山頂に三人揃って登頂成功！','ついに標高3193メートルの北岳山頂に三人揃って登頂！ 日本屈指の高みから見下ろす360度の大パノラマと、自分たちの足で登り切ったという確かな達成感が全身を包み込む。肩を組み、満面の笑みで記念撮影をパチリ。','2026-08-08','15:00','🚩','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,610,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.666940000,138.138890000,'雲上の避難所「北岳山荘」にチェックイン、夕暮れの赤く染まる峰々','本日の宿泊地である北岳山荘へ無事に到着。夕暮れ時、西の空に沈む夕日が南アルプスの山々を茜色に染め上げていくドラマチックなマジックアワーを眺める。冷たい風の中、温かい山小屋の食堂へと急ぎ足で滑り込む。','2026-08-08','17:00','🌅','0','',-10000,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,611,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.667220000,138.139170000,'山小屋の夜、消灯までのオッサン三人による熱い夜の語らい','山小屋の食堂の一角で、温かい夕食を食べながら至福の晩酌タイム。缶ビールやウイスキーを傾けつつ、昔の馬鹿な思い出や仕事の愚痴、これからの人生プランまで、普段は言えない本音を夜遅くまで語り合う忘れられない時間。','2026-08-08','19:30','🥃','0','',-1500,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,612,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.659170000,138.144170000,'ご来光の瞬間を待ちわびる、朝の寒さと静寂に包まれた「間ノ岳」への縦走','まだ夜が明けきらぬ暗闇の中、ヘッドライトの灯りを頼りに「間ノ岳」へ向けて出発。身を切るような早朝の寒さの中、じっと東の空を見つめ、漆黒の闇から鮮やかなオレンジ色の太陽が昇る感動的なご来光の瞬間を共有する。','2026-08-09','04:30','✨','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,613,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.656940000,138.145830000,'日本屈指のスケールを誇る「間ノ岳」山頂で記念撮影','なだらかな稜線を進み、日本百名山の一つである間ノ岳の山頂に到着。周囲の山々が朝日に照らされて黄金色に輝き、南アルプス南部の広大なスケール感を肌で実感する。達成感に満ちた男三人の表情が、朝の光に自然と映える。','2026-08-09','06:30','🏔️','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (41,614,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.665000000,138.150000000,'下山路の途中、バテた足を励まし合う「農鳥小屋」周辺の難所','ここからの長い下山路、連日の疲労が蓄積して足の踏ん張りが利かなくなる。名物小屋主で知られる農鳥小屋の周辺を通過しながら、足の痛みをこらえ、お互いの荷物を少しずつ持ち合いながら慎重に急な斜面を下っていく。','2026-08-09','09:00','⚠️','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,615,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.688890000,138.163330000,'無事に登山口の「広河原」へと生還、安堵の深呼吸','長い長い下りの末、ついにスタート地点である広河原へ無事に生還。無事故で全員が自分の足で戻ってこられた安堵感から、大きく息を吸い込んで「お疲れさん！」と固い握手を交わす。心地よい疲労感が全身を心地よく満たす。','2026-08-09','13:00','🎉','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (55,856,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559000000,133.533600000,'ひろめ市場で昼食','カツオのたたきを豪快にいただく。藁焼きの香りが最高でテンションが上がる。','2026-08-11','12:00','🍣','0000','',-1600,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (41,616,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.711110000,138.258330000,'下山後の至福、山梨の温泉施設で汗を流す','登山バスを乗り継ぎ、下山後に立ち寄った地元の温浴施設へ。冷えた温泉に浸かった瞬間、凝り固まった筋肉がほぐれていく至福の感覚に「生き返る〜」と思わず声が漏れる。湯上がりには冷たい牛乳を飲み干し、最高の爽快感を味わう。','2026-08-09','16:00','♨️','0','',-800,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,617,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.705000000,138.255560000,'打ち上げの居酒屋で甲州名物の馬刺しと地酒を堪能','旅の締めくくりは、地元の隠れ家的居酒屋での盛大な打ち上げ。新鮮な甲州名物の馬刺しやほうとうをつまみに、冷えたビールと地酒を次々と空けていく。「また来年もどこかの山に行こうぜ！」と熱い約束を交わし、笑いの絶えない夜を過ごす。','2026-08-09','18:30','🍺','0','',-5000,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (41,618,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.703890000,138.256110000,'「芦安駐車場」に戻り、それぞれの日常へと帰る解散の時','すべての行程を終えて芦安駐車場に戻り、愛車に乗り込む前にお互いの健闘をたたえ合って三者三様の帰路につく。過酷で最高に楽しいオッサン三人組の南アルプス登山旅行の余韻に浸りながら、また次の冒険への活力を胸にハンドルを握る。','2026-08-09','21:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-01 22:14:13.272362+09','2026-08-01 22:14:13.272362+09','{}'),
	 (64,1009,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.831912000,132.872044000,'道の駅たかので休憩','道の駅は広く段差が少ないため、お年寄りでも安心して利用できる。地元の野菜やお菓子が並び、旅の途中の休憩にぴったり。外のベンチで風を感じながらゆっくり過ごした。','2026-10-22','15:00','🛍️','0000','',-600,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (42,619,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.621940000,138.596670000,'「草津温泉バスターミナル」に到着、三世代みんな揃っての温泉旅の幕開け','心地よい硫黄の香りがふわりと漂う草津温泉バスターミナルに到着。元気いっぱいの孫たち、優しい笑顔の祖父母、そして頼もしい親世代の三世代全員が揃い、これから始まる家族みんなの温泉旅行への期待感に胸を弾ませる。記念すべき最初の家族写真をパシャリと撮影。','2026-09-12','10:00','🚌','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,620,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623610000,138.597780000,'湯けむりとエメラルドグリーンの湯が美しい象徴「湯畑」を散策','草津のシンボルである「湯畑」へ移動し、もうもうと湯煙を上げるダイナミックな源泉の光景にみんなで歓声をあげる。エメラルドグリーンの美しい温泉が滝のように流れ落ちる様子を眺めながら、木製の歩道橋をのんびりとお散歩。温泉街ならではの活気ある雰囲気を肌で感じる。','2026-09-12','10:45','♨️','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,621,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623060000,138.599170000,'1軒目：湯畑のすぐそばで味わう、湯上がりアツアツの温泉まんじゅう','湯畑周辺の賑やかな商店街を歩きながら、湯気香る老舗の店先で名物の温泉まんじゅうを買い求める。ふかしたての柔らかい皮と、上品な甘さの漉し餡が絶妙なバランスで、歩き疲れた祖父母や子どもたちも「美味しいね」と満面の笑みを浮かべる。','2026-09-12','11:30','🍭','0','',-450,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (54,829,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.513900000,133.563900000,'坂本龍馬像を見学','龍馬像の迫力に感動。太平洋を見つめる姿がかっこよくて、写真を何枚も撮ってしまった。','2026-08-04','11:40','🗿','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (42,622,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.621110000,138.595000000,'伝統の妙技に大盛り上がり！「熱乃湯」で湯もみ見学と体験','草津温泉の伝統文化である「湯もみ」のショーが開催される熱乃湯へ。威勢の良いかけ声とともに板で湯をかき混ぜるダイナミックなパフォーマンスを間近で鑑賞し、子どもたちは体験コーナーで実際に湯もみに挑戦して大はしゃぎ。家族みんなで大いに盛り上がる。','2026-09-12','13:00','🎭','0','',-2100,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,623,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.624720000,138.593890000,'2軒目：レトロ可愛いカフェで味わう草津名物の濃厚ソフトクリーム','温泉街の路地裏にある、おしゃれで落ち着いた雰囲気のカフェに立ち寄る。濃厚なミルクのコクと爽やかな甘さが絶品のソフトクリームをみんなでシェアして味わう。歩いて火照った体に冷たいスイーツが心地よく染みわたり、旅の会話が一層弾む。','2026-09-12','14:15','🍦','0','',-1200,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,624,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.619170000,138.591670000,'日本庭園の美しい温泉情緒あふれる「西の河原公園」をゆっくりお散歩','あちこちから温泉が湧き出す湯川沿いの「西の河原公園」へ足を延ばす。ゴロゴロとした岩の間から立ち上る湯気と、豊かな自然が織りなす幻想的な景色の中を、祖父母の手を優しく引きながら三世代でゆっくりと歩く。マイナスイオンに包まれて心が癒やされる。','2026-09-12','15:00','🌳','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,625,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.616940000,138.589170000,'日本最大級の露天風呂「西の河原露天風呂」の広大な湯船に浸かる','大自然の開放感あふれる西の河原露天風呂に到着。遮るもののない広大な湯船にゆったりと体を沈めると、心地よい温泉が全身の疲れを優しく解きほぐしてくれる。木々の緑を眺めながら、世代を超えて並んでお湯に浸かる贅沢なひとときを噛みしめる。','2026-09-12','15:45','♨️','0','',-2100,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,626,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.625830000,138.595560000,'3軒目：温泉街の老舗食堂で楽しむ、名物・舞茸天ぷらうどんのランチ','お昼時は、地元で長く愛されるアットホームな老舗食堂で家族みんな揃ってランチタイム。サクサクに揚がった香ばしい地元の名物・舞茸の天ぷらと、出汁がしっかりと効いた温かいおうどんをいただき、お腹も心もすっかり満たされる。','2026-09-13','12:00','🥢','0','',-3500,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,627,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.630000000,138.592500000,'「草津熱帯圏」で珍しい動物や可愛いおサルさんたちとふれあい','子どもたちが大喜びすること間違いなしの草津熱帯圏へ。ドーム型の館内で、珍しい南国の動物たちや元気なサル、カピバラたちの愛らしい姿を間近で見学する。間近で見る動物たちに、孫たちは大興奮で家族みんなの笑顔があふれる楽しい時間。','2026-09-13','13:30','🐒','0','',-4200,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,628,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623890000,138.598330000,'お土産選び：伝統の「草津温泉の素」と特製お漬物を吟味','夕方になり、再び湯畑周辺の土産物店街に戻ってお土産選びの時間。草津の温泉気分を自宅でも味わえる「草津温泉の素」や、職人こだわりの特製お漬物、温泉たまごなどを丁寧に選び、家族それぞれに思い出の品を買い揃える。','2026-09-13','15:30','🛍️','0','',-5000,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (55,857,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560300000,133.531900000,'高知城へ向かう','城下町の雰囲気が残る道を歩く。石垣が見えてくるとワクワクが高まる。','2026-08-11','13:00','🏯','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (42,629,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622500000,138.601110000,'伝統と温もりあふれる老舗温泉宿にチェックイン、客室でほっと一息','本日の宿泊先である、歴史ある和風の温泉宿にチェックイン。上品なしつらえの広々とした和室の客室に通され、お茶菓子をいただきながら窓の外に広がる温泉街の景色を眺め、旅の疲れを癒やしてほっと一息つく。','2026-09-13','16:30','宿','0','',-60000,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (42,630,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622780000,138.601390000,'宿の大浴場にて、草津の誇る名湯「万代鉱源泉」の湯を満喫','夕食の前に、宿自慢の大浴場と風情ある露天風呂へ。草津の名湯の一つである「万代鉱源泉」の強力な酸性泉にゆったりと体を預け、日頃の疲れが嘘のように消えていく至福の湯あみを家族それぞれが存分に堪能する。','2026-09-13','17:15','♨️','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (64,1010,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.833129000,132.876512000,'庄原の田園を眺める','道の駅近くの田園は広く、風が通り抜ける音が心地よい。ゆっくり歩きながら景色を眺めると、庄原らしい穏やかな時間が流れる。旅の終盤にふさわしい静かな場所だった。','2026-10-22','15:30','🌾','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (44,659,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.225000000,133.033330000,'「大三島・大山祇神社」を参拝、神聖なクスノキの巨樹からパワーを授かる','日本総鎮守として古くから信仰を集める大三島の「大山祇神社」に立ち寄る。境内を厳かに包み込む樹齢数千年のご神木の巨大なクスノキの姿に圧倒され、静寂に満ちた境内をゆっくりと歩きながら厳かなパワーをいただく。','2026-11-04','13:30','🌲','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (42,631,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622500000,138.601000000,'三世代みんなで囲む、上州牛のすき焼きと旬の会席料理の夕食','お待ちかねの夕食は、個室の食事処で三世代揃って華やかな会席料理を囲む。とろけるように柔らかい上州牛のすき焼きや、旬の川魚の塩焼きなど贅沢なご馳走に、祖父母も孫たちも「美味しいね！」と大喜びの賑やかな夜。','2026-09-13','18:30','🍽️','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,632,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.623330000,138.597500000,'夜のライトアップに彩られた幻想的な「湯畑」を夜のお散歩','夕食後、浴衣姿に丹前を羽織って夜の温泉街へお散歩に出かける。ライトアップされた幻想的な「湯畑」は昼間とは違ったムーディーな美しさがあり、湯けむりが夜空に浮かび上がる光景を眺めながら、家族仲良くのんびりと歩く。','2026-09-13','20:00','🌙','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,633,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.622500000,138.601110000,'4軒目：宿のロビーラウンジで味わう、湯上がりナイトデザート','お散歩から宿に戻った後は、温かいお部屋でくつろぎつつ、ロビーラウンジで用意された湯上がりの特製プリンや甘味をいただく。今日一日の楽しい思い出を家族みんなで語り合いながら、穏やかで温かい夜の時間がゆっくりと流れていく。','2026-09-13','21:00','🍮','0','',-800,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (42,634,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,36.621940000,138.596670000,'「草津温泉バスターミナル」にて、三世代の思い出深い旅のフィナーレ','翌日、すべての行程を温かい笑顔で終え、帰りのバスターミナルへ。「本当に楽しい旅行だったね、またみんなで来ようね」と祖父母と孫たちが手を振り合い、家族の絆が一段と深まった素晴らしい草津温泉・三世代旅行の幕を閉じる。','2026-09-14','10:00','👋','0','',0,1,0,0,0,0,false,'2026-08-01 22:18:37.768107+09','2026-08-01 22:18:37.768107+09','{}'),
	 (54,830,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514800000,133.561200000,'桂浜茶屋で休憩','名物のアイスクリンを食べながら海を眺める。軽い甘さが暑い体にちょうどいい。','2026-08-04','12:10','🍦','0000','',-350,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (43,635,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.693890000,'「JR姫路駅」に到着、目の前にそびえる白亜の姫路城に胸を高鳴らせる朝','歴史と現代が美しく調和するJR姫路駅に降り立ち、一直線に伸びる大手前通りの向こう側に堂々とそびえ立つ白亜の世界遺産・姫路城の姿を望む。青空の下で圧倒的な存在感を放つ「白鷺城」との出会いに、これからの歴史探訪の旅への期待感が一気に高まる。','2026-10-10','09:00','🚅','0','',0,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,636,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838890000,134.692500000,'1軒目：駅前のおしゃれなカフェで味わう、姫路モーニングと名物のアーモンドトースト','姫路ならではの食文化を楽しむため、駅前の老舗カフェへ朝のひとときに立ち寄る。香ばしいアーモンドの香りと濃厚なバターのコクが絶妙にマッチした名物の「アーモンドトースト」を一口頬張り、香り高いブレンドコーヒーとともに優雅で贅沢な朝の時間を過ごす。','2026-10-10','09:30','🍞','0','',-850,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (43,637,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.842220000,134.693890000,'「大手前公園」を抜け、美しい城の姿を間近に眺めながらのんびりお散歩','きれいに整備された大手前公園の開放的な歩道を、心地よい春風を感じながら北へと歩みを進める。木々の緑の向こう側に少しずつ大きく迫ってくる姫路城の美しく優美な大天守の姿に、思わず何度も足を止めてカメラのシャッターを切ってしまう。','2026-10-10','10:30','🌳','0','',0,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,638,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.845560000,134.693890000,'世界遺産・国宝「姫路城」の美しい大天守と巧みな防御の工夫を見学','ついに世界文化遺産・国宝である姫路城の境内へ足を踏み入れる。幾重にも張り巡らされた複雑な門や狭間など、戦国時代の高度な建築美と巧妙な防御の仕組みに感嘆しながら、真っ白な漆喰壁が美しい大天守の内部へとじっくりと登っていく。','2026-10-10','11:00','🏯','0','',-1000,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,639,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.843060000,134.690830000,'日本庭園の傑作「好古園」で、四季折々の自然と静寂な日本庭園を散策','姫路城の西側に広がる、趣の異なる九つの庭園群からなる本格的な日本庭園「好古園」へ。手入れされた美しい池や滝、見事な松の緑が織りなす静寂で雅な空間をゆっくりと歩き、日本の伝統的な美意識に触れながら心穏やかなひとときを過ごす。','2026-10-10','13:30','🍁','0','',-310,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,640,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.843330000,134.690000000,'2軒目：好古園内の茶室「好古園 活水軒」で味わう、優美な抹茶と和菓子','庭園の緑を一望できる好古園内の風情ある茶室「活水軒」に立ち寄る。静かに流れる水の音に耳を傾けながら、職人が一つひとつ丁寧に作り上げた上品な上生菓子と、点てたての香り高いお抹茶をいただく。旅の疲れがすーっと癒やされる至福の休憩時間。','2026-10-10','14:30','🍵','0','',-700,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,641,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.840560000,134.691670000,'3軒目：城下町の隠れ家的名店でいただく、ご当地グルメ「姫路おでん」のランチ','お昼時は、生姜醤油で食べるのがご当地流である名物の「姫路おでん」を味わいに老舗の食事処へ。じっくりと出汁の染み込んだ大根や牛すじに、キリッとした生姜醤油の風味がアクセントとなり、他では味わえない奥深い美味しさに箸が止まらない。','2026-10-11','12:00','🍢','0','',-1400,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (55,858,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560040000,133.531430000,'高知城天守に登る','天守からの眺めが最高。高知の街並みと青空が広がっていて気持ちが明るくなる。','2026-08-11','13:30','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,859,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559500000,133.532200000,'城下で休憩','城下のカフェでアイスコーヒー。旅の充実感がじんわり広がる。','2026-08-11','14:00','☕','0000','',-580,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (43,642,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.882220000,134.646390000,'ロープウェイに揺られ、映画のロケ地としても名高い「書写山円教寺」へ','市街地を離れて北西へ向かい、豊かな自然に包まれた書写山へ。ロープウェイの窓から眼下に広がる雄大な山々と播磨平野の景色を眺めながら空中散歩を楽しみ、西の比叡山とも称される歴史ある天台宗の古刹・円教寺の境内へと足を踏み入れる。','2026-10-11','13:30','🚡','0','',-1000,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,643,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.883330000,134.639170000,'重厚な木造建築が立ち並ぶ円教寺の国重要文化財「大講堂・食堂・常行堂」を見学','深い森の静寂に包まれた円教寺の核心部に到着。ダイナミックで重厚な佇まいを見せる「大講堂」「食堂」「常行堂」の三つのお堂（三之堂）を目の当たりにし、室町時代から受け継がれてきた圧倒的な歴史の重みと、木造建築の美しさに深く感動する。','2026-10-11','14:30','寺','0','',-500,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,644,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.686940000,'姫路の活気あふれる商店街「おみやげ歩行者天国」で特産品探し','夕暮れ時の街に戻り、地元の人や観光客で賑わうアーケード商店街をぶらりとお散歩。姫路名物の穴子寿司や、地元で愛される播磨の銘菓、可愛らしい姫路城グッズなど、旅の思い出を彩る素敵なお土産をじっくりと吟味して買い揃える。','2026-10-11','16:00','🛍️','0','',-4500,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (43,645,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838330000,134.693330000,'歴史ある佇まいとモダンが融合した、駅チカの上質なホテルにチェックイン','本日の宿泊先である、姫路の街並みに溶け込む洗練されたホテルにチェックイン。モダンで機能的ながらも落ち着きのある客室に通され、窓の外にライトアップが始まる直前の夕暮れの姫路城を遠くに眺めながら、旅の荷物を解いてほっと一息つく。','2026-10-11','17:00','宿','0','',-24000,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,646,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.694440000,'夜の闇に白く浮かび上がる幻想的な「ライトアップされた姫路城」を観賞','夕食の前に、夜の闇の中で美しくライトアップされた幻想的な「姫路城」を眺めに夜のお散歩へ。昼間の白さとは一変し、漆黒の夜空に浮かび上がる白鷺城の姿は息を呑むほどに妖艶で美しく、いつまでも眺めていたくなるような絶景が広がる。','2026-10-11','18:30','✨','0','',0,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (54,831,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559300000,133.531700000,'高知市中心部へ戻る','バスで市街地へ戻る。街の明るい雰囲気が心地よくて、歩くだけで楽しい。','2026-08-04','13:00','🚌','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (43,647,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.836670000,134.691170000,'4軒目：隠れ家風の割烹居酒屋で味わう、瀬戸内海の新鮮な海の幸と播磨の地酒','夜のメインディッシュは、播磨の旬の食材が味わえるこだわりの割烹居酒屋へ。目の前の瀬戸内海で水揚げされたばかりの新鮮なお造りや、名物の穴子の天ぷらを堪能しながら、キリッとした辛口の播磨の地酒を合わせ、至福の晩酌タイムをしみじみと楽しむ。','2026-10-11','19:15','🍶','0','',-6500,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,648,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838330000,134.693330000,'ホテルの最上階ラウンジで、旅を振り返る穏やかなナイトキャップ','一日の締めくくりに、ホテルの落ち着いたラウンジスペースへ。今日巡った世界遺産や古刹の風景、美味しい料理の思い出を静かに振り返りながら、温かいハーブティーを片手に、旅の余韻に浸る穏やかな夜の時間がゆっくりと流れていく。','2026-10-11','21:00','☕','0','',-1200,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,649,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.786940000,134.835830000,'翌日、少し足を延ばして訪れた瀬戸内海に面する美しい海岸線をドライブ','旅行2日目はレンタカーを借りて、穏やかな瀬戸内海の海岸線へとドライブに出かける。キラキラと太陽の光を反射して輝く青い海と、点在する島々の美しい景色を眺めながら、心地よい海風を感じる最高のドライブコースを満喫する。','2026-10-12','10:00','🚗','0','',-3000,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (43,650,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.839440000,134.693890000,'「JR姫路駅」に戻り、たくさんの思い出と感動を胸に帰路につく','すべての行程を大満足で終えて再びJR姫路駅へ戻る。駅ナカのショップで買い忘れたお土産を買い足し、新幹線のホームへと向かう。「歴史とグルメを満喫できた最高の旅だったね」と笑顔で語り合いながら、たくさんの思い出を胸に帰路の途につく。','2026-10-12','15:00','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:10:02.397611+09','2026-08-02 01:10:02.397611+09','{}'),
	 (44,651,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.404170000,133.201390000,'「JR尾道駅」に到着、目の前に広がる青い瀬戸内海と島影に胸が高鳴る朝','千光寺山の緑と穏やかな瀬戸内海に挟まれた風情あるJR尾道駅に降り立つ。目に前にきらめく海原と、対岸に浮かぶ島々の美しい風景を眺めながら、これから始まる瀬戸内海の島々を巡る絶景ドライブ＆フェリー旅への期待感に胸を弾ませる。','2026-11-03','09:00','🚢','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,652,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.405560000,133.199720000,'1軒目：尾道水道を望むレトロなカフェで味わう、自家製レモンスカッシュとモーニング','尾道水道を行き交う個性豊かな渡船を眺めながら、海沿いのスタイリッシュなカフェで朝のひととき。瀬戸内特産の爽やかなレモンをふんだんに使った自家製レモンスカッシュをいただき、心地よい海風を感じながら優雅で穏やかな朝の時間を満喫する。','2026-11-03','09:30','🍋','0','',-900,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,653,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.408330000,133.197500000,'「尾道本通商店街」をぶらりお散歩、ノスタルジックな昭和の面影に触れる','歴史ある寺社やおしゃれな雑貨店が立ち並ぶ、情緒あふれる尾道本通商店街をゆっくりとお散歩。昔ながらの看板建築や猫の細道へと続く路地裏の景色を楽しみながら、のんびりと流れる尾道ならではの温かい時間を肌で感じる。','2026-11-03','10:30','🐈','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (44,654,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.410560000,133.203330000,'ロープウェイで一気に登る「千光寺公園展望台」から、瀬戸内海の絶景を一望','ロープウェイに揺られて一気に山頂の千光寺公園展望台へとアクセス。眼下に広がる尾道水道と、点在する島々を結ぶ尾道大橋の壮大なパノラマビューを目の当たりにし、あまりの美しさに時間を忘れて見入ってしまう。','2026-11-03','11:30','🚡','0','',-700,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,655,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.401110000,133.178330000,'「しまなみ海道」の起点・向島から、多島美の海峡を渡るドライブのスタート','車に乗り込み、いよいよサイクリストの聖地としても名高い「しまなみ海道」の島々へ。最初の島である向島から、幾重にも重なる青い海と美しい島影が織りなす「多島美」の絶景の中へと車を走らせ、爽快なドライブを楽しむ。','2026-11-03','13:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,656,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.316670000,133.111110000,'2軒目：レモンの島・生口島「瀬戸田サンセットビーチ」で味わう名物ジェラート','レモンの生産量日本一を誇る生口島へ渡り、美しい白砂のビーチが広がる瀬戸田サンセットビーチに立ち寄る。地元の新鮮な柑橘やミルクをふんだんに使った絶品ジェラートを味わいながら、穏やかな波音を聞いて心からリフレッシュする。','2026-11-03','14:30','🍦','0','',-500,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,657,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.298610000,133.061390000,'「多々羅大橋」を渡り、空に浮かぶような斜張橋のダイナミックな造形美を体感','愛媛県と広島県を結ぶ日本屈指の美しさを誇る「多々羅大橋」を車で渡る。青い海と空の間に美しく架かる巨大な斜張橋の上からの眺めはまるで空を飛んでいるかのような爽快感があり、瀬戸内海のスケールの大きさに感動する。','2026-11-03','15:30','🌉','0','',-1000,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,658,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.300560000,133.058330000,'3軒目：多々羅しまなみ公園のレストランで味わう、新鮮な鯛の塩ラーメンのランチ','多々羅大橋のたもとにある道の駅のレストランで、遅めの贅沢なランチタイム。瀬戸内で水揚げされた新鮮な真鯛の旨味が凝縮された絶品の塩ラーメンをいただき、香ばしいスープの一滴まで残さず美味しく完食してお腹も大満足。','2026-11-04','12:00','🍜','0','',-950,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,660,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.404170000,133.201390000,'尾道市街地に戻り、夜の海風が心地よいウォーターフロントをナイトクルーズ','夕方再び尾道に戻り、ライトアップされた尾道大橋や夜の港を望むウォーターフロントへ。潮風を感じながらおだやかな海岸線をゆっくりと散策し、旅の1日目を締めくくる静かでロマンチックな夜のひとときを過ごす。','2026-11-04','16:30','🌙','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,662,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.403890000,133.200500000,'宿のメインダイニングにて、瀬戸内海の旬の海の幸と地野菜をふんだんに使った夕食','夕食は宿の美しいダイニングで、瀬戸内海の荒波にもまれた新鮮な魚介や地元の豊かな野菜をふんだんに使った創作コース料理を堪能。素材の持ち味を活かした繊細な味わいと、極上の地酒のマリアージュに心から酔いしれる。','2026-11-04','19:00','🍽️','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,663,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.347500000,133.722220000,'翌日、フェリーを乗り継いで現代アートの聖地・直島へ向かう海の旅','旅行2日目は少し趣向を変えてフェリーに乗り込み、瀬戸内海に浮かぶ現代アートの聖地・直島へと海の旅へ向かう。波飛沫を上げながら進むフェリーの甲板から、青く輝く海と遠くに見える島々の美しい景色を眺める贅沢な移動時間。','2026-11-05','10:00','⛴️','0','',-1500,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,664,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.455560000,133.916670000,'「直島・地中美術館」のコンクリート建築と自然が融合した空間芸術に圧倒される','自然を損なわないよう地下に埋設された「地中美術館」に到着。建物そのものが巨大なアート作品となっている空間の中で、モネの睡蓮をはじめとする世界的名作の数々と静かに対峙し、これまでにない深い感動と知的刺激を受ける。','2026-11-05','13:00','🎨','0','',-2100,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,665,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.458330000,133.980560000,'4軒目：直島の美しい海岸沿いのおしゃれなカフェで、島レモンタルトのティータイム','アート巡りの合間に、海の見える開放的なカフェテラスに立ち寄る。甘酸っぱい島レモンの風味が口いっぱいに広がる特製レモンタルトと、こだわりのアイスコーヒーをいただきながら、目の前に広がる瀬戸内海の絶景を眺めてのんびりティータイム。','2026-11-05','15:00','🍰','0','',-1100,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (44,666,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.453060000,133.919440000,'海の玄関口・直島のフェリーターミナルにて、たくさんの感動を胸に帰路につく','すべての行程を大満足で終え、直島の海の玄関口である象徴的なフェリーターミナルへ。「青い海と島々、そして素晴らしいアートに出会えた最高の旅だったね」と笑顔で語り合いながら、思い出深い瀬戸内海の旅のフィナーレを迎える。','2026-11-05','16:30','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:20.487912+09','{}'),
	 (44,661,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.402780000,133.198330000,'尾道水道の絶景を間近に臨む、隠れ家的なリノベーションホテルにチェックイン','本日の宿泊先である、歴史ある古い倉庫を美しくリノベーションした洗練されたホテルにチェックイン。窓の外に広がる穏やかな尾道水道の夜景を眺めながら、旅の荷物を解いてほっと一息ついてリラックスする。','2026-11-04','17:30','🏨','0','',-28000,1,0,0,0,0,false,'2026-08-02 01:13:20.487912+09','2026-08-02 01:13:53.504103+09','{}'),
	 (46,683,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.464170000,135.398610000,'「JR東舞鶴駅」に到着、歴史ある港町・舞鶴でのワクワクする観光の幕開け','かつて海軍の鎮守府として栄えた歴史の香りが漂うJR東舞鶴駅に降り立つ。ひんやりと心地よい潮風を感じながら、これから巡る歴史ある赤れんがの街並みや日本海に面した美しい景色への期待に胸を膨らませ、元気いっぱいに駅舎をあとにする。','2027-04-10','09:00','🚢','0','',0,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (64,1011,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.823144000,132.873912000,'庄原市街へ戻る','市街へ戻る道は平坦で歩きやすく、ゆっくり進むと今日の出来事が自然と頭に浮かんだ。庄原の静けさと三次の町並みが心に残り、落ち着いた旅になったと感じた。','2026-10-22','16:00','🚶','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (46,684,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.468060000,135.390560000,'1軒目：駅チカの老舗食堂で味わう、スパイシーで懐かしい「海軍カレー」のランチ','舞鶴の海上自衛隊の歴史にちなんだ名物グルメである「海軍カレー」を味わいに、地元の温かな食堂へ。じっくり煮込まれたコクのあるルーとゴロゴロとした具材が絶妙にマッチし、一口食べるごとに深い味わいが広がって心も体もポカポカと温まる。','2027-04-10','09:30','🍛','0','',-1100,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,685,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.452780000,135.391670000,'歴史とロマンが息づく重厚な建物群「舞鶴赤れんがパーク」の散策','明治から大正期にかけて建設されたレンガ倉庫群がそのまま残る「舞鶴赤れんがパーク」へ。レトロで重厚な赤れんがの建物が織りなす独特の美しい景観の中をのんびりと歩き、当時の旧海軍の歴史やロマンあふれる雰囲気を肌でしみじみと感じ取る。','2027-04-10','10:30','🧱','0','',-300,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,686,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.453330000,135.392220000,'2軒目：赤れんが棟の中にあるおしゃれなカフェで、特製珈琲とスイーツのひととき','赤れんがパーク内にある風情あるカフェに立ち寄り、歩き疲れた体を少し休める。レトロな内装が落ち着く空間の中で、香ばしいこだわり珈琲と甘い特製チーズケーキをいただきながら、窓の外に広がる穏やかな港町の景色を眺めて優雅な休憩時間を過ごす。','2027-04-10','11:30','🤩','0','',-850,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,687,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.451390000,135.395560000,'「舞鶴港遊覧船」に乗り込み、間近で見る自衛隊の護衛艦とリアス式海岸の迫力','舞鶴港から出航する遊覧船の甲板に乗り込み、海からの観光クルーズへ出発。目の前に次々と現れる迫力満点の海上自衛隊の巨大な護衛艦の姿や、若狭湾特有の美しいリアス式海岸の景色を間近で眺め、大迫力の海の冒険に大興奮。','2027-04-10','13:00','🛥️','0','',-1800,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,688,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.501390000,135.372500000,'「五老ヶ岳公園」の山頂へ、緑豊かなドライブウェイを抜けて爽快にアクセス','車窓から緑豊かな山の風景を楽しみながら、舞鶴湾を一望できる「五老ヶ岳公園」の山頂へと車を走らせる。心地よい山の空気を吸い込みながら、美しい自然に包まれたワインディングロードのドライブを爽やかに満喫する。','2027-04-10','14:30','🚗','0','',0,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,689,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.502780000,135.373610000,'近畿百景の第1位！「五老スカイタワー」から一望する舞鶴湾の壮大なパノラマ','五老ヶ岳公園の山頂にそびえる展望タワー「五老スカイタワー」の最上階へ。目に前に広がる、複雑に入り組んだリアス式海岸の「舞鶴湾」と点在する緑の島々が織りなす息をのむほどに美しい絶景パノラマに、思わず言葉を失うほどの感動を覚える。','2027-04-10','15:30','🗼','0','',-500,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (54,832,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559000000,133.533600000,'ひろめ市場で昼食','カツオのたたきを豪快にいただく。藁焼きの香りが最高で、思わず「うまい！」と声が出た。','2026-08-04','13:30','🍣','0000','',-1600,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (46,690,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.461670000,135.319440000,'趣ある城下町・西舞鶴エリアへ移動、歴史を感じる「田辺城資料館」を見学','東舞鶴から西舞鶴へと移動し、かつて細川幽斎が築いた田辺城の跡地である資料館へ。歴史の変遷を伝える貴重な資料や武具の数々をじっくりと見学しながら、丹後田辺藩の城下町として栄えた古い歴史のロマンに思いを馳せる。','2027-04-10','17:00','🏯','0','',-400,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,691,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.460560000,135.318060000,'3軒目：城下町の隠れ家的名店でいただく、日本海の新鮮な海の幸丼の夕暮れ前ランチ','日本海の荒波が育んだ極上の魚介が味わえる西舞鶴の老舗食事処に立ち寄る。朝に水揚げされたばかりのピチピチのマグロやタイ、甘エビが贅沢に盛り付けられた「海鮮丼」を頬張り、新鮮な海の美味しさに心からうっとりとする。','2027-04-11','12:00','🤩','0','',-1900,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,692,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.452220000,135.313890000,'水上家屋が立ち並ぶノスタルジックな水郷風景「吉原の地区」をのんびりお散歩','まるで海の上に家が浮かんでいるかのような珍しい景観が広がる、西舞鶴の漁師町「吉原地区」へ。細い路地や水面に影を落とすレトロな家々の佇まいを眺めながら、どこか懐かしく時が止まったかのような静かなお散歩を楽しむ。','2027-04-11','13:30','🏘️','0','',0,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,693,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.441670000,135.352780000,'日本海に面した海沿いのリゾート感あふれるホテルにチェックイン','本日の宿泊先である、穏やかな日本海の波打ち際に佇む上質なホテルにチェックイン。窓の外に広がる夕暮れの美しい海の景色を眺めながら旅の荷物をほどき、一日の充実した観光の思い出に浸りながらほっと一息ついてくつろぐ。','2027-04-11','16:30','🏨','0','',-26000,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,694,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.442220000,135.353330000,'ホテルの大浴場と露天風呂で、日本海の潮風を感じながらゆったりリフレッシュ','夕食の前に、広大な日本海を一望できるホテル自門の開放的な露天風呂へと足を運ぶ。心地よい波の音に耳を傾けながら温かいお湯に身を委ね、旅のドライブや散策の疲れがすーっと癒やされていく極上のリラックスタイムを満喫する。','2027-04-11','17:30','✨','0','',0,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,695,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.441390000,135.351940000,'4軒目：日本海の旬の味覚！ブランド蟹や鮮魚の舟盛りを味わう豪華な海の幸ディナー','お待ちかねの夕食は、日本海の新鮮な海の幸をふんだんに使った豪華な会席料理を堪能。今が旬の極上の魚介の舟盛りや、香ばしい焼き魚を味わいながら、地元の美味しい地酒を合わせて心から贅沢で幸せな夜のひとときを過ごす。','2027-04-11','19:00','🦀','0','',0,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (46,696,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.464170000,135.398610000,'翌日、新鮮な海の特産品が並ぶ道の駅「舞鶴港とれとれセンター」でお買い物','旅行2日目は、日本海側最大級の海鮮市場である「舞鶴港とれとれセンター」へ。活気あふれる店内で、ずらりと並ぶ新鮮なカニや干物、お土産用の特産品をじっくりと吟味し、旅の思い出を彩る素敵なお土産をたくさん買い揃える。','2027-04-12','10:00','🛍️','0','',-3500,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (55,861,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.766300000,'松山城ロープウェイ乗り場','ロープウェイで山頂へ。松山の街並みが一望できて爽快。','2026-08-12','09:30','🚡','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (46,697,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.465000000,135.399440000,'市場のイートインコーナーで味わう、その場で選んだお魚の海鮮網焼きランチ','とれとれセンター内で、ずらりと並ぶ新鮮な魚介の中から自分の好きな食材を選んでその場で焼いてもらう海鮮網焼きランチ。香ばしい磯の香りとジューシーな魚の旨味が口いっぱいに広がり、旅の締めくくりにふさわしい最高に贅沢な味わいを楽しむ。','2027-04-12','11:30','🦐','0','',-2200,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (46,698,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.464170000,135.398610000,'「JR東舞鶴駅」に戻り、港町のたくさんの思い出と感動を胸に帰路につく','すべての観光行程を大満足で終えて再びJR東舞鶴駅へ戻る。「海の景色も、美味しい海鮮も、赤れんがの歴史も全部素晴らしかったね！」と笑顔で語り合いながら、たくさんの温かい思い出を胸に、帰路の特急列車へと乗り込む。','2027-04-12','14:00','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:21:37.418736+09','2026-08-02 01:21:37.418736+09','{}'),
	 (47,699,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.530560000,134.225000000,'「JR鳥取駅」に到着、家族みんなのワクワクが止まらない鳥取旅行のスタート','家族みんなで特急列車に揺られ、いよいよ日本海側の街・JR鳥取駅に降り立つ。改札を出た瞬間から「どんなところかな？」と子供たちも目を輝かせ、これから始まる鳥取砂丘や美味しいグルメを巡る大満足の家族旅行への期待感に胸を弾ませる。','2027-05-15','09:00','🚂','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,700,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.532220000,134.223890000,'1軒目：話題の「すなば珈琲」で、香ばしいこだわり珈琲と名物モーニング','鳥取名物としてすっかりおなじみとなったユニークな「すなば珈琲」の店舗へ立ち寄る。香ばしく香り高い特製ブレンドコーヒーを味わいながら、子供たちはサクサクのトーストと名物のホットケーキを頬張り、朝から家族みんなでにっこり笑顔が広がる。','2027-05-15','09:30','☕','0','',-1100,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,701,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.541670000,134.229170000,'「鳥取砂丘こどもの国」で、緑豊かな自然の中のびのびと思いっきり遊ぶ','日本海を望む広大な敷地を持つ「鳥取砂丘こどもの国」へ到着。大型のアスレチック遊具や広々とした芝生エリアで、子供たちは「見て見て、すごい高いよ！」と元気いっぱいに走り回り、家族みんなで汗を流しながら思い切り体を動かして楽しむ。','2027-05-15','10:30','🏃','0','',-500,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,702,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.541940000,134.220560000,'2軒目：砂丘の目の前のおしゃれなお店で味わう、名物「砂丘らーめん」のランチ','お昼時は鳥取砂丘の近くにあるアットホームなレストランでランチタイム。スープの旨味がしっかりと効いたご当地の「砂丘らーめん」を注文し、ツルツルの麺とジューシーなチャーシューを夢中ですすりながら、お腹も心も大満足で満たされていく。','2027-05-15','12:00','🍜','0','',-950,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,703,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.545830000,134.222220000,'目の前に広がる壮大な大パノラマ！「鳥取砂丘」の馬の背を家族で登る','日本が誇る大自然の芸術・鳥取砂丘のメインエリアへ足を踏み入れる。どこまでも続く黄金色の砂の丘「馬の背」に向かって、足を砂に取られながらも「がんばれー！」と家族で声を掛け合わせながら一歩一歩力を合わせて頂上へと登りきる。','2027-05-15','13:30','🐪','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,704,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.546940000,134.223330000,'「鳥取砂丘」の頂上から望む、日本海のどこまでも青い水平線と美しい風紋に感動','急な坂道を登りきった馬の背の頂上から、目の前に広がる日本海のどこまでも青く澄んだ海原を一望する。風が作り出す美しい砂の模様「風紋」の神秘的な美しさに、「うわぁ、きれい！」と子供たちも感動のあまり歓声を上げ、家族みんなで記念の写真をパシャリと撮影する。','2027-05-15','14:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,705,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.544440000,134.223610000,'「鳥取砂丘リフト」に揺られて、空中散歩を楽しみながら砂丘を一望','砂丘の景色を違った角度から楽しむため、観光リフトに乗ってのんびり空中散歩。足元に広がる雄大な砂丘の風景と日本海の潮風を心地よく感じながら、ゆったりと揺られるリラックスした時間に家族みんなでほっこりとした笑顔になる。','2027-05-15','15:00','🚡','0','',-400,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,706,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.543060000,134.218060000,'世界的にも珍しい砂の彫刻美術館「砂の美術館」で、圧倒的なスケールのアートを鑑賞','“砂で世界を旅行する”をコンセプトにした大人気の「砂の美術館」へ足を運ぶ。世界最高峰の砂像彫刻家たちが手掛けた、細部まで驚くほど精巧で巨大な砂のアート作品の数々を間近で眺め、「これ本当に砂でできているの！？」と家族みんなで驚きの声を上げる。','2027-05-15','16:00','🎨','0','',-1200,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,707,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.539720000,134.148610000,'神話の舞台としても有名な、縁結びのパワースポット「白兎神社」を参拝','白いウサギの神話が残る、可愛らしいウサギの石像があちこちに鎮座する「白兎神社」へ。境内へと続く参道を家族みんなでのんびりとお散歩しながら、ウサギのモチーフが施された可愛らしいお守りを探したり、旅の安全を仲良くみんなでお願いする。','2027-05-16','10:30','🐇','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (47,708,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.538890000,134.149170000,'3軒目：白兎海岸の道の駅で味わう、濃厚でミルキーな「大山白バラ牛乳ソフト」','神話の舞台となった美しい白兎海岸を眺めながら、道の駅のテラスでひと休み。鳥取名物の濃厚な「大山白バラ牛乳」を使ったソフトクリームを家族みんなでシェアしていただき、ひんやり甘い美味しさに思わず「美味しいね！」と笑顔がこぼれる。','2027-05-16','11:30','🍦','0','',-450,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (64,1012,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.818902000,132.871233000,'三次駅へ戻る','車で三次へ戻ると、朝と同じ穏やかな空気が広がっていた。庄原と三次をゆっくり巡った一日を思い返すと、心が自然と落ち着く旅だったと感じる。','2026-10-22','16:30','🚗','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (47,709,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.501390000,134.234720000,'鳥取市街地に戻り、今夜の宿泊先である天然温泉付きの和風リゾートホテルにチェックイン','一日の楽しい観光を終えて鳥取市街地へと戻り、本日の宿泊先である温かな和風リゾートホテルにチェックイン。広々とした家族向けの和室の客室に通され、心地よい畳の香りに包まれながら、旅の荷物をほどいてほっと一息リラックスする。','2027-05-16','15:00','🏨','0','',-28000,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (55,862,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839400000,132.765200000,'松山城天守','天守からの眺めが美しくて写真を何枚も撮る。風が気持ちいい。','2026-08-12','10:00','📸','0','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (47,710,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.502780000,134.235560000,'ホテルの大浴場と露天風呂で、旅の疲れをほぐす極上の温泉リフレッシュタイム','夕食の前に、肌触りの優しい天然温泉が自慢のホテルの大浴場と露天風呂へ足を運ぶ。足を思いきり伸ばせる温かいお湯にゆったりと浸かりながら、「今日はいっぱい歩いて楽しかったね」と家族みんなで今日の思い出話に花を咲かせる。','2027-05-16','16:15','✨','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,711,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.500560000,134.233330000,'4軒目：日本海の海の幸と鳥取牛が勢揃い！家族みんなで囲む豪華な夕食バイキング','お待ちかねの夕食は、広々としたレストランでの豪華なバイキング形式。日本海で獲れたピチピチの新鮮なお造りや、香ばしく焼き上げられた地元食材の数々を、子供たちも「どれにしようかな？」とワクワクしながらお皿いっぱいに選んで楽しく賑やかに味わう。','2027-05-16','18:30','🦀','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,712,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.505560000,134.238890000,'翌日、活気あふれる鳥取の台所「賀露港・海鮮市場モルトフレア」でお買い物','旅行2日目は、新鮮な海の特産品がずらりと並ぶ地元の人気の海鮮市場「賀露港」へと車を走らせる。威勢のいい掛け声が行き交う活気あふれる店内で、大きなカニや干物などの特産品を楽しく吟味し、家族みんなでお土産をたくさん選び取る。','2027-05-17','10:00','🛍️','0','',-3000,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,713,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.506110000,134.239440000,'市場内の食堂で味わう、日本海の海の幸がてんこ盛りの豪華な「海鮮丼」のランチ','市場内にあるアットホームな食堂で、旅の締めくくりとなる贅沢なランチタイム。朝に水揚げされたばかりの新鮮なマグロや白身魚、いくらが贅沢に盛り付けられたボリューム満点の「海鮮丼」を頬張り、その美味しさに家族みんなが大感動する。','2027-05-17','11:30','🐟','0','',-2100,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (47,714,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.530560000,134.225000000,'「JR鳥取駅」に戻り、たくさんの楽しい思い出を胸にみんなで笑顔で帰路につく','すべての観光とグルメを家族みんなで大満足して、再び出発地のJR鳥取駅へ戻る。「砂丘の景色も、ラクダも、美味しいご飯も全部楽しかったね！」と満面の笑みで語り合いながら、温かい家族の思い出がぎっしりと詰まった特急列車に乗り込んで帰路につく。','2027-05-17','14:00','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:24:51.398762+09','2026-08-02 01:24:51.398762+09','{}'),
	 (54,833,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559200000,133.533900000,'市場内をぶらぶら','地元のお店が並んでいて見ているだけで楽しい。お土産の試食もあってテンションが上がる。','2026-08-04','14:00','🛍️','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (48,715,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.426390000,133.333330000,'「JR米子駅」に到着、山陰の活気ある街・米子でのワクワクする観光のスタート','山陰の交通の要所であり、妖怪ブロンズ像がお出迎えしてくれる活気あふれるJR米子駅に降り立つ。爽やかな日本海の風を感じながら、これから巡る歴史ある米子城跡や名湯・皆生温泉への期待に胸を膨らませ、元気いっぱいに駅舎をあとにして出発する。','2027-06-12','09:00','🚉','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,716,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.428330000,133.331110000,'1軒目：駅前のレトロな喫茶店で味わう、名物「米子珈琲」と香ばしいモーニング','旅の始まりは、米子駅の近くにある地元で愛され続ける落ち着いた雰囲気のレトロな喫茶店へ。じっくりと丁寧に淹れられた香り高いこだわり珈琲を一口飲むと、すっきりと目が覚め、バターが香るサクサクのトーストとともに心も体もホッと満たされる。','2027-06-12','09:30','☕','0','',-750,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,717,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.428610000,133.321670000,'天空の城とも称される名城「米子城跡」の石垣がそびえる山頂へと爽快に登る','かつて壮大な天守閣がそびえ立っていた歴史ある「米子城跡」の美しい石垣が残る遊歩道へ足を踏み入れる。木漏れ日の心地よい山道を一歩一歩のんびりと登りながら、かつての城主が眺めたであろう壮大な歴史のロマンに思いを馳せる。','2027-06-12','10:30','🏯','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,718,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.428890000,133.321940000,'「米子城跡」の山頂から一望する、中海や弓ヶ浜、そして雄大な大山の絶景に感動','見事に組み上げられた米子城跡の山頂に登りきると、目の前には青く輝く中海や美しい弧を描く弓ヶ浜、そして頂上に雲をまとった雄大な大山の姿が広がる。360度の大パノラマが生み出す息をのむほどの絶景に、「うわぁ、すごい！」と思わず大きな歓声を上げる。','2027-06-12','11:15','⛰️','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,719,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.425560000,133.315000000,'2軒目：城下町エリアの人気店で味わう、ジューシーなご当地「米子牛すじ丼」のランチ','歴史ある街並みが残るエリアの隠れ家的な食堂で、ボリューム満点のランチタイム。じっくりと柔らかく煮込まれた旨味たっぷりの牛すじがご飯の上に贅沢にのせられたご当地名物の丼を頬張り、その美味しさに思わず笑顔がこぼれて大満足する。','2027-06-12','12:30','丼','0','',-1100,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,720,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.431390000,133.342220000,'白砂青松の美しい海岸線が続く「弓ヶ浜」の海岸をのんびりとお散歩','“日本の白砂青松100選”にも選ばれている、見事な弧を描く美しい海岸線「弓ヶ浜」へと足を運ぶ。サラサラとした白い砂浜を歩きながら、打ち寄せる日本海の心地よい波の音に耳を傾け、どこまでも広がる青い海を眺めて穏やかなリラックスタイムを過ごす。','2027-06-12','14:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,721,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.433330000,133.344440000,'3軒目：海の近くのオシャレなカフェでいただく、甘酸っぱい特製フルーツタルトと珈琲','弓ヶ浜の美しい景色を一望できる海沿いのスタイリッシュなカフェに立ち寄り、ティータイム。旬の瑞々しいフルーツがたっぷりと乗ったサクサクの特製タルトを味わいながら、窓の外に広がるきらめく海原を眺めて優雅で贅沢なひとときを堪能する。','2027-06-12','15:15','🍰','0','',-900,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,722,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.438890000,133.383330000,'日本海に面した全国屈指の名湯「皆生温泉」の情緒あふれる温泉街をそぞろ歩き','“日本の朝焼け100選”にも選ばれる美しい海岸沿いに広がる、塩の湯が自慢の「皆生温泉」の街並みへ。温泉情緒が漂うレトロな小道を家族や友達とのんびりとお散歩しながら、湯煙が立ち上る温泉街ならではの温かな雰囲気をたっぷりと楽しむ。','2027-06-12','16:30','♨️','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,723,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.439440000,133.384720000,'本日の宿泊先である、日本海の絶景を望む皆生温泉の上質なリゾートホテルにチェックイン','波の音がすぐ近くに聞こえる皆生温泉のオーシャンビューホテルに到着してチェックイン。窓一面に日本海の美しい水平線が広がる明るく広々とした客室に通され、旅の荷物をほどいてほっと一息つきながら、これからの温泉タイムに胸を弾ませる。','2027-06-12','17:30','🏨','0','',-29000,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,724,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.439720000,133.385280000,'ホテルの大浴場と塩の温泉が自慢の露天風呂で、日本海の波音を聞きながらリフレッシュ','夕食の前に、ミネラルたっぷりの皆生温泉が満たされたホテルの大浴場と開放的な露天風呂へ。潮風を感じながら温かい温泉にゆったりと体を預けると、一日のドライブや散策の疲れがすーっと溶けていくような極上の癒やし時間を満喫する。','2027-06-12','18:30','✨','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (48,725,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.438610000,133.383890000,'4軒目：日本海の新鮮な海の幸と鳥取のブランド食材を味わう、豪華な会席ディナー','お待ちかねの夕食は、日本海の荒波が育んだ新鮮な魚介の舟盛りや、香ばしい山陰の味覚をふんだんに盛り込んだ豪華な会席料理。地元の美味しい日本酒とともに、素材本来の豊かな旨味を心ゆくまで堪能し、笑顔が絶えない贅沢な夜のひとときを過ごす。','2027-06-12','19:30','🦀','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,726,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.440000000,133.386110000,'夜の温泉街を浴衣でそぞろ歩き、波の音を聞きながら星空を見上げるロマンチックな夜','夕食後、色鮮やかな浴衣に身を包んで夜の皆生温泉の海岸線をのんびりと散歩する。潮風に吹かれながら見上げる夜空には満天の星がきらめき、波の音が心地よく響く幻想的でロマンチックな夜の雰囲気に浸る。','2027-06-12','21:00','🌌','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,727,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.358330000,133.541670000,'翌日、車を走らせて霊峰「大山」の麓に広がる豊かな自然スポットへと向かう','旅行2日目は、中国地方の最高峰であり神々が宿る美しい霊峰「大山」の麓へとドライブ。車窓から緑豊かな山々の美しい景色を眺めながら、鳥取が誇る雄大な自然に囲まれた爽やかなエリアへと軽快に車を進める。','2027-06-13','10:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,728,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.361110000,133.538890000,'大山の美しい緑に囲まれた歴史ある「大山寺」の神秘的な境内をのんびり参拝','聖なる山として古くから信仰を集めてきた歴史ある「大山寺」の境内へと足を運ぶ。澄んだ山の空気に包まれた厳かな参道をゆっくりと歩き、苔むした石段や歴史あるお堂の佇まいを眺めながら、心洗われるような静寂と癒やしの時間を過ごす。','2027-06-13','11:00','⛩️','0','',-300,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,729,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.356940000,133.540280000,'5軒目：大山の中腹にある山小屋風カフェで味わう、濃厚な「大山乳業ソフトクリーム」','大山の豊かな自然を感じられる山小屋風のオシャレなカフェに立ち寄り、ご当地スイーツを堪能。地元の大山乳業のミルクをたっぷり使った濃厚でなめらかなソフトクリームを一口食べると、ミルクの優しい甘みが口いっぱいに広がり最高の笑顔になる。','2027-06-13','12:15','🍦','0','',-450,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (48,730,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.426390000,133.333330000,'「JR米子駅」に戻り、山陰の美しい景色と美味しい思い出を胸に笑顔で帰路につく','すべての観光とグルメを大満足で満喫し、再び出発地のJR米子駅へと戻る。「お城の景色も、皆生温泉も、美味しいご飯も全部最高だったね！」とみんなで元気よく笑顔で語り合いながら、山陰・米子の温かい思い出が詰まった特急列車に乗り込んで帰路につく。','2027-06-13','14:30','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:28:09.13564+09','2026-08-02 01:28:09.13564+09','{}'),
	 (45,667,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.613330000,135.021390000,'「淡路ハイウェイオアシス」に到着、青く輝く海と明石海峡大橋の絶景に大興奮','本州から海を渡り、爽快なドライブの途中で最初に立ち寄った淡路ハイウェイオアシス。目の前にパノラマで広がる真っ青な播磨灘と雄大な明石海峡大橋の姿に、思わずみんなで「わぁ、きれい！」と歓声を上げる。心地よい潮風を受けながら、最高の淡路島ドライブ旅がいよいよ元気にスタートする。','2026-12-04','09:00','🚗','0','',0,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,668,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.586866879,135.009956360,'1軒目：絶景テラスカフェで味わう、淡路島特産タマネギの甘みたっぷりスープとモーニング','緑豊かな公園内にある開放的なテラスカフェで、きらめく海を眺めながらの朝のひととき。驚くほど甘みが強い淡路島産タマネギをじっくり煮込んだ特製オニオンスープを一口飲むと、優しい旨味が体にじんわりと広がり、今日の楽しい旅へのワクワク感が一段と高まっていく。','2026-12-04','09:30','🧅','0','',-800,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,669,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.571940000,134.981670000,'「ニジゲンノモリ」の広大な自然の中で、人気アニメの世界観を体感して大はしゃぎ','県立淡路島公園の中にある大人気のアニメパーク「ニジゲンノモリ」へ。木漏れ日がきらめく爽やかな森の中を歩きながら、ダイナミックなアトラクションや色鮮やかなキャラクターのモニュメントを見つけては大はしゃぎ。童心に帰って思いっきり体を動かし、笑顔があふれる楽しい時間。','2026-12-04','10:30','🌳','0','',-3500,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,670,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.455560000,134.891670000,'2軒目：海沿いの人気店でガブッとかぶりつく、ジューシーな「淡路島バーガー」のランチ','お昼時は、海沿いのオシャレなバーガーショップで大人気の「淡路島バーガー」をランチにチョイス。ふっくらジューシーな淡路牛パティと、ソテーされて甘みが凝縮された極厚の淡路島産タマネギが絶妙にマッチし、一口食べるごとに美味しさが口いっぱいに広がる最高のご馳走。','2026-12-04','12:30','🍔','0','',-1350,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (52,792,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.070000000,134.441670000,'第14番札所「常楽寺」で美しい庭園と静寂に包まれ、心洗われるお参り','美しい庭園と穏やかな空気が流れる第14番札所「常楽寺」へ。心地よい風が吹く境内で、夫婦揃って静かにお線香をあげ、日々の平穏とこれからの旅の無事を祈願する。二人で並んで過ごす時間が何よりも贅沢に感じられる素晴らしいひとときとなる。','2027-10-03','12:30','🍀','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (45,671,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.436110000,134.873610000,'「あわじ花さじ敷」の丘一面に広がる、季節のカラフルな花畑と青空のコントラストに感動','見渡す限りの青い海と空に向かって広がる「あわじ花さじ敷」の美しい丘陵地帯へ。季節の鮮やかな花々が絨毯のように一面を埋め尽くす圧巻の景色の中をのんびりとお散歩。どこを切り取っても絵になる絶景ロケーションで、記念の写真を何枚もパシャリと楽しく撮影する。','2026-12-04','14:00','🌸','0','',0,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,672,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.498610000,134.872220000,'青い海に映えるポップな建物「HELLO KITTY SMILE」でキュートな世界に夢中','西海岸のキラキラした海沿いに佇む、乙女心をくすぐるキュートな施設「HELLO KITTY SMILE」に到着。全面ガラス張りのドームから見下ろすエメラルドグリーンの海と、遊び心あふれるプロジェクションマッピングや可愛い演出に、思わず時間を忘れてワクワクと夢中になってしまう。','2026-12-04','15:30','🎀','0','',-2300,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,673,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.508330000,134.873610000,'3軒目：海風感じる「淡路シェフガーデン」で楽しむ、色とりどりのオープンエアランチ','目の前に瀬戸内海の絶景が広がる開放的なフードパーク「淡路シェフガーデン」に立ち寄る。個性豊かな屋台やコンテナショップが並ぶ賑やかな空間で、島食材を使ったバラエティ豊かな絶品グルメをみんなでシェアしながら、太陽の下でわいわいと楽しいランチタイムを満喫。','2026-12-05','12:00','🍴','0','',-1600,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,674,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.330678877,134.734096527,'国の名勝「鳴門の渦潮」を間近で見るため、迫力満点の観潮船クルーズへ','島をさらに南下して、世界屈指のダイナミックな潮の流れを誇る鳴門海峡へ。真っ白な飛沫を上げて激しく渦巻く大迫力の「渦潮」を間近で見物できる観光船に乗り込み、船のデッキから「うわぁ、すごい！」と大興奮のスリル満点な海の冒険を体験する。','2026-12-05','13:30','🚢','0','',-2400,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (54,834,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560300000,133.531900000,'高知城へ向かう','城下町の雰囲気が残る道を歩く。石垣が見えてくるとワクワクがさらに高まる。','2026-08-04','14:40','🏯','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (45,675,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350097386,134.745941162,'大鳴門橋の真下にある「渦の道」の海上遊歩道で、足元の豪快な潮流をのぞき見','大鳴門橋の車道の下に設置された海上遊歩道「渦の道」へと歩みを進める。海上45メートルのガラス張りの床から真下を覗き込むと、轟音とともに激しくぶつかり合う日本海の潮の潮流がダイナミックに見え、スリルと爽快感が入り混じる不思議な空中散歩を楽しむ。','2026-12-05','14:30','🌉','0','',-510,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,676,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.340601305,134.745426178,'4軒目：道の駅うずしお周辺で味わう、濃厚で甘い「淡路島牛乳ソフトクリーム」','たくさん歩いてちょっぴり熱くなった体に嬉しい、ご当地グルメの淡路島牛乳ソフトクリームをゲット。搾り立てのミルクならではの濃厚なコクとなめらかな口溶けがたまらなく美味しく、甘いひんやりスイーツに思わず笑顔がこぼれる最高の休憩タイム。','2026-12-05','15:30','🍦','0','',-450,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,677,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.379004205,134.764137268,'「人形浄瑠璃館」にて、伝統芸能の華麗なパフォーマンスとユーモアある人形劇を鑑賞','淡路島に古くから伝わる伝統文化に触れるため、地元の人形浄瑠璃館へ足を運ぶ。三味線の音色に合わせて生き生きと動き回るダイナミックで繊細なお人形のパフォーマンスに引き込まれ、日本の伝統芸能の奥深さと面白さを楽しくたっぷりと堪能する。','2026-12-05','16:30','🎭','0','',-1000,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,678,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.444440000,134.891670000,'オレンジ色に染まる夕陽を眺めながら、西海岸のロマンチックな海岸線をドライブ','夕暮れ時になり、刻々と空と海の色がオレンジ色から茜色へと移り変わる淡路島の西海岸線を車で走らせる。水平線に沈んでいく美しい夕陽を横目に、お気に入りの音楽をかけながら心地よい風を感じる、最高にロマンチックでエモーショナルなドライブ時間。','2026-12-05','17:45','🌅','0','',0,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (45,679,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.519440000,134.880560000,'リゾート感満載の全室オーシャンビューのオシャレなホテルにチェックイン','本日の宿泊先である、南国ムード漂うスタイリッシュなリゾートホテルにチェックイン。窓一面に真っ青な海が広がる明るく爽やかな客室に通され、旅の荷物をほどいてリラックスしながら、これから始まる楽しい夜に胸を弾ませる。','2026-12-05','18:30','🏨','0','',-32000,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,680,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.522220000,134.881940000,'ホテルの大浴場と露天風呂で、きらめく星空を見上げながらのびのびリフレッシュ','夕食の前に、波の音が心地よく響くホテル自慢の開放的な露天風呂へと向かう。心地よいお湯にゆったりと体を預けながら、頭上に広がる満天の星空を眺めて一日の旅の疲れがすーっと溶けていくような極上のリラックスタイムを過ごす。','2026-12-05','19:15','✨','0','',0,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,681,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.518330000,134.879170000,'海の幸とブランド肉の競演！淡路ビーフと新鮮魚介を味わう豪華リゾートディナー','お待ちかねの夕食は、南国リゾートの風がそよぐ明るいダイニングで豪華なディナータイム。きめ細やかな肉質でとろけるような甘みの「淡路ビーフ」のステーキや、瀬戸内海で獲れたピチピチの新鮮なお魚を堪能し、美味しいお酒とともに笑顔が絶えない賑やかな夜を過ごす。','2026-12-05','20:15','🍷','0','',0,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (45,682,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.613330000,135.021390000,'旅のフィナーレ：「淡路ハイウェイオアシス」で楽しかった思い出を胸に笑顔で出発地へ','翌日、すべての行程を太陽のような満面の笑顔で大満喫し、再び淡路ハイウェイオアシスへ。「美味しいものも絶景も全部最高だったね、また絶対に遊びに来ようね！」とみんなで元気よく手を振り合い、明るく温かい思い出がいっぱいに詰まった最高の淡路島旅行の幕を閉じる。','2026-12-06','10:00','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:29:33.198912+09','2026-08-02 01:29:33.198912+09','{}'),
	 (55,845,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.347820000,134.054720000,'骨付鳥ランチ','香川名物の骨付鳥がジューシーで最高。食べるたびに笑顔になる味。','2026-08-10','13:00','🍗','0000','',-1500,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,846,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350930000,134.060140000,'ことでん瓦町駅周辺散策','レトロな雰囲気が漂う街並み。地元の生活感があって歩いているだけで楽しい。','2026-08-10','14:00','🚋','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (49,731,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489170000,134.171940000,'「土庄港」に到着、穏やかな瀬戸内海の青い海と島風に家族みんなで大はしゃぎ','フェリーに揺られて、瀬戸内海に浮かぶ美しい島・小豆島の玄関口である土庄港へ到着。船を降りた瞬間から、キラキラと輝く穏やかな海と爽やかな潮風に包まれ、「わぁ、綺麗な海！」と子供たちも大はしゃぎ。これから始まるワクワクの島内観光旅行がいよいよ元気にスタートする。','2027-09-18','09:00','🚢','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,732,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.485830000,134.168060000,'1軒目：港近くの可愛いカフェで味わう、小豆島オリーブオイル香る絶品モーニング','土庄港の近くにある温かな雰囲気のカフェで、旅の始まりを祝う朝のひととき。小豆島特産の新鮮なオリーブオイルをたっぷりとかけたサクサクのトーストと、香り高いこだわり珈琲を味わいながら、家族みんなでにっこり笑顔が広がる最高のモーニングタイムを満喫する。','2027-09-18','09:30','☕','0','',-800,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,733,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.483330000,134.173610000,'潮の満ち引きで道が現れる神秘的な名所「エンジェルロード」を家族で手をつなぎ渡る','干潮時にだけ現れる砂の道「エンジェルロード」へと歩みを進める。“大切な人と手をつないで渡ると願いが叶うんだよ”と教え合いながら、貝殻を探したり波打ち際を歩いたりしながら、家族みんなで仲良く砂の道を歩いて渡りきる感動的な体験をする。','2027-09-18','10:30','✨','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,734,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.482220000,134.172500000,'「エンジェルロード」を見下ろす丘の上の「約束の丘展望台」で幸せの鐘を鳴らす','エンジェルロードの美しい全景が一望できる高台の「約束の丘展望台」へと登る。青い海に囲まれた美しい小道の景色に感嘆の声を上げながら、家族みんなの健康とこれからの幸せを祈って、展望台にある可愛い「幸せの鐘」を元気いっぱいに鳴り響かせる。','2027-09-18','11:15','🔔','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (49,735,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.520000000,134.331670000,'「小豆島オリーブ公園」で、白いギリシャ風風車をバックにほうきに跨って記念撮影','一面にオリーブの木が広がる美しい「小豆島オリーブ公園」へ到着。青空に向かってそびえる真っ白なギリシャ風風車の前で、映画の魔女のようにほうきを借りて空を飛んでいるかのようなポーズを取りながら、家族みんなで大爆笑しながら記念写真を何枚もパシャリと撮影する。','2027-09-18','12:30','🧹','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,736,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.521390000,134.333330000,'2軒目：オリーブの緑に囲まれたオシャレなレストランで味わう「オリーブ牛」のランチ','園内にある開放的なレストランで、小豆島ブランドの「オリーブ牛」を贅沢に使ったランチタイム。きめ細やかな肉質で旨味がギュッと詰まったジューシーなステーキ丼を頬張り、「お肉がとっても柔らかくて美味しいね！」と家族全員が大満足の笑顔になる。','2027-09-18','13:15','🥩','0','',-2200,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,738,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.512220000,134.316670000,'伝統的な木桶が並ぶレトロな醤油蔵が立ち並ぶ「醤油の郷」の街並みをそぞろ歩き','島特産の醤油造りの歴史が息づく「醤油の郷」エリアへと車を走らせる。黒い焼き板の壁が続く情緒あふれる小道を歩くだけで、ふわりと香ばしい醤油の芳醇な香りが鼻腔をくすぐり、日本の伝統的な食文化の深さを肌でしみじみと感じ取る。','2027-09-18','15:45','🍶','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,739,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.513330000,134.318060000,'3軒目：醤油蔵のカフェで味わう、甘じょっぱさがクセになる名物「醤油ソフトクリーム」','歴史ある醤油蔵をリノベーションしたおしゃれなカフェに立ち寄り、話題のご当地スイーツをゲット。コクのあるミルクソフトクリームに特製の諸味醤油が絶妙にマッチした、甘じょっぱくてクリーミーな「醤油ソフトクリーム」を味わい、子供たちも「これ美味しい！」と大喜び。','2027-09-18','16:30','🍦','0','',-450,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,740,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.508330000,134.291670000,'日本三大渓谷美の一つ！ロープウェイに乗って空中から眺める「寒霞渓」の雄大な大自然','秋の紅葉や新緑が美しい絶景スポット「寒霞渓」へと向かい、渓谷美を空から望むロープウェイに乗り込む。眼下に広がる奇岩や深い緑の山々と瀬戸内海の絶景パノラマに、「わぁ、すごい景色！」と息をのむほどのダイナミックな空中散歩を家族みんなで満喫する。','2027-09-19','10:00','🚠','0','',-1500,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (64,1013,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.820144000,132.883291000,'旅の締め','駅前で深呼吸すると、広島県北部の静かな空気が胸に広がった。派手さはないが、心が落ち着く田舎旅となり、お年寄りでも安心して楽しめる一日だった。','2026-10-22','16:40','🌅','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (49,741,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.488890000,134.238890000,'本日の宿泊先である、瀬戸内海の絶景を一望する温泉リゾートホテルにチェックイン','穏やかな海を望む小豆島のリゾートホテルに到着し、温かな笑顔に出迎えられてチェックイン。窓一面に真っ青な海が広がる広々とした和洋室の客室に通され、旅の荷物をほどいてリラックスしながら、これから始まる島での夜に胸を弾ませる。','2027-09-19','12:00','🏨','0','',-32000,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,742,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489440000,134.239440000,'ホテルの大浴場と露天風呂で、瀬戸内海の潮風を感じながらのびのび温泉リフレッシュ','夕食の前に、美しい海を眺めながらゆったりと浸かれるホテルの温泉大浴場と露天風呂へ。心地よいお湯に体を預けて一日の観光の疲れをほぐしながら、「今日はたくさん歩いて楽しかったね」と家族みんなで温かな思い出話に花を咲かせる。','2027-09-19','13:00','♨️','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (55,847,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.013510000,134.586240000,'徳島駅に移動','電車で徳島へ。駅前の青空が広がっていて気持ちが明るくなる。','2026-08-10','15:20','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,848,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.067540000,134.559890000,'眉山ロープウェイ乗り場','ロープウェイで山頂へ。徳島の街並みが一望できて爽快感がすごい。','2026-08-10','15:50','🚡','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (55,849,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.068240000,134.559300000,'眉山山頂','山頂の風が気持ちよくて景色が最高。写真を何枚も撮ってしまう。','2026-08-10','16:10','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,850,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.065900000,134.559900000,'阿波踊り会館見学','阿波踊りの歴史を知る展示が面白い。太鼓の音が心に響く。','2026-08-10','16:40','🥁','0000','',-600,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (49,743,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.488330000,134.238060000,'4軒目：瀬戸内海の新鮮な海の幸と島の恵みが詰まった豪華なバイキングディナー','お待ちかねの夕食は、瀬戸内海で獲れたピチピチのお造りや小豆島そうめん、オリーブ料理がずらりと並ぶ豪華なバイキング。子供たちも「どれにしようかな？」とワクワクしながらお皿いっぱいに美味しいお料理を選び、家族みんなで笑顔が絶えない賑やかなディナータイムを過ごす。','2027-09-19','18:00','🦀','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,744,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489170000,134.171940000,'翌日、島の特産品が集まるお土産市場で、オリーブ製品や佃煮のお買い物','旅行2日目は、小豆島の美味しい特産品がたくさん揃う人気の大きなお土産市場へ立ち寄る。極上のオリーブオイルや、甘辛く煮込まれた名物の佃煮、可愛い小豆島グッズをじっくりと吟味し、旅の思い出を彩る素敵なお土産を家族みんなでたくさん選び取る。','2027-09-20','10:00','🎁','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,745,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.486940000,134.169440000,'市場内の食堂で味わう、ツルツル食感がたまらない名物「小豆島そうめん」のランチ','お土産選びのあとは、市場内にあるアットホームな食堂で名物の「小豆島そうめん」をランチにいただく。手延べならではのコシの強さとツルッとなめらかな喉越しが抜群に美味しく、旅の締めくくりにふさわしい優しい味わいに心から癒やされる。','2027-09-20','11:30','🍜','0','',-900,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,746,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.489170000,134.171940000,'「土庄港」に戻り、瀬戸内海のたくさんの温かい思い出を胸に笑顔で帰路につく','すべての観光とグルメを家族みんなで大満足して、再び出発地の土庄港へと戻る。“オリーブもエンジェルロードも、美味しいご飯も全部最高だったね！”と満面の笑みで語り合いながら、たくさんの温かい思い出がぎっしり詰まったフェリーに乗り込んで帰路につく。','2027-09-20','14:00','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:31:59.461128+09','{}'),
	 (49,737,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.550114760,134.338073730,'昭和レトロな映画の世界にタイムスリップ「二十四の瞳映画村」をのんびりお散歩','木造の校舎や昔懐かしい昭和の街並みがそのまま残る「二十四の瞳映画村」へと足を運ぶ。ノスタルジックな雰囲気が漂うレトロな教室の椅子に座ってみたり、目の前に広がる穏やかな海沿いの道をのんびりとお散歩しながら、家族みんなでタイムスリップしたような不思議で温かい時間を過ごす。','2027-09-18','14:30','🏫','0','',-850,1,0,0,0,0,false,'2026-08-02 01:31:59.461128+09','2026-08-02 01:32:36.162364+09','{}'),
	 (50,747,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.348330000,134.048330000,'「JR高松駅」に到着、男同士の熱い「讃岐うどん食べつくスの旅」がいよいよ始動','讃岐うどんの本場・香川の玄関口であるJR高松駅に男同士で意気揚々と降り立つ。「何杯ハシゴできるか勝負だな！」と気合十分で熱い握手を交わし、これから始まる最高に贅沢で腹パンパン間違いなしのうどん巡り＆男旅のスタートにテンションが一気に最高潮へと跳ね上がる。','2027-10-09','09:00','🚂','0','',0,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,748,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.346940000,134.045560000,'1軒目：駅チカの朝から行列ができる有名店で、コシ抜群の「ぶっかけうどん」をすする','高松駅からすぐの場所にある、朝から地元の常連客や旅人で賑わう超人気うどん店へ突撃。目の前に運ばれてきた、ツヤツヤでエッジの立った麺に特製だしをぶっかけた一杯を豪快にかき込む。ガツンとくる強力なコシと小麦の香ばしさに「うまっ！」と声が漏れ、1軒目から大感動。','2027-10-09','09:30','🍜','0','',-600,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,749,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.283330000,134.013890000,'車を走らせて讃岐平野の中にある名店へ、のどかな田園風景の中をドライブ','高松市内からレンタカーを走らせて、讃岐平野に点在するディープな名店エリアへと移動する。車窓から広がるのどかな田園風景を眺めながら、「次の店は出汁が美味いらしいぞ」などと男同士でうどん談義に華を咲かせ、ドライブの爽快な風を全身に浴びながらテンポよく移動する。','2027-10-09','10:30','🚗','0','',0,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (50,750,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.279720000,134.010560000,'2軒目：行列必至の人気セルフ店で、自分で茹でるアツアツの「釜玉うどん」をガツンと喰らう','地元民でごった返す大人気のセルフうどん店に到着し、ワクワクしながら列に並ぶ。自分で麺をテボに入れて温め、生卵と特製醤油を絡めて豪快に掻き込む「釜玉うどん」を注文。濃厚な卵と熱々のうどんが絡み合う極上のジャンクな旨さに、男二人で思わず顔を見合わせて唸る。','2027-10-09','11:15','🔥','0','',-500,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,751,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.331670000,134.043330000,'日本三大庭園の一つ「栗林公園」の圧倒的な緑の中を男二人で歩いて腹ごなし','うどんの連続攻撃でお腹がいっぱいになったところで、国の特別名勝「栗林公園」の広大な庭園へ。見事な松の緑や美しい池の景色を眺めながら、男同士でこれまでの人生や仕事の熱い野望について語り合いながら、心地よい汗を流しつつ次のうどんへ向けて胃袋のスペースを空ける。','2027-10-09','12:30','🌳','0','',-410,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,752,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343330000,134.053890000,'3軒目：繁華街の隠れ家的名店で味わう、キリッとしたイリコ出汁が染みる「かけうどん」','高松市内の中心街に戻り、地元民に愛され続ける通好みの一軒へと足を踏み入れる。透明感のある黄金色のスープにイリコ出汁の香りがふわっと広がる「かけうどん」をすする。優しくも芯のある深い味わいに、歩き疲れた体に染み渡る最高の美味さを実感して思わず笑顔になる。','2027-10-09','14:00','🥢','0','',-450,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,753,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.345000000,134.055000000,'商店街の中の活気あるお土産処で、讃岐うどんの乾麺や出汁醤油を爆買い','日本一の長さを誇る高松中央商店街をぶらり歩きながら、厳選された讃岐うどんの特産品が並ぶショップへ。自宅や友人へのお土産として、職人のこだわりが詰まった極上の半生うどんや特製のいりこ出汁醤油を「どれが一番美味いか」と真剣に吟味して大量に買い込む。','2027-10-09','15:00','🛍️','0','',-3500,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (55,851,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.013510000,134.586240000,'徳島駅で休憩','駅ナカのカフェでアイスコーヒー。今日の写真を見返しながら余韻に浸る。','2026-08-10','17:10','☕','0000','',-520,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (50,754,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.349170000,134.060000000,'4軒目：夕暮れ時に立ち寄る老舗の製麺所直営店で、豪快な「肉ぶっかけ」にかぶりつく','麺がなくなり次第終了という伝説の製麺所直営店に夕暮れ滑り込みセーフで到着。甘辛くじっくり煮込まれたボリューム満点的牛肉がどっさり乗った「肉ぶっかけ」を男らしく勢いよく平らげる。濃厚な肉汁とうどんのコシのハーモニーに、お腹が限界を迎えつつも箸が止まらない。','2027-10-09','16:30','🥩','0','',-750,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,755,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.344440000,134.052220000,'本日の宿泊先である、高松市街地の中心にあるモダンなビジネスホテルにチェックイン','一日中うどんを食べ歩いて大満足したところで、街の中心部にあるスタイリッシュなホテルにチェックイン。清潔感あふれるモダンな客室に通され、男二人で「今日何杯食べたっけ？」とスマホの万歩計や食べたうどんの数を振り返りながら、ベッドに倒れ込んで一息つく。','2027-10-09','18:00','🏨','0','',-12000,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,756,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.345280000,134.053060000,'ホテルの大浴場とサウナで、うどん巡りで歩き疲れた体を徹底的にリフレッシュ','夕食の前に、ホテルの最上階にある大浴場とサウナへと急ぐ。熱々のサウナでしっかりと汗を流し、キンキンに冷えた水風呂で一気に身体を引き締めたあと、足を思い切り伸ばせる大きなお湯に浸かりながら、最高の男旅の充実感に浸って心身ともに完全にリフレッシュする。','2027-10-09','19:00','♨️','0','',0,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (51,769,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.598330000,133.774440000,'柳並木が続く倉敷川の川面を、伝統的な「倉敷川舟流し」の小舟でゆったりとお散歩','倉敷川の穏やかな水面に浮かぶ小さな木造船「川舟」に乗り込み、水上からの景色を楽しむ。船頭さんの心地よい竿さばきと解説を聞きながら、緑豊かな柳並木と美しい白壁の町並みを眺める優雅な船旅の風情を全身でたっぷりと味わい尽くす。','2027-11-12','16:15','🛶','0','',-700,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (50,757,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343890000,134.051390000,'5軒目：香川の夜のもう一つの主役！香ばしすぎる名物「骨付鳥」にかぶりつく男の晩餐','うどんだけでは終わらない香川の夜、香ばしいスパイスの香りが漂う大人気の骨付鳥専門店へ。「親鳥」と「若鶏」をそれぞれ一本ずつ注文し、豪快にかぶりついてキンキンに冷えたビールをグイッと流し込む。ジューシーな肉汁とスパイシーな味付けがビールと最強に合いすぎて男二人で絶叫する。','2027-10-09','20:00','🍗','0','',-3500,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (50,758,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.346670000,134.057500000,'夜の繁華街のバーで、男同士で夢や今後の目標について熱く語り合うディープな夜','骨付鳥でお腹を満たしたあとは、隠れ家風のクールなバーへとハシゴしてしっぽりとお酒を傾ける。お酒の力を借りて、普段は照れくさくて言えないこれからの夢や仕事への熱い想いを男同士でぶつけ合い、忘れられない最高に濃い夜の時間を満喫する。','2027-10-09','21:30','🥃','0','',-4000,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,759,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.341390000,134.111110000,'翌日、絶景の源平合戦の舞台「屋島」の山頂へとレンタカーで駆け上がる','旅行2日目は、瀬戸内海の美しい島々を一望できる歴史の舞台「屋島」の山頂へと車を走らせる。ワインディングロードを軽快に駆け抜け、展望台へと到着すると目の前に広がる青い海と島々の圧倒的な大パノラマに男二人で「すげぇ…」と息を呑む。','2027-10-10','10:00','🚙','0','',0,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,760,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.340000000,134.108330000,'6軒目：屋島の絶景テラスにある絶品うどん店で、景色を肴に最後の「釜上げうどん」','屋島の絶景を一望できるロケーション抜群のうどん店で、旅のフィナーレを飾る一杯を注文。大きな桶に入った熱々の麺を特製出汁にくぐらせてすする「釜上げうどん」は格別の美味しさ。目の前に広がる絶景を眺めながら味わう最後のうどんに言葉を失う。','2027-10-10','11:00','🤤','0','',-650,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,761,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342220000,134.046390000,'高松市街に戻り、香川のソウルフードである「しょうゆ豆」などのお土産を総仕上げ','高松市街へと戻り、旅の最後に地元の老舗お土産店へ立ち寄る。香川の伝統的なおつまみである「しょうゆ豆」や、地酒、讃岐うどんの有名店セットをカゴいっぱいに詰め込み、男旅の完璧なお土産の買い出しをスピーディーかつ完璧に完了させる。','2027-10-10','13:00','🎁','0','',-2500,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (50,762,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.348330000,134.048330000,'「JR高松駅」に戻り、腹パンパンの大満足と最高の思い出を胸に帰路につく','全6軒のうどん巡りと骨付鳥制覇を成し遂げ、再び出発地のJR高松駅へと戻る。「想像以上に食いすぎて腹がちぎれそうだけど、最高すぎる男旅だったな！」と駅のホームで固い握手を交わし、忘れられない香川の熱い思い出を胸に帰路の列車へと乗り込む。','2027-10-10','14:30','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:35:59.916499+09','2026-08-02 01:35:59.916499+09','{}'),
	 (51,763,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.666110000,133.918060000,'「JR岡山駅」に到着、晴れの国・岡山の観光めぐりがいよいよ元気にスタート','新幹線を降り立った瞬間から爽やかな青空が広がる「晴れの国・岡山」の玄関口、JR岡山駅へ到着。「今日はどんな美味しいものに出会えるかな？」と胸をときめかせながら、これから始まる充実の岡山観光めぐりに向けて笑顔で元気いっぱいに出発する。','2027-11-12','09:00','🚅','0','',0,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,764,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.664440000,133.928890000,'1軒目：駅チカの老舗洋食店でサクサクの岡山名物「デミカツ丼」にかぶりつく','岡山駅のすぐ近くにある地元で愛され続ける老舗洋食店へ直行し、ランチタイム。揚げたてのサクサクなトンカツの上に、濃厚でコクのある特製デミグラスソースがたっぷりとかかった岡山名物「デミカツ丼」を頬張り、その美味しさに最初の一口目から大感動する。','2027-11-12','09:30','🍛','0','',-1100,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,765,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.667220000,133.936110000,'日本三名園の一つ、四季折々の美しい緑が広がる「岡山後楽園」をのんびりお散歩','路面電車に揺られて、日本三名園に数えられる広大な名勝「岡山後楽園」へと足を運ぶ。手入れが行き届いた見事な芝生や美しい池のまわりをゆったりと歩きながら、風情ある和の景色と穏やかな時間の流れに心から癒やされる贅沢なひとときを過ごす。','2027-11-12','11:00','🌳','0','',-410,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (55,852,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559705000,133.531110000,'高知駅へ移動','電車で高知へ。南国の空気が広がっていて気持ちが明るくなる。','2026-08-11','09:00','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,853,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.514350000,133.562870000,'桂浜へ到着','太平洋の広さに圧倒される桂浜。波の音が心地よくてしばらく砂浜でぼーっとする。','2026-08-11','10:00','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (51,766,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.668890000,133.935000000,'「岡山後楽園」の橋を渡り、別名「烏城」と呼ばれる黒く美しい「岡山城」へ登城','後楽園の橋を渡ってすぐ目の前にある、漆黒の天守閣が圧倒的な存在感を放つ「岡山城（烏城）」へ。凛々しい佇まいの城内をじっくりと見学し、最上階の展望フロアからは旭川の流れと岡山の街並みを一望するダイナミックな景色を満喫して歴史のロマンに浸る。','2027-11-12','12:15','🏯','0','',-400,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,767,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.662220000,133.921670000,'2軒目：おしゃれなフルーツパーラーで、旬の果物が山盛りの絶品「岡山フルーツパフェ」','岡山駅前へと戻り、フルーツ王国として名高い岡山ならではの人気フルーツパーラーへ。グラスの上に瑞々しいシャインマスカットや桃などの旬の果物がこれでもかと贅沢にトッピングされた、美しすぎる特製フルーツパフェを味わい、甘くて爽やかな味わいに思わず笑顔がこぼれる。','2027-11-12','14:00','🍨','0','',-1500,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,768,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.601110000,133.775000000,'電車に乗って歴史ある白壁の街並みが残る「倉敷美観地区」へと風情ある移動','岡山駅から電車に揺られて約20分、白壁の蔵やなまこ壁が美しい伝統的建造物群保存地区「倉敷美観地区」へと到着する。一歩足を踏み入れた瞬間から、江戸時代からの歴史を感じさせる情緒あふれる美しい景観に包まれ、まるでタイムスリップしたかのような気分になる。','2027-11-12','15:30','🚃','0','',-330,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,770,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.600000000,133.772780000,'3軒目：美観地区の古民家カフェで、名物の「ママカリの寿司」や地元のランチ','歴史ある古民家を丁寧にリノベーションした風情抜群のカフェに入り、ちょっと遅めのランチタイム。岡山ならではの郷土料理である「ママカリの寿司」や瀬戸内の海の幸を上品に味わい、レトロで落ち着いた店内で至福のグルメ時間をゆっくりと楽しむ。','2027-11-12','17:15','🍣','0','',-1400,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,771,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.596670000,133.773390000,'倉敷アイビースクエアの赤レンガとツタが織りなすレトロモダンな空間を散策','明治時代の赤レンガ紡績工場を保存・活用した複合文化施設「倉敷アイビースクエア」へ立ち寄る。建物全体を覆う鮮やかな緑のツタと赤いレンガのコントラストが最高に美しく、どこを切り取っても絵になるおしゃれなレトロモダンな空間の中をのんびりと歩いて巡る。','2027-11-13','10:00','🧱','0','',0,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,772,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.595000000,133.771670000,'美観地区のこだわりのお土産ショップで、可愛い倉敷デニムやマスキングテープ選び','日本発祥のジーンズ文化が息づく倉敷ならではのショップや、種類豊富な可愛いマスキングテープが揃うお店へ。職人のこだわりが詰まったおしゃれなデニム雑貨や、お土産にぴったりのカラフルな文房具をじっくりと手にとってお気に入りの品を楽しく選び取る。','2027-11-13','11:00','🛍️','0','',-2000,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,773,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.481670000,133.805560000,'JRで南下し、瀬戸内海の美しい島々と巨大な橋が望める絶景スポット「鷲羽山」へ','さらに足を延ばして、瀬戸大橋の壮大なスケールと穏やかな多島美を一望できる「鷲羽山」の山頂エリアへ車を走らせる。展望台へと到着すると、眼下に広がる青い海と雄大な瀬戸大橋の絶景パノラマに「すごい大迫力！」と感動の声を上げる。','2027-11-13','12:30','🌉','0','',0,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,774,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.664440000,133.921110000,'本日の宿泊先である、岡山駅周辺の利便性抜群なアーバンホテルにチェックイン','観光を満喫したあとは、岡山駅のすぐ近くにあるスタイリッシュで快適なホテルへと戻りチェックイン。清潔感あふれる広々とした客室に通され、今日一日で巡ったたくさんの素敵な景色や美味しい思い出を振り返りながら、心地よいベッドでリラックスする。','2027-11-13','15:00','🏨','0','',-14000,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,775,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.665560000,133.919440000,'ホテルの大浴場とサウナで、一日中歩いて回った観光の疲れをすっきりと癒やす','夕食の前に、ホテル館内にある広々とした大浴場とリフレッシュサウナへ足を運ぶ。温かいお湯にゆっくりと体を沈めて一日の歩き疲れを芯からほぐしながら、「今日は本当に盛りだくさんで楽しかったね」と心身ともに完全にリラックスしてリフレッシュする。','2027-11-13','16:00','♨️','0','',0,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,776,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.663330000,133.923890000,'4軒目：岡山の夜を彩る、瀬戸内海の新鮮な魚介と黄ニラなどのご当地グルメの晩餐','岡山の賑やかな繁華街にある人気の居酒屋に繰り出し、旅の夜を祝う豪華なディナータイム。瀬戸内海で獲れたピチピチのお造りや、岡山の名産である珍しい「黄ニラ」を使った絶品料理を味わい、美味しいお酒とともに最高に贅沢で楽しい夜を満喫する。','2027-11-13','18:30','🐟','0','',-4500,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (51,777,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.664720000,133.918890000,'翌日、駅ビルのお土産市場で、岡山名物の「きびだんご」やフルーツゼリーの総仕上げ','旅行最終日の2日目は、岡山駅ビルにある大きなお土産市場へと立ち寄る。パッケージも可愛い定番の「きびだんご」や、白桃やマスカットの贅沢なフルーツゼリーをカゴいっぱいに選び抜き、家族や友人への素敵なお土産の買い出しを完璧に済ませる。','2027-11-14','10:00','🎁','0','',-2500,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (51,778,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.666110000,133.918060000,'「JR岡山駅」に戻り、瀬戸内・岡山のたくさんの温かい思い出を胸に笑顔で帰路につく','すべての観光地巡りと美味しいグルメを大満足で終え、出発地点のJR岡山駅へと戻る。「後楽園も美観地区も、ご飯も全部最高だったね！」と満面の笑みで語り合いながら、素晴らしい思い出がぎっしり詰まった新幹線に乗り込んで帰路につく。','2027-11-14','11:30','👋','0','',0,1,0,0,0,0,false,'2026-08-02 01:38:38.092158+09','2026-08-02 01:38:38.092158+09','{}'),
	 (52,779,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.170560000,134.483890000,'第1番札所「霊山寺」に到着、夫婦二人で心を新たにするお遍路の旅がいよいよ始動','お遍路の始まりの地である第1番札所「霊山寺」に到着する。白衣に身を包み、夫婦二人で本堂と大師堂に丁寧にお参りをしてから、これから始まる全八十八ヶ所の長い道のりに向けて「二人で支え合って無事に結願しようね」と静かに誓い合い、記念すべき最初の一歩を踏み出す。','2027-10-01','08:30','🙏','0','',-1000,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,780,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.162780000,134.471670000,'第2番札所「極楽寺」の長寿杉を見上げ、夫婦の健康とこれからの穏やかな日々を祈願','静寂に包まれた境内が美しい第2番札所「極楽寺」へ。樹齢を重ねた見事な長寿杉の圧倒的な存在感に夫婦で深く感嘆しながら、これまでの人生を振り返りつつ、これからも健康で仲良く穏やかに歳を重ねていけますようにと心を込めて手を合わせ、境内をゆっくりと巡る。','2027-10-01','09:45','🌲','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,781,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.135000000,134.453330000,'第3番札所「金泉寺」で名物の「長寿湧水」に触れ、旅の無事と健勝を祈る','弘法大師が掘り当てたと伝えられる霊水が湧き出る第3番札所「金泉寺」へ到着。清らかな湧水に手を浸して身を清め、これからの長い道のりを元気に歩き抜くための体力と、夫婦二人で無事に結願を迎えられることを祈願しながら、お遍路旅ならではの厳かな雰囲気を肌で感じる。','2027-10-01','11:00','💧','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,782,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.120560000,134.460000000,'第4番札所「大日寺」の静かな境内で、二人並んで心を落ち着かせるお参り','緑豊かな木々に囲まれた落ち着いた佇まいの第4番札所「大日寺」へ足を運ぶ。静まり返った境内で、夫婦揃って並んでお線香とロウソクを奉納し、お経を唱える。日々の喧騒を離れ、二人だけの静かな時間を共有しながら心が穏やかに満たされていく贅沢なひとときを過ごす。','2027-10-01','12:30','🌿','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,783,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.116670000,134.433330000,'第5番札所「地蔵寺」の樹齢千年の大銀杏の下で、深まる秋の気配と歴史を感じる','境内にある圧倒的な大銀杏がシンボルとなっている第5番札所「地蔵寺」へ。歴史の重みを感じさせる厳かな境内で、お互いにこれまでの感謝の言葉をそっと交わしつつ、境内をゆっくりと散策しながら、夫婦の絆をさらに深める温かい時間をのんびりと楽しむ。','2027-10-01','14:00','🍂','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,784,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.110000000,134.398610000,'第6番札所「安楽寺」の美しい温泉湧出の歴史に触れ、旅の疲れを優しく癒やす','静かな山あいに佇む第6番札所「安楽寺」に到着し、お参りを済ませる。古くから温泉が湧き出たという境内のお寺の歴史に思いを馳せながら、ここまで歩んできた足の疲れを少しずつほぐし、明日からの長い道のりに向けて心身をしっかりとリラックスさせる。','2027-10-01','15:30','♨️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,785,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.103890000,134.382220000,'第7番札所「十楽寺」の厳かな山門をくぐり、夫婦で心静かに合掌する','美しい山門が出迎えてくれる第7番札所「十楽寺」へ到着する。静寂に包まれた境内で、夫婦二人でゆっくりと階段を上がり、本尊に向かってこれまでの無事に感謝しつつ、これからの旅の安全と家族の健康を心を込めて祈りながら、丁寧にお参りをしっかりと行う。','2027-10-02','08:30','⛩️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,786,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.100000000,134.341670000,'第8番札所「熊谷寺」の壮大な多宝塔を見上げ、歴史ある境内をしっとりとお散歩','見事な多宝塔や立派な仁王門が訪れる者を圧倒する第8番札所「熊谷寺」へ。緑豊かな境内を夫婦で並んで歩きながら、歴史ある建築美や季節の草花の美しさに目を奪われ、まるで時間がゆっくりと流れているような心地よい空間の中で穏やかなお参りを楽しむ。','2027-10-02','10:00','🏯','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (52,787,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.095000000,134.321110000,'第9番札所「法輪寺」の美しい庭園を眺め、お遍路の道中で心穏やかなひととき','落ち着いた雰囲気が漂う第9番札所「法輪寺」に到着。綺麗に手入れされた境内の庭園を夫婦二人で眺めながら、「ここまで順調に回れてよかったね」と優しく声を掛け合い、これまでの疲れを癒やしながら静かに手を合わせてお参りを済ませる。','2027-10-02','11:30','🌸','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,788,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.075000000,134.316670000,'第10番札所「切幡寺」の長い石段を二人で励まし合いながら一段ずつ登る','境内へと続く数百段の長い石段を前にして、夫婦で顔を見合わせながら気合を入れ直して登り始める。「一歩ずつゆっくり行こうね」と声を掛け合いながら励まし合って登り切り、達成感に包まれながら素晴らしい景色が広がる本堂でお参りを行う。','2027-10-02','13:00','🧗','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,789,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.053890000,134.305560000,'第11番札所「藤井寺」で次なる険しい山道に備え、夫婦でしっかりと気持ちを引き締める','次の難所である「焼山寺」へと続く遍路道の出発点でもある第11番札所「藤井寺」へ。これから始まる本格的な山岳霊場に向けて、「二人でしっかり足元に気をつけて歩こうね」と地図を確認し合いながら、気持ちをしっかりと引き締めてお参りをする。','2027-10-02','14:30','🗺️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,790,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.027780000,134.238890000,'第12番札所「焼山寺」へ至至難の山道を車で慎重に登り、深い歴史と自然の神秘に感動','険しい山道を車で慎重に進み、難所として知られる第12番札所「焼山寺」の境内へ到着する。古い杉木立に囲まれた神秘的な雰囲気に包まれた本堂で、無事にたどり着けたことに心から感謝しながら、夫婦二人で深く頭を下げて丁寧にお参りをする。','2027-10-03','09:00','🚗','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,791,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.072220000,134.425000000,'第13番札所「大日寺」の穏やかな境内で、これまでの道中を振り返る','徳島市内の静かな住宅街と自然が調和する第13番札所「大日寺」へと到着する。ここまで順調に巡ってきたお遍路の旅を振り返りながら、「だんだんお参りの作法にも慣れてきたね」と夫婦で笑顔で語り合い、本堂に向かって静かに合掌する。','2027-10-03','11:00','🕊️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,793,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.062500000,134.444440000,'第15番札所「国分寺」の歴史ある境内を歩き、阿波国の古刹の重みを感じ取る','阿波国分寺として長い歴史を誇る第15番札所「国分寺」へ到着する。落ち着いた佇まいの境内をゆっくりと歩きながら、古代から続くお寺の歴史の深さに思いを馳せ、夫婦二人でいつまでも健康で仲良く暮らせることを願いながら丁寧にお参りを行う。','2027-10-03','14:00','🏮','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,794,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.043330000,134.455000000,'第16番札所「観音寺」の温かい雰囲気に迎えられ、旅の疲れを優しく癒やす','アットホームで温かい雰囲気が漂う第16番札所「観音寺」へ到着する。境内を吹き抜ける爽やかな風を感じながら、夫婦二人でお互いの体調を気遣い合い、ここまで元気に歩けていることに感謝しながら心を込めてお参りを済ませる。','2027-10-03','15:30','☕','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,795,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.020560000,134.458330000,'第17番札所「井戸寺」の不思議な「お加持水」の伝説に夫婦で静かに感動する','境内に湧き出る井戸の伝説が残る第17番札所「井戸寺」へ。水面に自分の姿を映して吉凶を占ったという歴史ある井戸を覗き込みながら、神秘的な伝説に夫婦で感心し、本堂の前でこれからの道中の安全をしっかりと祈願する。','2027-10-04','08:30','🔮','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,796,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.978330000,134.461110000,'第18番札所「恩山寺」の急な山道を二人で支え合いながら登り切り、境内で一息','源義経の母にまつわる悲話が残る歴史的な第18番札所「恩山寺」の山門へと到着する。少し急な坂道を二人で声を掛け合いながら登り切ったあと、本堂の前で心地よい達成感に浸りながら、夫婦揃ってゆっくりと深呼吸をして休憩する。','2027-10-04','10:00','⛰️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (54,826,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.558900000,133.533300000,'朝うどんで腹ごしらえ','高知名物の「田舎うどん」をいただく。素朴な味が朝の体に染みていく。','2026-08-04','10:00','🍜','0000','',-520,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (52,797,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.945638453,134.515914917,'第19番札所「立江寺」で「関所寺」の厳かな雰囲気に触れ、身を引き締めてお参り','悪人を裁く関所であったという「関所寺」として知られる第19番札所「立江寺」へ。身が引き締まるような厳かな空気が漂う境内で、夫婦二人でこれまでの言動を静かに振り返り、清らかな気持ちで本堂に向かって丁寧にお参りをする。','2027-10-04','11:30','🛡️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,798,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.959308210,134.566040039,'第20番札所「鶴林寺」の険しい山深い杉木立の中を登り、圧倒的な自然美に浸る','標高の高い山奥に位置する難所の一つ、第20番札所「鶴林寺」へ車で慎重にアクセスする。古い杉木立に囲まれた荘厳な境内に足を踏み入れると、外界から切り離されたような圧倒的な静寂と自然の美しさに夫婦二人で深く感動する。','2027-10-04','13:30','🌲','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,799,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.916670000,134.577780000,'第21番札所「太龍寺」へロープウェイで空中散歩しながら、壮大な山岳霊場へ','西の高野山とも呼ばれる霊峰に位置する第21番札所「太龍寺」へ向かうためロープウェイに乗車する。空中から見下ろす壮大な山々の景色に「すごい絶景だね！」と夫婦で大興奮しながら、山上の荘厳な境内へと降り立って厳かにお参りする。','2027-10-05','09:00','🚠','0','',-2500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,800,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.844440000,134.552780000,'第22番札所「平等寺」の清らかな湧き水に癒やされ、心身をリフレッシュする','美しい自然に囲まれた静かな第22番札所「平等寺」へと到着する。境内にある清らかな湧き水の手水舎でしっかりと身を清め、ここまで巡ってきた旅の疲れを心地よく癒やしながら、本堂の前で夫婦二人で穏やかに手を合わせる。','2027-10-05','11:00','💧','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,801,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.822220000,134.333330000,'第23番札所「薬王寺」に到着し、厄除けの階段を夫婦揃って一段ずつ慎重に登る','徳島県最後の札所であり、厄除けの寺として名高い第23番札所「薬王寺」へ。男女それぞれの厄坂と呼ばれる階段があり、「お互い健康で元気にここまで来られてよかったね」と話し合いながら、一段一段を大切に踏みしめて登り切る。','2027-10-05','13:30','⛩️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,802,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.722220000,134.250000000,'徳島県から高知県へ！「最御崎寺」へと続く室戸岬の雄大な海岸線をドライブ','ついに徳島県を抜けて高知県へと突入し、太平洋の荒波が打ち寄せる室戸岬の絶景ロードをレンタカーで爽快に走る。車窓から広がるどこまでも青い海のパノラマに「いよいよ土佐に入ったね！」と夫婦で旅の盛り上がりを喜び合う。','2027-10-06','09:00','🌊','0','',0,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,803,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.719440000,134.175000000,'第24番札所「最御崎寺」の亜熱帯植物が広がる境内で、太平洋の絶景を眺める','室戸岬の先端近くの山上に位置する第24番札所「最御崎寺」へ到着する。境内を覆う珍しい亜熱帯植物の緑と、目の前に広がる真っ青な太平洋のコントラストが素晴らしく、荒波の音を聞きながら夫婦二人で雄大な景色に感動して手を合わせる。','2027-10-06','10:30','🌴','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,804,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.583330000,134.163890000,'第25番札所「津照寺」の港町を見下ろす高台の境内で、穏やかな海風を感じる','港町を一望する高台に佇む第25番札所「津照寺」へ。まるで船の形をした境内へと続く階段を登りながら、眼下に広がる穏やかな漁港の景色を眺め、海風を心地よく感じつつ、夫婦二人でゆっくりとお参りを済ませて次の目的地へと向かう。','2027-10-06','13:00','⚓','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,805,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.511110000,134.177780000,'第26番札所「金剛頂寺」の深い樹林に包まれた静寂の境内で、心を一つにしてお参り','豊かな自然林にすっぽりと包まれた第26番札所「金剛頂寺」の厳かな境内へ。木漏れ日が差し込む静かな参道を夫婦で並んでゆっくりと歩き、これまでの長旅の安全と無事に感謝を捧げながら、本堂の前で静かに心を一つにして合掌する。','2027-10-06','15:00','🌲','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (55,854,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.513900000,133.563900000,'坂本龍馬像を見学','龍馬像の迫力に感動。太平洋を見つめる姿がかっこよくて写真を何枚も撮る。','2026-08-11','10:20','🗿','0','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (52,806,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.366670000,134.025000000,'第27番札所「神峯寺」の急な山道を登り切り、高知の海と空の大パノラマに息を呑む','「土佐の修行の道場」の険しい山道を登りきった先にある第27番札所「神峯寺」へ到着する。苦労して登った境内の展望が開けた場所から見渡す高知の海と空の大パノラマに、「本当にここまで頑張って来てよかったね」と夫婦で感動の涙ぐむ。','2027-10-07','10:00','⛰️','0','',-500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,807,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.561110000,133.530560000,'高知市内の名店で、名物の「カツオの藁焼きタタキ」を夫婦で囲んで絶品の晩餐','お遍路の道中を一休みし、高知市内の活気ある名店へと繰り出して夕食タイム。香ばしい藁の香りがたまらない名物の「カツオの藁焼きタタキ」を厚切りで頬張り、「やっぱり本場の味は格別だね！」と地酒を少し傾けながら最高に幸せな夫婦の時間を満喫する。','2027-10-07','18:30','🐟','0','',-4500,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (52,808,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.591110000,133.560000000,'「高知駅」周辺の快適なホテルで一日の旅の疲れを癒やし、明日からの道のりへ英気を養う','快適なホテルのお部屋に戻り、今日巡ったたくさんの素晴らしい寺院や美しい景色の思い出をアルバムのように振り返る。「明日からも二人でゆっくり頑張ろうね」と優しく微笑み合いながら、心地よいベッドでしっかりと体を休めて明日への英気を養う。','2027-10-07','21:00','🏨','0','',-14000,1,0,0,0,0,false,'2026-08-02 01:45:05.83731+09','2026-08-02 01:45:05.83731+09','{}'),
	 (54,824,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559705000,133.531110000,'高知駅に到着','南国の空気がふわっと広がる高知駅。駅前のヤシの木が旅のテンションを一気に上げてくれる。','2026-08-04','09:20','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (54,825,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560820000,133.536900000,'高知駅前で朝の散歩','駅前広場を軽く散歩。青空が広がっていて、今日の旅が絶対楽しくなる予感がした。','2026-08-04','09:40','🌞','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (54,835,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.560040000,133.531430000,'高知城天守に登る','天守からの眺めが最高。高知の街並みと青空が広がっていて、気持ちが明るくなる景色。','2026-08-04','15:10','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (54,836,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559500000,133.532200000,'城下で休憩','城下のカフェでアイスコーヒーを飲みながら写真を整理。旅の充実感がじんわり広がる。','2026-08-04','15:40','☕','0000','',-580,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (54,837,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559000000,133.533600000,'ひろめ市場でお土産購入','カツオ関連のお土産を購入。店員さんが気さくで、つい色々買ってしまった。','2026-08-04','16:20','🎁','0000','',-1400,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (54,838,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.559705000,133.531110000,'高知駅で旅の締め','駅ナカで軽く休憩しながら今日の写真を見返す。明るく楽しい一日だった。','2026-08-04','17:00','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 01:59:40.217868+09','2026-08-02 01:59:40.217868+09','{}'),
	 (55,839,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.342566000,134.046549000,'高松駅に到着','四国旅のスタートは高松駅。瀬戸内の明るい空気が気持ちよくてワクワクが広がる。','2026-08-10','09:10','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (55,840,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.344143000,134.050210000,'高松港で海風を感じる','港の海風が心地よくて瀬戸内海の穏やかな景色に自然と笑顔になる。','2026-08-10','09:40','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,841,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.343720000,134.046930000,'うどんで腹ごしらえ','香川名物のかけうどんをいただく。出汁の香りが最高で旅のテンションが上がる。','2026-08-10','10:00','🍜','0000','',-480,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,842,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.320030000,134.042430000,'栗林公園散策','庭園の緑が鮮やかで池の反射も美しい。歩くだけで気持ちが軽くなる。','2026-08-10','11:00','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,843,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.319310000,134.043010000,'茶屋で抹茶休憩','抹茶と和菓子を楽しみながら庭園を眺める贅沢な時間。心がふわっと明るくなる。','2026-08-10','11:40','🍵','0000','',-700,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,844,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.350120000,134.056030000,'商店街をぶらぶら','アーケードが長くて歩きやすい。地元のお店を見て回るだけで楽しい気分になる。','2026-08-10','12:30','🛍️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (29,417,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.195400000,135.152000000,'加太へ移動','海が見えてテンション上がる。写真を撮りながらのんびり移動。','2026-08-10','13:20','🙂','0','',0,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (55,864,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'道後温泉本館へ移動','レトロな建物が美しくてテンションが上がる。温泉街の雰囲気も最高。','2026-08-12','11:00','🏮','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,865,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839700000,132.770300000,'道後温泉で入浴','湯がやわらかくて体が軽くなる。旅の疲れがすっと抜けていく感じが最高。','2026-08-12','11:30','♨️','0000','',-420,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,866,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.770900000,'温泉街で昼食','鯛めしをいただく。ふわっとした食感がたまらなくて幸せな気分になる。','2026-08-12','12:00','🍚','0000','',-1400,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (55,867,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.841640000,132.765300000,'松山駅で休憩','駅ナカでアイスコーヒー。四国旅の写真を見返しながら余韻に浸る。','2026-08-12','13:00','☕','0000','',-520,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (56,869,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'道後温泉に到着','家族で車を降りた瞬間にふわっと温泉街の香りがして「来たねえ」と声がそろった。レトロな建物が並ぶ道後の街は歩くだけで楽しくて、みかん色の提灯がゆらゆら揺れているのがかわいかった。旅の始まりにぴったりのやわらかい空気に包まれた。','2026-09-12','10:10','🏮','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,870,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839700000,132.770300000,'道後温泉でひと風呂','湯に浸かった瞬間に体がふわっと軽くなって家族みんなで「気持ちいい〜」と声が漏れた。湯上がりに飲んだみかん牛乳が驚くほど甘くて、子どもが「これ毎日飲みたい」と笑った。旅の疲れがすっと抜けていくようなやさしい時間だった。','2026-09-12','11:00','♨️','0000','',-420,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,871,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.770900000,'温泉街で昼食','道後の食堂で鯛めしをいただく。ふわっとした鯛の甘さが口いっぱいに広がって、家族みんなで「おいしい！」と声がそろった。窓から見える温泉街のゆるい雰囲気も心地よくて、旅の最初の食事として最高だった。','2026-09-12','12:00','🍚','0000','',-1400,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,872,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.853200000,132.786500000,'松山城へ向かうドライブ','坂道を車で登っていくと松山城が少しずつ見えてきて、子どもが「お城や！」と指をさして喜んだ。城下町の雰囲気が残る道を走るのは気持ちよくて、窓から入る風もやわらかかった。家族でのんびり景色を楽しむ時間になった。','2026-09-12','13:00','🚗','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,873,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839400000,132.765200000,'松山城天守に登る','天守から見える松山の街並みがとてもきれいで、家族みんなで「すごいねえ」と声がそろった。風が気持ちよくて、しばらく景色を眺めながらゆっくり過ごした。みかん色の屋根がちらほら見えるのも愛媛らしくてかわいかった。','2026-09-12','13:40','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,874,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.860200000,132.708900000,'伊予市方面へドライブ','海沿いの道を走ると、窓から入ってくる風が少し甘いような気がして「みかんの匂いする？」と家族で笑った。道の両側に広がる畑がオレンジ色に染まっていて、走っているだけで気持ちが明るくなる道だった。','2026-09-12','14:20','🚗','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,875,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757900000,132.703400000,'道の駅ふたみ到着','海がすぐ目の前に広がっていて、家族みんなで「きれい！」と声がそろった。しぼりたてみかんジュースを飲んだら驚くほど濃くて、子どもが「これ本物の味や！」と笑った。海とみかんの香りが混じった風がとても気持ちよかった。','2026-09-12','15:00','🍊','0000','',-600,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,876,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757500000,132.703900000,'ふたみ海岸を散歩','夕方の海岸は光がやわらかくて、波の音が心地よかった。家族で並んで歩きながら「今日いろいろ楽しかったね」と話して、ゆっくりとした時間を過ごした。みかん畑が海の向こうに見えるのも愛媛らしくてかわいかった。','2026-09-12','16:00','🌅','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,877,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744200000,132.703800000,'宿へ向かうドライブ','海沿いの道をゆっくり走りながら、夕日がみかん色に染まっていくのを眺めた。家族で「きれいすぎる」と何度も言いながら、今日の思い出を話し合った。車内の空気がやわらかくて幸せな時間だった。','2026-09-12','17:00','🚗','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,878,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'海沿いの宿に到着','宿のロビーから見える海が夕日に染まっていて、家族みんなで「すごい…」と声を失った。波の音が静かに響いていて、今日の疲れがすっと抜けていくような気がした。みかんの香りのアメニティがかわいくてテンションが上がった。','2026-09-12','17:30','🏨','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (56,879,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'宿の夕食','夕食に出てきたみかんを使ったサラダが驚くほど爽やかで、家族みんなで「これ家でも作りたい」と話した。海の幸も新鮮で、旅の夜にぴったりのやさしい味だった。ゆっくり食べながら今日の思い出を振り返った。','2026-09-12','18:30','🍽️','0000','',-1800,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,880,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'家族で夜の海を眺める','宿のテラスから夜の海を眺めると、波の音が静かに響いていてとても落ち着いた。子どもが「また明日も海見たい」と言って、家族で笑いながらゆっくり過ごした。旅の夜らしいやわらかい時間だった。','2026-09-12','20:00','🌙','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,881,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.744900000,132.703200000,'翌朝の海散歩','朝の海は光がきらきらしていて、家族みんなで「昨日よりきれいかも」と話しながら散歩した。潮風に少しみかんの香りが混じっているような気がして、愛媛らしい朝だなと感じた。','2026-09-13','07:00','🌤️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,882,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757900000,132.703400000,'道の駅ふたみに再訪','昨日飲んだみかんジュースが忘れられなくて再訪。今日のジュースも濃くて甘くて、家族みんなで「やっぱりこれやな」と笑った。海も朝の光でとてもきれいだった。','2026-09-13','08:00','🍊','0000','',-600,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (65,1015,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.404722000,133.190556000,'向島へ渡るフェリー','短い船旅でも海の上を進む感覚が楽しくて、旅の気分が一気に高まる。','2026-08-04','09:00','🤩','0000','',-180,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (56,883,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.757500000,132.703900000,'海岸で写真撮影','朝の海岸は光がやわらかくて、家族写真を撮るのにぴったりだった。みかん畑が遠くに見えて、愛媛らしい一枚になった。子どもが「また来ようね」と言ってくれて嬉しかった。','2026-09-13','08:40','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,884,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.860200000,132.708900000,'帰り道のドライブ','帰り道の海沿いの道は昨日より少し明るくて、家族で「また来たいね」と話しながら走った。みかん畑がキラキラしていて、旅の終わりにぴったりの景色だった。','2026-09-13','09:30','🚗','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,885,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'道後温泉街に戻る','旅の最後に道後温泉街をもう一度歩いた。昨日より人が多くて賑やかだったけど、みかん色の提灯がかわいくてやっぱり好きな場所だと思った。家族で「また来ようね」と話しながら歩いた。','2026-09-13','10:30','🏮','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,886,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839700000,132.770300000,'最後のひと風呂','帰る前にもう一度温泉へ。湯に浸かると昨日の疲れがすっと抜けていく感じがして、家族みんなで「やっぱり道後はいいね」と話した。湯上がりのみかん牛乳も最高だった。','2026-09-13','11:00','♨️','0000','',-420,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (56,887,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839900000,132.770900000,'温泉街でお土産購入','みかんゼリーやジュースを家族で選びながら「これおいしそう！」と盛り上がった。店員さんが優しくて、旅の最後にほっこりした気持ちになった。','2026-09-13','11:40','🎁','0000','',-1600,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (56,888,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.839800000,132.770200000,'旅の締め','車に荷物を積みながら「楽しかったね」と家族で話した。みかん色の風景と海の音がずっと心に残る旅になった。また来たいと思えるやさしい1泊旅だった。','2026-09-13','12:00','🚗','0000','',0,1,0,0,0,0,false,'2026-08-02 02:18:25.92342+09','2026-08-02 02:18:25.92342+09','{}'),
	 (57,889,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'広島駅に集合','大学の友達4人で広島駅に集合。久しぶりの旅行でテンションが上がり、駅前で「今日めっちゃ楽しもうな」と声を合わせた。荷物を軽くまとめて、まずは市内を歩きながら旅のスタートをゆっくり味わった。','2026-10-05','09:10','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,890,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.391480000,132.452900000,'原爆ドームへ移動','駅から歩いて原爆ドームへ。静かな空気の中で4人とも自然と声が少なくなり、歴史の重さを感じながらゆっくり見学した。友達同士でもこういう時間を共有できるのが嬉しかった。','2026-10-05','09:40','🏛️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,891,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.391030000,132.453530000,'平和記念公園を散策','公園内を歩きながら、川沿いの静けさと広い空に少し気持ちが軽くなった。友達と「こういう場所に来ると考えること増えるよな」と話しながら、ゆっくりとした時間を過ごした。','2026-10-05','10:10','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,892,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.392030000,132.454900000,'資料館を見学','展示を見ながら4人とも真剣な表情になり、言葉少なめに歩いた。出口付近で「来てよかったな」と自然に声が出て、大学生の旅らしい少し大人な時間になった。','2026-10-05','11:00','📘','0000','',-200,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,893,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.392900000,132.457200000,'お好み村で昼食','お好み焼きを囲んで4人でワイワイ。「広島来たらこれやろ！」と盛り上がり、鉄板の音とソースの香りでテンションが一気に回復。大学生らしい賑やかな昼食になった。','2026-10-05','12:00','🍳','0000','',-1500,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,894,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.396260000,132.459840000,'紙屋町をぶらぶら','街中を歩きながらカフェやショップを見て回る。友達が「この街めっちゃ好きかも」と言い、みんなでゆるい雰囲気を楽しんだ。都会すぎず落ち着いた感じが心地よかった。','2026-10-05','13:00','🛍️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,895,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295130000,132.319690000,'宮島口へ移動','電車で宮島口へ向かう道中、4人で大学の話や最近の悩みをゆるく話しながら移動。旅の途中のこういう時間が一番楽しいかもしれないと思った。','2026-10-05','14:00','🚆','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,896,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.302030000,132.319450000,'フェリーで宮島へ','フェリーに乗ると海風が気持ちよくて、4人で写真を撮りまくった。「大学生の旅って感じするな！」と笑いながら、海の上の短い時間を楽しんだ。','2026-10-05','14:30','⛴️','0000','',-500,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,897,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295490000,132.319690000,'宮島に上陸','鹿が近づいてきて4人で大騒ぎ。「かわいいけど近い近い！」と笑いながら写真を撮った。島の空気がゆっくりしていて、歩くだけで気持ちが軽くなる場所だった。','2026-10-05','15:00','🦌','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (57,898,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295450000,132.319230000,'厳島神社へ参拝','鳥居を見た瞬間「うわ、ほんまに来たんや」と4人で感動。海に浮かぶような景色が美しくて、しばらく無言で眺めてしまった。大学生の旅でもこういう瞬間は心に残る。','2026-10-05','15:30','⛩️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,899,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295900000,132.319900000,'宮島商店街で食べ歩き','もみじ饅頭を食べながら「これうますぎん？」と盛り上がる。揚げもみじを初めて食べて感動し、4人でシェアしながら歩いた。商店街の賑やかさが楽しくてずっと笑っていた。','2026-10-05','16:00','🍡','0000','',-800,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (65,1014,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.408056000,133.204167000,'尾道駅から旅を始める','朝の尾道駅は静かで海風が心地よい。ここからしまなみ海道の旅が始まると思うと胸が高鳴る。','2026-08-04','08:30','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (57,900,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.295130000,132.319690000,'フェリーで帰路へ','夕方のフェリーは風が少し冷たくて、4人で「今日めっちゃ濃かったな」と話しながら帰った。海の色がゆっくり変わっていくのを眺める時間が心地よかった。','2026-10-05','17:00','⛴️','0000','',-500,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,901,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.396260000,132.459840000,'市内のカフェで休憩','歩き疲れてカフェに入り、4人で写真を見返しながら「これめっちゃいいやん」と盛り上がった。大学生らしいゆるい時間が心地よくて、旅の余韻をゆっくり味わった。','2026-10-05','18:00','☕','0000','',-700,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,902,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.392900000,132.457200000,'夜のお好み焼き屋へ','昼に続いて夜もお好み焼き。「広島来たら2回食べてもええやろ」と笑いながら、鉄板を囲んで大学生らしい賑やかな夜ごはんになった。','2026-10-05','19:00','🍳','0000','',-1800,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,903,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.396260000,132.459840000,'夜の紙屋町を散歩','夜の街は昼より少し静かで、4人でゆっくり歩きながら「今日めっちゃ良かったな」と話した。ライトに照らされた街並みがきれいで、旅の締めにぴったりの時間だった。','2026-10-05','20:00','🌙','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,904,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'広島駅へ戻る','駅に戻ると少し疲れが出てきたけど、4人で「また来たいな」と話しながらゆっくり歩いた。旅の終わりの静かな時間が心地よかった。','2026-10-05','20:40','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,905,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'駅でお土産購入','もみじ饅頭や広島限定のお菓子を選びながら「これ絶対うまいやつ」と盛り上がった。友達同士でお土産を選ぶ時間が楽しくて、旅の最後にいい思い出ができた。','2026-10-05','21:00','🎁','0000','',-1600,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,906,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'駅前で記念撮影','駅前の広場で4人並んで記念撮影。「今日めっちゃ良かったな」と笑いながら撮った写真は、大学生活の大事な思い出になりそうだった。','2026-10-05','21:20','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (57,907,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'帰りの電車待ち','ホームで電車を待ちながら、4人で今日の写真を見返して「これSNSにあげよ」と盛り上がった。旅の終わりの少し寂しい感じも大学生らしくて良かった。','2026-10-05','21:40','🚆','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (57,908,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.397720000,132.475310000,'広島旅の締め','電車に乗り込む前に「また4人でどっか行こな」と約束した。広島の景色と笑い声がずっと心に残る、大学生らしい最高の1日旅になった。','2026-10-05','22:00','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:29:17.135538+09','2026-08-02 02:29:17.135538+09','{}'),
	 (59,924,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957414280,130.940354910,'下関駅に到着','大学生4人で下関駅に集合。駅前の広場には朝の光がやわらかく差し込み、潮の香りがほんのり混じっていた。これから始まる「フグ食べつくし旅」への期待が自然と高まり、旅のスタートにふさわしい落ち着いた空気が流れていた。荷物を整えながら、まずは唐戸市場へ向かうルートを確認し、駅前の静かな雰囲気を楽しんだ。','2026-11-03','09:10','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,925,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957982110,130.941145770,'唐戸市場前に到着','駅からバスで唐戸市場へ向かうと、車窓から海がきらきらと光り、旅の目的が一気に現実味を帯びてきた。市場の建物が見えてくると、食べ歩きへの期待が自然と高まり、4人の表情が明るくなる。市場前の広場は活気に満ちており、下関の食文化を象徴する雰囲気が漂っていた。','2026-11-03','09:40','🚌','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,926,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957842330,130.941873220,'唐戸市場でフグ寿司','市場に入ると海鮮の香りと活気ある声が広がり、自然と気持ちが高まった。名物のフグ寿司を口に入れると、身がぷりっと弾むようで、旅の序盤から満足度が一気に上昇した。市場の賑やかさとフグの旨味が相まって、下関ならではの食体験が強く印象に残った。','2026-11-03','10:00','🍣','0000','',-900,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,927,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957765440,130.942102880,'市場横の海沿いデッキで休憩','市場横の海沿いデッキに出ると、関門海峡を渡る風が心地よく、食べ歩きの合間にぴったりの休憩時間になった。船が行き交う景色を眺めながら、フグ寿司の余韻を楽しむ。海の青さが広がり、旅の中にゆるやかな時間が流れた。','2026-11-03','10:30','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,928,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957050120,130.942600440,'みもすそ川公園で海峡を眺める','赤間神宮から坂を下ると、みもすそ川公園に到着。関門海峡が目の前に広がり、海風が心地よく体を冷ましてくれた。源平合戦の史跡が残る場所で、歴史と海の景色が同時に楽しめる。食べ歩きの合間に訪れるには最適のスポットだった。','2026-11-03','11:20','🌉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,929,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.969612880,130.941912330,'火の山公園展望台','ロープウェイで火の山公園へ向かうと、展望台から関門海峡が一望できた。海と街が広がる景色は圧巻で、旅の中でも特に印象に残る瞬間となった。展望台の静けさが心地よく、食の旅に風景の魅力が加わった。','2026-11-03','12:00','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,930,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.951122770,130.927744110,'長府城下町を散策','長府の城下町は静かで落ち着いた雰囲気が広がり、石畳の道を歩くだけで気持ちが整う。歴史的な建物が並び、下関の中心部とは違う魅力が感じられた。食べ歩きの合間に訪れると、旅の流れに心地よい変化が生まれた。','2026-11-03','13:00','🏯','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,931,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.950212110,130.928844770,'功山寺で静かな時間','功山寺の境内は深い静けさに包まれており、旅の喧騒から離れて心が落ち着く場所だった。歴史ある建物と木々の香りが心地よく、大学生4人の旅にも静かな時間が流れた。下関の多様な魅力を感じられるスポットだった。','2026-11-03','13:40','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (65,1018,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.285556000,133.204444000,'因島でレモンソフトを食べる','名物のレモンソフトは爽やかで暑い日にぴったり。島の雰囲気と相まって気分が良くなる。','2026-08-04','11:00','🤩','0000','',-350,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (59,932,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.041280622,130.929565430,'角島大橋を歩く','角島大橋は海の上をまっすぐ伸びる絶景スポットで、4人とも自然と声を失った。海の青さが圧倒的で、写真を撮る手が止まらない。下関中心部から離れた場所だが、旅の中でも特に印象に残る体験となった。','2026-11-03','14:40','🌅','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,933,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.073137412,130.902099609,'角島灯台を見学','角島灯台は白い塔が美しく、海の青さとのコントラストが印象的だった。灯台周辺の散策路を歩くと、風が心地よく旅の疲れを癒してくれた。下関の食文化だけでなく、自然の魅力も感じられる時間となった。','2026-11-03','15:10','🌤️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,934,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.960744880,130.943544110,'ノーフォーク広場で休憩','海沿いのノーフォーク広場は風が心地よく、旅の合間にぴったりの場所だった。ベンチに座りながら海峡を眺めると、今日の食べ歩きの思い出が自然と蘇る。広場の穏やかな雰囲気が心地よかった。','2026-11-03','15:40','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,935,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.960144550,130.942244330,'海峡ゆめタワー展望室','海峡ゆめタワーの展望室からは、関門海峡と街並みが一望できた。夕方の光が差し込み、海が金色に輝く景色は圧巻だった。旅の締めにふさわしい絶景で、4人とも静かに景色を眺めていた。','2026-11-03','16:10','🏙️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,936,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.948744220,130.919544990,'長府毛利邸を見学','長府毛利邸は庭園が美しく、静かな時間が流れていた。歴史ある建物と手入れされた庭が印象的で、旅の中に落ち着いたひとときを与えてくれた。下関の多様な魅力を感じられるスポットだった。','2026-11-03','16:40','🏡','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,937,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957144880,130.940744550,'下関駅前でお土産購入','駅前のショップでフグ関連のお土産を選びながら、今日の食べ歩きの思い出を振り返った。大学生4人の旅らしい賑やかな時間で、旅の終わりにふさわしい締めくくりとなった。','2026-11-03','17:00','🎁','0000','',-1600,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (59,938,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.957414280,130.940354910,'旅の締め','駅前の広場で4人並んで記念撮影。下関の海と食文化、そしてフグの美味しさが強く印象に残る旅となった。「また来たい」と自然に言葉が出る、満足度の高い一日だった。','2026-11-03','17:20','🐡','0000','',0,1,0,0,0,0,false,'2026-08-02 02:38:15.311653+09','2026-08-02 02:38:15.311653+09','{}'),
	 (60,939,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401002110,132.685744880,'出雲大社前駅に到着','出雲大社前駅に降り立つと、レトロな駅舎が迎えてくれた。空気がどこか澄んでいて、旅の始まりにふさわしい静けさが漂う。駅前の道はゆるやかに大社へ続いており、歩きながら「この土地は何か特別なものを持っている」と自然に感じられた。参道の石畳を踏みしめながら、今日の縁結び旅への期待が静かに高まった。','2026-10-12','09:10','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,940,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401844550,132.685012330,'勢溜の大鳥居をくぐる','勢溜の大鳥居は想像以上に大きく、くぐった瞬間に空気が変わるような感覚があった。鳥居の向こうに続く参道は広く、ゆっくり歩くと心が落ち着いていく。朝の光が木々の間から差し込み、旅の始まりにふさわしい神聖な雰囲気が漂っていた。','2026-10-12','09:30','⛩️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (60,941,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.402744220,132.684544110,'松の参道を歩く','勢溜から続く松の参道は、両側に立ち並ぶ松が美しく、歩くだけで気持ちが整う。砂利道の音が心地よく、ゆっくり進むと自然と背筋が伸びるような感覚があった。参拝前の時間として最適で、出雲らしい穏やかな空気が流れていた。','2026-10-12','09:50','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,942,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.403544990,132.684012880,'拝殿で参拝','拝殿の前に立つと、その大きさと美しさに自然と息をのんだ。二礼四拍手一礼でゆっくり参拝すると、心が静かに整っていく。周囲の空気は澄んでいて、参拝後には気持ちが軽くなるような感覚があった。出雲大社ならではの特別な時間だった。','2026-10-12','10:10','🙏','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,943,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.403944330,132.683544550,'本殿を参拝','本殿は厳かな雰囲気に包まれており、近づくほどに心が静かになる。木の香りがほのかに漂い、歴史の深さを感じられた。参拝を終えると、気持ちがすっと軽くなり、旅の目的である「縁結び」が自然と心に浮かんだ。','2026-10-12','10:30','🏯','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,944,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.404744880,132.683012440,'神楽殿で大しめ縄を見る','神楽殿の大しめ縄は圧倒的な存在感で、近くで見るとその迫力に驚かされる。太い縄の編み込みが美しく、写真では伝わらない重厚さがあった。参拝客の穏やかな声が響き、出雲らしいゆったりした時間が流れていた。','2026-10-12','10:50','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,945,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.405544220,132.682544330,'御本殿裏の素鵞社へ','素鵞社は本殿裏にひっそりと佇み、静かな空気が流れていた。参拝すると心がすっと整い、出雲の神聖さをより深く感じられた。木々に囲まれた場所で、風の音が心地よく響いていた。','2026-10-12','11:10','🌲','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,946,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.405944990,132.681744880,'出雲そばで昼食','参道沿いのそば屋で出雲そばをいただく。黒めのそばは香りが強く、つゆとの相性が抜群だった。店内は落ち着いた雰囲気で、旅の途中の食事として最適。体がほっと温まり、午後の散策への活力が湧いた。','2026-10-12','12:00','🍜','0000','',-1200,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,947,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.404144550,132.680544330,'古代出雲歴史博物館を見学','博物館では出雲の神話や歴史を深く知ることができ、展示の迫力に驚かされた。巨大な柱の復元模型は圧巻で、古代出雲の壮大さを感じられた。静かな展示室を歩くと、旅のテーマである「縁結び」がより意味深く感じられた。','2026-10-12','13:00','🏛️','0000','',-620,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (65,1019,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.250833000,133.226944000,'生口橋を渡る','白い橋が美しくて、瀬戸内海の穏やかな景色が広がる。写真を撮りたくなる場所。','2026-08-04','11:40','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (60,948,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.402244110,132.677744220,'稲佐の浜へ移動','稲佐の浜は白い砂浜と青い海が広がり、神話の舞台らしい静けさが漂っていた。波の音が心地よく、歩くだけで気持ちが整う。弁天島を眺めながら深呼吸すると、旅の中でも特に印象に残る時間となった。','2026-10-12','14:00','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,949,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401544330,132.676544880,'浜辺で写真撮影','稲佐の浜の光はやわらかく、写真を撮るとどれも美しく写った。海風が心地よく、旅の思い出として残したい景色が広がっていた。静かな浜辺で過ごす時間は、出雲らしい穏やかさに満ちていた。','2026-10-12','14:30','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (60,950,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401844550,132.685012330,'参道で甘味を楽しむ','参道の甘味処でぜんざいをいただく。温かい甘さが体に染みて、歩き疲れた体がほっと落ち着いた。店内は静かで、旅の途中の休憩として最適。出雲の優しい空気を感じられる時間だった。','2026-10-12','15:00','🍡','0000','',-800,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,951,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.400744220,132.686144550,'出雲大社前でお守り購入','出雲大社前の授与所で縁結びのお守りを選ぶ。白と赤の優しい色合いが美しく、手に取ると自然と気持ちが引き締まった。旅の記念として最適で、今日の体験が形として残る瞬間だった。','2026-10-12','15:30','🎁','0000','',-1500,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,952,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401002110,132.685744880,'駅へ戻る道を歩く','駅へ戻る参道は夕方の光が差し込み、朝とは違う表情を見せていた。歩きながら今日の出来事を思い返すと、どれも穏やかで心に残るものばかりだった。出雲の空気が旅の終わりをやさしく包んでくれた。','2026-10-12','16:00','🚶','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (60,953,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.401002110,132.685744880,'旅の締め','駅前で深呼吸すると、出雲の静かな空気が胸に広がった。縁結びの地を巡った一日は、心が自然と整うような穏やかな時間だった。お守りを手にしながら「また来たい」と思える旅になった。','2026-10-12','16:20','🌸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:43:50.260199+09','2026-08-02 02:43:50.260199+09','{}'),
	 (61,954,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.676842110,131.792544880,'萩・石見空港に到着','萩・石見空港に降り立つと、周囲は静かな山々に囲まれていて、都市の空港とはまったく違う穏やかな空気が流れていた。ターミナルの外に出ると鳥の声が響き、遠くに日本海の気配が感じられる。まずは空港周辺を軽く歩きながら、今日の散策ルートを確認。観光地が少ない地域だからこそ、自然の中でゆっくり過ごす旅になりそうだと感じた。','2026-10-20','09:10','🛬','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,955,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.682144550,131.797744330,'空港展望台で離着陸を見る','空港の展望スペースに向かうと、滑走路が一望でき、山に囲まれた空港ならではの静かな景色が広がっていた。離陸する機体の音が山に反響し、どこか心地よい。観光地ではないが、石見らしい素朴な魅力が感じられる場所で、旅の始まりにふさわしい時間となった。','2026-10-20','09:40','🚶','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,956,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.669217363,131.800231934,'空港北側の山道を散策','空港北側には小さな山道があり、歩き始めると木々の香りがふわっと広がった。舗装されていない道だが、鳥の声や風の音が心地よく、自然の中を歩く楽しさがある。観光地ではないが、静けさを求める旅にはぴったりの場所だった。','2026-10-20','10:20','🌲','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,957,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.692791545,131.821689606,'山の稜線から日本海を望む','山道をさらに進むと稜線に出て、日本海が遠くに見えた。荒々しい海の青さと山の緑が対照的で、石見らしい風景が広がる。観光地ではないが、こうした自然の景色が旅の印象を強くしてくれる。しばらく風を感じながら景色を眺めた。','2026-10-20','11:00','🌄','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,958,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.698860457,131.846752167,'山の麓の小さな神社を参拝','山を下る途中に小さな神社があり、苔むした鳥居が静かに佇んでいた。地元の人が守ってきた場所らしく、派手さはないが落ち着いた空気が流れている。旅の途中でこうした場所に出会うと、自然と気持ちが整う。','2026-10-20','11:40','⛩️','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,959,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.712831377,131.858940125,'山里の集落を歩く','山の麓には小さな集落があり、古い家屋が並んでいた。人の気配は少ないが、静かな生活の空気が感じられる。道端には季節の花が咲き、歩くだけで心が落ち着く。観光地ではないが、石見の素朴さがよく伝わる場所だった。','2026-10-20','12:20','🏡','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (61,960,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.718898820,131.866493225,'日本海側へ向かう山道を走る','集落を抜けて海へ向かう山道を歩くと、道の両側に広がる木々が風に揺れ、自然の音だけが響いていた。車通りもほとんどなく、石見の静けさを存分に味わえる。海が近づくにつれ、潮の香りが少しずつ混じってきた。','2026-10-20','13:00','🚶','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,961,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.748665166,131.873703003,'日本海の海岸線に到着','海岸線に出ると、荒々しい波が岩にぶつかり、迫力ある音が響いていた。観光地ではないが、石見らしい力強い海の景色が広がる。風が強く、海の匂いが濃く感じられた。しばらく波を眺めながら、自然の大きさを感じる時間となった。','2026-10-20','13:40','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,962,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.757268605,131.871814728,'海沿いの小さな漁港を散策','海岸線を歩くと小さな漁港があり、漁船が静かに並んでいた。人の姿は少ないが、港特有のゆったりした空気が流れている。海風が心地よく、旅の途中の散策として最適だった。石見の素朴な海の暮らしを感じられる場所だった。','2026-10-20','14:10','⚓','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,963,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.757268605,131.877822876,'海沿いの展望地で休憩','漁港から少し歩くと小さな展望地があり、日本海が広く見渡せた。波の音が絶えず響き、風が強く吹き抜ける。観光地ではないが、石見の海の力強さを感じられる場所で、旅の印象を深めてくれた。','2026-10-20','14:40','🌅','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,964,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.749934582,131.893787384,'海沿いの食堂で昼食','海沿いの小さな食堂に入り、地元の魚を使った定食をいただく。派手さはないが、丁寧に作られた味で体がほっと落ち着いた。窓から見える海の景色が心地よく、旅の途中の食事として最適だった。','2026-10-20','15:10','🚶','0000','',-1200,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,965,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.764742996,131.907691956,'海岸線をゆっくり歩く','昼食後、海岸線をゆっくり歩くと、風が少し弱まり、海の音がよりはっきり聞こえるようになった。岩場に打ち寄せる波を眺めながら歩く時間は、石見の自然を深く感じられる瞬間だった。','2026-10-20','15:40','🤩','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,966,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.754588941,131.932411194,'海沿いの岩場で写真撮影','岩場に出ると、海の迫力がさらに増し、写真を撮るとどれも力強い景色になった。観光地ではないが、自然のままの海が広がり、旅の記録として残したい場所だった。','2026-10-20','16:10','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,967,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.742882023,131.909065247,'山へ戻る道を歩く','海から山へ戻る道は静かで、風の音と鳥の声だけが響いていた。自然の中を歩く時間が長くなるほど、石見の素朴さが心に染みてくる。観光地ではないが、こうした静けさが旅の魅力になった。','2026-10-20','16:40','🌲','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:04.629722+09','{}'),
	 (61,968,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.675993863,131.795210838,'空港に戻り旅の締め','空港に戻ると、朝と同じ静かな空気が広がっていた。山と海を歩いた一日を思い返すと、派手さはないが心が落ち着く旅だったと感じる。石見の自然は素朴で、ゆっくり過ごす旅にぴったりだった。','2026-10-20','17:10','🛫','0000','',0,1,0,0,0,0,false,'2026-08-02 02:53:04.629722+09','2026-08-02 02:53:41.649515+09','{}'),
	 (62,969,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371240000,131.182760000,'長門市駅に到着','長門市駅に着くと、静かな港町らしい穏やかな空気が広がっていた。駅前で自転車を整えながら今日のルートを確認し、まずは仙崎方面へ向かうことにした。山と海が近い土地ならではの風が心地よく、サイクリング旅の始まりとして気持ちが引き締まる。観光地の喧騒とは無縁の、長門らしいゆったりした空気が流れていた。','2026-10-18','09:10','🚴','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (62,970,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.388460521,131.202464104,'仙崎港を走る','駅から北へ走ると仙崎港に入り、海の香りがふわっと漂ってきた。漁船が並ぶ港を横目に走ると、地元の生活の気配が感じられ、観光地とは違う素朴な魅力があった。道は平坦で走りやすく、海風が背中を押してくれるようだった。','2026-10-18','09:40','⚓','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,971,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.403510505,131.200447083,'青海島入口に到着','仙崎から橋を渡ると青海島の入口に到着。海上アルプスと呼ばれる島らしく、遠くに見える岩肌が迫力を感じさせる。ここからは海沿いの道が続き、景色が一気に変わる。自転車で走ると風が強くなるが、その分だけ海の存在が近く感じられた。','2026-10-18','10:10','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,972,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.406059882,131.207141876,'青海島・海岸線を走る','島の海岸線は変化に富んだ岩場が続き、走るたびに景色が変わる。断崖の上を走る区間では海が真下に広がり、風が強くて少し緊張するが、その分だけ達成感がある。観光地のような整備は少ないが、自然の迫力をそのまま感じられる道だった。','2026-10-18','10:40','🚴','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,973,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.424469737,131.212635040,'青海島・千畳敷展望地','海岸線を進むと小さな展望地があり、岩場と海が一望できた。波が岩にぶつかる音が響き、自然の力強さを感じる。自転車を止めてしばらく景色を眺めると、旅の中でも特に印象に残る時間となった。','2026-10-18','11:10','📸','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,974,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.425177728,131.218471527,'青海島・遊歩道入口','展望地から少し走ると遊歩道の入口があり、自転車を置いて歩くことにした。木々に囲まれた道は静かで、鳥の声が響く。海岸線の迫力とは違う、青海島の穏やかな一面が感じられた。','2026-10-18','11:40','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,975,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.430275082,131.246452332,'青海島・岩場の絶景ポイント','遊歩道を進むと岩場の絶景ポイントに出た。海の青さと岩肌の迫力が目の前に広がり、写真を撮る手が止まらない。観光地のような案内はないが、自然そのままの景色が旅の印象を強くしてくれる。','2026-10-18','12:10','🌄','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,976,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.412008124,131.178131104,'仙崎へ戻る道を走る','島内を巡ったあと仙崎へ戻る道を走ると、海風が少し弱まり、走りやすくなった。港町が近づくにつれ、生活の気配が戻ってくる。自然の迫力を感じた後に町へ戻ると、旅の流れに心地よい緩急が生まれた。','2026-10-18','12:40','🚴','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,977,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.383810000,131.193310000,'仙崎の食堂で昼食','港町の食堂に入り、地元の魚を使った定食をいただく。派手さはないが、丁寧に作られた味で体がほっと落ち着いた。窓から見える港の景色が心地よく、サイクリングの途中の食事として最適だった。','2026-10-18','13:10','🤩','0000','',-1200,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,978,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.380310000,131.189980000,'仙崎の海沿いをゆっくり走る','昼食後、海沿いの道をゆっくり走ると、風が心地よく、港町らしい穏やかな景色が広がっていた。自転車の速度を落として走ると、海の音がよりはっきり聞こえ、旅の中でも特に落ち着く時間となった。','2026-10-18','13:40','🌊','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,979,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.374810000,131.184310000,'長門市街へ戻る道を走る','仙崎から長門市街へ戻る道は緩やかな坂が続き、海から山へ景色が変わっていく。風が少し強くなるが、走るほどに体が軽くなるような感覚があった。町が近づくにつれ、旅の終わりが見えてくる。','2026-10-18','14:10','🚴','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (65,1020,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.276389000,133.142222000,'瀬戸田でレモンケーキを買う','瀬戸田の商店街は小さくて温かい雰囲気。名物のレモンケーキを買って小休憩。','2026-08-04','12:20','🙂','0000','',-600,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (4,37,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710000000,139.810700000,'とうきょうスカイツリー駅で合流','朝からテンション高めで全員集合。駅を降りた瞬間に目の前にそびえ立つ巨大なスカイツリーの迫力に思わず歓声が上がる。学生最後の思い出づくりがここからスタートする。','2026-03-15','10:00','🎓','0','',0,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,38,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710300000,139.811300000,'東京スカイツリー展望デッキ','高速エレベーターで一気に地上350mの展望デッキへ。窓の外に広がる東京の絶景にみんなで大興奮しながら記念撮影の嵐。遠くの方まで見渡せて本当に気持ちがいい。','2026-03-15','10:45','✨','0','',-2100,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (4,39,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.710500000,139.810500000,'東京ソラマチで早めのランチ','展望台を満喫したあとは、ソラマチのレストラン街でガッツリとランチ。みんなで違うメニューを頼んでシェアしながら、これまでの大学生活の思い出話で盛り上がる。','2026-03-15','12:30','😋','0','',-1600,1,0,0,0,0,true,'2026-08-01 09:54:55.982108+09','2026-08-02 22:20:39.048588+09','{}'),
	 (62,980,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371810000,131.182310000,'長門市街のカフェで休憩','市街地のカフェに入り、冷たい飲み物で体を落ち着かせる。サイクリングの疲れがすっと抜けていき、旅の途中の休憩として最適だった。窓から見える町の景色が穏やかで、青海島の迫力との対比が印象的だった。','2026-10-18','14:40','🤩','0000','',-700,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,981,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.370210000,131.180810000,'長門市街をゆっくり走る','休憩後、市街地をゆっくり走ると、地元の生活の気配が感じられ、旅の終盤らしい落ち着いた時間が流れた。観光地ではないが、町の静けさが心地よく、サイクリング旅の締めにふさわしい時間となった。','2026-10-18','15:10','🚴','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (65,1017,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.427778000,133.156111000,'因島大橋を渡る瞬間','橋の上から見える海が美しくて、思わず速度を落として景色を眺めた。','2026-08-04','10:20','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (62,982,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371240000,131.182760000,'長門市駅前でお土産購入','駅前の店で地元の海産物を使ったお土産を選びながら、今日のサイクリングを振り返る。青海島の迫力ある景色と仙崎の穏やかな港町が印象に残り、長門らしい旅になったと感じた。','2026-10-18','15:40','🎁','0000','',-1500,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (62,983,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.371240000,131.182760000,'旅の締め','駅前で自転車を返却し、深呼吸すると長門の静かな空気が胸に広がった。青海島の自然と港町の穏やかさを感じられる、満足度の高いサイクリング旅となった。','2026-10-18','16:00','🌅','0000','',0,1,0,0,0,0,false,'2026-08-02 03:03:11.237429+09','2026-08-02 03:03:11.237429+09','{}'),
	 (64,999,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.804912000,132.882144000,'三次駅に到着','三次駅に降り立つと、広島県北部らしい穏やかな空気が広がっていた。駅前は静かで歩きやすく、ゆっくり旅を始めるにはちょうどよい雰囲気。まずは周辺を軽く散策しながら今日の行き先を確認。遠くに見える山並みがやわらかく、都会の喧騒から離れた落ち着いた旅になりそうだと感じた。','2026-10-22','09:10','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (64,1000,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.809331000,132.866144000,'三次本通り商店街を散策','駅からほど近い本通り商店街は昔ながらの店が並び、ゆっくり歩くとどこか懐かしい気持ちになる。お年寄りでも歩きやすい平坦な道で、地元の人の挨拶が心地よい。小さな和菓子店に立ち寄ると、優しい味の饅頭が旅の始まりを彩ってくれた。','2026-10-22','09:40','🍡','0000','',-300,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (64,1001,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.812345000,132.864912000,'三次もののけミュージアム前','ミュージアム前は広い歩道が整備されており、休憩ベンチも多い。館内に入らなくても周辺の散策だけで十分楽しめる。川沿いの風が心地よく、ゆっくり歩く旅にぴったりの場所だった。','2026-10-22','10:10','🏛️','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (64,1002,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.815733000,132.857491000,'馬洗川沿いをゆっくり散歩','馬洗川沿いの遊歩道は平坦で歩きやすく、川の流れを眺めながらゆっくり進める。水面に映る空が美しく、心が落ち着く時間が流れる。途中にあるベンチでひと休みしながら、三次らしい穏やかな風景を楽しんだ。','2026-10-22','10:40','🌿','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (64,1003,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.827441000,132.859744000,'三次の小さな神社を参拝','川沿いにある小さな神社は段差が少なく、お年寄りでも参拝しやすい。境内は静かで、木々の香りが心地よい。地元の人が大切にしてきた場所らしく、派手さはないが落ち着いた空気が流れていた。','2026-10-22','11:10','⛩️','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (64,1004,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.838512000,132.861744000,'三次ワイナリーで休憩','三次ワイナリーは広い敷地で段差が少なく、ゆっくり歩ける場所。売店には地元産のジュースやお菓子が並び、軽い休憩にちょうどよい。外の芝生広場は風が気持ちよく、旅の途中に立ち寄るには最適だった。','2026-10-22','11:40','🍇','0000','',-800,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (64,1005,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.841902000,132.868331000,'庄原市街を散策','庄原市街は道幅が広く、歩道も整備されていて歩きやすい。昔ながらの商店が並び、ゆっくり歩くとどこか懐かしい気持ちになる。地元の人の挨拶が温かく、旅の印象をやさしくしてくれた。','2026-10-22','12:50','🏘️','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (3,27,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.013500000,135.677500000,'JR嵯峨嵐山駅で合流','朝の改札前で無事に待ち合わせに成功した。<br>少し肌寒いけど秋晴れの最高の天気で、2人のテンションも自然と上がっていく。<br>これから始まる嵐山デートの計画をワクワクしながら確認する。','2026-09-12','09:30','🥰','0','',0,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,28,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.011800000,135.677000000,'古民家風の朝カフェでコーヒー','歩き出す前に、駅近くの小さなカフェで温かいカフェラテをテイクアウトした。<br>香ばしいコーヒーの香りに癒やされながら、並んで歩き始める。<br>朝の静かな街並みがとても心地よい。','2026-09-12','09:50','☕','0','',-900,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,29,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.012300000,135.672500000,'天龍寺の境内と庭園を散策','世界遺産の天龍寺に立ち寄り、見事な雲龍図と美しい庭園を眺めた。<br>縁側に並んで腰掛け、池の周りを泳ぐ鯉をぼんやりと眺める。<br>心がすーっと洗われるような贅沢な時間を2人で共有できた。','2026-09-12','10:30','🌿','0','',-1200,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,30,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.015000000,135.670500000,'竹林の小径をのんびり歩く','観光客でにぎわう有名な竹林の小径へ足を踏み入れた。<br>天高くまっすぐ伸びる竹の隙間から、やわらかい木漏れ日が差し込んでいる。<br>風が吹くたびにサラサラと鳴る竹の葉の音がとても心地よかった。','2026-09-12','11:20','✨','0','',0,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (3,31,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.017800000,135.670000000,'野宮神社の縁結びスポット','竹林を抜けたところにある小さな神社にお参りした。<br>恋愛成就の御利益があるということで、2人でしっかりとお守りを授かる。<br>彼女が真剣な顔でおみくじを引いている姿が少し微笑ましかった。','2026-09-12','12:00','⛩️','0','',-600,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,32,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.016000000,135.673000000,'嵐山トロッコ駅周辺の隠れ家食堂','メインストリートから少し離れた、観光客の少ない穴場の食堂でランチにした。<br>湯豆腐と手打ち蕎麦のセットを頼んで、温かい出汁の味にホッと一息つく。<br>静かな場所だからこそ、ゆっくりといろんな話をすることができた。','2026-09-12','13:00','😋','0','',-2400,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (3,33,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,35.011000000,135.675000000,'渡月橋のたもとで川風を感じる','お腹が満たされたあとは、定番の渡月橋の周辺へと戻ってきた。<br>桂川を渡る涼しい風が心地よくて、思わず大きく深呼吸をする。<br>川面に映る山々の景色が絵画のように美しくて、しばらく言葉を失って見とれてしまった。','2026-09-12','14:30','🏞️','0','',0,1,0,0,0,0,false,'2026-08-01 09:56:56.740325+09','2026-08-01 09:56:56.740325+09','{}'),
	 (6,81,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,43.061200000,141.411200000,'モエレ沼公園の広大なアートを満喫','イサム・ノグチがデザインした広大なモエレ沼公園へ。ガラスのピラミッドを見たり、大きな山の上から札幌の街並みを眺めたりして、子どもたちは芝生を思い切り駆け回る。','2026-07-21','14:15','⛰️','0','',0,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (6,82,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,42.812300000,141.651200000,'新千歳空港でお土産を大量買い出し','楽しかった旅行も終盤。早めに空港へ戻り、大きなお土産売り場で定番のバターサンドや海鮮弁当、チーズケーキなどを家族みんなで吟味してカゴいっぱいに買い込む。','2026-07-21','16:30','🛍️','0','',-6000,1,0,0,0,0,false,'2026-08-01 10:13:54.239894+09','2026-08-01 10:13:54.239894+09','{}'),
	 (29,418,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196000000,135.150000000,'加太の海辺散歩','海風が気持ちよくて最高。友達と写真を撮り合って盛り上がる。','2026-08-10','14:00','🤩','0','',0,1,0,0,0,0,false,'2026-08-01 19:28:58.796123+09','2026-08-01 19:28:58.796123+09','{}'),
	 (37,540,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.705670000,135.188900000,'「神戸布引ハーブ園」でロープウェイ空中散歩とハーブの香り','ロープウェイに揺られて、眼下に広がる神戸の街並みと港を眺めながら空中散歩を楽しむ。山頂駅に到着すると、季節のハーブや色鮮やかな花々が咲き誇る美しいガーデンがお出迎え。心地よい香りに包まれながら、優雅なハーブティーを味わい心からリフレッシュ。','2026-12-04','10:45','🌿','0','',-1800,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (37,541,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.701230000,135.185430000,'1軒目：北野坂のおしゃれな隠れ家カフェでランチ','北野坂の上品な雰囲気に溶け込む、隠れ家のような素敵なカフェでランチタイム。地元の新鮮な野菜をふんだんに使った彩り豊かなオープンサンドと、香り高い自家焙煎コーヒーをいただく。窓から差し込む柔らかな光の中で、楽しくおしゃべりに花が咲く。','2026-12-04','12:30','☕','0','',-1600,1,0,0,0,0,false,'2026-08-01 21:42:22.107491+09','2026-08-01 21:42:22.107491+09','{}'),
	 (55,860,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,33.841640000,132.765300000,'松山駅に移動','電車で松山へ。駅前の落ち着いた雰囲気が心地よい。','2026-08-12','09:00','🚉','0000','',0,1,0,0,0,0,false,'2026-08-02 02:10:10.753314+09','2026-08-02 02:10:10.753314+09','{}'),
	 (65,1021,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.245556000,133.132222000,'耕三寺を見学','赤い建物が印象的で、島にこんな場所があるのかと驚く。静かで落ち着いた時間を過ごせた。','2026-08-04','13:00','🙂','0000','',-1200,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}');
INSERT INTO public.t_memo_detail_pub (archive_id,seq,user_id,latitude,longitude,title,body,memo_date,memo_time,face_emoji,weather_code,link_url,memo_price,feel_type,count_funny,count_love,count_surprise,count_sad,del_flg,create_tim,update_tim,click_stats) VALUES
	 (65,1022,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.240833000,133.097222000,'多々羅大橋を渡る','しまなみ海道でも特に美しい橋。海と島の重なりが絶景で、思わず声が出るほど。','2026-08-04','14:00','🤩','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (65,1023,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.196944000,133.030833000,'大三島の道の駅で休憩','名物のじゃこ天を食べてエネルギー補給。地元の人の温かさを感じる場所。','2026-08-04','14:40','🙂','0000','',-300,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (65,1016,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.407222000,133.168333000,'向島の海沿いを散歩','海沿いの道は静かで、波の音だけが聞こえる。ゆったりした時間が流れて心が落ち着く。','2026-08-04','09:40','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}'),
	 (64,1006,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.844512000,132.858733000,'庄原の食堂で昼食','庄原の食堂は落ち着いた雰囲気で、地元の野菜を使った定食が優しい味だった。量もほどよく、お年寄りでも食べやすい。窓から見える田園風景が心地よく、ゆっくりとした昼食時間になった。','2026-10-22','13:20','🌿','0000','',-1200,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (64,1007,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.852291000,132.870912000,'上野公園を散策','庄原の上野公園は広く平坦で、お年寄りでも安心して歩ける。池の周りをゆっくり歩くと風が心地よく、鳥の声が響く。ベンチも多く、休憩しながら自然を楽しめる場所だった。','2026-10-22','14:00','🌳','0000','',0,1,0,0,0,0,false,'2026-08-02 07:21:29.702263+09','2026-08-02 07:21:29.702263+09','{}'),
	 (65,1025,'940e5f31-a52c-46c2-8e01-d66265d65f12'::uuid,34.158333000,133.006111000,'伯方島へ移動','海沿いの道が続き、潮風が心地よい。ゆったりした島時間を感じる。','2026-08-04','16:00','🙂','0000','',0,1,0,0,0,0,false,'2026-08-02 07:32:11.881072+09','2026-08-02 07:32:11.881072+09','{}');
